// --- HELPER COMPONENTS ---

// 1. Throttled Slider
interface ThrottledSliderProps {
    value: number;
    min: number;
    max: number;
    step: number;
    onChange: (val: number) => void;
    className?: string;
    style?: React.CSSProperties;
}

const ThrottledSlider: React.FC<ThrottledSliderProps> = ({
    value,
    min,
    max,
    step,
    onChange,
    className = "",
    style
}) => {
    const [localValue, setLocalValue] = useState(value);
    const lastEmit = useRef(0);
    const timer = useRef<number | null>(null);

    // Sync from parent if changed externally
    useEffect(() => {
        setLocalValue(value);
    }, [value]);

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const newVal = parseFloat(e.target.value);
        setLocalValue(newVal);

        const now = Date.now();
        // Throttle to ~33ms (30fps) for heavy operations
        if (now - lastEmit.current > 33) {
            onChange(newVal);
            lastEmit.current = now;
        } else {
            // Trailing edge call to ensure final value is set
            if (timer.current) clearTimeout(timer.current);
            timer.current = window.setTimeout(() => {
                onChange(newVal);
                lastEmit.current = Date.now();
            }, 33);
        }
    };

    return (
        <input 
            type="range" 
            min={min} 
            max={max} 
            step={step}
            value={localValue}
            onChange={handleChange}
            className={className}
            style={style}
        />
    );
};

// 2. Number Input
const NumberInput = ({
    value,
    min,
    max,
    onChange,
    suffix = "",
    className = ""
}: {
    value: number;
    min: number;
    max: number;
    onChange: (val: number) => void;
    suffix?: string;
    className?: string;
}) => {
    const [text, setText] = useState(value.toString());
    const [error, setError] = useState<string | null>(null);

    useEffect(() => {
        if (parseInt(text) !== value) {
             setText(value.toString());
             setError(null);
        }
    }, [value]);

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const val = e.target.value;
        if (val !== '' && !/^\d+$/.test(val)) return;
        setText(val);
        if (val === '') return; 

        const num = parseInt(val, 10);
        if (num < min || num > max) {
            setError(`Range: ${min}-${max}`);
        } else {
            setError(null);
            onChange(num);
        }
    };

    const handleBlur = () => {
        if (text === '' || error) {
            setText(value.toString());
            setError(null);
        }
    };

    return (
        <div className="flex flex-col flex-grow">
            <div className="relative">
                <input 
                    type="text" 
                    inputMode="numeric"
                    value={text}
                    onChange={handleChange}
                    onBlur={handleBlur}
                    className={`w-full bg-slate-700 rounded p-2 text-sm text-white border border-slate-600 focus:outline-none focus:border-blue-500 transition-colors ${className} ${error ? 'border-red-500 focus:border-red-500' : ''}`}
                />
                {suffix && <span className="absolute right-3 top-2 text-sm text-slate-400 pointer-events-none">{suffix}</span>}
            </div>
            {error && <span className="text-[10px] text-red-400 mt-1 font-bold animate-pulse">{error}</span>}
        </div>
    );
};

// 3. Key Bind Button
interface KeyBindButtonProps {
    label: string;
    code: string;
    onBind: () => void;
