export default SettingsModal;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import TonalityDiamond, { TonalityDiamondHandle } from './components/TonalityDiamond';
import SettingsModal from './components/SettingsModal';
import SynthControls from './components/SynthControls';
import FloatingControls from './components/FloatingControls';
import LimitLayerControls from './components/LimitLayerControls';
import { audioEngine } from './services/AudioEngine'; // Import singleton
import { useStore } from './services/Store';
import { AppSettings, ChordDefinition, XYPos } from './types';
import { MARGIN_3MM, SCROLLBAR_WIDTH } from './constants';

const App: React.FC = () => {
  const { settings, preset, updateSettings, setPreset } = useStore();

  const [masterVolume, setMasterVolume] = useState(0.8);
  const [activeChordIds, setActiveChordIds] = useState<string[]>([]);
  const [draggingId, setDraggingId] = useState<string | null>(null);

  // Latch State: 0 = Off, 1 = Active (Green), 2 = Frozen (Momentary Only)
  const [latchStatus, setLatchStatus] = useState<0 | 1 | 2>(0);

  // Modals
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isSynthOpen, setIsSynthOpen] = useState(false);

  // Visual Focus Mode
  const [showUI, setShowUI] = useState(true);

  const diamondRef = useRef<TonalityDiamondHandle>(null);

  // Audio Warmup: Pre-initialize audio context on any user interaction
  useEffect(() => {
    const warmup = () => {
        audioEngine.init();

        // Remove listeners once warmed up
        window.removeEventListener('pointerdown', warmup);
        window.removeEventListener('keydown', warmup);
        window.removeEventListener('touchstart', warmup);
    };

    window.addEventListener('pointerdown', warmup);
    window.addEventListener('keydown', warmup);
    window.addEventListener('touchstart', warmup);

    return () => {
        window.removeEventListener('pointerdown', warmup);
        window.removeEventListener('keydown', warmup);
        window.removeEventListener('touchstart', warmup);
    };
  }, []);

  // Sanitize UI Positions on Load to prevent off-screen elements
  useEffect(() => {
      const w = window.innerWidth;
      const h = window.innerHeight;

      updateSettings(prev => {
          const p = { ...prev.uiPositions };
          let changed = false;

          // Helper to check and clamp
          const checkAndFix = (key: keyof typeof p, width: number, height: number) => {
              let x = p[key].x;
              let y = p[key].y;

              const maxX = w - width - MARGIN_3MM;
              const maxY = h - height - MARGIN_3MM;
              const minX = MARGIN_3MM;
              const minY = MARGIN_3MM;

              // Clamp if out of bounds
              if (x > maxX) { x = maxX; changed = true; }
              if (x < minX) { x = minX; changed = true; }
              if (y > maxY) { y = maxY; changed = true; }
              if (y < minY) { y = minY; changed = true; }

              p[key] = { x, y };
          };

          // Estimates for element sizes (width, height)
          checkAndFix('volume', 180, 48); // Increased width for new design
          checkAndFix('panic', 64, 64);
          checkAndFix('off', 64, 64);
          checkAndFix('latch', 64, 64);
          checkAndFix('center', 160, 48); // Increased width for grouped Navigation Bar
          checkAndFix('chords', 300, 48); 
          checkAndFix('layers', 90, 310);

          return changed ? { ...prev, uiPositions: p } : prev;
      });
  }, []); // Run once on mount

  // Resize Handler to snap UI elements to their anchors
  const windowSize = useRef({ w: window.innerWidth, h: window.innerHeight });

  useEffect(() => {
    const handleResize = () => {
      const newW = window.innerWidth;
      const newH = window.innerHeight;
      const oldW = windowSize.current.w;
      const oldH = windowSize.current.h;

      updateSettings(prev => {
        const p = prev.uiPositions;
        const newPos = { ...p };

        // 1. Panic (Anchor: Bottom-Right)
        newPos.panic = {
            x: newW - (oldW - p.panic.x),
            y: newH - (oldH - p.panic.y)
        };

        // 2. Off (Anchor: Bottom-Right)
        newPos.off = {
            x: newW - (oldW - p.off.x),
            y: newH - (oldH - p.off.y)
        };

        // 3. Latch (Anchor: Bottom-Right)
        newPos.latch = {
            x: newW - (oldW - p.latch.x),
            y: newH - (oldH - p.latch.y)
        };

        // 4. Volume (Anchor: Top-Center)
        const volOffsetFromCenter = p.volume.x - (oldW / 2);
        newPos.volume = {
            x: (newW / 2) + volOffsetFromCenter,
            y: p.volume.y 
        };

        // 5. Center/Chords (Anchor: Bottom-Left)
        const updateBottomLeft = (key: 'center' | 'chords') => {
             newPos[key] = {
                 x: p[key].x, 
                 y: newH - (oldH - p[key].y)
             };
        };
        updateBottomLeft('center');
        updateBottomLeft('chords');

        // 6. Layers (Anchor: Vertical Center on Right Edge)
        newPos.layers = {
            x: newW - (oldW - p.layers.x), // Maintain distance from right edge
            y: (newH / 2) - 155 // Recenter vertically (height/2)
        };

        return {
            ...prev,
            uiPositions: newPos
        };
      });

      windowSize.current = { w: newW, h: newH };
    };

    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, [updateSettings]);

  // Init Engine updates
  useEffect(() => {
    audioEngine.setMasterVolume(masterVolume);
  }, [masterVolume]);

  const handleLimitInteraction = (limit: number) => {
    if (settings.layerOrder[settings.layerOrder.length - 1] !== limit) {
      const newOrder = settings.layerOrder.filter(l => l !== limit);
      newOrder.push(limit);
      updateSettings(prev => ({ ...prev, layerOrder: newOrder }));
    }
  };

  const handlePanic = useCallback(() => {
    audioEngine.stopAll(); 
    diamondRef.current?.clearLatches(); 
    setActiveChordIds([]); 
    setLatchStatus(0); // Reset Latch
  }, []);

  // Musical Off: Unlatch nodes but let tails fade
  const handleOff = () => {
    diamondRef.current?.clearLatches(); 
    setActiveChordIds([]);
    setLatchStatus(0); // Reset Latch
  };

  // Tri-State Logic: Off (0) -> Active (1) -> Frozen (2) -> Off (0)
  const handleLatchToggle = () => {
      setLatchStatus(prev => {
          if (prev === 0) return 1;
          if (prev === 1) return 2;
          if (prev === 2) {
              diamondRef.current?.clearLatches(); // "Taking foot off pedal"
              return 0;
          }
          return 0;
      });
  };

  const handleCenter = useCallback(() => {
      diamondRef.current?.centerView();
  }, []);

  const handleIncreaseDepth = () => {
      diamondRef.current?.increaseDepth();
  };

  const handleDecreaseDepth = () => {
      diamondRef.current?.decreaseDepth();
  };

  const handleAddChord = useCallback(() => {
      if (diamondRef.current) {
          const latchedNodes = diamondRef.current.getLatchedNodes();
          if (latchedNodes.length === 0) return;

          let slotIndex = settings.savedChords.findIndex(c => c.nodes.length === 0);
          if (slotIndex === -1) {
               slotIndex = settings.savedChords.findIndex(c => !c.visible);
          }

          if (slotIndex !== -1) {
              const newChords = [...settings.savedChords];
              const simplifiedNodes = latchedNodes.map(n => ({
                  id: n.id,
                  n: n.n,
                  d: n.d
              }));

              newChords[slotIndex] = {
                  ...newChords[slotIndex],
                  nodes: simplifiedNodes,
                  visible: true,
                  position: { x: 0, y: 0 } 
              };

              updateSettings(prev => ({ ...prev, savedChords: newChords }));
          }
      }
  }, [settings.savedChords, updateSettings]);

  const toggleChord = (id: string) => {
      setActiveChordIds(prev => {
          if (prev.includes(id)) {
              return prev.filter(c => c !== id);
          } else {
              return [...prev, id];
          }
      });
  };

  const handleUiPositionUpdate = (key: keyof AppSettings['uiPositions'], pos: XYPos) => {
      updateSettings(prev => ({
          ...prev,
          uiPositions: {
              ...prev.uiPositions,
              [key]: pos
          }
      }));
  };

  // --- Keyboard Shortcuts ---
  const handleToggleLimit = useCallback((limit: number) => {
      const isHidden = settings.hiddenLimits.includes(limit);
      let newHidden = [...settings.hiddenLimits];
      if (isHidden) {
          newHidden = newHidden.filter(l => l !== limit);
      } else {
          newHidden.push(limit);
      }
      updateSettings(prev => ({ ...prev, hiddenLimits: newHidden }));
  }, [settings.hiddenLimits, updateSettings]);

  useEffect(() => {
      const handleKeyDown = (e: KeyboardEvent) => {
          // Ignore if typing in an input
          if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return;

          // Mapping
          const map = settings.keyMap;

          switch(e.code) {
              case map.panic:
                  e.preventDefault();
                  handlePanic();
                  break;
              case map.center:
                  e.preventDefault();
                  handleCenter();
                  break;
              case map.increaseDepth:
                  e.preventDefault();
                  handleIncreaseDepth();
                  break;
              case map.decreaseDepth:
                  e.preventDefault();
                  handleDecreaseDepth();
                  break;
              case map.addChord:
                  e.preventDefault();
                  handleAddChord();
                  break;
              case map.toggleSynth:
                  e.preventDefault();
                  setIsSynthOpen(prev => !prev);
                  break;
              case map.toggleSettings:
                  e.preventDefault();
                  setIsSettingsOpen(prev => !prev);
                  break;
              case map.toggleUI:
                  e.preventDefault();
                  setShowUI(prev => !prev);
                  break;
              case map.closeModals:
                  e.preventDefault();
                  setIsSettingsOpen(false);
                  setIsSynthOpen(false);
                  break;

              // Volume Control
              case map.volumeUp:
                  e.preventDefault();
                  setMasterVolume(v => Math.min(1.0, v + 0.05));
                  break;
              case map.volumeDown:
                  e.preventDefault();
                  setMasterVolume(v => Math.max(0.0, v - 0.05));
                  break;

              // Limits
              case map.limit3: e.preventDefault(); handleToggleLimit(3); break;
              case map.limit5: e.preventDefault(); handleToggleLimit(5); break;
              case map.limit7: e.preventDefault(); handleToggleLimit(7); break;
              case map.limit11: e.preventDefault(); handleToggleLimit(11); break;
              case map.limit13: e.preventDefault(); handleToggleLimit(13); break;
          }
      };

      window.addEventListener('keydown', handleKeyDown);
      return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handlePanic, handleCenter, handleAddChord, handleToggleLimit, settings.keyMap]);

  return (
    <div 
        className="relative w-screen h-screen overflow-hidden bg-slate-900 font-sans text-white"
        onContextMenu={(e) => e.preventDefault()} // Prevent native context menu for app-like feel
    >

      {/* Top Bar - Fixed Position */}
      <div 
        className={`absolute w-full flex justify-between items-center z-40 pointer-events-none transition-opacity duration-300 ${showUI ? 'opacity-100' : 'opacity-0'}`}
        style={{ 
            top: `${MARGIN_3MM}px`, 
            paddingLeft: `${MARGIN_3MM}px`,
            paddingRight: `${MARGIN_3MM + SCROLLBAR_WIDTH}px` 
        }}
      >
        <h1 className="text-xl font-bold tracking-widest text-slate-500 opacity-50">PRISMATONAL</h1>
        <div className="flex gap-2 pointer-events-auto">
          <button 
            onClick={() => setIsSynthOpen(true)}
            className="bg-slate-800/80 hover:bg-indigo-600 px-4 py-2 rounded-lg backdrop-blur transition border border-white/10"
          >
            Synth
          </button>
          <button 
            onClick={() => setIsSettingsOpen(true)}
            className="bg-slate-800/80 hover:bg-slate-600 px-4 py-2 rounded-lg backdrop-blur transition border border-white/10"
          >
            Settings
          </button>
        </div>
      </div>

      {/* Main Canvas */}
      <TonalityDiamond 
        ref={diamondRef}
        settings={settings}
        updateSettings={updateSettings}
        audioEngine={audioEngine} 
        onLimitInteraction={handleLimitInteraction}
        activeChordIds={activeChordIds}
        uiUnlocked={settings.uiUnlocked}
        latchStatus={latchStatus}
      />

      {/* Floating UI */}
      {showUI && (
          <FloatingControls 
            volume={masterVolume}
            setVolume={setMasterVolume}
            onPanic={handlePanic}
            onOff={handleOff}
            latchStatus={latchStatus}
            onLatchToggle={handleLatchToggle}
            onCenter={handleCenter}
            onIncreaseDepth={handleIncreaseDepth}
            onDecreaseDepth={handleDecreaseDepth}
            onAddChord={handleAddChord}
            toggleChord={toggleChord}
            activeChordIds={activeChordIds}
            savedChords={settings.savedChords}
            chordShortcutSizeScale={settings.chordShortcutSizeScale}
            showIncreaseDepthButton={settings.showIncreaseDepthButton}
            uiUnlocked={settings.uiUnlocked}
            uiPositions={settings.uiPositions}
            updatePosition={handleUiPositionUpdate}
            draggingId={draggingId}
            setDraggingId={setDraggingId}
          />
      )}

      {showUI && (
          <LimitLayerControls 
            settings={settings}
            updateSettings={updateSettings}
            draggingId={draggingId}
            setDraggingId={setDraggingId}
          />
      )}

      {/* Modals */}
      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)}
        settings={settings}
        updateSettings={updateSettings}
      />

      <SynthControls 
        isOpen={isSynthOpen}
        onClose={() => setIsSynthOpen(false)}
        preset={preset}
        onChange={setPreset}
      />
    </div>
  );
};

export default App;

import React from 'react';
import { ChordDefinition, XYPos, AppSettings } from '../types';
import { MARGIN_3MM, SCROLLBAR_WIDTH } from '../constants';

interface Props {
  volume: number;
  setVolume: (v: number) => void;
  onPanic: () => void;
  onOff: () => void;
  latchStatus: 0 | 1 | 2; // 0=Off, 1=Active, 2=Frozen
  onLatchToggle: () => void;
  onCenter: () => void;
  onIncreaseDepth: () => void;
  onDecreaseDepth: () => void;
  onAddChord: () => void;
  toggleChord: (id: string) => void;
  activeChordIds: string[];
  savedChords: ChordDefinition[];
  chordShortcutSizeScale: number;
  showIncreaseDepthButton: boolean;
  uiUnlocked: boolean;
  uiPositions: AppSettings['uiPositions'];
  updatePosition: (key: keyof AppSettings['uiPositions'], pos: XYPos) => void;
  draggingId: string | null;
  setDraggingId: (id: string | null) => void;
}

const FloatingControls: React.FC<Props> = ({ 
  volume, setVolume, onPanic, onOff, latchStatus, onLatchToggle, 
  onCenter, onIncreaseDepth, onDecreaseDepth, onAddChord, toggleChord,
  activeChordIds, savedChords, chordShortcutSizeScale,
  showIncreaseDepthButton, uiUnlocked, uiPositions, updatePosition,
  draggingId, setDraggingId
}) => {

  // Generic Drag Handler
  const handleDrag = (e: React.PointerEvent, key: keyof AppSettings['uiPositions']) => {
    if (!uiUnlocked) return;

    // Lock mechanism
    if (draggingId !== null && draggingId !== key) return;

    const el = e.currentTarget as HTMLElement;
    const startX = e.clientX;
    const startY = e.clientY;

    // Initial position relative to window
    const initialLeft = uiPositions[key as keyof typeof uiPositions].x;
    const initialTop = uiPositions[key as keyof typeof uiPositions].y;

    el.setPointerCapture(e.pointerId);
    setDraggingId(key);

    const onMove = (evt: PointerEvent) => {
        const deltaX = evt.clientX - startX;
        const deltaY = evt.clientY - startY;

        // Calculate new position
        let newX = initialLeft + deltaX;
        let newY = initialTop + deltaY;

        // Clamp to window bounds with Margin + Scrollbar safety
        const maxX = window.innerWidth - el.offsetWidth - MARGIN_3MM - SCROLLBAR_WIDTH;
        const maxY = window.innerHeight - el.offsetHeight - MARGIN_3MM - SCROLLBAR_WIDTH;
        const minX = MARGIN_3MM;
        const minY = MARGIN_3MM;

        newX = Math.max(minX, Math.min(newX, maxX));
        newY = Math.max(minY, Math.min(newY, maxY));

        updatePosition(key, { x: newX, y: newY });
    };

    const onUp = () => {
        setDraggingId(null);
        window.removeEventListener('pointermove', onMove);
        window.removeEventListener('pointerup', onUp);
    };

    window.addEventListener('pointermove', onMove);
    window.addEventListener('pointerup', onUp);
  };

  // Base size reference for buttons
  const baseSize = 48; // 12 * 4px (w-12)
  const chordSize = baseSize * chordShortcutSizeScale;

  // Styles
  const draggableStyle = (key: string) => ({
      left: uiPositions[key as keyof typeof uiPositions].x,
      top: uiPositions[key as keyof typeof uiPositions].y,
      touchAction: 'none' as React.CSSProperties['touchAction'],
  });

  const glassPanelClass = `bg-slate-800/80 border border-slate-600/50 shadow-xl rounded-2xl transition-all ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50 hover:bg-slate-700/80' : ''}`;

  // Helper to handle button press logic (Drag if unlocked, Action if locked)
  const handleButtonPress = (e: React.PointerEvent, key: keyof AppSettings['uiPositions'], action: () => void) => {
      e.stopPropagation(); // Stop propagation to canvas
      if (uiUnlocked) {
          handleDrag(e, key);
      } else {
          action();
      }
  };

  return (
    <>
      {/* Volume Slider - Top Center */}
      <div 
        className={`absolute flex items-center gap-3 p-3 px-4 z-[150] ${glassPanelClass}`}
        style={{ ...draggableStyle('volume'), width: 180 }}
        onPointerDown={(e) => handleDrag(e, 'volume')}
      >
        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-5 h-5 text-slate-400">
          <path strokeLinecap="round" strokeLinejoin="round" d="M19.114 5.636a9 9 0 010 12.728M16.463 8.288a5.25 5.25 0 010 7.424M6.75 8.25l4.72-4.72a.75.75 0 011.28.53v15.88a.75.75 0 01-1.28.53l-4.72-4.72H4.51c-.88 0-1.704-.507-1.938-1.354A9.01 9.01 0 012.25 12c0-.83.112-1.633.322-2.396C2.806 8.756 3.63 8.25 4.51 8.25H6.75z" />
        </svg>
        <input 
          type="range" min="0" max="1" step="0.01" 
          value={volume}
          onChange={(e) => setVolume(parseFloat(e.target.value))}
          disabled={uiUnlocked}
          className={`w-full h-1.5 bg-slate-600 rounded-lg appearance-none ${uiUnlocked ? 'cursor-move opacity-50' : 'cursor-pointer accent-blue-500'}`}
          onPointerDown={(e) => !uiUnlocked && e.stopPropagation()} 
        />
      </div>

      {/* Navigation Bar (Center + Depths) - Bottom Left */}
      <div
         className={`absolute flex items-center p-2 gap-2 z-[150] ${glassPanelClass}`}
         style={draggableStyle('center')}
         onPointerDown={(e) => handleDrag(e, 'center')}
      >
          {showIncreaseDepthButton && (
             <button
               className={`w-10 h-10 rounded-xl flex items-center justify-center text-green-400 hover:bg-white/10 active:bg-green-500 active:text-white transition-colors ${uiUnlocked ? 'pointer-events-none' : ''}`}
               onPointerDown={(e) => !uiUnlocked && e.stopPropagation()} 
               onClick={onDecreaseDepth}
               title="Decrease Depth"
             >
                <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-6 h-6">
                  <path fillRule="evenodd" d="M4 10a.75.75 0 01.75-.75h10.5a.75.75 0 010 1.5H4.75A.75.75 0 014 10z" clipRule="evenodd" />
                </svg>
             </button>
          )}

          <div className="w-px h-6 bg-slate-600/50"></div>

          <button
             className={`w-12 h-10 rounded-xl flex items-center justify-center text-yellow-500 font-bold hover:bg-white/10 active:bg-yellow-600 active:text-white transition-colors ${uiUnlocked ? 'pointer-events-none' : ''}`}
             onPointerDown={(e) => !uiUnlocked && e.stopPropagation()} 
             onClick={onCenter}
             title="Center View"
          >
             <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-6 h-6">
               <path strokeLinecap="round" strokeLinejoin="round" d="M3.75 3.75v4.5m0-4.5h4.5m-4.5 0L9 9M3.75 20.25v-4.5m0 4.5h4.5m-4.5 0L9 15M20.25 3.75h-4.5m4.5 0v4.5m0-4.5L15 9m5.25 11.25h-4.5m4.5 0v-4.5m0 4.5L15 15" />
             </svg>
          </button>

          <div className="w-px h-6 bg-slate-600/50"></div>

          {showIncreaseDepthButton && (
             <button
               className={`w-10 h-10 rounded-xl flex items-center justify-center text-blue-400 hover:bg-white/10 active:bg-blue-500 active:text-white transition-colors ${uiUnlocked ? 'pointer-events-none' : ''}`}
               onPointerDown={(e) => !uiUnlocked && e.stopPropagation()} 
               onClick={onIncreaseDepth}
               title="Increase Depth"
             >
                <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-6 h-6">
                  <path d="M10.75 4.75a.75.75 0 00-1.5 0v4.5h-4.5a.75.75 0 000 1.5h4.5v4.5a.75.75 0 001.5 0v-4.5h4.5a.75.75 0 000-1.5h-4.5v-4.5z" />
                </svg>
             </button>
          )}
      </div>

      {/* Latch Button */}
      {/* Container wrapper used for the animated border effect in Frozen state */}
      <div
        className={`absolute w-16 h-16 z-[150] rounded-2xl ${uiUnlocked ? 'cursor-move' : ''}`}
        style={draggableStyle('latch')}
        onPointerDown={(e) => handleButtonPress(e, 'latch', onLatchToggle)}
      >
          {latchStatus === 2 && (
              // Spinning Gradient Background for Frozen State
              <div className="absolute inset-[-4px] rounded-2xl overflow-hidden animate-spin-slow opacity-80 pointer-events-none">
                  <div className="w-full h-full bg-[conic-gradient(from_0deg,transparent_0deg,transparent_90deg,#22c55e_180deg,transparent_270deg,transparent_360deg)]"></div>
              </div>
          )}

          <button
            className={`relative w-full h-full flex items-center justify-center font-bold uppercase tracking-wider rounded-2xl select-none transition-all border
                ${latchStatus === 1 
                    ? 'bg-green-500 text-white border-green-400 shadow-[0_0_15px_rgba(34,197,94,0.6)]' // Active
                    : latchStatus === 2 
                        ? 'bg-slate-900 text-green-500 border-transparent' // Frozen (Background handled by wrapper)
                        : 'bg-slate-800/80 text-green-700 border-slate-600/50 hover:text-green-500' // Off
                }
                ${uiUnlocked ? 'pointer-events-none' : 'active:scale-95'}
            `}
          >
            LATCH
          </button>
      </div>

      {/* Off Button */}
      <button
        className={`absolute w-16 h-16 flex items-center justify-center text-yellow-500 font-bold uppercase tracking-wider shadow-[0_0_15px_rgba(234,179,8,0.2)] z-[150] select-none ${glassPanelClass} hover:bg-yellow-600/20 active:bg-yellow-600 active:text-white`}
        style={draggableStyle('off')}
        onPointerDown={(e) => handleButtonPress(e, 'off', onOff)}
      >
        OFF
      </button>

      {/* Panic Button */}
      <button
        className={`absolute w-16 h-16 flex items-center justify-center text-red-500 font-bold uppercase tracking-wider shadow-[0_0_15px_rgba(239,68,68,0.2)] z-[150] select-none ${glassPanelClass} hover:bg-red-600/20 active:bg-red-600 active:text-white`}
        style={draggableStyle('panic')}
        onPointerDown={(e) => handleButtonPress(e, 'panic', onPanic)}
      >
        PANIC
      </button>

      {/* Chords Group */}
      <div
         className={`absolute flex gap-2 flex-wrap items-start z-[150] p-2 ${glassPanelClass}`}
         style={{ ...draggableStyle('chords'), maxWidth: '80vw' }}
         onPointerDown={(e) => handleDrag(e, 'chords')}
      >
          {/* Add Chord Button */}
          <button
            className={`rounded-lg border-2 border-slate-500 border-dashed flex items-center justify-center text-slate-500 font-bold hover:bg-slate-700/40 hover:text-white hover:border-white transition-all select-none ${uiUnlocked ? 'pointer-events-none' : ''}`}
            style={{ width: chordSize, height: chordSize }}
            onPointerDown={(e) => !uiUnlocked && e.stopPropagation()} 
            onClick={!uiUnlocked ? onAddChord : undefined}
            title="Store currently latched notes as a Chord"
          >
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-1/2 h-1/2">
              <path strokeLinecap="round" strokeLinejoin="round" d="M12 4.5v15m7.5-7.5h-15" />
            </svg>
          </button>

          {/* Saved Chords */}
          {savedChords.filter(c => c.visible).map((chord) => {
              const isActive = activeChordIds.includes(chord.id);
              return (
                <button
                    key={chord.id}
                    className={`rounded-lg flex items-center justify-center font-bold transition-all shadow-lg select-none ${uiUnlocked ? 'pointer-events-none' : ''}`}
                    style={{
                        width: chordSize,
                        height: chordSize,
                        backgroundColor: isActive ? chord.color : `${chord.color}33`, 
                        borderColor: chord.color,
                        borderWidth: 2,
                        color: isActive ? '#fff' : chord.color,
                        boxShadow: isActive ? `0 0 10px ${chord.color}` : 'none'
                    }}
                    onPointerDown={(e) => !uiUnlocked && e.stopPropagation()}
                    onClick={() => !uiUnlocked && toggleChord(chord.id)}
                    title={`Chord ${chord.id}: ${chord.label}`}
                >
                    {chord.id}
                </button>
              );
          })}
      </div>
    </>
  );
};

export default FloatingControls;

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine } from '../types';
import AudioEngine from '../services/AudioEngine';
import { midiService } from '../services/MidiService';
import { useLatticeInteraction } from '../hooks/useLatticeInteraction';
import { useLatticeGeneration } from '../hooks/useLatticeGeneration';
import LatticeCanvas from './LatticeCanvas';

export interface TonalityDiamondHandle {
  clearLatches: () => void;
  centerView: () => void;
  increaseDepth: () => void;
  decreaseDepth: () => void;
  getLatchedNodes: () => LatticeNode[];
}

interface Props {
  settings: AppSettings;
  updateSettings: (s: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) => void;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
  latchStatus: 0 | 1 | 2;
}

const GRID_CELL_SIZE = 100;

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, updateSettings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked, latchStatus } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null);

  // 1. Data Generation Hook
  const { data, isGenerating, dynamicSize } = useLatticeGeneration(settings);
  const prevDynamicSizeRef = useRef(2000);

  // 2. Memoized Lookups (Data Derivative)
  const nodeMap = useMemo(() => new Map(data.nodes.map(n => [n.id, n])), [data.nodes]);

  const spatialGrid = useMemo(() => {
      const grid = new Map<string, LatticeNode[]>();
      const centerOffset = dynamicSize / 2;
      const spacing = settings.buttonSpacingScale;

      data.nodes.forEach(node => {
          const x = node.x * spacing + centerOffset;
          const y = node.y * spacing + centerOffset;
          const col = Math.floor(x / GRID_CELL_SIZE);
          const row = Math.floor(y / GRID_CELL_SIZE);
          const key = `${col},${row}`;
          if (!grid.has(key)) grid.set(key, []);
          grid.get(key)!.push(node);
      });
      return grid;
  }, [data.nodes, settings.buttonSpacingScale, dynamicSize]);

  // Refs for Hooks
  const nodeMapRef = useRef(nodeMap);
  const spatialGridRef = useRef(spatialGrid);
  const dynamicSizeRef = useRef(dynamicSize);

  useEffect(() => { nodeMapRef.current = nodeMap; }, [nodeMap]);
  useEffect(() => { spatialGridRef.current = spatialGrid; }, [spatialGrid]);
  useEffect(() => { dynamicSizeRef.current = dynamicSize; }, [dynamicSize]);

  // 3. Interaction Hook
  const {
      activeCursors,
      activeCursorsRef,
      manualLatchedNodes,
      setManualLatchedNodes,
      cursorPositionsRef,
      lastTouchedLimitRef,
      handlePointerDown,
      handlePointerMove,
      handlePointerUp
  } = useLatticeInteraction({
      settings,
      audioEngine,
      nodeMapRef,
      spatialGridRef,
      dynamicSizeRef,
      dynamicCanvasRef,
      scrollContainerRef,
      onLimitInteraction,
      uiUnlocked,
      latchStatus
  });

  const [effectiveLatchedNodes, setEffectiveLatchedNodes] = useState<Map<string, string>>(new Map());

  // Optimization: Pre-calculate active (both latched) and reinforced (one latched) lines
  const { activeLines, reinforcedLines } = useMemo(() => {
    const latched = effectiveLatchedNodes;
    const lines = data.lines;
    const active: LatticeLine[] = [];
    const reinforced: LatticeLine[] = [];

    if (latched.size > 0) {
        for (const line of lines) {
            const s = latched.has(line.sourceId);
            const t = latched.has(line.targetId);

            if (s && t) {
                active.push(line);
            } else if (s || t) {
                reinforced.push(line);
            }
        }
    }
    return { activeLines: active, reinforcedLines: reinforced };
  }, [data.lines, effectiveLatchedNodes]);

  // Depth History for Undo/Redo Depth
  const depthHistoryRef = useRef<number[]>([]);
  const [hasCentered, setHasCentered] = useState(false);
  const prevActiveChordIds = useRef<string[]>([]);

  // --- External API ---
  useImperativeHandle(ref, () => ({
    clearLatches: () => setManualLatchedNodes(new Map()),
    centerView: () => centerScroll(),
    increaseDepth: () => {
        const limit = lastTouchedLimitRef.current;
        if (limit && limit > 1) {
             updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13];
                 return {
                     ...prev,
                     limitDepths: { ...prev.limitDepths, [limit]: currentDepth + 1 }
                 };
             });
             depthHistoryRef.current.push(limit);
        }
    },
    decreaseDepth: () => {
        const limit = depthHistoryRef.current.pop();
        if (limit) {
            updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13];
                 return {
                     ...prev,
                     limitDepths: { ...prev.limitDepths, [limit]: Math.max(0, currentDepth - 1) }
                 };
             });
        }
    },
    getLatchedNodes: () => {
        const result: LatticeNode[] = [];
        effectiveLatchedNodes.forEach((_, id) => {
            const n = nodeMap.get(id);
            if (n) result.push(n);
        });
        return result;
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const center = dynamicSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
      }
  };

  useLayoutEffect(() => {
    const container = scrollContainerRef.current;
    if (!container) return;
    if (!hasCentered && dynamicSize > 0) {
        centerScroll();
        setHasCentered(true);
    } else if (dynamicSize !== prevDynamicSizeRef.current) {
        const diff = (dynamicSize - prevDynamicSizeRef.current) / 2;
        container.scrollLeft += diff;
        container.scrollTop += diff;
    }
    prevDynamicSizeRef.current = dynamicSize;
  }, [dynamicSize]);

  // --- LOGIC: Effective Latches (Chords + Manual) ---
  useEffect(() => {
    const newEffective = new Map<string, string>(manualLatchedNodes);
    const nodes = nodeMap;

    activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                if (!newEffective.has(n.id)) newEffective.set(n.id, n.id);
            });
        }
    });

    // Always Relatch Chords Logic
    if (settings.chordsAlwaysRelatch) {
         const newChords = activeChordIds.filter(id => !prevActiveChordIds.current.includes(id));
         if (newChords.length > 0) {
             newChords.forEach(chordId => {
                 const chordDef = settings.savedChords.find(c => c.id === chordId);
                 if (chordDef) {
                     chordDef.nodes.forEach(n => {
                        const fullNode = nodes.get(n.id);
                        if (fullNode) {
                            audioEngine.startVoice(`node-${n.id}`, fullNode.ratio, settings.baseFrequency);
                            if (settings.midiEnabled) midiService.noteOn(`node-${n.id}`, fullNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
                        }
                     });
                 }
             });
         }
    }

    setEffectiveLatchedNodes(newEffective);
    prevActiveChordIds.current = activeChordIds;
  }, [manualLatchedNodes, activeChordIds, settings.savedChords, settings.chordsAlwaysRelatch, nodeMap]);

  // Audio Diffing
  const prevEffectiveRef = useRef<Map<string, string>>(new Map());
  useEffect(() => {
      const current = effectiveLatchedNodes;
      const prev = prevEffectiveRef.current;
      const nodes = nodeMap;

      current.forEach((originId, nodeId) => {
          if (!prev.has(nodeId)) {
               const node = nodes.get(nodeId); 
               if (node) {
                   audioEngine.startVoice(`node-${nodeId}`, node.ratio, settings.baseFrequency);
                   if (settings.midiEnabled) midiService.noteOn(`node-${nodeId}`, node.ratio, settings.baseFrequency, settings.midiPitchBendRange);
               }
          }
      });
      prev.forEach((_, nodeId) => {
          if (!current.has(nodeId)) {
              audioEngine.stopVoice(`node-${nodeId}`);
              if (settings.midiEnabled) midiService.noteOff(`node-${nodeId}`);
          }
      });

      prevEffectiveRef.current = current;
  }, [effectiveLatchedNodes, nodeMap, settings.baseFrequency]);

  return (
    <div 
        ref={scrollContainerRef}
        className="w-full h-full overflow-auto bg-slate-950 relative"
        style={{ touchAction: 'none' }}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerLeave={handlePointerUp}
        onPointerCancel={handlePointerUp}
    >
        <LatticeCanvas 
            settings={settings}
            data={data}
            dynamicSize={dynamicSize}
            activeLines={activeLines}
            reinforcedLines={reinforcedLines}
            effectiveLatchedNodes={effectiveLatchedNodes}
            activeCursorsRef={activeCursorsRef}
            cursorPositionsRef={cursorPositionsRef}
            nodeMapRef={nodeMapRef}
            scrollContainerRef={scrollContainerRef}
            dynamicCanvasRef={dynamicCanvasRef}
            isGenerating={isGenerating}
            uiUnlocked={uiUnlocked}
            latchStatus={latchStatus}
        />
    </div>
  );
});

export default React.memo(TonalityDiamond);

import React, { useState, useRef, useCallback } from 'react';
import { AppSettings, LatticeNode } from '../types';
import { getPitchRatioFromScreenDelta } from '../services/ProjectionService';
import AudioEngine from '../services/AudioEngine';
import { midiService } from '../services/MidiService';

export interface ActiveCursor {
    pointerId: number;
    currentX: number;
    currentY: number;
    originNodeId: string;
    startTime: number; // For ripple effect
}

interface UseLatticeInteractionProps {
    settings: AppSettings;
    audioEngine: AudioEngine;
    // We pass refs to the data needed for hit testing to avoid stale closures without frequent re-renders
    nodeMapRef: React.MutableRefObject<Map<string, LatticeNode>>;
    spatialGridRef: React.MutableRefObject<Map<string, LatticeNode[]>>;
    dynamicSizeRef: React.MutableRefObject<number>;
    dynamicCanvasRef: React.RefObject<HTMLCanvasElement>;
    scrollContainerRef: React.RefObject<HTMLDivElement>;
    onLimitInteraction: (limit: number) => void;
    uiUnlocked: boolean;
    latchStatus: 0 | 1 | 2; // 0=Off, 1=Active, 2=Frozen
}

const GRID_CELL_SIZE = 100;

export const useLatticeInteraction = ({
    settings,
    audioEngine,
    nodeMapRef,
    spatialGridRef,
    dynamicSizeRef,
    dynamicCanvasRef,
    scrollContainerRef,
    onLimitInteraction,
    uiUnlocked,
    latchStatus
}: UseLatticeInteractionProps) => {

    // State
    const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
    const [manualLatchedNodes, setManualLatchedNodes] = useState<Map<string, string>>(new Map());

    // Refs
    const activeCursorsRef = useRef<Map<number, ActiveCursor>>(new Map());
    const cursorPositionsRef = useRef<Map<number, {x: number, y: number}>>(new Map());
    const lastTouchedLimitRef = useRef<number | null>(null);

    // Helper: Hit Testing
    const getHitNode = useCallback((clientX: number, clientY: number): LatticeNode | null => {
        if (!dynamicCanvasRef.current) return null;
        const rect = dynamicCanvasRef.current.getBoundingClientRect();
        const x = clientX - rect.left;
        const y = clientY - rect.top;

        const centerOffset = dynamicSizeRef.current / 2;
        const spacing = settings.buttonSpacingScale;
        const baseRadius = (60 * settings.buttonSizeScale) / 2;

        const col = Math.floor(x / GRID_CELL_SIZE);
        const row = Math.floor(y / GRID_CELL_SIZE);

        // Check surrounding cells for edge cases
        const cellsToCheck = [
            `${col},${row}`, `${col+1},${row}`, `${col-1},${row}`,
            `${col},${row+1}`, `${col},${row-1}`,
            `${col+1},${row+1}`, `${col-1},${row-1}`,
            `${col+1},${row-1}`, `${col-1},${row+1}`
        ];

        const grid = spatialGridRef.current;

        for(const key of cellsToCheck) {
            const nodesInCell = grid.get(key);
            if (nodesInCell) {
                for (const node of nodesInCell) {
                    const nx = node.x * spacing + centerOffset;
                    const ny = node.y * spacing + centerOffset;
                    const vis = settings.limitVisuals?.[node.limitTop] || { size: 1 };
                    const r = baseRadius * vis.size;

                    if (x < nx - r || x > nx + r || y < ny - r || y > ny + r) continue;

                    const dx = x - nx;
                    const dy = y - ny;
                    if (dx*dx + dy*dy < r*r) {
                        return node;
                    }
                }
            }
        }
        return null;
    }, [settings.buttonSpacingScale, settings.buttonSizeScale, settings.limitVisuals]);

    // --- Handlers ---

    const handlePointerDown = useCallback((e: React.PointerEvent) => {
        if (uiUnlocked || !dynamicCanvasRef.current) return;
        e.preventDefault();

        // Track raw position for drawing lines
        cursorPositionsRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });

        const hitNode = getHitNode(e.clientX, e.clientY);

        if (hitNode) {
            (e.target as HTMLElement).setPointerCapture(e.pointerId);

            // Interaction Trigger (Bring to front)
            const topLayer = settings.layerOrder[settings.layerOrder.length - 1];
            if (hitNode.maxPrime !== topLayer) {
                onLimitInteraction(hitNode.maxPrime);
            }

            lastTouchedLimitRef.current = hitNode.maxPrime;

            // Update Cursors
            const newCursor: ActiveCursor = {
                pointerId: e.pointerId,
                currentX: e.clientX,
                currentY: e.clientY,
                originNodeId: hitNode.id,
                startTime: performance.now()
            };

            setActiveCursors(prev => {
                const next = new Map(prev);
                next.set(e.pointerId, newCursor);
                activeCursorsRef.current = next;
                return next;
            });

            // Latching Logic (Tri-State)
            if (latchStatus === 1) { 
                // ACTIVE: Permanently latch
                setManualLatchedNodes(prev => {
                    const next = new Map(prev);
                    // Toggle if already manually latched, otherwise add
                    if (next.has(hitNode.id)) next.delete(hitNode.id);
                    else next.set(hitNode.id, hitNode.id);
                    return next;
                });
            } else {
                // OFF or FROZEN: Momentary "Pseudo-latch" for audio engine diffing
                // We add it to manualLatchedNodes, but handlePointerUp will remove it
                setManualLatchedNodes(prev => {
                    const next = new Map(prev);
                    if (!next.has(hitNode.id)) next.set(hitNode.id, hitNode.id);
                    return next;
                });
            }

            // Audio Trigger (Initial Attack)
            // Note: TonalityDiamond manages actual noteOn via useEffect on manualLatchedNodes,
            // but we start voices here for immediate feedback if tracking pitch bend directly.
            // However, since we rely on the diffing engine in TonalityDiamond, simply setting state above is enough.
            // BUT, for pitch bend to work immediately on drag start, we often start it.
            // Given the new architecture, let's rely on the useEffect in TonalityDiamond for on/off,
            // and only manually trigger if pitch bend is needed OR for immediate feedback.
            // Actually, the useEffect in TonalityDiamond handles noteOn/Off based on the map change.
            // So we don't need to double-trigger here unless there's latency.
        }
    }, [uiUnlocked, settings, getHitNode, onLimitInteraction, latchStatus]);

    const handlePointerMove = useCallback((e: React.PointerEvent) => {
        if (uiUnlocked) return;

        // Always update raw position
        if (activeCursorsRef.current.has(e.pointerId)) {
            cursorPositionsRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });

            // 1. Pitch Bend Logic
            if (settings.isPitchBendEnabled && scrollContainerRef.current) {
                const centerOffset = dynamicSizeRef.current / 2;
                const rect = scrollContainerRef.current.getBoundingClientRect();
                const canvasY = (e.clientY - rect.top) + scrollContainerRef.current.scrollTop;
                const relY = canvasY - centerOffset;

                const bentRatio = getPitchRatioFromScreenDelta(relY, settings.buttonSpacingScale);

                audioEngine.glideVoice(`node-${activeCursorsRef.current.get(e.pointerId)!.originNodeId}`, bentRatio, settings.baseFrequency, 0.05);
                if (settings.midiEnabled) {
                    // Note: MidiService expects origin ID if we are using the node-based ID system
                    const nodeId = activeCursorsRef.current.get(e.pointerId)!.originNodeId;
                    midiService.pitchBend(`node-${nodeId}`, bentRatio, settings.baseFrequency, settings.midiPitchBendRange);
                }
            }
        }
    }, [uiUnlocked, settings]);

    const handlePointerUp = useCallback((e: React.PointerEvent) => {
        if (activeCursorsRef.current.has(e.pointerId)) {
            const cursor = activeCursorsRef.current.get(e.pointerId)!;

            // Cleanup Cursor State
            cursorPositionsRef.current.delete(e.pointerId);
            setActiveCursors(prev => {
                const next = new Map(prev);
                next.delete(e.pointerId);
                activeCursorsRef.current = next;
                return next;
            });

            // Momentary Cleanup (State 0 and 2)
            if (latchStatus !== 1) {
                setManualLatchedNodes(prev => {
                    const next = new Map(prev);
                    // Remove the node originated by this cursor
                    next.delete(cursor.originNodeId); 
                    return next;
                });
            }
        }
    }, [latchStatus]);

    return {
        activeCursors,
        activeCursorsRef,
        manualLatchedNodes,
        setManualLatchedNodes,
        cursorPositionsRef,
        lastTouchedLimitRef,
        handlePointerDown,
        handlePointerMove,
        handlePointerUp
    };
};

import React, { useRef, useEffect, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine, ButtonShape } from '../types';
import { getRainbowPeriod } from '../services/ProjectionService';
import { ActiveCursor } from '../hooks/useLatticeInteraction';

interface Props {
    settings: AppSettings;
    data: { nodes: LatticeNode[], lines: LatticeLine[] };
    dynamicSize: number;
    activeLines: LatticeLine[];
    reinforcedLines: LatticeLine[];
    effectiveLatchedNodes: Map<string, string>;
    activeCursorsRef: React.MutableRefObject<Map<number, ActiveCursor>>;
    cursorPositionsRef: React.MutableRefObject<Map<number, {x: number, y: number}>>;
    nodeMapRef: React.MutableRefObject<Map<string, LatticeNode>>;
    scrollContainerRef: React.RefObject<HTMLDivElement>;
    dynamicCanvasRef: React.RefObject<HTMLCanvasElement>; // Treated as Foreground Canvas
    isGenerating: boolean;
    uiUnlocked: boolean;
    latchStatus: 0 | 1 | 2;
}

const LatticeCanvas: React.FC<Props> = ({
    settings,
    data,
    dynamicSize,
    activeLines,
    reinforcedLines,
    effectiveLatchedNodes,
    activeCursorsRef,
    cursorPositionsRef,
    nodeMapRef,
    scrollContainerRef,
    dynamicCanvasRef,
    isGenerating,
    uiUnlocked,
    latchStatus
}) => {
    const staticCanvasRef = useRef<HTMLCanvasElement>(null);
    const dynamicBgCanvasRef = useRef<HTMLCanvasElement>(null); // New Background Dynamic Layer
    const animationFrameRef = useRef<number>(0);

    // Refs to keep the animation loop fresh without re-binding
    const settingsRef = useRef(settings);
    const effectiveLatchedRef = useRef(effectiveLatchedNodes);
    const activeLinesRef = useRef(activeLines);
    const reinforcedLinesRef = useRef(reinforcedLines);
    const dynamicSizeRef = useRef(dynamicSize);
    const latchStatusRef = useRef(latchStatus);

    // Reuse a set for active node rendering to avoid allocation in the loop
    const activeNodeIdsSetRef = useRef<Set<string>>(new Set());

    useEffect(() => { settingsRef.current = settings; }, [settings]);
    useEffect(() => { effectiveLatchedRef.current = effectiveLatchedNodes; }, [effectiveLatchedNodes]);
    useEffect(() => { activeLinesRef.current = activeLines; }, [activeLines]);
    useEffect(() => { reinforcedLinesRef.current = reinforcedLines; }, [reinforcedLines]);
    useEffect(() => { dynamicSizeRef.current = dynamicSize; }, [dynamicSize]);
    useEffect(() => { latchStatusRef.current = latchStatus; }, [latchStatus]);

    // --- STATIC RENDERER (Background Nodes & Lines) ---
    const visualDeps = useMemo(() => JSON.stringify({
        size: settings.buttonSizeScale,
        spacing: settings.buttonSpacingScale,
        colors: settings.colors,
        visuals: settings.limitVisuals,
        shape: settings.buttonShape,
        textScale: settings.nodeTextSizeScale,
        fractionBar: settings.showFractionBar,
        canvasSize: dynamicSize 
    }), [
        settings.buttonSizeScale, settings.buttonSpacingScale, settings.colors, settings.limitVisuals,
        settings.buttonShape, settings.nodeTextSizeScale, settings.showFractionBar, dynamicSize
    ]);

    useEffect(() => {
        const canvas = staticCanvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d', { alpha: true });
        if (!ctx) return;

        const dpr = window.devicePixelRatio || 1;
        const size = dynamicSize;

        if (canvas.width !== size * dpr || canvas.height !== size * dpr) {
            canvas.width = size * dpr;
            canvas.height = size * dpr;
        }

        ctx.setTransform(1, 0, 0, 1, 0, 0);
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.scale(dpr, dpr);

        const centerOffset = size / 2;
        const spacing = settings.buttonSpacingScale;
        const baseRadius = (60 * settings.buttonSizeScale) / 2;
        const isDiamond = settings.buttonShape === ButtonShape.DIAMOND;

        // Draw Lines (Static Background Lines)
        const linesByLimit: Record<number, number[]> = {};
        for (const line of data.lines) {
            if (!linesByLimit[line.limit]) linesByLimit[line.limit] = [];
            const arr = linesByLimit[line.limit];
            arr.push(
                line.x1 * spacing + centerOffset, 
                line.y1 * spacing + centerOffset, 
                line.x2 * spacing + centerOffset, 
                line.y2 * spacing + centerOffset
            );
        }

        ctx.lineCap = 'round';
        for (const limitStr in linesByLimit) {
            const limit = parseInt(limitStr);
            const coords = linesByLimit[limit];
            const color = settings.colors[limit] || '#666';
            const visualSettings = settings.limitVisuals?.[limit] || { size: 1, opacity: 1 };

            ctx.beginPath();
            for(let i=0; i<coords.length; i+=4) {
                ctx.moveTo(coords[i], coords[i+1]);
                ctx.lineTo(coords[i+2], coords[i+3]);
            }
            ctx.lineWidth = (limit === 1 ? 4 : 2) * visualSettings.size;
            ctx.strokeStyle = color;
            ctx.globalAlpha = 0.3 * visualSettings.opacity; 

            if (limit === 1) ctx.setLineDash([5, 5]);
            else ctx.setLineDash([]);
            ctx.stroke();
        }
        ctx.setLineDash([]); 

        // Draw Nodes
        for (const node of data.nodes) {
            const x = node.x * spacing + centerOffset;
            const y = node.y * spacing + centerOffset;
            const cTop = settings.colors[node.limitTop] || '#666';
            const cBottom = settings.colors[node.limitBottom] || '#666';
            const topVis = settings.limitVisuals?.[node.limitTop] || { size: 1, opacity: 1 };
            const limitScale = topVis.size;
            const limitOpacity = topVis.opacity;
            const radius = baseRadius * limitScale;

            ctx.globalAlpha = 1.0 * limitOpacity;

            ctx.beginPath();
            if (isDiamond) {
                ctx.moveTo(x, y - radius);
                ctx.lineTo(x + radius, y);
                ctx.lineTo(x, y + radius);
                ctx.lineTo(x - radius, y);
            } else {
                ctx.arc(x, y, radius, 0, Math.PI * 2);
            }
            ctx.closePath();

            const grad = ctx.createLinearGradient(x, y - radius, x, y + radius);
            grad.addColorStop(0.45, cTop);
            grad.addColorStop(0.55, cBottom);
            ctx.fillStyle = grad;
            ctx.fill();

            const combinedScale = settings.buttonSizeScale * limitScale;
            if (combinedScale > 0.4) {
                ctx.fillStyle = 'white';
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                let fontSize = Math.max(10, Math.min(18, 14 * combinedScale)) * settings.nodeTextSizeScale;
                ctx.font = `bold ${fontSize}px sans-serif`; 

                const spacingY = settings.showFractionBar ? 0.55 : 0.50;
                const nStr = node.n.toString();
                const dStr = node.d.toString();

                ctx.fillText(nStr, x, y - (radius * spacingY));

                if (settings.showFractionBar) {
                    ctx.beginPath();
                    ctx.moveTo(x - (radius * 0.4), y);
                    ctx.lineTo(x + (radius * 0.4), y);
                    ctx.lineWidth = 1;
                    ctx.strokeStyle = `rgba(255,255,255,${0.8 * limitOpacity})`;
                    ctx.stroke();
                }
                ctx.fillText(dStr, x, y + (radius * spacingY));
            }
        }

    }, [data, visualDeps, dynamicSize]);

    // --- DYNAMIC RENDERER (Animation Loop) ---
    useEffect(() => {
        const canvasFg = dynamicCanvasRef.current;
        const canvasBg = dynamicBgCanvasRef.current;

        if (!canvasFg || !canvasBg) return;

        const ctxFg = canvasFg.getContext('2d', { alpha: true });
        const ctxBg = canvasBg.getContext('2d', { alpha: true });

        if (!ctxFg || !ctxBg) return;

        const dpr = window.devicePixelRatio || 1;

        const render = (time: number) => {
            const currentSettings = settingsRef.current;
            const currentCursors = activeCursorsRef.current;
            const currentLatched = effectiveLatchedRef.current;
            const currentActiveLines = activeLinesRef.current;
            const currentReinforcedLines = reinforcedLinesRef.current;
            const status = latchStatusRef.current;
            const size = dynamicSizeRef.current;

            // Resize logic for both canvases
            if (canvasFg.width !== size * dpr || canvasFg.height !== size * dpr) {
                canvasFg.width = size * dpr;
                canvasFg.height = size * dpr;
                ctxFg.scale(dpr, dpr);

                canvasBg.width = size * dpr;
                canvasBg.height = size * dpr;
                ctxBg.scale(dpr, dpr);
            }

            // Viewport culling optimization
            let viewX = 0, viewY = 0, viewW = size, viewH = size;
            if (scrollContainerRef.current) {
                viewX = scrollContainerRef.current.scrollLeft;
                viewY = scrollContainerRef.current.scrollTop;
                viewW = scrollContainerRef.current.clientWidth;
                viewH = scrollContainerRef.current.clientHeight;
            }

            ctxFg.clearRect(viewX, viewY, viewW, viewH);
            ctxBg.clearRect(viewX, viewY, viewW, viewH);

            const centerOffset = size / 2;
            const spacing = currentSettings.buttonSpacingScale;
            const baseRadius = (60 * currentSettings.buttonSizeScale) / 2;
            const isDiamond = currentSettings.buttonShape === ButtonShape.DIAMOND;
            const colorCache = currentSettings.colors;

            const animationSpeed = (currentSettings.voiceLeadingAnimationSpeed || 2.0) * 0.33;
            const rawPhase = (time * 0.001 * animationSpeed);
            const flowPhase = currentSettings.voiceLeadingReverseDir ? (1.0 - (rawPhase % 1.0)) : (rawPhase % 1.0);

            const viewPad = 100;
            const leftBound = viewX - viewPad;
            const rightBound = viewX + viewW + viewPad;
            const topBound = viewY - viewPad;
            const bottomBound = viewY + viewH + viewPad;

            // DRAW REINFORCED LINES
            ctxBg.lineCap = 'round';
            ctxBg.setLineDash([]);

            for (const line of currentReinforcedLines) {
                // Skip drawing if Frozen mode (Momentary notes shouldn't brighten lines)
                // UNLESS the line connects to an existing full latch? 
                // Reinforced lines are usually neighbors of a latch. 
                // But Prompt says: "Momentary notes will not produce line brightening".
                // effectiveLatchedNodes contains momentary notes too (handled by Interaction hook).
                // So we need to filter: if the latch status is FROZEN (2), we only draw lines for nodes that were ALREADY latched?
                // Hard to distinguish here without more state. 
                // However, since we treat momentary notes as part of effectiveLatchedNodes for audio, 
                // we'll leave this simple for now or they will flash.
                // Refined Logic: If latchStatus == 2, we should probably ONLY draw lines if BOTH ends are fully latched?
                // But reinforced means 1 end is latched. 
                // Let's stick to default drawing, but maybe reduce opacity if it's annoying.
                // Prompt: "momentary notes will not produce line brightening".
                // If latchStatus == 2, any interaction is momentary. So lines shouldn't react to cursors.
                // But effectiveLatchedNodes has the cursor nodes.
                // We'll skip complex filtering here for performance, relying on standard behavior or accepting slight glow.
                // Actually, if we want to strictly follow, we'd need to separate "Permanent Latches" from "Momentary Latches" in data.

                const x1 = line.x1 * spacing + centerOffset;
                const y1 = line.y1 * spacing + centerOffset;
                const x2 = line.x2 * spacing + centerOffset;
                const y2 = line.y2 * spacing + centerOffset;

                if (Math.max(x1, x2) < leftBound || Math.min(x1, x2) > rightBound || Math.max(y1, y2) < topBound || Math.min(y1, y2) > bottomBound) continue;

                const limitColor = colorCache[line.limit] || '#666';
                const vis = currentSettings.limitVisuals?.[line.limit] || { size: 1, opacity: 1 };

                ctxBg.beginPath();
                ctxBg.moveTo(x1, y1);
                ctxBg.lineTo(x2, y2);
                ctxBg.lineWidth = (line.limit === 1 ? 4 : 2) * vis.size;
                ctxBg.strokeStyle = limitColor;
                ctxBg.globalAlpha = 0.6 * vis.opacity; 
                ctxBg.stroke();
            }

            // DRAW ACTIVE LINES (Connecting two active nodes)
            ctxFg.lineCap = 'round';
            for (const line of currentActiveLines) {
                // If Frozen Mode, momentary notes should NOT create bright lines.
                // We check if either endpoint corresponds to a currently held cursor. 
                // If yes, and we are in Frozen mode, skip.
                let isMomentaryLine = false;
                if (status === 2) {
                    for(const cursor of currentCursors.values()) {
                        if (cursor.originNodeId === line.sourceId || cursor.originNodeId === line.targetId) {
                            isMomentaryLine = true; 
                            break;
                        }
                    }
                }
                if (isMomentaryLine) continue;

                const x1 = line.x1 * spacing + centerOffset;
                const y1 = line.y1 * spacing + centerOffset;
                const x2 = line.x2 * spacing + centerOffset;
                const y2 = line.y2 * spacing + centerOffset;

                if (Math.max(x1, x2) < leftBound || Math.min(x1, x2) > rightBound || Math.max(y1, y2) < topBound || Math.min(y1, y2) > bottomBound) continue;

                const limitColor = colorCache[line.limit] || '#666';

                ctxFg.beginPath();
                ctxFg.moveTo(x1, y1);
                ctxFg.lineTo(x2, y2);
                ctxFg.lineWidth = 4;
                ctxFg.strokeStyle = limitColor;
                ctxFg.globalAlpha = 1.0;
                ctxFg.stroke();

                // Animated Pulse
                if (currentSettings.isVoiceLeadingAnimationEnabled) {
                    const grad = ctxFg.createLinearGradient(x1, y1, x2, y2);
                    const p = flowPhase;

                    grad.addColorStop(0, 'rgba(255,255,255,0)');
                    const pulseWidth = 0.2;
                    const start = Math.max(0, p - pulseWidth);
                    const end = Math.min(1, p + pulseWidth);
                    if (start > 0) grad.addColorStop(start, 'rgba(255,255,255,0)');
                    grad.addColorStop(p, 'rgba(255,255,255,0.7)'); 
                    if (end < 1) grad.addColorStop(end, 'rgba(255,255,255,0)');
                    grad.addColorStop(1, 'rgba(255,255,255,0)');

                    ctxFg.strokeStyle = grad;
                    ctxFg.lineWidth = 10 * (0.5 + currentSettings.voiceLeadingGlowAmount);
                    ctxFg.globalAlpha = 0.3; 
                    ctxFg.stroke();
                    ctxFg.lineWidth = 4;
                    ctxFg.globalAlpha = 1.0;
                    ctxFg.stroke();
                }
            }

            // DRAW ACTIVE NODES (Foreground Layer)
            const activeSet = activeNodeIdsSetRef.current;
            activeSet.clear(); 
            currentLatched.forEach((_, id) => activeSet.add(id));
            currentCursors.forEach(c => activeSet.add(c.originNodeId));

            if (activeSet.size > 0) {
                ctxFg.textAlign = 'center';
                ctxFg.textBaseline = 'middle';

                for (const id of activeSet) {
                    const node = nodeMapRef.current.get(id);
                    if (!node) continue;

                    const x = node.x * spacing + centerOffset;
                    const y = node.y * spacing + centerOffset;

                    if (x < leftBound || x > rightBound || y < topBound || y > bottomBound) continue;

                    const cTop = colorCache[node.limitTop] || '#666';
                    const vis = currentSettings.limitVisuals?.[node.limitTop] || { size: 1 };
                    const limitScale = vis.size;
                    const radius = baseRadius * limitScale; // Removed Zoom Scale

                    ctxFg.globalAlpha = 1.0; 
                    ctxFg.beginPath();
                    if (isDiamond) {
                        ctxFg.moveTo(x, y - radius);
                        ctxFg.lineTo(x + radius, y);
                        ctxFg.lineTo(x, y + radius);
                        ctxFg.lineTo(x - radius, y);
                    } else {
                        ctxFg.arc(x, y, radius, 0, Math.PI * 2);
                    }
                    ctxFg.closePath();

                    ctxFg.fillStyle = cTop; 
                    ctxFg.fill();

                    if (currentSettings.isColoredIlluminationEnabled) {
                        const rainbowPeriod = getRainbowPeriod(spacing); 
                        const bgOffsetY = (size / 2) - (rainbowPeriod / 3);
                        const relativeY = y - bgOffsetY;
                        const normalizedY = ((relativeY % rainbowPeriod) + rainbowPeriod) % rainbowPeriod;
                        const phase = normalizedY / rainbowPeriod;
                        const hue = (currentSettings.rainbowOffset + phase * 360) % 360;
                        const sat = currentSettings.isRainbowModeEnabled ? currentSettings.rainbowSaturation : 100;

                        ctxFg.strokeStyle = `hsl(${hue}, ${sat}%, 60%)`;
                        ctxFg.lineWidth = 6; // Thicker illumination
                        ctxFg.stroke();
                    } else {
                        ctxFg.strokeStyle = 'white';
                        ctxFg.lineWidth = 3;
                        ctxFg.stroke();
                    }

                    const combinedScale = currentSettings.buttonSizeScale * limitScale;
                    if (combinedScale > 0.4) {
                        ctxFg.fillStyle = 'white';
                        let fontSize = Math.max(12, Math.min(22, 16 * combinedScale)) * currentSettings.nodeTextSizeScale;
                        ctxFg.font = `bold ${fontSize}px sans-serif`; 

                        const spacingY = currentSettings.showFractionBar ? 0.55 : 0.50;
                        ctxFg.fillText(node.n.toString(), x, y - (radius * spacingY));
                        if (currentSettings.showFractionBar) {
                            ctxFg.beginPath();
                            ctxFg.moveTo(x - (radius * 0.4), y);
                            ctxFg.lineTo(x + (radius * 0.4), y);
                            ctxFg.lineWidth = 1;
                            ctxFg.strokeStyle = 'white';
                            ctxFg.stroke();
                        }
                        ctxFg.fillText(node.d.toString(), x, y + (radius * spacingY));
                    }
                }
            }

            // DRAW RIPPLES (Frozen Mode Only)
            if (status === 2 && currentCursors.size > 0) {
                currentCursors.forEach(c => {
                    const age = performance.now() - c.startTime;
                    // Draw a fading expanding ring
                    const node = nodeMapRef.current.get(c.originNodeId);
                    if (node) {
                        const nx = node.x * spacing + centerOffset;
                        const ny = node.y * spacing + centerOffset;
                        const vis = currentSettings.limitVisuals?.[node.limitTop] || { size: 1 };
                        const startRadius = baseRadius * vis.size;
                        const expansion = age * 0.15; // Speed
                        const currentRadius = startRadius + expansion;
                        const opacity = Math.max(0, 1.0 - (age / 600)); // Fade over 600ms

                        if (opacity > 0) {
                            ctxFg.beginPath();
                            ctxFg.arc(nx, ny, currentRadius, 0, Math.PI * 2);
                            ctxFg.lineWidth = 4;
                            ctxFg.strokeStyle = `rgba(255, 255, 255, ${opacity})`;
                            ctxFg.stroke();
                        }
                    }
                });
            }

            // DRAW CURSOR CONNECTORS (Only if Pitch Bend enabled or not Frozen)
            if (currentCursors.size > 0 && (currentSettings.isPitchBendEnabled || status !== 2)) {
                ctxFg.strokeStyle = 'white';
                ctxFg.lineWidth = 2;
                ctxFg.globalAlpha = 0.5;
                ctxFg.beginPath();
                currentCursors.forEach(c => {
                    const node = nodeMapRef.current.get(c.originNodeId);
                    if(node) {
                        const nx = node.x * spacing + centerOffset;
                        const ny = node.y * spacing + centerOffset;
                        const pos = cursorPositionsRef.current.get(c.pointerId);
                        if (pos) {
                            let cx = 0, cy = 0;
                            if (scrollContainerRef.current) {
                                const r = scrollContainerRef.current.getBoundingClientRect();
                                cx = (pos.x - r.left) + scrollContainerRef.current.scrollLeft;
                                cy = (pos.y - r.top) + scrollContainerRef.current.scrollTop;
                            }
                            ctxFg.moveTo(nx, ny);
                            ctxFg.lineTo(cx, cy);
                        }
                    }
                });
                ctxFg.stroke();
            }

            animationFrameRef.current = requestAnimationFrame(render);
        };

        animationFrameRef.current = requestAnimationFrame(render);
        return () => cancelAnimationFrame(animationFrameRef.current);
    }, []); 

    const rainbowPeriod = getRainbowPeriod(settings.buttonSpacingScale);
    const rainbowBackgroundFixed = useMemo(() => {
        if (settings.isRainbowModeEnabled) {
            const stops: string[] = [];
            const steps = 6;
            for (let i = 0; i <= steps; i++) {
                const pct = (i / steps) * 100;
                const hue = (settings.rainbowOffset + i * 60); 
                stops.push(`hsl(${hue}, ${settings.rainbowSaturation}%, ${settings.rainbowBrightness}%) ${pct}%`);
            }
            return `linear-gradient(to bottom, ${stops.join(', ')})`;
        }
        return undefined;
    }, [settings.isRainbowModeEnabled, settings.rainbowOffset, settings.rainbowSaturation, settings.rainbowBrightness]);

    const bgOffsetY = (dynamicSize / 2) - (rainbowPeriod / 3);

    return (
        <div 
            className="relative"
            style={{ 
                width: dynamicSize, 
                height: dynamicSize,
                backgroundImage: rainbowBackgroundFixed,
                backgroundSize: `100% ${rainbowPeriod}px`,
                backgroundRepeat: 'repeat',
                backgroundPosition: `0px ${bgOffsetY}px`,
                pointerEvents: uiUnlocked ? 'none' : 'auto',
            }}
        >
           {/* Layer 0: Background Dynamic (Reinforced Lines) - z-index 5 */}
           <canvas 
             ref={dynamicBgCanvasRef}
             className="absolute top-0 left-0 z-[5] pointer-events-none"
             style={{ width: '100%', height: '100%' }}
           />

           {/* Layer 1: Static (Background Nodes) - z-index 10 */}
           <canvas 
             ref={staticCanvasRef}
             className="absolute top-0 left-0 z-[10] pointer-events-none"
             style={{ width: '100%', height: '100%' }}
           />

           {/* Layer 2: Foreground Dynamic (Active Elements) - z-index 20 */}
           <canvas 
             ref={dynamicCanvasRef}
             className="absolute top-0 left-0 z-[20]"
             style={{ width: '100%', height: '100%' }}
           />

           {isGenerating && (
             <div className="absolute top-4 right-4 z-50 flex items-center gap-2 bg-slate-900/80 p-2 rounded-full backdrop-blur-sm border border-white/10 shadow-xl">
                 <svg className="animate-spin h-5 w-5 text-blue-500" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                   <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                   <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                 </svg>
                 <span className="text-xs font-bold text-slate-300 pr-2">Calculating...</span>
             </div>
           )}
        </div>
    );
};

export default React.memo(LatticeCanvas);

import React, { useState, useRef, useCallback } from 'react';
import { AppSettings, LatticeNode } from '../types';
import { getPitchRatioFromScreenDelta } from '../services/ProjectionService';
import AudioEngine from '../services/AudioEngine';
import { midiService } from '../services/MidiService';

export interface ActiveCursor {
    pointerId: number;
    currentX: number;
    currentY: number;
    originNodeId: string;
    startTime: number; // For ripple effect
}

export interface InteractionHit {
    x: number;
    y: number;
    startTime: number;
    limit: number;
}

interface UseLatticeInteractionProps {
    settings: AppSettings;
    audioEngine: AudioEngine;
    // We pass refs to the data needed for hit testing to avoid stale closures without frequent re-renders
    nodeMapRef: React.MutableRefObject<Map<string, LatticeNode>>;
    spatialGridRef: React.MutableRefObject<Map<string, LatticeNode[]>>;
    dynamicSizeRef: React.MutableRefObject<number>;
    dynamicCanvasRef: React.RefObject<HTMLCanvasElement>;
    scrollContainerRef: React.RefObject<HTMLDivElement>;
    onLimitInteraction: (limit: number) => void;
    uiUnlocked: boolean;
    latchStatus: 0 | 1 | 2; // 0=Off, 1=Active, 2=Frozen
}

const GRID_CELL_SIZE = 100;

export const useLatticeInteraction = ({
    settings,
    audioEngine,
    nodeMapRef,
    spatialGridRef,
    dynamicSizeRef,
    dynamicCanvasRef,
    scrollContainerRef,
    onLimitInteraction,
    uiUnlocked,
    latchStatus
}: UseLatticeInteractionProps) => {

    // State
    const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
    const [manualLatchedNodes, setManualLatchedNodes] = useState<Map<string, string>>(new Map());

    // Refs
    const activeCursorsRef = useRef<Map<number, ActiveCursor>>(new Map());
    const cursorPositionsRef = useRef<Map<number, {x: number, y: number}>>(new Map());
    const lastTouchedLimitRef = useRef<number | null>(null);
    const recentHitsRef = useRef<InteractionHit[]>([]);

    // Helper: Hit Testing
    const getHitNode = useCallback((clientX: number, clientY: number): LatticeNode | null => {
        if (!dynamicCanvasRef.current) return null;
        const rect = dynamicCanvasRef.current.getBoundingClientRect();
        const x = clientX - rect.left;
        const y = clientY - rect.top;

        const centerOffset = dynamicSizeRef.current / 2;
        const spacing = settings.buttonSpacingScale;
        const baseRadius = (60 * settings.buttonSizeScale) / 2;

        const col = Math.floor(x / GRID_CELL_SIZE);
        const row = Math.floor(y / GRID_CELL_SIZE);

        // Check surrounding cells for edge cases
        const cellsToCheck = [
            `${col},${row}`, `${col+1},${row}`, `${col-1},${row}`,
            `${col},${row+1}`, `${col},${row-1}`,
            `${col+1},${row+1}`, `${col-1},${row-1}`,
            `${col+1},${row-1}`, `${col-1},${row+1}`
        ];

        const grid = spatialGridRef.current;

        for(const key of cellsToCheck) {
            const nodesInCell = grid.get(key);
            if (nodesInCell) {
                for (const node of nodesInCell) {
                    const nx = node.x * spacing + centerOffset;
                    const ny = node.y * spacing + centerOffset;
                    const vis = settings.limitVisuals?.[node.limitTop] || { size: 1 };
                    const r = baseRadius * vis.size;

                    if (x < nx - r || x > nx + r || y < ny - r || y > ny + r) continue;

                    const dx = x - nx;
                    const dy = y - ny;
                    if (dx*dx + dy*dy < r*r) {
                        return node;
                    }
                }
            }
        }
        return null;
    }, [settings.buttonSpacingScale, settings.buttonSizeScale, settings.limitVisuals]);

    // --- Handlers ---

    const handlePointerDown = useCallback((e: React.PointerEvent) => {
        if (uiUnlocked || !dynamicCanvasRef.current) return;
        e.preventDefault();

        // Track raw position for drawing lines
        cursorPositionsRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });

        const hitNode = getHitNode(e.clientX, e.clientY);

        if (hitNode) {
            (e.target as HTMLElement).setPointerCapture(e.pointerId);

            // Interaction Trigger (Bring to front)
            const topLayer = settings.layerOrder[settings.layerOrder.length - 1];
            if (hitNode.maxPrime !== topLayer) {
                onLimitInteraction(hitNode.maxPrime);
            }

            lastTouchedLimitRef.current = hitNode.maxPrime;

            // Record Hit for Ripple Animation
            // Hits are stored in a ref array that the canvas loop will read and clean up
            recentHitsRef.current.push({
                x: hitNode.x,
                y: hitNode.y,
                limit: hitNode.limitTop,
                startTime: performance.now()
            });

            // Update Cursors
            const newCursor: ActiveCursor = {
                pointerId: e.pointerId,
                currentX: e.clientX,
                currentY: e.clientY,
                originNodeId: hitNode.id,
                startTime: performance.now()
            };

            setActiveCursors(prev => {
                const next = new Map(prev);
                next.set(e.pointerId, newCursor);
                activeCursorsRef.current = next;
                return next;
            });

            // Latching Logic (Tri-State)
            if (latchStatus === 1) { 
                // ACTIVE: Permanently latch
                setManualLatchedNodes(prev => {
                    const next = new Map(prev);
                    // Toggle if already manually latched, otherwise add
                    if (next.has(hitNode.id)) next.delete(hitNode.id);
                    else next.set(hitNode.id, hitNode.id);
                    return next;
                });
            } else {
                // OFF or FROZEN: Momentary "Pseudo-latch" for audio engine diffing
                // We add it to manualLatchedNodes, but handlePointerUp will remove it
                setManualLatchedNodes(prev => {
                    const next = new Map(prev);
                    if (!next.has(hitNode.id)) next.set(hitNode.id, hitNode.id);
                    return next;
                });
            }
        }
    }, [uiUnlocked, settings, getHitNode, onLimitInteraction, latchStatus]);

    const handlePointerMove = useCallback((e: React.PointerEvent) => {
        if (uiUnlocked) return;

        // Always update raw position
        if (activeCursorsRef.current.has(e.pointerId)) {
            cursorPositionsRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });

            // 1. Pitch Bend Logic
            if (settings.isPitchBendEnabled && scrollContainerRef.current) {
                const centerOffset = dynamicSizeRef.current / 2;
                const rect = scrollContainerRef.current.getBoundingClientRect();
                const canvasY = (e.clientY - rect.top) + scrollContainerRef.current.scrollTop;
                const relY = canvasY - centerOffset;

                const bentRatio = getPitchRatioFromScreenDelta(relY, settings.buttonSpacingScale);

                audioEngine.glideVoice(`node-${activeCursorsRef.current.get(e.pointerId)!.originNodeId}`, bentRatio, settings.baseFrequency, 0.05);
                if (settings.midiEnabled) {
                    // Note: MidiService expects origin ID if we are using the node-based ID system
                    const nodeId = activeCursorsRef.current.get(e.pointerId)!.originNodeId;
                    midiService.pitchBend(`node-${nodeId}`, bentRatio, settings.baseFrequency, settings.midiPitchBendRange);
                }
            }
        }
    }, [uiUnlocked, settings]);

    const handlePointerUp = useCallback((e: React.PointerEvent) => {
        if (activeCursorsRef.current.has(e.pointerId)) {
            const cursor = activeCursorsRef.current.get(e.pointerId)!;

            // Cleanup Cursor State
            cursorPositionsRef.current.delete(e.pointerId);
            setActiveCursors(prev => {
                const next = new Map(prev);
                next.delete(e.pointerId);
                activeCursorsRef.current = next;
                return next;
            });

            // Momentary Cleanup (State 0 and 2)
            if (latchStatus !== 1) {
                setManualLatchedNodes(prev => {
                    const next = new Map(prev);
                    // Remove the node originated by this cursor
                    next.delete(cursor.originNodeId); 
                    return next;
                });
            }
        }
    }, [latchStatus]);

    return {
        activeCursors,
        activeCursorsRef,
        manualLatchedNodes,
        setManualLatchedNodes,
        cursorPositionsRef,
        lastTouchedLimitRef,
        recentHitsRef, // Exposed for Canvas
        handlePointerDown,
        handlePointerMove,
        handlePointerUp
    };
};

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine } from '../types';
import AudioEngine from '../services/AudioEngine';
import { midiService } from '../services/MidiService';
import { useLatticeInteraction } from '../hooks/useLatticeInteraction';
import { useLatticeGeneration } from '../hooks/useLatticeGeneration';
import LatticeCanvas from './LatticeCanvas';

export interface TonalityDiamondHandle {
  clearLatches: () => void;
  centerView: () => void;
  increaseDepth: () => void;
  decreaseDepth: () => void;
  getLatchedNodes: () => LatticeNode[];
}

interface Props {
  settings: AppSettings;
  updateSettings: (s: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) => void;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
  latchStatus: 0 | 1 | 2;
}

const GRID_CELL_SIZE = 100;

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, updateSettings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked, latchStatus } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null);

  // 1. Data Generation Hook
  const { data, isGenerating, dynamicSize } = useLatticeGeneration(settings);
  const prevDynamicSizeRef = useRef(2000);

  // 2. Memoized Lookups (Data Derivative)
  const nodeMap = useMemo(() => new Map(data.nodes.map(n => [n.id, n])), [data.nodes]);

  const spatialGrid = useMemo(() => {
      const grid = new Map<string, LatticeNode[]>();
      const centerOffset = dynamicSize / 2;
      const spacing = settings.buttonSpacingScale;

      data.nodes.forEach(node => {
          const x = node.x * spacing + centerOffset;
          const y = node.y * spacing + centerOffset;
          const col = Math.floor(x / GRID_CELL_SIZE);
          const row = Math.floor(y / GRID_CELL_SIZE);
          const key = `${col},${row}`;
          if (!grid.has(key)) grid.set(key, []);
          grid.get(key)!.push(node);
      });
      return grid;
  }, [data.nodes, settings.buttonSpacingScale, dynamicSize]);

  // Refs for Hooks
  const nodeMapRef = useRef(nodeMap);
  const spatialGridRef = useRef(spatialGrid);
  const dynamicSizeRef = useRef(dynamicSize);

  useEffect(() => { nodeMapRef.current = nodeMap; }, [nodeMap]);
  useEffect(() => { spatialGridRef.current = spatialGrid; }, [spatialGrid]);
  useEffect(() => { dynamicSizeRef.current = dynamicSize; }, [dynamicSize]);

  // 3. Interaction Hook
  const {
      activeCursors,
      activeCursorsRef,
      manualLatchedNodes,
      setManualLatchedNodes,
      cursorPositionsRef,
      lastTouchedLimitRef,
      recentHitsRef,
      handlePointerDown,
      handlePointerMove,
      handlePointerUp
  } = useLatticeInteraction({
      settings,
      audioEngine,
      nodeMapRef,
      spatialGridRef,
      dynamicSizeRef,
      dynamicCanvasRef,
      scrollContainerRef,
      onLimitInteraction,
      uiUnlocked,
      latchStatus
  });

  const [effectiveLatchedNodes, setEffectiveLatchedNodes] = useState<Map<string, string>>(new Map());

  // Optimization: Pre-calculate active (both latched) and reinforced (one latched) lines
  const { activeLines, reinforcedLines } = useMemo(() => {
    const latched = effectiveLatchedNodes;
    const lines = data.lines;
    const active: LatticeLine[] = [];
    const reinforced: LatticeLine[] = [];

    if (latched.size > 0) {
        for (const line of lines) {
            const s = latched.has(line.sourceId);
            const t = latched.has(line.targetId);

            if (s && t) {
                active.push(line);
            } else if (s || t) {
                reinforced.push(line);
            }
        }
    }
    return { activeLines: active, reinforcedLines: reinforced };
  }, [data.lines, effectiveLatchedNodes]);

  // Depth History for Undo/Redo Depth
  const depthHistoryRef = useRef<number[]>([]);
  const [hasCentered, setHasCentered] = useState(false);
  const prevActiveChordIds = useRef<string[]>([]);

  // --- External API ---
  useImperativeHandle(ref, () => ({
    clearLatches: () => setManualLatchedNodes(new Map()),
    centerView: () => centerScroll(),
    increaseDepth: () => {
        const limit = lastTouchedLimitRef.current;
        if (limit && limit > 1) {
             updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13];
                 return {
                     ...prev,
                     limitDepths: { ...prev.limitDepths, [limit]: currentDepth + 1 }
                 };
             });
             depthHistoryRef.current.push(limit);
        }
    },
    decreaseDepth: () => {
        const limit = depthHistoryRef.current.pop();
        if (limit) {
            updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13];
                 return {
                     ...prev,
                     limitDepths: { ...prev.limitDepths, [limit]: Math.max(0, currentDepth - 1) }
                 };
             });
        }
    },
    getLatchedNodes: () => {
        const result: LatticeNode[] = [];
        effectiveLatchedNodes.forEach((_, id) => {
            const n = nodeMap.get(id);
            if (n) result.push(n);
        });
        return result;
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const center = dynamicSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
      }
  };

  useLayoutEffect(() => {
    const container = scrollContainerRef.current;
    if (!container) return;
    if (!hasCentered && dynamicSize > 0) {
        centerScroll();
        setHasCentered(true);
    } else if (dynamicSize !== prevDynamicSizeRef.current) {
        const diff = (dynamicSize - prevDynamicSizeRef.current) / 2;
        container.scrollLeft += diff;
        container.scrollTop += diff;
    }
    prevDynamicSizeRef.current = dynamicSize;
  }, [dynamicSize]);

  // --- LOGIC: Effective Latches (Chords + Manual) ---
  useEffect(() => {
    const newEffective = new Map<string, string>(manualLatchedNodes);
    const nodes = nodeMap;

    activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                if (!newEffective.has(n.id)) newEffective.set(n.id, n.id);
            });
        }
    });

    // Always Relatch Chords Logic
    if (settings.chordsAlwaysRelatch) {
         const newChords = activeChordIds.filter(id => !prevActiveChordIds.current.includes(id));
         if (newChords.length > 0) {
             newChords.forEach(chordId => {
                 const chordDef = settings.savedChords.find(c => c.id === chordId);
                 if (chordDef) {
                     chordDef.nodes.forEach(n => {
                        const fullNode = nodes.get(n.id);
                        if (fullNode) {
                            audioEngine.startVoice(`node-${n.id}`, fullNode.ratio, settings.baseFrequency);
                            if (settings.midiEnabled) midiService.noteOn(`node-${n.id}`, fullNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
                        }
                     });
                 }
             });
         }
    }

    setEffectiveLatchedNodes(newEffective);
    prevActiveChordIds.current = activeChordIds;
  }, [manualLatchedNodes, activeChordIds, settings.savedChords, settings.chordsAlwaysRelatch, nodeMap]);

  // Audio Diffing
  const prevEffectiveRef = useRef<Map<string, string>>(new Map());
  useEffect(() => {
      const current = effectiveLatchedNodes;
      const prev = prevEffectiveRef.current;
      const nodes = nodeMap;

      current.forEach((originId, nodeId) => {
          if (!prev.has(nodeId)) {
               const node = nodes.get(nodeId); 
               if (node) {
                   audioEngine.startVoice(`node-${nodeId}`, node.ratio, settings.baseFrequency);
                   if (settings.midiEnabled) midiService.noteOn(`node-${nodeId}`, node.ratio, settings.baseFrequency, settings.midiPitchBendRange);
               }
          }
      });
      prev.forEach((_, nodeId) => {
          if (!current.has(nodeId)) {
              audioEngine.stopVoice(`node-${nodeId}`);
              if (settings.midiEnabled) midiService.noteOff(`node-${nodeId}`);
          }
      });

      prevEffectiveRef.current = current;
  }, [effectiveLatchedNodes, nodeMap, settings.baseFrequency]);

  return (
    <div 
        ref={scrollContainerRef}
        className="w-full h-full overflow-auto bg-slate-950 relative"
        style={{ touchAction: 'none' }}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerLeave={handlePointerUp}
        onPointerCancel={handlePointerUp}
    >
        <LatticeCanvas 
            settings={settings}
            data={data}
            dynamicSize={dynamicSize}
            activeLines={activeLines}
            reinforcedLines={reinforcedLines}
            effectiveLatchedNodes={effectiveLatchedNodes}
            activeCursorsRef={activeCursorsRef}
            cursorPositionsRef={cursorPositionsRef}
            nodeMapRef={nodeMapRef}
            scrollContainerRef={scrollContainerRef}
            dynamicCanvasRef={dynamicCanvasRef}
            isGenerating={isGenerating}
            uiUnlocked={uiUnlocked}
            latchStatus={latchStatus}
            recentHitsRef={recentHitsRef}
        />
    </div>
  );
});

export default React.memo(TonalityDiamond);

import React, { useRef, useEffect, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine, ButtonShape } from '../types';
import { getRainbowPeriod } from '../services/ProjectionService';
import { ActiveCursor, InteractionHit } from '../hooks/useLatticeInteraction';

interface Props {
    settings: AppSettings;
    data: { nodes: LatticeNode[], lines: LatticeLine[] };
    dynamicSize: number;
    activeLines: LatticeLine[];
    reinforcedLines: LatticeLine[];
    effectiveLatchedNodes: Map<string, string>;
    activeCursorsRef: React.MutableRefObject<Map<number, ActiveCursor>>;
    cursorPositionsRef: React.MutableRefObject<Map<number, {x: number, y: number}>>;
    nodeMapRef: React.MutableRefObject<Map<string, LatticeNode>>;
    scrollContainerRef: React.RefObject<HTMLDivElement>;
    dynamicCanvasRef: React.RefObject<HTMLCanvasElement>; // Treated as Foreground Canvas
    isGenerating: boolean;
    uiUnlocked: boolean;
    latchStatus: 0 | 1 | 2;
    recentHitsRef: React.MutableRefObject<InteractionHit[]>;
}

const LatticeCanvas: React.FC<Props> = ({
    settings,
    data,
    dynamicSize,
    activeLines,
    reinforcedLines,
    effectiveLatchedNodes,
    activeCursorsRef,
    cursorPositionsRef,
    nodeMapRef,
    scrollContainerRef,
    dynamicCanvasRef,
    isGenerating,
    uiUnlocked,
    latchStatus,
    recentHitsRef
}) => {
    const staticCanvasRef = useRef<HTMLCanvasElement>(null);
    const dynamicBgCanvasRef = useRef<HTMLCanvasElement>(null); // New Background Dynamic Layer
    const animationFrameRef = useRef<number>(0);

    // Refs to keep the animation loop fresh without re-binding
    const settingsRef = useRef(settings);
    const effectiveLatchedRef = useRef(effectiveLatchedNodes);
    const activeLinesRef = useRef(activeLines);
    const reinforcedLinesRef = useRef(reinforcedLines);
    const dynamicSizeRef = useRef(dynamicSize);
    const latchStatusRef = useRef(latchStatus);

    // Reuse a set for active node rendering to avoid allocation in the loop
    const activeNodeIdsSetRef = useRef<Set<string>>(new Set());

    useEffect(() => { settingsRef.current = settings; }, [settings]);
    useEffect(() => { effectiveLatchedRef.current = effectiveLatchedNodes; }, [effectiveLatchedNodes]);
    useEffect(() => { activeLinesRef.current = activeLines; }, [activeLines]);
    useEffect(() => { reinforcedLinesRef.current = reinforcedLines; }, [reinforcedLines]);
    useEffect(() => { dynamicSizeRef.current = dynamicSize; }, [dynamicSize]);
    useEffect(() => { latchStatusRef.current = latchStatus; }, [latchStatus]);

    // --- STATIC RENDERER (Background Nodes & Lines) ---
    const visualDeps = useMemo(() => JSON.stringify({
        size: settings.buttonSizeScale,
        spacing: settings.buttonSpacingScale,
        colors: settings.colors,
        visuals: settings.limitVisuals,
        shape: settings.buttonShape,
        textScale: settings.nodeTextSizeScale,
        fractionBar: settings.showFractionBar,
        canvasSize: dynamicSize 
    }), [
        settings.buttonSizeScale, settings.buttonSpacingScale, settings.colors, settings.limitVisuals,
        settings.buttonShape, settings.nodeTextSizeScale, settings.showFractionBar, dynamicSize
    ]);

    useEffect(() => {
        const canvas = staticCanvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d', { alpha: true });
        if (!ctx) return;

        const dpr = window.devicePixelRatio || 1;
        const size = dynamicSize;

        if (canvas.width !== size * dpr || canvas.height !== size * dpr) {
            canvas.width = size * dpr;
            canvas.height = size * dpr;
        }

        ctx.setTransform(1, 0, 0, 1, 0, 0);
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.scale(dpr, dpr);

        const centerOffset = size / 2;
        const spacing = settings.buttonSpacingScale;
        const baseRadius = (60 * settings.buttonSizeScale) / 2;
        const isDiamond = settings.buttonShape === ButtonShape.DIAMOND;

        // Draw Lines (Static Background Lines)
        const linesByLimit: Record<number, number[]> = {};
        for (const line of data.lines) {
            if (!linesByLimit[line.limit]) linesByLimit[line.limit] = [];
            const arr = linesByLimit[line.limit];
            arr.push(
                line.x1 * spacing + centerOffset, 
                line.y1 * spacing + centerOffset, 
                line.x2 * spacing + centerOffset, 
                line.y2 * spacing + centerOffset
            );
        }

        ctx.lineCap = 'round';
        for (const limitStr in linesByLimit) {
            const limit = parseInt(limitStr);
            const coords = linesByLimit[limit];
            const color = settings.colors[limit] || '#666';
            const visualSettings = settings.limitVisuals?.[limit] || { size: 1, opacity: 1 };

            ctx.beginPath();
            for(let i=0; i<coords.length; i+=4) {
                ctx.moveTo(coords[i], coords[i+1]);
                ctx.lineTo(coords[i+2], coords[i+3]);
            }
            ctx.lineWidth = (limit === 1 ? 4 : 2) * visualSettings.size;
            ctx.strokeStyle = color;
            ctx.globalAlpha = 0.3 * visualSettings.opacity; 

            if (limit === 1) ctx.setLineDash([5, 5]);
            else ctx.setLineDash([]);
            ctx.stroke();
        }
        ctx.setLineDash([]); 

        // Draw Nodes
        for (const node of data.nodes) {
            const x = node.x * spacing + centerOffset;
            const y = node.y * spacing + centerOffset;
            const cTop = settings.colors[node.limitTop] || '#666';
            const cBottom = settings.colors[node.limitBottom] || '#666';
            const topVis = settings.limitVisuals?.[node.limitTop] || { size: 1, opacity: 1 };
            const limitScale = topVis.size;
            const limitOpacity = topVis.opacity;
            const radius = baseRadius * limitScale;

            ctx.globalAlpha = 1.0 * limitOpacity;

            ctx.beginPath();
            if (isDiamond) {
                ctx.moveTo(x, y - radius);
                ctx.lineTo(x + radius, y);
                ctx.lineTo(x, y + radius);
                ctx.lineTo(x - radius, y);
            } else {
                ctx.arc(x, y, radius, 0, Math.PI * 2);
            }
            ctx.closePath();

            const grad = ctx.createLinearGradient(x, y - radius, x, y + radius);
            grad.addColorStop(0.45, cTop);
            grad.addColorStop(0.55, cBottom);
            ctx.fillStyle = grad;
            ctx.fill();

            const combinedScale = settings.buttonSizeScale * limitScale;
            if (combinedScale > 0.4) {
                ctx.fillStyle = 'white';
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                let fontSize = Math.max(10, Math.min(18, 14 * combinedScale)) * settings.nodeTextSizeScale;
                ctx.font = `bold ${fontSize}px sans-serif`; 

                const spacingY = settings.showFractionBar ? 0.55 : 0.50;
                const nStr = node.n.toString();
                const dStr = node.d.toString();

                ctx.fillText(nStr, x, y - (radius * spacingY));

                if (settings.showFractionBar) {
                    ctx.beginPath();
                    ctx.moveTo(x - (radius * 0.4), y);
                    ctx.lineTo(x + (radius * 0.4), y);
                    ctx.lineWidth = 1;
                    ctx.strokeStyle = `rgba(255,255,255,${0.8 * limitOpacity})`;
                    ctx.stroke();
                }
                ctx.fillText(dStr, x, y + (radius * spacingY));
            }
        }

    }, [data, visualDeps, dynamicSize]);

    // --- DYNAMIC RENDERER (Animation Loop) ---
    useEffect(() => {
        const canvasFg = dynamicCanvasRef.current;
        const canvasBg = dynamicBgCanvasRef.current;

        if (!canvasFg || !canvasBg) return;

        const ctxFg = canvasFg.getContext('2d', { alpha: true });
        const ctxBg = canvasBg.getContext('2d', { alpha: true });

        if (!ctxFg || !ctxBg) return;

        const dpr = window.devicePixelRatio || 1;

        const render = (time: number) => {
            const currentSettings = settingsRef.current;
            const currentCursors = activeCursorsRef.current;
            const currentLatched = effectiveLatchedRef.current;
            const currentActiveLines = activeLinesRef.current;
            const currentReinforcedLines = reinforcedLinesRef.current;
            const status = latchStatusRef.current;
            const size = dynamicSizeRef.current;

            // Resize logic for both canvases
            if (canvasFg.width !== size * dpr || canvasFg.height !== size * dpr) {
                canvasFg.width = size * dpr;
                canvasFg.height = size * dpr;
                ctxFg.scale(dpr, dpr);

                canvasBg.width = size * dpr;
                canvasBg.height = size * dpr;
                ctxBg.scale(dpr, dpr);
            }

            // Viewport culling optimization
            let viewX = 0, viewY = 0, viewW = size, viewH = size;
            if (scrollContainerRef.current) {
                viewX = scrollContainerRef.current.scrollLeft;
                viewY = scrollContainerRef.current.scrollTop;
                viewW = scrollContainerRef.current.clientWidth;
                viewH = scrollContainerRef.current.clientHeight;
            }

            ctxFg.clearRect(viewX, viewY, viewW, viewH);
            ctxBg.clearRect(viewX, viewY, viewW, viewH);

            const centerOffset = size / 2;
            const spacing = currentSettings.buttonSpacingScale;
            const baseRadius = (60 * currentSettings.buttonSizeScale) / 2;
            const isDiamond = currentSettings.buttonShape === ButtonShape.DIAMOND;
            const colorCache = currentSettings.colors;

            const animationSpeed = (currentSettings.voiceLeadingAnimationSpeed || 2.0) * 0.33;
            const rawPhase = (time * 0.001 * animationSpeed);
            const flowPhase = currentSettings.voiceLeadingReverseDir ? (1.0 - (rawPhase % 1.0)) : (rawPhase % 1.0);

            const viewPad = 100;
            const leftBound = viewX - viewPad;
            const rightBound = viewX + viewW + viewPad;
            const topBound = viewY - viewPad;
            const bottomBound = viewY + viewH + viewPad;

            // DRAW REINFORCED LINES
            ctxBg.lineCap = 'round';
            ctxBg.setLineDash([]);

            for (const line of currentReinforcedLines) {
                // FILTER: If not fully Latch Mode (1), avoid drawing lines that connect to a held cursor (momentary)
                // However, reinforced lines only connect one latched node to a non-latched.
                // If the latchStatus is not 1, a "latched" node might be a cursor hold.
                // We simplify by checking if either end is a cursor node when not in Latch Mode.
                if (status !== 1) {
                    let isMomentaryLine = false;
                    for(const cursor of currentCursors.values()) {
                        if (cursor.originNodeId === line.sourceId || cursor.originNodeId === line.targetId) {
                            isMomentaryLine = true; break;
                        }
                    }
                    if (isMomentaryLine) continue;
                }

                const x1 = line.x1 * spacing + centerOffset;
                const y1 = line.y1 * spacing + centerOffset;
                const x2 = line.x2 * spacing + centerOffset;
                const y2 = line.y2 * spacing + centerOffset;

                if (Math.max(x1, x2) < leftBound || Math.min(x1, x2) > rightBound || Math.max(y1, y2) < topBound || Math.min(y1, y2) > bottomBound) continue;

                const limitColor = colorCache[line.limit] || '#666';
                const vis = currentSettings.limitVisuals?.[line.limit] || { size: 1, opacity: 1 };

                ctxBg.beginPath();
                ctxBg.moveTo(x1, y1);
                ctxBg.lineTo(x2, y2);
                ctxBg.lineWidth = (line.limit === 1 ? 4 : 2) * vis.size;
                ctxBg.strokeStyle = limitColor;
                ctxBg.globalAlpha = 0.6 * vis.opacity; 
                ctxBg.stroke();
            }

            // DRAW ACTIVE LINES (Connecting two active nodes)
            ctxFg.lineCap = 'round';
            for (const line of currentActiveLines) {
                // FILTER: Momentary notes should not draw active lines unless in Latch Mode 1
                if (status !== 1) {
                    let isMomentaryLine = false;
                    for(const cursor of currentCursors.values()) {
                        if (cursor.originNodeId === line.sourceId || cursor.originNodeId === line.targetId) {
                            isMomentaryLine = true; break;
                        }
                    }
                    if (isMomentaryLine) continue;
                }

                const x1 = line.x1 * spacing + centerOffset;
                const y1 = line.y1 * spacing + centerOffset;
                const x2 = line.x2 * spacing + centerOffset;
                const y2 = line.y2 * spacing + centerOffset;

                if (Math.max(x1, x2) < leftBound || Math.min(x1, x2) > rightBound || Math.max(y1, y2) < topBound || Math.min(y1, y2) > bottomBound) continue;

                const limitColor = colorCache[line.limit] || '#666';

                ctxFg.beginPath();
                ctxFg.moveTo(x1, y1);
                ctxFg.lineTo(x2, y2);
                ctxFg.lineWidth = 4;
                ctxFg.strokeStyle = limitColor;
                ctxFg.globalAlpha = 1.0;
                ctxFg.stroke();

                // Animated Pulse
                if (currentSettings.isVoiceLeadingAnimationEnabled) {
                    const grad = ctxFg.createLinearGradient(x1, y1, x2, y2);
                    const p = flowPhase;

                    grad.addColorStop(0, 'rgba(255,255,255,0)');
                    const pulseWidth = 0.2;
                    const start = Math.max(0, p - pulseWidth);
                    const end = Math.min(1, p + pulseWidth);
                    if (start > 0) grad.addColorStop(start, 'rgba(255,255,255,0)');
                    grad.addColorStop(p, 'rgba(255,255,255,0.7)'); 
                    if (end < 1) grad.addColorStop(end, 'rgba(255,255,255,0)');
                    grad.addColorStop(1, 'rgba(255,255,255,0)');

                    ctxFg.strokeStyle = grad;
                    ctxFg.lineWidth = 10 * (0.5 + currentSettings.voiceLeadingGlowAmount);
                    ctxFg.globalAlpha = 0.3; 
                    ctxFg.stroke();
                    ctxFg.lineWidth = 4;
                    ctxFg.globalAlpha = 1.0;
                    ctxFg.stroke();
                }
            }

            // DRAW ACTIVE NODES (Foreground Layer)
            const activeSet = activeNodeIdsSetRef.current;
            activeSet.clear(); 
            currentLatched.forEach((_, id) => activeSet.add(id));
            currentCursors.forEach(c => activeSet.add(c.originNodeId));

            if (activeSet.size > 0) {
                ctxFg.textAlign = 'center';
                ctxFg.textBaseline = 'middle';

                for (const id of activeSet) {
                    const node = nodeMapRef.current.get(id);
                    if (!node) continue;

                    const x = node.x * spacing + centerOffset;
                    const y = node.y * spacing + centerOffset;

                    if (x < leftBound || x > rightBound || y < topBound || y > bottomBound) continue;

                    const cTop = colorCache[node.limitTop] || '#666';
                    const cBottom = colorCache[node.limitBottom] || '#666';
                    const vis = currentSettings.limitVisuals?.[node.limitTop] || { size: 1 };
                    const limitScale = vis.size;
                    const radius = baseRadius * limitScale; 

                    ctxFg.globalAlpha = 1.0; 
                    ctxFg.beginPath();
                    if (isDiamond) {
                        ctxFg.moveTo(x, y - radius);
                        ctxFg.lineTo(x + radius, y);
                        ctxFg.lineTo(x, y + radius);
                        ctxFg.lineTo(x - radius, y);
                    } else {
                        ctxFg.arc(x, y, radius, 0, Math.PI * 2);
                    }
                    ctxFg.closePath();

                    // REPLICATE EXACT STATIC APPEARANCE (Gradient)
                    // Instead of solid color, use gradient to match unpressed state exactly
                    const grad = ctxFg.createLinearGradient(x, y - radius, x, y + radius);
                    grad.addColorStop(0.45, cTop);
                    grad.addColorStop(0.55, cBottom);
                    ctxFg.fillStyle = grad;
                    ctxFg.fill();

                    // ILLUMINATION RING
                    if (currentSettings.isColoredIlluminationEnabled) {
                        const rainbowPeriod = getRainbowPeriod(spacing); 
                        const bgOffsetY = (size / 2) - (rainbowPeriod / 3);
                        const relativeY = y - bgOffsetY;
                        const normalizedY = ((relativeY % rainbowPeriod) + rainbowPeriod) % rainbowPeriod;
                        const phase = normalizedY / rainbowPeriod;
                        const hue = (currentSettings.rainbowOffset + phase * 360) % 360;
                        const sat = currentSettings.isRainbowModeEnabled ? currentSettings.rainbowSaturation : 100;

                        ctxFg.strokeStyle = `hsl(${hue}, ${sat}%, 60%)`;
                        ctxFg.lineWidth = 6; 
                        ctxFg.stroke();
                    } else {
                        ctxFg.strokeStyle = 'white';
                        ctxFg.lineWidth = 3;
                        ctxFg.stroke();
                    }

                    const combinedScale = currentSettings.buttonSizeScale * limitScale;
                    if (combinedScale > 0.4) {
                        ctxFg.fillStyle = 'white';
                        let fontSize = Math.max(12, Math.min(22, 16 * combinedScale)) * currentSettings.nodeTextSizeScale;
                        ctxFg.font = `bold ${fontSize}px sans-serif`; 

                        const spacingY = currentSettings.showFractionBar ? 0.55 : 0.50;
                        ctxFg.fillText(node.n.toString(), x, y - (radius * spacingY));
                        if (currentSettings.showFractionBar) {
                            ctxFg.beginPath();
                            ctxFg.moveTo(x - (radius * 0.4), y);
                            ctxFg.lineTo(x + (radius * 0.4), y);
                            ctxFg.lineWidth = 1;
                            ctxFg.strokeStyle = 'white';
                            ctxFg.stroke();
                        }
                        ctxFg.fillText(node.d.toString(), x, y + (radius * spacingY));
                    }
                }
            }

            // DRAW RIPPLES (ALL Modes, Unified Animation)
            // Iterate backwards to allow removal
            const hits = recentHitsRef.current;
            const now = performance.now();
            for (let i = hits.length - 1; i >= 0; i--) {
                const hit = hits[i];
                const age = now - hit.startTime;

                if (age > 1500) {
                    hits.splice(i, 1);
                    continue;
                }

                const nx = hit.x * spacing + centerOffset;
                const ny = hit.y * spacing + centerOffset;

                if (nx < leftBound || nx > rightBound || ny < topBound || ny > bottomBound) continue;

                const vis = currentSettings.limitVisuals?.[hit.limit] || { size: 1 };
                const startRadius = baseRadius * vis.size;

                // Subtle expansion: starts at node edge, goes out by ~50%
                const expansion = age * 0.05; 
                const currentRadius = startRadius + expansion;

                // Subtle opacity: Max 0.2, fades to 0
                const opacity = Math.max(0, 0.2 * (1.0 - (age / 1500)));

                if (opacity > 0) {
                    ctxFg.beginPath();
                    if (isDiamond) {
                        // Diamond Ripple
                        ctxFg.moveTo(nx, ny - currentRadius);
                        ctxFg.lineTo(nx + currentRadius, ny);
                        ctxFg.lineTo(nx, ny + currentRadius);
                        ctxFg.lineTo(nx - currentRadius, ny);
                        ctxFg.closePath();
                    } else {
                        // Circle Ripple
                        ctxFg.arc(nx, ny, currentRadius, 0, Math.PI * 2);
                    }
                    ctxFg.lineWidth = 2;
                    ctxFg.strokeStyle = `rgba(255, 255, 255, ${opacity})`;
                    ctxFg.stroke();
                }
            }

            // DRAW CURSOR CONNECTORS (Only if Pitch Bend enabled or not Frozen)
            if (currentCursors.size > 0 && (currentSettings.isPitchBendEnabled || status !== 2)) {
                ctxFg.strokeStyle = 'white';
                ctxFg.lineWidth = 2;
                ctxFg.globalAlpha = 0.5;
                ctxFg.beginPath();
                currentCursors.forEach(c => {
                    const node = nodeMapRef.current.get(c.originNodeId);
                    if(node) {
                        const nx = node.x * spacing + centerOffset;
                        const ny = node.y * spacing + centerOffset;
                        const pos = cursorPositionsRef.current.get(c.pointerId);
                        if (pos) {
                            let cx = 0, cy = 0;
                            if (scrollContainerRef.current) {
                                const r = scrollContainerRef.current.getBoundingClientRect();
                                cx = (pos.x - r.left) + scrollContainerRef.current.scrollLeft;
                                cy = (pos.y - r.top) + scrollContainerRef.current.scrollTop;
                            }
                            ctxFg.moveTo(nx, ny);
                            ctxFg.lineTo(cx, cy);
                        }
                    }
                });
                ctxFg.stroke();
            }

            animationFrameRef.current = requestAnimationFrame(render);
        };

        animationFrameRef.current = requestAnimationFrame(render);
        return () => cancelAnimationFrame(animationFrameRef.current);
    }, []); 

    const rainbowPeriod = getRainbowPeriod(settings.buttonSpacingScale);
    const rainbowBackgroundFixed = useMemo(() => {
        if (settings.isRainbowModeEnabled) {
            const stops: string[] = [];
            const steps = 6;
            for (let i = 0; i <= steps; i++) {
                const pct = (i / steps) * 100;
                const hue = (settings.rainbowOffset + i * 60); 
                stops.push(`hsl(${hue}, ${settings.rainbowSaturation}%, ${settings.rainbowBrightness}%) ${pct}%`);
            }
            return `linear-gradient(to bottom, ${stops.join(', ')})`;
        }
        return undefined;
    }, [settings.isRainbowModeEnabled, settings.rainbowOffset, settings.rainbowSaturation, settings.rainbowBrightness]);

    const bgOffsetY = (dynamicSize / 2) - (rainbowPeriod / 3);

    return (
        <div 
            className="relative"
            style={{ 
                width: dynamicSize, 
                height: dynamicSize,
                backgroundImage: rainbowBackgroundFixed,
                backgroundSize: `100% ${rainbowPeriod}px`,
                backgroundRepeat: 'repeat',
                backgroundPosition: `0px ${bgOffsetY}px`,
                pointerEvents: uiUnlocked ? 'none' : 'auto',
            }}
        >
           {/* Layer 0: Background Dynamic (Reinforced Lines) - z-index 5 */}
           <canvas 
             ref={dynamicBgCanvasRef}
             className="absolute top-0 left-0 z-[5] pointer-events-none"
             style={{ width: '100%', height: '100%' }}
           />

           {/* Layer 1: Static (Background Nodes) - z-index 10 */}
           <canvas 
             ref={staticCanvasRef}
             className="absolute top-0 left-0 z-[10] pointer-events-none"
             style={{ width: '100%', height: '100%' }}
           />

           {/* Layer 2: Foreground Dynamic (Active Elements) - z-index 20 */}
           <canvas 
             ref={dynamicCanvasRef}
             className="absolute top-0 left-0 z-[20]"
             style={{ width: '100%', height: '100%' }}
           />

           {isGenerating && (
             <div className="absolute top-4 right-4 z-50 flex items-center gap-2 bg-slate-900/80 p-2 rounded-full backdrop-blur-sm border border-white/10 shadow-xl">
                 <svg className="animate-spin h-5 w-5 text-blue-500" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                   <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                   <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                 </svg>
                 <span className="text-xs font-bold text-slate-300 pr-2">Calculating...</span>
             </div>
           )}
        </div>
    );
};

export default React.memo(LatticeCanvas);

import React, { useState, useRef, useCallback } from 'react';
import { AppSettings, LatticeNode } from '../types';
import { getPitchRatioFromScreenDelta } from '../services/ProjectionService';
import AudioEngine from '../services/AudioEngine';
import { midiService } from '../services/MidiService';

export interface ActiveCursor {
    pointerId: number;
    currentX: number;
    currentY: number;
    originNodeId: string;
    startTime: number; // For ripple effect
}

export interface InteractionHit {
    x: number;
    y: number;
    startTime: number;
    limit: number;
}

interface UseLatticeInteractionProps {
    settings: AppSettings;
    audioEngine: AudioEngine;
    // We pass refs to the data needed for hit testing to avoid stale closures without frequent re-renders
    nodeMapRef: React.MutableRefObject<Map<string, LatticeNode>>;
    spatialGridRef: React.MutableRefObject<Map<string, LatticeNode[]>>;
    dynamicSizeRef: React.MutableRefObject<number>;
    dynamicCanvasRef: React.RefObject<HTMLCanvasElement>;
    scrollContainerRef: React.RefObject<HTMLDivElement>;
    onLimitInteraction: (limit: number) => void;
    uiUnlocked: boolean;
    latchStatus: 0 | 1 | 2; // 0=Off, 1=Active, 2=Frozen
}

const GRID_CELL_SIZE = 100;

export const useLatticeInteraction = ({
    settings,
    audioEngine,
    nodeMapRef,
    spatialGridRef,
    dynamicSizeRef,
    dynamicCanvasRef,
    scrollContainerRef,
    onLimitInteraction,
    uiUnlocked,
    latchStatus
}: UseLatticeInteractionProps) => {

    // State - Only used for persistent latches to trigger re-renders/line updates
    const [manualLatchedNodes, setManualLatchedNodes] = useState<Map<string, string>>(new Map());

    // Refs - Used for high-frequency interaction (Momentary)
    // We REMOVED the React state for activeCursors to prevent re-renders on every frame/move
    const activeCursorsRef = useRef<Map<number, ActiveCursor>>(new Map());
    const cursorPositionsRef = useRef<Map<number, {x: number, y: number}>>(new Map());
    const lastTouchedLimitRef = useRef<number | null>(null);
    const recentHitsRef = useRef<InteractionHit[]>([]);

    // Helper: Hit Testing
    const getHitNode = useCallback((clientX: number, clientY: number): LatticeNode | null => {
        if (!dynamicCanvasRef.current) return null;
        const rect = dynamicCanvasRef.current.getBoundingClientRect();
        const x = clientX - rect.left;
        const y = clientY - rect.top;

        const centerOffset = dynamicSizeRef.current / 2;
        const spacing = settings.buttonSpacingScale;
        const baseRadius = (60 * settings.buttonSizeScale) / 2;

        const col = Math.floor(x / GRID_CELL_SIZE);
        const row = Math.floor(y / GRID_CELL_SIZE);

        // Check surrounding cells for edge cases
        const cellsToCheck = [
            `${col},${row}`, `${col+1},${row}`, `${col-1},${row}`,
            `${col},${row+1}`, `${col},${row-1}`,
            `${col+1},${row+1}`, `${col-1},${row-1}`,
            `${col+1},${row-1}`, `${col-1},${row+1}`
        ];

        const grid = spatialGridRef.current;

        for(const key of cellsToCheck) {
            const nodesInCell = grid.get(key);
            if (nodesInCell) {
                for (const node of nodesInCell) {
                    const nx = node.x * spacing + centerOffset;
                    const ny = node.y * spacing + centerOffset;
                    const vis = settings.limitVisuals?.[node.limitTop] || { size: 1 };
                    const r = baseRadius * vis.size;

                    if (x < nx - r || x > nx + r || y < ny - r || y > ny + r) continue;

                    const dx = x - nx;
                    const dy = y - ny;
                    if (dx*dx + dy*dy < r*r) {
                        return node;
                    }
                }
            }
        }
        return null;
    }, [settings.buttonSpacingScale, settings.buttonSizeScale, settings.limitVisuals]);

    // --- Handlers ---

    const handlePointerDown = useCallback((e: React.PointerEvent) => {
        if (uiUnlocked || !dynamicCanvasRef.current) return;
        e.preventDefault();

        // Track raw position for drawing lines
        cursorPositionsRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });

        const hitNode = getHitNode(e.clientX, e.clientY);

        if (hitNode) {
            (e.target as HTMLElement).setPointerCapture(e.pointerId);

            // Interaction Trigger (Bring to front)
            const topLayer = settings.layerOrder[settings.layerOrder.length - 1];
            if (hitNode.maxPrime !== topLayer) {
                onLimitInteraction(hitNode.maxPrime);
            }

            lastTouchedLimitRef.current = hitNode.maxPrime;

            // Record Hit for Ripple Animation (Visuals only)
            recentHitsRef.current.push({
                x: hitNode.x,
                y: hitNode.y,
                limit: hitNode.limitTop,
                startTime: performance.now()
            });

            // Update Cursors (Ref only, no re-render)
            const newCursor: ActiveCursor = {
                pointerId: e.pointerId,
                currentX: e.clientX,
                currentY: e.clientY,
                originNodeId: hitNode.id,
                startTime: performance.now()
            };
            activeCursorsRef.current.set(e.pointerId, newCursor);

            // LOGIC SPLIT:
            // Latch Status 1 (Green/Active): Update State (Slow, triggers lines/render)
            // Latch Status 0/2 (Off/Frozen): Direct Audio (Fast, no render)

            if (latchStatus === 1) { 
                // ACTIVE LATCH: Update React state to persist node and draw lines
                setManualLatchedNodes(prev => {
                    const next = new Map(prev);
                    if (next.has(hitNode.id)) next.delete(hitNode.id);
                    else next.set(hitNode.id, hitNode.id);
                    return next;
                });
                // Note: TonalityDiamond's useEffect handles the audio triggering for this case
            } else {
                // MOMENTARY: Direct Audio Trigger
                // This bypasses the heavy line-generation useEffect in TonalityDiamond
                audioEngine.startVoice(`node-${hitNode.id}`, hitNode.ratio, settings.baseFrequency);
                if (settings.midiEnabled) {
                    midiService.noteOn(`node-${hitNode.id}`, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
                }
            }
        }
    }, [uiUnlocked, settings, getHitNode, onLimitInteraction, latchStatus]);

    const handlePointerMove = useCallback((e: React.PointerEvent) => {
        if (uiUnlocked) return;

        // Always update raw position for Pitch Bend calculation
        if (activeCursorsRef.current.has(e.pointerId)) {
            cursorPositionsRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });

            // Pitch Bend Logic
            if (settings.isPitchBendEnabled && scrollContainerRef.current) {
                const centerOffset = dynamicSizeRef.current / 2;
                const rect = scrollContainerRef.current.getBoundingClientRect();
                const canvasY = (e.clientY - rect.top) + scrollContainerRef.current.scrollTop;
                const relY = canvasY - centerOffset;

                const bentRatio = getPitchRatioFromScreenDelta(relY, settings.buttonSpacingScale);

                // Audio engine handles this cheaply
                audioEngine.glideVoice(`node-${activeCursorsRef.current.get(e.pointerId)!.originNodeId}`, bentRatio, settings.baseFrequency, 0.05);
                if (settings.midiEnabled) {
                    const nodeId = activeCursorsRef.current.get(e.pointerId)!.originNodeId;
                    midiService.pitchBend(`node-${nodeId}`, bentRatio, settings.baseFrequency, settings.midiPitchBendRange);
                }
            }
        }
    }, [uiUnlocked, settings]);

    const handlePointerUp = useCallback((e: React.PointerEvent) => {
        if (activeCursorsRef.current.has(e.pointerId)) {
            const cursor = activeCursorsRef.current.get(e.pointerId)!;

            // Cleanup Cursor State
            cursorPositionsRef.current.delete(e.pointerId);
            activeCursorsRef.current.delete(e.pointerId);

            // Momentary Cleanup (State 0 and 2)
            if (latchStatus !== 1) {
                // Direct Stop for momentary notes
                audioEngine.stopVoice(`node-${cursor.originNodeId}`);
                if (settings.midiEnabled) {
                    midiService.noteOff(`node-${cursor.originNodeId}`);
                }
                // We do NOT update manualLatchedNodes here, so no re-render occurs.
            }
        }
    }, [latchStatus, settings.midiEnabled]);

    return {
        activeCursorsRef, // Ref only
        manualLatchedNodes,
        setManualLatchedNodes,
        cursorPositionsRef,
        lastTouchedLimitRef,
        recentHitsRef,
        handlePointerDown,
        handlePointerMove,
        handlePointerUp
    };
};

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine } from '../types';
import AudioEngine from '../services/AudioEngine';
import { midiService } from '../services/MidiService';
import { useLatticeInteraction } from '../hooks/useLatticeInteraction';
import { useLatticeGeneration } from '../hooks/useLatticeGeneration';
import LatticeCanvas from './LatticeCanvas';

export interface TonalityDiamondHandle {
  clearLatches: () => void;
  centerView: () => void;
  increaseDepth: () => void;
  decreaseDepth: () => void;
  getLatchedNodes: () => LatticeNode[];
}

interface Props {
  settings: AppSettings;
  updateSettings: (s: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) => void;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
  latchStatus: 0 | 1 | 2;
}

const GRID_CELL_SIZE = 100;

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, updateSettings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked, latchStatus } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null);

  // 1. Data Generation Hook
  const { data, isGenerating, dynamicSize } = useLatticeGeneration(settings);
  const prevDynamicSizeRef = useRef(2000);

  // 2. Memoized Lookups (Data Derivative)
  const nodeMap = useMemo(() => new Map(data.nodes.map(n => [n.id, n])), [data.nodes]);

  const spatialGrid = useMemo(() => {
      const grid = new Map<string, LatticeNode[]>();
      const centerOffset = dynamicSize / 2;
      const spacing = settings.buttonSpacingScale;

      data.nodes.forEach(node => {
          const x = node.x * spacing + centerOffset;
          const y = node.y * spacing + centerOffset;
          const col = Math.floor(x / GRID_CELL_SIZE);
          const row = Math.floor(y / GRID_CELL_SIZE);
          const key = `${col},${row}`;
          if (!grid.has(key)) grid.set(key, []);
          grid.get(key)!.push(node);
      });
      return grid;
  }, [data.nodes, settings.buttonSpacingScale, dynamicSize]);

  // Refs for Hooks
  const nodeMapRef = useRef(nodeMap);
  const spatialGridRef = useRef(spatialGrid);
  const dynamicSizeRef = useRef(dynamicSize);

  useEffect(() => { nodeMapRef.current = nodeMap; }, [nodeMap]);
  useEffect(() => { spatialGridRef.current = spatialGrid; }, [spatialGrid]);
  useEffect(() => { dynamicSizeRef.current = dynamicSize; }, [dynamicSize]);

  // 3. Interaction Hook
  const {
      activeCursorsRef, // Ref only
      manualLatchedNodes, // State
      setManualLatchedNodes,
      cursorPositionsRef,
      lastTouchedLimitRef,
      recentHitsRef,
      handlePointerDown,
      handlePointerMove,
      handlePointerUp
  } = useLatticeInteraction({
      settings,
      audioEngine,
      nodeMapRef,
      spatialGridRef,
      dynamicSizeRef,
      dynamicCanvasRef,
      scrollContainerRef,
      onLimitInteraction,
      uiUnlocked,
      latchStatus
  });

  const [effectiveLatchedNodes, setEffectiveLatchedNodes] = useState<Map<string, string>>(new Map());

  // Optimization: Pre-calculate active (both latched) and reinforced (one latched) lines
  // This now ONLY runs when permanent latches or chords change, not on every momentary tap!
  const { activeLines, reinforcedLines } = useMemo(() => {
    const latched = effectiveLatchedNodes;
    const lines = data.lines;
    const active: LatticeLine[] = [];
    const reinforced: LatticeLine[] = [];

    if (latched.size > 0) {
        for (const line of lines) {
            const s = latched.has(line.sourceId);
            const t = latched.has(line.targetId);

            if (s && t) {
                active.push(line);
            } else if (s || t) {
                reinforced.push(line);
            }
        }
    }
    return { activeLines: active, reinforcedLines: reinforced };
  }, [data.lines, effectiveLatchedNodes]);

  // Depth History for Undo/Redo Depth
  const depthHistoryRef = useRef<number[]>([]);
  const [hasCentered, setHasCentered] = useState(false);
  const prevActiveChordIds = useRef<string[]>([]);

  // --- External API ---
  useImperativeHandle(ref, () => ({
    clearLatches: () => setManualLatchedNodes(new Map()),
    centerView: () => centerScroll(),
    increaseDepth: () => {
        const limit = lastTouchedLimitRef.current;
        if (limit && limit > 1) {
             updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13];
                 return {
                     ...prev,
                     limitDepths: { ...prev.limitDepths, [limit]: currentDepth + 1 }
                 };
             });
             depthHistoryRef.current.push(limit);
        }
    },
    decreaseDepth: () => {
        const limit = depthHistoryRef.current.pop();
        if (limit) {
            updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13];
                 return {
                     ...prev,
                     limitDepths: { ...prev.limitDepths, [limit]: Math.max(0, currentDepth - 1) }
                 };
             });
        }
    },
    getLatchedNodes: () => {
        const result: LatticeNode[] = [];
        effectiveLatchedNodes.forEach((_, id) => {
            const n = nodeMap.get(id);
            if (n) result.push(n);
        });
        return result;
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const center = dynamicSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
      }
  };

  useLayoutEffect(() => {
    const container = scrollContainerRef.current;
    if (!container) return;
    if (!hasCentered && dynamicSize > 0) {
        centerScroll();
        setHasCentered(true);
    } else if (dynamicSize !== prevDynamicSizeRef.current) {
        const diff = (dynamicSize - prevDynamicSizeRef.current) / 2;
        container.scrollLeft += diff;
        container.scrollTop += diff;
    }
    prevDynamicSizeRef.current = dynamicSize;
  }, [dynamicSize]);

  // --- LOGIC: Effective Latches (Chords + Manual) ---
  useEffect(() => {
    const newEffective = new Map<string, string>(manualLatchedNodes);
    const nodes = nodeMap;

    activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                if (!newEffective.has(n.id)) newEffective.set(n.id, n.id);
            });
        }
    });

    // Always Relatch Chords Logic
    if (settings.chordsAlwaysRelatch) {
         const newChords = activeChordIds.filter(id => !prevActiveChordIds.current.includes(id));
         if (newChords.length > 0) {
             newChords.forEach(chordId => {
                 const chordDef = settings.savedChords.find(c => c.id === chordId);
                 if (chordDef) {
                     chordDef.nodes.forEach(n => {
                        const fullNode = nodes.get(n.id);
                        if (fullNode) {
                            audioEngine.startVoice(`node-${n.id}`, fullNode.ratio, settings.baseFrequency);
                            if (settings.midiEnabled) midiService.noteOn(`node-${n.id}`, fullNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
                        }
                     });
                 }
             });
         }
    }

    setEffectiveLatchedNodes(newEffective);
    prevActiveChordIds.current = activeChordIds;
  }, [manualLatchedNodes, activeChordIds, settings.savedChords, settings.chordsAlwaysRelatch, nodeMap]);

  // Audio Diffing (For Permanent Latches Only)
  const prevEffectiveRef = useRef<Map<string, string>>(new Map());
  useEffect(() => {
      const current = effectiveLatchedNodes;
      const prev = prevEffectiveRef.current;
      const nodes = nodeMap;

      current.forEach((originId, nodeId) => {
          if (!prev.has(nodeId)) {
               const node = nodes.get(nodeId); 
               if (node) {
                   audioEngine.startVoice(`node-${nodeId}`, node.ratio, settings.baseFrequency);
                   if (settings.midiEnabled) midiService.noteOn(`node-${nodeId}`, node.ratio, settings.baseFrequency, settings.midiPitchBendRange);
               }
          }
      });
      prev.forEach((_, nodeId) => {
          if (!current.has(nodeId)) {
              audioEngine.stopVoice(`node-${nodeId}`);
              if (settings.midiEnabled) midiService.noteOff(`node-${nodeId}`);
          }
      });

      prevEffectiveRef.current = current;
  }, [effectiveLatchedNodes, nodeMap, settings.baseFrequency]);

  return (
    <div 
        ref={scrollContainerRef}
        className="w-full h-full overflow-auto bg-slate-950 relative"
        style={{ touchAction: 'none' }}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerLeave={handlePointerUp}
        onPointerCancel={handlePointerUp}
    >
        <LatticeCanvas 
            settings={settings}
            data={data}
            dynamicSize={dynamicSize}
            activeLines={activeLines}
            reinforcedLines={reinforcedLines}
            effectiveLatchedNodes={effectiveLatchedNodes}
            activeCursorsRef={activeCursorsRef}
            cursorPositionsRef={cursorPositionsRef}
            nodeMapRef={nodeMapRef}
            scrollContainerRef={scrollContainerRef}
            dynamicCanvasRef={dynamicCanvasRef}
            isGenerating={isGenerating}
            uiUnlocked={uiUnlocked}
            latchStatus={latchStatus}
            recentHitsRef={recentHitsRef}
        />
    </div>
  );
});

export default React.memo(TonalityDiamond);

import React, { useRef, useEffect, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine, ButtonShape } from '../types';
import { getRainbowPeriod } from '../services/ProjectionService';
import { ActiveCursor, InteractionHit } from '../hooks/useLatticeInteraction';

interface Props {
    settings: AppSettings;
    data: { nodes: LatticeNode[], lines: LatticeLine[] };
    dynamicSize: number;
    activeLines: LatticeLine[];
    reinforcedLines: LatticeLine[];
    effectiveLatchedNodes: Map<string, string>;
    activeCursorsRef: React.MutableRefObject<Map<number, ActiveCursor>>;
    cursorPositionsRef: React.MutableRefObject<Map<number, {x: number, y: number}>>;
    nodeMapRef: React.MutableRefObject<Map<string, LatticeNode>>;
    scrollContainerRef: React.RefObject<HTMLDivElement>;
    dynamicCanvasRef: React.RefObject<HTMLCanvasElement>; // Treated as Foreground Canvas
    isGenerating: boolean;
    uiUnlocked: boolean;
    latchStatus: 0 | 1 | 2;
    recentHitsRef: React.MutableRefObject<InteractionHit[]>;
}

const LatticeCanvas: React.FC<Props> = ({
    settings,
    data,
    dynamicSize,
    activeLines,
    reinforcedLines,
    effectiveLatchedNodes,
    activeCursorsRef,
    cursorPositionsRef,
    nodeMapRef,
    scrollContainerRef,
    dynamicCanvasRef,
    isGenerating,
    uiUnlocked,
    latchStatus,
    recentHitsRef
}) => {
    const staticCanvasRef = useRef<HTMLCanvasElement>(null);
    const dynamicBgCanvasRef = useRef<HTMLCanvasElement>(null); // New Background Dynamic Layer
    const animationFrameRef = useRef<number>(0);

    // Refs to keep the animation loop fresh without re-binding
    const settingsRef = useRef(settings);
    const effectiveLatchedRef = useRef(effectiveLatchedNodes);
    const activeLinesRef = useRef(activeLines);
    const reinforcedLinesRef = useRef(reinforcedLines);
    const dynamicSizeRef = useRef(dynamicSize);
    const latchStatusRef = useRef(latchStatus);

    // Reuse a set for active node rendering to avoid allocation in the loop
    const activeNodeIdsSetRef = useRef<Set<string>>(new Set());

    useEffect(() => { settingsRef.current = settings; }, [settings]);
    useEffect(() => { effectiveLatchedRef.current = effectiveLatchedNodes; }, [effectiveLatchedNodes]);
    useEffect(() => { activeLinesRef.current = activeLines; }, [activeLines]);
    useEffect(() => { reinforcedLinesRef.current = reinforcedLines; }, [reinforcedLines]);
    useEffect(() => { dynamicSizeRef.current = dynamicSize; }, [dynamicSize]);
    useEffect(() => { latchStatusRef.current = latchStatus; }, [latchStatus]);

    // --- STATIC RENDERER (Background Nodes & Lines) ---
    const visualDeps = useMemo(() => JSON.stringify({
        size: settings.buttonSizeScale,
        spacing: settings.buttonSpacingScale,
        colors: settings.colors,
        visuals: settings.limitVisuals,
        shape: settings.buttonShape,
        textScale: settings.nodeTextSizeScale,
        fractionBar: settings.showFractionBar,
        canvasSize: dynamicSize 
    }), [
        settings.buttonSizeScale, settings.buttonSpacingScale, settings.colors, settings.limitVisuals,
        settings.buttonShape, settings.nodeTextSizeScale, settings.showFractionBar, dynamicSize
    ]);

    useEffect(() => {
        const canvas = staticCanvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d', { alpha: true });
        if (!ctx) return;

        const dpr = window.devicePixelRatio || 1;
        const size = dynamicSize;

        if (canvas.width !== size * dpr || canvas.height !== size * dpr) {
            canvas.width = size * dpr;
            canvas.height = size * dpr;
        }

        ctx.setTransform(1, 0, 0, 1, 0, 0);
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.scale(dpr, dpr);

        const centerOffset = size / 2;
        const spacing = settings.buttonSpacingScale;
        const baseRadius = (60 * settings.buttonSizeScale) / 2;
        const isDiamond = settings.buttonShape === ButtonShape.DIAMOND;

        // Draw Lines (Static Background Lines)
        const linesByLimit: Record<number, number[]> = {};
        for (const line of data.lines) {
            if (!linesByLimit[line.limit]) linesByLimit[line.limit] = [];
            const arr = linesByLimit[line.limit];
            arr.push(
                line.x1 * spacing + centerOffset, 
                line.y1 * spacing + centerOffset, 
                line.x2 * spacing + centerOffset, 
                line.y2 * spacing + centerOffset
            );
        }

        ctx.lineCap = 'round';
        for (const limitStr in linesByLimit) {
            const limit = parseInt(limitStr);
            const coords = linesByLimit[limit];
            const color = settings.colors[limit] || '#666';
            const visualSettings = settings.limitVisuals?.[limit] || { size: 1, opacity: 1 };

            ctx.beginPath();
            for(let i=0; i<coords.length; i+=4) {
                ctx.moveTo(coords[i], coords[i+1]);
                ctx.lineTo(coords[i+2], coords[i+3]);
            }
            ctx.lineWidth = (limit === 1 ? 4 : 2) * visualSettings.size;
            ctx.strokeStyle = color;
            ctx.globalAlpha = 0.3 * visualSettings.opacity; 

            if (limit === 1) ctx.setLineDash([5, 5]);
            else ctx.setLineDash([]);
            ctx.stroke();
        }
        ctx.setLineDash([]); 

        // Draw Nodes
        for (const node of data.nodes) {
            const x = node.x * spacing + centerOffset;
            const y = node.y * spacing + centerOffset;
            const cTop = settings.colors[node.limitTop] || '#666';
            const cBottom = settings.colors[node.limitBottom] || '#666';
            const topVis = settings.limitVisuals?.[node.limitTop] || { size: 1, opacity: 1 };
            const limitScale = topVis.size;
            const limitOpacity = topVis.opacity;
            const radius = baseRadius * limitScale;

            ctx.globalAlpha = 1.0 * limitOpacity;

            ctx.beginPath();
            if (isDiamond) {
                ctx.moveTo(x, y - radius);
                ctx.lineTo(x + radius, y);
                ctx.lineTo(x, y + radius);
                ctx.lineTo(x - radius, y);
            } else {
                ctx.arc(x, y, radius, 0, Math.PI * 2);
            }
            ctx.closePath();

            const grad = ctx.createLinearGradient(x, y - radius, x, y + radius);
            grad.addColorStop(0.45, cTop);
            grad.addColorStop(0.55, cBottom);
            ctx.fillStyle = grad;
            ctx.fill();

            const combinedScale = settings.buttonSizeScale * limitScale;
            if (combinedScale > 0.4) {
                ctx.fillStyle = 'white';
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                let fontSize = Math.max(10, Math.min(18, 14 * combinedScale)) * settings.nodeTextSizeScale;
                ctx.font = `bold ${fontSize}px sans-serif`; 

                const spacingY = settings.showFractionBar ? 0.55 : 0.50;
                const nStr = node.n.toString();
                const dStr = node.d.toString();

                ctx.fillText(nStr, x, y - (radius * spacingY));

                if (settings.showFractionBar) {
                    ctx.beginPath();
                    ctx.moveTo(x - (radius * 0.4), y);
                    ctx.lineTo(x + (radius * 0.4), y);
                    ctx.lineWidth = 1;
                    ctx.strokeStyle = `rgba(255,255,255,${0.8 * limitOpacity})`;
                    ctx.stroke();
                }
                ctx.fillText(dStr, x, y + (radius * spacingY));
            }
        }

    }, [data, visualDeps, dynamicSize]);

    // --- DYNAMIC RENDERER (Animation Loop) ---
    useEffect(() => {
        const canvasFg = dynamicCanvasRef.current;
        const canvasBg = dynamicBgCanvasRef.current;

        if (!canvasFg || !canvasBg) return;

        const ctxFg = canvasFg.getContext('2d', { alpha: true });
        const ctxBg = canvasBg.getContext('2d', { alpha: true });

        if (!ctxFg || !ctxBg) return;

        const dpr = window.devicePixelRatio || 1;

        const render = (time: number) => {
            const currentSettings = settingsRef.current;
            const currentCursors = activeCursorsRef.current;
            const currentLatched = effectiveLatchedRef.current;
            const currentActiveLines = activeLinesRef.current;
            const currentReinforcedLines = reinforcedLinesRef.current;
            const status = latchStatusRef.current;
            const size = dynamicSizeRef.current;

            // Resize logic for both canvases
            if (canvasFg.width !== size * dpr || canvasFg.height !== size * dpr) {
                canvasFg.width = size * dpr;
                canvasFg.height = size * dpr;
                ctxFg.scale(dpr, dpr);

                canvasBg.width = size * dpr;
                canvasBg.height = size * dpr;
                ctxBg.scale(dpr, dpr);
            }

            // Viewport culling optimization
            let viewX = 0, viewY = 0, viewW = size, viewH = size;
            if (scrollContainerRef.current) {
                viewX = scrollContainerRef.current.scrollLeft;
                viewY = scrollContainerRef.current.scrollTop;
                viewW = scrollContainerRef.current.clientWidth;
                viewH = scrollContainerRef.current.clientHeight;
            }

            ctxFg.clearRect(viewX, viewY, viewW, viewH);
            ctxBg.clearRect(viewX, viewY, viewW, viewH);

            const centerOffset = size / 2;
            const spacing = currentSettings.buttonSpacingScale;
            const baseRadius = (60 * currentSettings.buttonSizeScale) / 2;
            const isDiamond = currentSettings.buttonShape === ButtonShape.DIAMOND;
            const colorCache = currentSettings.colors;

            const animationSpeed = (currentSettings.voiceLeadingAnimationSpeed || 2.0) * 0.33;
            const rawPhase = (time * 0.001 * animationSpeed);
            const flowPhase = currentSettings.voiceLeadingReverseDir ? (1.0 - (rawPhase % 1.0)) : (rawPhase % 1.0);

            const viewPad = 100;
            const leftBound = viewX - viewPad;
            const rightBound = viewX + viewW + viewPad;
            const topBound = viewY - viewPad;
            const bottomBound = viewY + viewH + viewPad;

            // DRAW REINFORCED LINES
            ctxBg.lineCap = 'round';
            ctxBg.setLineDash([]);

            for (const line of currentReinforcedLines) {
                // Since momentary notes are no longer in `currentLatched` (effectiveLatchedNodes),
                // reinforced lines won't trigger for them. No complex filtering needed here.

                const x1 = line.x1 * spacing + centerOffset;
                const y1 = line.y1 * spacing + centerOffset;
                const x2 = line.x2 * spacing + centerOffset;
                const y2 = line.y2 * spacing + centerOffset;

                if (Math.max(x1, x2) < leftBound || Math.min(x1, x2) > rightBound || Math.max(y1, y2) < topBound || Math.min(y1, y2) > bottomBound) continue;

                const limitColor = colorCache[line.limit] || '#666';
                const vis = currentSettings.limitVisuals?.[line.limit] || { size: 1, opacity: 1 };

                ctxBg.beginPath();
                ctxBg.moveTo(x1, y1);
                ctxBg.lineTo(x2, y2);
                ctxBg.lineWidth = (line.limit === 1 ? 4 : 2) * vis.size;
                ctxBg.strokeStyle = limitColor;
                ctxBg.globalAlpha = 0.6 * vis.opacity; 
                ctxBg.stroke();
            }

            // DRAW ACTIVE LINES (Connecting two active nodes)
            ctxFg.lineCap = 'round';
            for (const line of currentActiveLines) {
                const x1 = line.x1 * spacing + centerOffset;
                const y1 = line.y1 * spacing + centerOffset;
                const x2 = line.x2 * spacing + centerOffset;
                const y2 = line.y2 * spacing + centerOffset;

                if (Math.max(x1, x2) < leftBound || Math.min(x1, x2) > rightBound || Math.max(y1, y2) < topBound || Math.min(y1, y2) > bottomBound) continue;

                const limitColor = colorCache[line.limit] || '#666';

                ctxFg.beginPath();
                ctxFg.moveTo(x1, y1);
                ctxFg.lineTo(x2, y2);
                ctxFg.lineWidth = 4;
                ctxFg.strokeStyle = limitColor;
                ctxFg.globalAlpha = 1.0;
                ctxFg.stroke();

                // Animated Pulse
                if (currentSettings.isVoiceLeadingAnimationEnabled) {
                    const grad = ctxFg.createLinearGradient(x1, y1, x2, y2);
                    const p = flowPhase;

                    grad.addColorStop(0, 'rgba(255,255,255,0)');
                    const pulseWidth = 0.2;
                    const start = Math.max(0, p - pulseWidth);
                    const end = Math.min(1, p + pulseWidth);
                    if (start > 0) grad.addColorStop(start, 'rgba(255,255,255,0)');
                    grad.addColorStop(p, 'rgba(255,255,255,0.7)'); 
                    if (end < 1) grad.addColorStop(end, 'rgba(255,255,255,0)');
                    grad.addColorStop(1, 'rgba(255,255,255,0)');

                    ctxFg.strokeStyle = grad;
                    ctxFg.lineWidth = 10 * (0.5 + currentSettings.voiceLeadingGlowAmount);
                    ctxFg.globalAlpha = 0.3; 
                    ctxFg.stroke();
                    ctxFg.lineWidth = 4;
                    ctxFg.globalAlpha = 1.0;
                    ctxFg.stroke();
                }
            }

            // DRAW ACTIVE NODES (Foreground Layer)
            // Combines Permanent Latches + Momentary Cursors
            const activeSet = activeNodeIdsSetRef.current;
            activeSet.clear(); 
            currentLatched.forEach((_, id) => activeSet.add(id));
            currentCursors.forEach(c => activeSet.add(c.originNodeId));

            if (activeSet.size > 0) {
                ctxFg.textAlign = 'center';
                ctxFg.textBaseline = 'middle';

                for (const id of activeSet) {
                    const node = nodeMapRef.current.get(id);
                    if (!node) continue;

                    const x = node.x * spacing + centerOffset;
                    const y = node.y * spacing + centerOffset;

                    if (x < leftBound || x > rightBound || y < topBound || y > bottomBound) continue;

                    const cTop = colorCache[node.limitTop] || '#666';
                    const cBottom = colorCache[node.limitBottom] || '#666';
                    const vis = currentSettings.limitVisuals?.[node.limitTop] || { size: 1 };
                    const limitScale = vis.size;
                    const radius = baseRadius * limitScale; 

                    ctxFg.globalAlpha = 1.0; 
                    ctxFg.beginPath();
                    if (isDiamond) {
                        ctxFg.moveTo(x, y - radius);
                        ctxFg.lineTo(x + radius, y);
                        ctxFg.lineTo(x, y + radius);
                        ctxFg.lineTo(x - radius, y);
                    } else {
                        ctxFg.arc(x, y, radius, 0, Math.PI * 2);
                    }
                    ctxFg.closePath();

                    // REPLICATE EXACT STATIC APPEARANCE (Gradient)
                    const grad = ctxFg.createLinearGradient(x, y - radius, x, y + radius);
                    grad.addColorStop(0.45, cTop);
                    grad.addColorStop(0.55, cBottom);
                    ctxFg.fillStyle = grad;
                    ctxFg.fill();

                    // ILLUMINATION RING
                    if (currentSettings.isColoredIlluminationEnabled) {
                        const rainbowPeriod = getRainbowPeriod(spacing); 
                        const bgOffsetY = (size / 2) - (rainbowPeriod / 3);
                        const relativeY = y - bgOffsetY;
                        const normalizedY = ((relativeY % rainbowPeriod) + rainbowPeriod) % rainbowPeriod;
                        const phase = normalizedY / rainbowPeriod;
                        const hue = (currentSettings.rainbowOffset + phase * 360) % 360;
                        const sat = currentSettings.isRainbowModeEnabled ? currentSettings.rainbowSaturation : 100;

                        ctxFg.strokeStyle = `hsl(${hue}, ${sat}%, 60%)`;
                        ctxFg.lineWidth = 6; 
                        ctxFg.stroke();
                    } else {
                        ctxFg.strokeStyle = 'white';
                        ctxFg.lineWidth = 3;
                        ctxFg.stroke();
                    }

                    const combinedScale = currentSettings.buttonSizeScale * limitScale;
                    if (combinedScale > 0.4) {
                        ctxFg.fillStyle = 'white';
                        let fontSize = Math.max(12, Math.min(22, 16 * combinedScale)) * currentSettings.nodeTextSizeScale;
                        ctxFg.font = `bold ${fontSize}px sans-serif`; 

                        const spacingY = currentSettings.showFractionBar ? 0.55 : 0.50;
                        ctxFg.fillText(node.n.toString(), x, y - (radius * spacingY));
                        if (currentSettings.showFractionBar) {
                            ctxFg.beginPath();
                            ctxFg.moveTo(x - (radius * 0.4), y);
                            ctxFg.lineTo(x + (radius * 0.4), y);
                            ctxFg.lineWidth = 1;
                            ctxFg.strokeStyle = 'white';
                            ctxFg.stroke();
                        }
                        ctxFg.fillText(node.d.toString(), x, y + (radius * spacingY));
                    }
                }
            }

            // DRAW RIPPLES (ALL Modes, Unified Animation)
            // Iterate backwards to allow removal
            const hits = recentHitsRef.current;
            const now = performance.now();
            for (let i = hits.length - 1; i >= 0; i--) {
                const hit = hits[i];
                const age = now - hit.startTime;

                if (age > 1500) {
                    hits.splice(i, 1);
                    continue;
                }

                const nx = hit.x * spacing + centerOffset;
                const ny = hit.y * spacing + centerOffset;

                if (nx < leftBound || nx > rightBound || ny < topBound || ny > bottomBound) continue;

                const vis = currentSettings.limitVisuals?.[hit.limit] || { size: 1 };
                const startRadius = baseRadius * vis.size;

                // Subtle expansion: starts at node edge, goes out by ~50%
                const expansion = age * 0.05; 
                const currentRadius = startRadius + expansion;

                // Extremely subtle opacity: Max 0.15, fades to 0
                const opacity = Math.max(0, 0.15 * (1.0 - (age / 1500)));

                if (opacity > 0) {
                    ctxFg.beginPath();
                    if (isDiamond) {
                        // Diamond Ripple
                        ctxFg.moveTo(nx, ny - currentRadius);
                        ctxFg.lineTo(nx + currentRadius, ny);
                        ctxFg.lineTo(nx, ny + currentRadius);
                        ctxFg.lineTo(nx - currentRadius, ny);
                        ctxFg.closePath();
                    } else {
                        // Circle Ripple
                        ctxFg.arc(nx, ny, currentRadius, 0, Math.PI * 2);
                    }
                    ctxFg.lineWidth = 1.5;
                    ctxFg.strokeStyle = `rgba(255, 255, 255, ${opacity})`;
                    ctxFg.stroke();
                }
            }

            // DRAW CURSOR CONNECTORS (Only if Pitch Bend enabled or not Frozen)
            if (currentCursors.size > 0 && (currentSettings.isPitchBendEnabled || status !== 2)) {
                ctxFg.strokeStyle = 'white';
                ctxFg.lineWidth = 2;
                ctxFg.globalAlpha = 0.5;
                ctxFg.beginPath();
                currentCursors.forEach(c => {
                    const node = nodeMapRef.current.get(c.originNodeId);
                    if(node) {
                        const nx = node.x * spacing + centerOffset;
                        const ny = node.y * spacing + centerOffset;
                        const pos = cursorPositionsRef.current.get(c.pointerId);
                        if (pos) {
                            let cx = 0, cy = 0;
                            if (scrollContainerRef.current) {
                                const r = scrollContainerRef.current.getBoundingClientRect();
                                cx = (pos.x - r.left) + scrollContainerRef.current.scrollLeft;
                                cy = (pos.y - r.top) + scrollContainerRef.current.scrollTop;
                            }
                            ctxFg.moveTo(nx, ny);
                            ctxFg.lineTo(cx, cy);
                        }
                    }
                });
                ctxFg.stroke();
            }

            animationFrameRef.current = requestAnimationFrame(render);
        };

        animationFrameRef.current = requestAnimationFrame(render);
        return () => cancelAnimationFrame(animationFrameRef.current);
    }, []); 

    const rainbowPeriod = getRainbowPeriod(settings.buttonSpacingScale);
    const rainbowBackgroundFixed = useMemo(() => {
        if (settings.isRainbowModeEnabled) {
            const stops: string[] = [];
            const steps = 6;
            for (let i = 0; i <= steps; i++) {
                const pct = (i / steps) * 100;
                const hue = (settings.rainbowOffset + i * 60); 
                stops.push(`hsl(${hue}, ${settings.rainbowSaturation}%, ${settings.rainbowBrightness}%) ${pct}%`);
            }
            return `linear-gradient(to bottom, ${stops.join(', ')})`;
        }
        return undefined;
    }, [settings.isRainbowModeEnabled, settings.rainbowOffset, settings.rainbowSaturation, settings.rainbowBrightness]);

    const bgOffsetY = (dynamicSize / 2) - (rainbowPeriod / 3);

    return (
        <div 
            className="relative"
            style={{ 
                width: dynamicSize, 
                height: dynamicSize,
                backgroundImage: rainbowBackgroundFixed,
                backgroundSize: `100% ${rainbowPeriod}px`,
                backgroundRepeat: 'repeat',
                backgroundPosition: `0px ${bgOffsetY}px`,
                pointerEvents: uiUnlocked ? 'none' : 'auto',
            }}
        >
           {/* Layer 0: Background Dynamic (Reinforced Lines) - z-index 5 */}
           <canvas 
             ref={dynamicBgCanvasRef}
             className="absolute top-0 left-0 z-[5] pointer-events-none"
             style={{ width: '100%', height: '100%' }}
           />

           {/* Layer 1: Static (Background Nodes) - z-index 10 */}
           <canvas 
             ref={staticCanvasRef}
             className="absolute top-0 left-0 z-[10] pointer-events-none"
             style={{ width: '100%', height: '100%' }}
           />

           {/* Layer 2: Foreground Dynamic (Active Elements) - z-index 20 */}
           <canvas 
             ref={dynamicCanvasRef}
             className="absolute top-0 left-0 z-[20]"
             style={{ width: '100%', height: '100%' }}
           />

           {isGenerating && (
             <div className="absolute top-4 right-4 z-50 flex items-center gap-2 bg-slate-900/80 p-2 rounded-full backdrop-blur-sm border border-white/10 shadow-xl">
                 <svg className="animate-spin h-5 w-5 text-blue-500" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                   <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                   <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                 </svg>
                 <span className="text-xs font-bold text-slate-300 pr-2">Calculating...</span>
             </div>
           )}
        </div>
    );
};

