// --- BANK GENERATION HELPERS ---
const generateBank = (bankPrefix: string, bankType: 'pads' | 'leads' | 'bass' | 'keys' | 'mallets'): SynthPreset[] => {
    const presets: SynthPreset[] = [];
    for(let i=1; i<=8; i++) {
        const p = generateInitPatch(`${bankPrefix} ${i}`, `${bankType}-${i}`);
        // Add slight randomization so they aren't identical slots
        if (bankType === 'pads') {
            p.osc1.attack = 0.5 + (i * 0.1);
            p.osc1.release = 1.0 + (i * 0.1);
            p.osc2.enabled = true;
            p.osc2.coarseDetune = (i % 2 === 0) ? 5 : -5;
        } else if (bankType === 'bass') {
            p.osc1.waveform = WaveformType.SAWTOOTH;
            p.osc1.filterCutoff = 300 + (i * 50);
            p.gain = 0.6;
        }
        presets.push(p);
    }
    return presets;
}

