        if(this.panPhase > 1.0) this.panPhase -= 1.0;
        // -1 to 1 sine wave for auto pan
        const autoPanVal = Math.sin(this.panPhase * TWO_PI) * panDepth;

        for (let i = 0; i < this.voices.length; i++) {
            const v = this.voices[i];
            if (v.active) {
                const val = v.process(this.oscConfigs, this.modMatrix, dt);
                if (Number.isFinite(val)) {
                    // Spread + AutoPan Logic
                    // Base pan from spread
                    let p = v.panPos * spreadAmount;

                    // Add global auto-pan
                    p += autoPanVal;

                    // Clamp
                    p = Math.max(-1.0, Math.min(1.0, p));

                    // Linear Pan Power (Simple)
                    const gainL = 0.5 * (1.0 - p);
                    const gainR = 0.5 * (1.0 + p);

                    mixL += val * gainL;
                    mixR += val * gainR;
                } else {
                    v.hardStop();
                }
            }
        }

        // --- GAIN STAGE (PRE-FX) ---
        mixL *= 0.1;
        mixR *= 0.1;

        // --- SOFT CLIPPER (Stereo) ---
        mixL = Math.tanh(mixL * 0.7);
        mixR = Math.tanh(mixR * 0.7);

        // --- DC BLOCKER (Stereo) ---
        // Left
        const yL = mixL - this.xm1L + 0.995 * this.ym1L;
        this.xm1L = mixL;
        this.ym1L = yL;

        // Right
        const yR = mixR - this.xm1R + 0.995 * this.ym1R;
        this.xm1R = mixR;
        this.ym1R = yR;

        channelL[s] = yL;
        if (channelR) channelR[s] = yR;
    }

    const masterGain = this.preset.gain;
    for (let s = 0; s < len; s++) {
        channelL[s] *= masterGain;
        if (channelR) channelR[s] *= masterGain;
    }

    return true;
  }
}

