                                </label>
                                <input 
                                    type="range" min="0" max="360" 
                                    value={settings.rainbowOffset}
                                    onChange={(e) => handleChange('rainbowOffset', parseInt(e.target.value))}
                                    className="w-full h-1 bg-slate-600 rounded-lg appearance-none cursor-pointer"
                                    style={{
                                        backgroundImage: 'linear-gradient(to right, #f00, #ff0, #0f0, #0ff, #00f, #f0f, #f00)'
                                    }}
                                />
                            </div>
                        </div>
                      </div>

                       <div className="bg-slate-900/50 p-4 rounded-lg border border-slate-700 space-y-3">
                         <label className="flex items-center space-x-3 cursor-pointer">
                            <input type="checkbox" checked={settings.isColoredIlluminationEnabled} onChange={(e) => handleChange('isColoredIlluminationEnabled', e.target.checked)} className="w-5 h-5 rounded border-slate-600 text-pink-500 focus:ring-pink-500" />
                            <div>
                                <span className="font-bold text-white block">Colored Illumination</span>
                                <span className="text-xs text-slate-400">Node outline uses pitch-rainbow color when latched</span>
                            </div>
                        </label>

                        <button 
                            onClick={resetColors}
                            className="w-full py-2 bg-slate-700 hover:bg-slate-600 rounded text-xs font-bold text-white transition-colors border border-slate-500/50 mb-2"
                        >
                            Default Colors
                        </button>

                        <button 
                            onClick={pairLimitColors}
                            className="w-full py-2 bg-slate-700 hover:bg-slate-600 rounded text-xs font-bold text-white transition-colors border border-slate-500/50"
                        >
                            Pair Limit Colors with Background
                        </button>
                        <p className="text-[10px] text-slate-400 mt-1">Updates Limit Colors to match the background hue at 1/1, 3/2, 5/4, etc.</p>
                       </div>

                  </div>
               </div>
            )}

            {/* --- MIDI Tab --- */}
            {activeTab === 'midi' && (
                <div className="space-y-8 animate-in fade-in duration-300">
                    <div className="space-y-6">
                        <h3 className="font-semibold text-green-400 border-b border-slate-700 pb-1">MIDI Configuration</h3>

                        <div className="p-4 bg-slate-900/50 rounded-lg border border-slate-700 space-y-4">
                            <label className="flex items-center space-x-3 cursor-pointer">
                                <input 
                                    type="checkbox" 
                                    checked={settings.midiEnabled} 
                                    onChange={(e) => handleChange('midiEnabled', e.target.checked)} 
                                    className="w-6 h-6 rounded border-slate-600 text-green-500 focus:ring-green-500" 
                                />
                                <div>
                                    <span className={`font-bold block ${settings.midiEnabled ? 'text-green-400' : 'text-slate-300'}`}>
                                        Enable MIDI Output
                                    </span>
                                    <span className="text-xs text-slate-400">Send notes to external synths/DAW</span>
                                </div>
                            </label>

                            <div className={`${settings.midiEnabled ? 'opacity-100' : 'opacity-40 pointer-events-none'} transition-opacity space-y-4`}>
                                <div>
                                    <label className="block text-sm font-semibold mb-2">Output Device</label>
                                    <select 
                                        value={settings.midiOutputId || ''}
                                        onChange={(e) => {
                                            const id = e.target.value || null;
                                            handleChange('midiOutputId', id);
                                            midiService.setOutput(id);
                                        }}
                                        className="w-full bg-slate-700 border border-slate-600 rounded p-2 text-white"
                                    >
                                        <option value="">Select MIDI Output...</option>
                                        {midiDevices.map(device => (
                                            <option key={device.id} value={device.id}>{device.name}</option>
                                        ))}
                                    </select>
                                    {midiDevices.length === 0 && (
                                        <p className="text-[10px] text-orange-400 mt-1">No MIDI devices found. Check connection or browser permissions.</p>
                                    )}
                                </div>

                                <div>
                                    <label className="block text-sm font-semibold mb-2">Pitch Bend Range (+/- Semitones)</label>
                                    <p className="text-[10px] text-slate-400 mb-2">
                                        Must match the setting on your external synth for accurate microtonality.
                                        MPE Synths usually default to 48 or 24.
                                    </p>
                                    <div className="flex gap-2">
                                        {[2, 12, 24, 48].map(range => (
                                            <button 
                                                key={range}
                                                onClick={() => handleChange('midiPitchBendRange', range)}
                                                className={`px-3 py-1 rounded text-xs font-bold border ${settings.midiPitchBendRange === range ? 'bg-green-600 border-green-500 text-white' : 'bg-slate-700 border-slate-600 text-slate-400'}`}
                                            >
                                                {range}
                                            </button>
                                        ))}
                                    </div>
                                </div>
                            </div>
                        </div>

                        <div className="p-4 bg-blue-900/20 rounded-lg border border-blue-700/30">
                             <h4 className="text-sm font-bold text-blue-300 mb-2">How it works (MPE Style)</h4>
                             <p className="text-xs text-slate-300 leading-relaxed">
                                PrismaTonal rotates through MIDI Channels 1-16 for every new note trigger. 
                                This allows each touch to have its own independent Pitch Bend message, enabling true polyphonic microtonality.
                                <br/><br/>
                                Ensure your external synth is in <strong>MPE Mode</strong> or set to <strong>Multi-Channel</strong> mode with the same patch loaded on all channels.
                             </p>
                        </div>
                    </div>
                </div>
            )}

        </div>
      </div>
    </div>
  );
};

export default SettingsModal;

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine, ButtonShape } from '../types';
import { getHarmonicDistance, generateLattice } from '../services/LatticeService';
import { getPitchRatioFromScreenDelta, getRainbowPeriod } from '../services/ProjectionService';
import AudioEngine from '../services/AudioEngine';
import { midiService } from '../services/MidiService';

export interface TonalityDiamondHandle {
  clearLatches: () => void;
  centerView: () => void;
  increaseDepth: () => void;
  decreaseDepth: () => void;
  getLatchedNodes: () => LatticeNode[];
}

interface Props {
  settings: AppSettings;
  updateSettings: (s: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) => void;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
  latchMode: 0 | 1 | 2; // 0=Off, 1=LatchAll, 2=Sustain
}

interface ActiveCursor {
  pointerId: number;
  currentX: number;
  currentY: number;
  originNodeId: string | null; // ID if started on a node (Held), Null if started on background (Strum)
  hoverNodeId: string | null;  // Current node under pointer
}

// Spatial Grid Constants
const GRID_CELL_SIZE = 100; // Pixel size of spatial buckets

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, updateSettings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked, latchMode } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);

  // Dual Canvas Strategy
  const staticCanvasRef = useRef<HTMLCanvasElement>(null); 
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null); 

  const animationFrameRef = useRef<number>(0);

  // Data State
  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });
  const [isGenerating, setIsGenerating] = useState(false);

  // Auto-calculated Dimensions
  const [dynamicSize, setDynamicSize] = useState(2000);
  const prevDynamicSizeRef = useRef(2000);

  // Optimization: Memoized Lookups & Spatial Grid
  const nodeMap = useMemo(() => {
      return new Map(data.nodes.map(n => [n.id, n]));
  }, [data.nodes]);

  const spatialGrid = useMemo(() => {
      const grid = new Map<string, LatticeNode[]>();
      const centerOffset = dynamicSize / 2;
      const spacing = settings.buttonSpacingScale;

      data.nodes.forEach(node => {
          const x = node.x * spacing + centerOffset;
          const y = node.y * spacing + centerOffset;

          const col = Math.floor(x / GRID_CELL_SIZE);
          const row = Math.floor(y / GRID_CELL_SIZE);
          const key = `${col},${row}`;

          if (!grid.has(key)) grid.set(key, []);
          grid.get(key)!.push(node);
      });
      return grid;
  }, [data.nodes, settings.buttonSpacingScale, dynamicSize]);

  // Interaction State
  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  const [persistentLatches, setPersistentLatches] = useState<Map<string, string>>(new Map());

  // Computed Effective Latched Nodes (Memoized to prevent render loops)
  // This combines Persistent Latches + Active Chords + Currently Held/Strummed Cursors
  const effectiveLatchedNodes = useMemo(() => {
      const effective = new Map<string, string>(persistentLatches);

      // Add Chords
      activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                if (!effective.has(n.id)) effective.set(n.id, n.id);
            });
        }
      });

      // Add Active Cursors
      activeCursors.forEach(cursor => {
          // CASE 1: Held Note (Pitch Bend Active)
          // If we started on a node, we hold it regardless of where we drag.
          if (cursor.originNodeId) {
              effective.set(cursor.originNodeId, cursor.originNodeId);
          } 
          // CASE 2: Strummed Note (Momentary)
          // If we started on empty space, we play what we hover
          // Only enabled if NOT in Latch Mode 1 (Latch All)
          else if (cursor.hoverNodeId && latchMode !== 1) {
              effective.set(cursor.hoverNodeId, cursor.hoverNodeId);
          }
      });

      return effective;
  }, [persistentLatches, activeChordIds, settings.savedChords, activeCursors, latchMode]);

  // Optimization: Pre-calculate active lines
  const activeLines = useMemo(() => {
    const latched = effectiveLatchedNodes;
    const cursors = activeCursors;
    const lines = data.lines;
    const active: LatticeLine[] = [];

    // We filter out "Purely Strummed" notes from lines to reduce noise.
    // A note is purely strummed if it is NOT persistent, NOT in a chord, and NOT held by a cursor (origin!=null).

    const isStable = (id: string) => {
        if (persistentLatches.has(id)) return true;

        // Check Chords
        const inChord = activeChordIds.some(cid => {
            const c = settings.savedChords.find(ch => ch.id === cid);
            return c?.nodes.some(n => n.id === id);
        });
        if (inChord) return true;

        // Check Held Cursors
        for (const c of cursors.values()) {
            if (c.originNodeId === id) return true;
        }
        return false;
    };

    if (latched.size > 0) {
        for (const line of lines) {
            const s = line.sourceId;
            const t = line.targetId;
            // Only draw lines if BOTH ends are stable (Latched/Held)
            if (latched.has(s) && latched.has(t)) {
                if (isStable(s) && isStable(t)) {
                    active.push(line);
                }
            }
        }
    }
    return active;
  }, [data.lines, effectiveLatchedNodes, activeCursors, persistentLatches, activeChordIds, settings.savedChords]);

  // --- LINE BRIGHTENING LOGIC ---

  // 1. Identify currently held nodes (distinct from latched/strummed)
  const heldNodeIds = useMemo(() => {
      const ids = new Set<string>();
      activeCursors.forEach(c => {
          if (c.originNodeId) ids.add(c.originNodeId);
      });
      return Array.from(ids).sort(); // Stabilize for dependency check
  }, [activeCursors]);

  const heldNodeKey = heldNodeIds.join(',');

  // 2. Compute brightened lines
  const brightenedLines = useMemo(() => {
      if (!settings.lineBrighteningEnabled || heldNodeIds.length === 0) return [];

      const heldSet = new Set(heldNodeIds);
      const resultLines = new Set<LatticeLine>();

      const step1Neighbors = new Set<string>();

      // Step 1 Pass: Find lines connected to held nodes
      data.lines.forEach(line => {
          const sHeld = heldSet.has(line.sourceId);
          const tHeld = heldSet.has(line.targetId);

          if (sHeld || tHeld) {
              resultLines.add(line);
              if (sHeld) step1Neighbors.add(line.targetId);
              if (tHeld) step1Neighbors.add(line.sourceId);
          }
      });

      // Step 2 Pass: Find lines connected to Step 1 neighbors
      if (settings.lineBrighteningSteps === 2) {
          data.lines.forEach(line => {
              if (resultLines.has(line)) return;

              const sNeighbor = step1Neighbors.has(line.sourceId);
              const tNeighbor = step1Neighbors.has(line.targetId);

              // We extend brightness from the neighbors outwards
              if (sNeighbor || tNeighbor) {
                  resultLines.add(line);
              }
          });
      }

      return Array.from(resultLines);
  }, [heldNodeKey, data.lines, settings.lineBrighteningEnabled, settings.lineBrighteningSteps]);

  // Refs for Render Loop
  const settingsRef = useRef(settings);
  const dataRef = useRef(data);
  const activeCursorsRef = useRef<Map<number, ActiveCursor>>(activeCursors);
  const effectiveLatchedRef = useRef(effectiveLatchedNodes);
  const nodeMapRef = useRef(nodeMap);
  const activeLinesRef = useRef(activeLines);
  const brightenedLinesRef = useRef(brightenedLines);
  const spatialGridRef = useRef(spatialGrid);
  const dynamicSizeRef = useRef(dynamicSize);

  const cursorPositionsRef = useRef<Map<number, {x: number, y: number}>>(new Map());

  // Sync Refs
  useEffect(() => { settingsRef.current = settings; }, [settings]);
  useEffect(() => { dataRef.current = data; }, [data]);
  useEffect(() => { activeCursorsRef.current = activeCursors; }, [activeCursors]);
  useEffect(() => { effectiveLatchedRef.current = effectiveLatchedNodes; }, [effectiveLatchedNodes]);
  useEffect(() => { nodeMapRef.current = nodeMap; }, [nodeMap]);
  useEffect(() => { activeLinesRef.current = activeLines; }, [activeLines]);
  useEffect(() => { brightenedLinesRef.current = brightenedLines; }, [brightenedLines]);
  useEffect(() => { spatialGridRef.current = spatialGrid; }, [spatialGrid]);
  useEffect(() => { dynamicSizeRef.current = dynamicSize; }, [dynamicSize]);

  // Interaction State
  const lastTouchedLimitRef = useRef<number | null>(null);
  const depthHistoryRef = useRef<number[]>([]);
  const [hasCentered, setHasCentered] = useState(false);
  const prevActiveChordIds = useRef<string[]>([]);

  // --- External API ---
  useImperativeHandle(ref, () => ({
    clearLatches: () => setPersistentLatches(new Map()),
    centerView: () => {
        centerScroll();
    },
    increaseDepth: () => {
        const limit = lastTouchedLimitRef.current;
        if (limit && limit > 1) {
             updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13];
                 return {
                     ...prev,
                     limitDepths: {
                         ...prev.limitDepths,
                         [limit]: currentDepth + 1
                     }
                 };
             });
             depthHistoryRef.current.push(limit);
        }
    },
    decreaseDepth: () => {
        const limit = depthHistoryRef.current.pop();
        if (limit) {
            updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13];
                 return {
                     ...prev,
                     limitDepths: {
                         ...prev.limitDepths,
                         [limit]: Math.max(0, currentDepth - 1)
                     }
                 };
             });
        }
    },
    getLatchedNodes: () => {
        const result: LatticeNode[] = [];
        effectiveLatchedNodes.forEach((_, id) => {
            const n = nodeMap.get(id);
            if (n) result.push(n);
        });
        return result;
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const center = dynamicSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
      }
  };

  useLayoutEffect(() => {
    const container = scrollContainerRef.current;
    if (!container) return;

    if (!hasCentered && dynamicSize > 0) {
        centerScroll();
        setHasCentered(true);
    } else if (dynamicSize !== prevDynamicSizeRef.current) {
        const diff = (dynamicSize - prevDynamicSizeRef.current) / 2;
        container.scrollLeft += diff;
        container.scrollTop += diff;
    }
    prevDynamicSizeRef.current = dynamicSize;
  }, [dynamicSize]);

  // --- Data Generation ---
  const generationDeps = useMemo(() => {
      return JSON.stringify({
          depths: settings.limitDepths,
          complexities: settings.limitComplexities,
          hidden: settings.hiddenLimits,
          ratio: settings.latticeAspectRatio
      });
  }, [settings.limitDepths, settings.limitComplexities, settings.hiddenLimits, settings.latticeAspectRatio]);

  useEffect(() => {
    setIsGenerating(true);
    const timerId = setTimeout(() => {
        const effectiveSettings: AppSettings = JSON.parse(JSON.stringify(settings));
        const hiddenLimits = effectiveSettings.hiddenLimits || [];
        hiddenLimits.forEach((limit: number) => {
            // @ts-ignore
            if (effectiveSettings.limitDepths[limit] !== undefined) {
                // @ts-ignore
                effectiveSettings.limitDepths[limit] = 0;
            }
        });

        const result = generateLattice(effectiveSettings);
        const visibleNodeIds = new Set(result.nodes.map(n => n.id));
        const visibleLines = result.lines.filter(l => {
            if (hiddenLimits.includes(l.limit)) return false;
            if (!visibleNodeIds.has(l.sourceId) || !visibleNodeIds.has(l.targetId)) return false;
            return true;
        });

        let maxExtent = 0;
        for (const n of result.nodes) {
            const absX = Math.abs(n.x);
            const absY = Math.abs(n.y);
            if (absX > maxExtent) maxExtent = absX;
            if (absY > maxExtent) maxExtent = absY;
        }

        const padding = 600; 
        const spacing = settingsRef.current.buttonSpacingScale; 
        const calculatedSize = (maxExtent * spacing * 2) + padding;
        const finalSize = Math.max(calculatedSize, window.innerWidth, window.innerHeight);

        if (Math.abs(finalSize - dynamicSizeRef.current) > 50) {
            setDynamicSize(finalSize);
        }

        setData({ nodes: result.nodes, lines: visibleLines });
        setIsGenerating(false);
    }, 10);
    return () => clearTimeout(timerId);
  }, [generationDeps]); 

  useEffect(() => {
      let maxExtent = 0;
      for (const n of data.nodes) {
          const absX = Math.abs(n.x);
          const absY = Math.abs(n.y);
          if (absX > maxExtent) maxExtent = absX;
          if (absY > maxExtent) maxExtent = absY;
      }

      const padding = 600; 
      const spacing = settings.buttonSpacingScale;
      const calculatedSize = (maxExtent * spacing * 2) + padding;
      const finalSize = Math.max(calculatedSize, window.innerWidth, window.innerHeight);

      if (Math.abs(finalSize - dynamicSize) > 50) {
          setDynamicSize(finalSize);
      }
  }, [settings.buttonSpacingScale]);


  // --- STATIC CANVAS RENDERER ---
  const visualDeps = useMemo(() => JSON.stringify({
      size: settings.buttonSizeScale,
      spacing: settings.buttonSpacingScale,
      colors: settings.colors,
      visuals: settings.limitVisuals,
      shape: settings.buttonShape,
      textScale: settings.nodeTextSizeScale,
      fractionBar: settings.showFractionBar,
      canvasSize: dynamicSize 
  }), [
      settings.buttonSizeScale,
      settings.buttonSpacingScale,
      settings.colors,
      settings.limitVisuals,
      settings.buttonShape,
      settings.nodeTextSizeScale,
      settings.showFractionBar,
      dynamicSize
  ]);

  useEffect(() => {
      const canvas = staticCanvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d', { alpha: true });
      if (!ctx) return;

      const dpr = window.devicePixelRatio || 1;
      const size = dynamicSize;

      if (canvas.width !== size * dpr || canvas.height !== size * dpr) {
          canvas.width = size * dpr;
          canvas.height = size * dpr;
      }

      ctx.setTransform(1, 0, 0, 1, 0, 0);
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.scale(dpr, dpr);

      const centerOffset = size / 2;
      const spacing = settings.buttonSpacingScale;
      const baseRadius = (60 * settings.buttonSizeScale) / 2;
      const isDiamond = settings.buttonShape === ButtonShape.DIAMOND;

      const linesByLimit: Record<number, number[]> = {};
      for (const line of data.lines) {
          if (!linesByLimit[line.limit]) linesByLimit[line.limit] = [];
          const arr = linesByLimit[line.limit];
          arr.push(
              line.x1 * spacing + centerOffset, 
              line.y1 * spacing + centerOffset, 
              line.x2 * spacing + centerOffset, 
              line.y2 * spacing + centerOffset
          );
      }

      ctx.lineCap = 'round';
      for (const limitStr in linesByLimit) {
          const limit = parseInt(limitStr);
          const coords = linesByLimit[limit];
          const color = settings.colors[limit] || '#666';
          const visualSettings = settings.limitVisuals?.[limit] || { size: 1, opacity: 1 };

          ctx.beginPath();
          for(let i=0; i<coords.length; i+=4) {
              ctx.moveTo(coords[i], coords[i+1]);
              ctx.lineTo(coords[i+2], coords[i+3]);
          }
          ctx.lineWidth = (limit === 1 ? 4 : 2) * visualSettings.size;
          ctx.strokeStyle = color;
          ctx.globalAlpha = 0.3 * visualSettings.opacity; 

          if (limit === 1) ctx.setLineDash([5, 5]);
          else ctx.setLineDash([]);
          ctx.stroke();
      }
      ctx.setLineDash([]); 

      for (const node of data.nodes) {
          const x = node.x * spacing + centerOffset;
          const y = node.y * spacing + centerOffset;
          const cTop = settings.colors[node.limitTop] || '#666';
          const cBottom = settings.colors[node.limitBottom] || '#666';
          const topVis = settings.limitVisuals?.[node.limitTop] || { size: 1, opacity: 1 };
          const limitScale = topVis.size;
          const limitOpacity = topVis.opacity;
          const radius = baseRadius * limitScale;

          ctx.globalAlpha = 1.0 * limitOpacity;

          ctx.beginPath();
          if (isDiamond) {
              ctx.moveTo(x, y - radius);
              ctx.lineTo(x + radius, y);
              ctx.lineTo(x, y + radius);
              ctx.lineTo(x - radius, y);
          } else {
              ctx.arc(x, y, radius, 0, Math.PI * 2);
          }
          ctx.closePath();

          const grad = ctx.createLinearGradient(x, y - radius, x, y + radius);
          grad.addColorStop(0.45, cTop);
          grad.addColorStop(0.55, cBottom);
          ctx.fillStyle = grad;
          ctx.fill();

          const combinedScale = settings.buttonSizeScale * limitScale;
          if (combinedScale > 0.4) {
              ctx.fillStyle = 'white';
              ctx.textAlign = 'center';
              ctx.textBaseline = 'middle';
              let fontSize = Math.max(10, Math.min(18, 14 * combinedScale)) * settings.nodeTextSizeScale;
              ctx.font = `bold ${fontSize}px sans-serif`; 

              const spacingY = settings.showFractionBar ? 0.55 : 0.50;
              const nStr = node.n.toString();
              const dStr = node.d.toString();

              ctx.fillText(nStr, x, y - (radius * spacingY));

              if (settings.showFractionBar) {
                  ctx.beginPath();
                  ctx.moveTo(x - (radius * 0.4), y);
                  ctx.lineTo(x + (radius * 0.4), y);
                  ctx.lineWidth = 1;
                  ctx.strokeStyle = `rgba(255,255,255,${0.8 * limitOpacity})`;
                  ctx.stroke();
              }
              ctx.fillText(dStr, x, y + (radius * spacingY));
          }
      }

  }, [data, visualDeps]); 


  // --- Logic: Latches & Audio Sync ---
  useEffect(() => {
    if (settings.chordsAlwaysRelatch) {
         const newChords = activeChordIds.filter(id => !prevActiveChordIds.current.includes(id));
         if (newChords.length > 0) {
             const nodes = nodeMap;
             newChords.forEach(chordId => {
                 const chordDef = settings.savedChords.find(c => c.id === chordId);
                 if (chordDef) {
                     chordDef.nodes.forEach(n => {
                        const fullNode = nodes.get(n.id);
                        if (fullNode) {
                            audioEngine.startVoice(`node-${n.id}`, fullNode.ratio, settings.baseFrequency);
                            if (settings.midiEnabled) midiService.noteOn(`node-${n.id}`, fullNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
                        }
                     });
                 }
             });
         }
    }
    prevActiveChordIds.current = activeChordIds;
  }, [activeChordIds, settings.savedChords, settings.chordsAlwaysRelatch, nodeMap]);

  const prevEffectiveRef = useRef<Map<string, string>>(new Map());
  useEffect(() => {
      const current = effectiveLatchedNodes;
      const prev = prevEffectiveRef.current;
      const nodes = nodeMap;

      current.forEach((originId, nodeId) => {
          if (!prev.has(nodeId)) {
               const node = nodes.get(nodeId); 
               if (node) {
                   audioEngine.startVoice(`node-${nodeId}`, node.ratio, settings.baseFrequency);
                   if (settings.midiEnabled) midiService.noteOn(`node-${nodeId}`, node.ratio, settings.baseFrequency, settings.midiPitchBendRange);
               }
          }
      });
      prev.forEach((_, nodeId) => {
          if (!current.has(nodeId)) {
              audioEngine.stopVoice(`node-${nodeId}`);
              if (settings.midiEnabled) midiService.noteOff(`node-${nodeId}`);
          }
      });

      prevEffectiveRef.current = current;
  }, [effectiveLatchedNodes, nodeMap, settings.baseFrequency]);

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony]);

  // Helper for Hit Testing
  const getHitNode = (clientX: number, clientY: number): LatticeNode | null => {
      if (!dynamicCanvasRef.current) return null;
      const rect = dynamicCanvasRef.current.getBoundingClientRect();
      const x = clientX - rect.left;
      const y = clientY - rect.top;

      const centerOffset = dynamicSizeRef.current / 2;
      const spacing = settings.buttonSpacingScale;
      const baseRadius = (60 * settings.buttonSizeScale) / 2;

      const col = Math.floor(x / GRID_CELL_SIZE);
      const row = Math.floor(y / GRID_CELL_SIZE);

      const cellsToCheck = [
          `${col},${row}`, `${col+1},${row}`, `${col-1},${row}`,
          `${col},${row+1}`, `${col},${row-1}`,
          `${col+1},${row+1}`, `${col-1},${row-1}`,
          `${col+1},${row-1}`, `${col-1},${row+1}`
      ];

      const grid = spatialGridRef.current;

      for(const key of cellsToCheck) {
          const nodesInCell = grid.get(key);
          if (nodesInCell) {
              for (const node of nodesInCell) {
                  const nx = node.x * spacing + centerOffset;
                  const ny = node.y * spacing + centerOffset;
                  const vis = settings.limitVisuals?.[node.limitTop] || { size: 1 };
                  const r = baseRadius * vis.size;

                  if (x < nx - r || x > nx + r || y < ny - r || y > ny + r) continue;

                  const dx = x - nx;
                  const dy = y - ny;
                  if (dx*dx + dy*dy < r*r) {
                      return node;
                  }
              }
          }
      }
      return null;
  };

  // --- Interaction Handlers ---
  const handlePointerDown = (e: React.PointerEvent) => {
      if (uiUnlocked || !dynamicCanvasRef.current) return;
      e.preventDefault();
      (e.target as HTMLElement).setPointerCapture(e.pointerId);

      cursorPositionsRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });

      const hitNode = getHitNode(e.clientX, e.clientY);
      const nodeId = hitNode ? hitNode.id : null;

      // Stop Strumming initiation if in Latch Mode 1 (Latch All)
      if (!hitNode && latchMode === 1) {
          return;
      }

      // Track cursor logic
      setActiveCursors(prev => {
          const next = new Map(prev);
          next.set(e.pointerId, {
              pointerId: e.pointerId,
              currentX: e.clientX,
              currentY: e.clientY,
              originNodeId: nodeId, // Where we started
              hoverNodeId: nodeId   // Where we are now
          });
          return next;
      });

      if (hitNode) {
        // Limit expansion logic
        const topLayer = settings.layerOrder[settings.layerOrder.length - 1];
        if (hitNode.maxPrime !== topLayer) {
             onLimitInteraction(hitNode.maxPrime);
        }
        lastTouchedLimitRef.current = hitNode.maxPrime;

        // Latch Mode Logic (Persistent Toggles)
        // Mode 1: Latch All (Toggle)
        if (latchMode === 1) {
             setPersistentLatches(prev => {
                 const next = new Map(prev);
                 if (next.has(hitNode.id)) next.delete(hitNode.id);
                 else next.set(hitNode.id, hitNode.id);
                 return next;
             });
        }

        if (settings.isPitchBendEnabled && latchMode !== 1) {
            audioEngine.startVoice(`cursor-${e.pointerId}`, hitNode.ratio, settings.baseFrequency);
            if (settings.midiEnabled) midiService.noteOn(`cursor-${e.pointerId}`, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
        }
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (uiUnlocked) return;
    if (!activeCursorsRef.current.has(e.pointerId)) return;

    cursorPositionsRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });

    const cursor = activeCursorsRef.current.get(e.pointerId)!;

    // DECISION: Are we Holding (Pitch Bending) or Strumming?

    if (cursor.originNodeId) {
        // --- HELD NOTE (Started on Node) ---
        // We are locked to the origin note.
        // Logic: Calculate Pitch Bend. Do NOT strum other notes.

        if (settings.isPitchBendEnabled && latchMode !== 1 && scrollContainerRef.current) {
             const centerOffset = dynamicSizeRef.current / 2;
             const rect = scrollContainerRef.current.getBoundingClientRect();

             // Get Origin Node Position
             const originNode = nodeMapRef.current.get(cursor.originNodeId);
             if (originNode) {
                 const spacing = settings.buttonSpacingScale;
                 const originScreenY = (originNode.y * spacing + centerOffset) + rect.top - scrollContainerRef.current.scrollTop;

                 // Delta Y on Screen
                 const deltaY = e.clientY - originScreenY;

                 // Apply Pitch Bend
                 const bentRatio = getPitchRatioFromScreenDelta(deltaY, settings.buttonSpacingScale);
                 const finalRatio = originNode.ratio * bentRatio;

                 audioEngine.glideVoice(`cursor-${e.pointerId}`, finalRatio, settings.baseFrequency, 0.05);
                 if (settings.midiEnabled) midiService.pitchBend(`cursor-${e.pointerId}`, finalRatio, settings.baseFrequency, settings.midiPitchBendRange);
             }
        }
    } else {
        // --- STRUMMING (Started on Empty) ---
        // Logic: Momentarily trigger nodes we hover over.
        // Ignored in Latch Mode 1.

        if (latchMode === 1) return;

        const hitNode = getHitNode(e.clientX, e.clientY);
        const hitId = hitNode ? hitNode.id : null;

        if (cursor.hoverNodeId !== hitId) {
            // Trigger Limit Expansion if needed
            if (hitNode) {
                 const topLayer = settingsRef.current.layerOrder[settingsRef.current.layerOrder.length - 1];
                 if (hitNode.maxPrime !== topLayer) {
                     onLimitInteraction(hitNode.maxPrime);
                 }
            }

            // Update Cursor State safely
            setActiveCursors((prev: Map<number, ActiveCursor>) => {
                const next = new Map(prev);
                const existing = next.get(e.pointerId);
                if (existing) {
                    const c = { ...existing }; // Clone to avoid mutation of previous state
                    c.hoverNodeId = hitId;
                    next.set(e.pointerId, c);
                    return next;
                }
                return prev;
            });
        }
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursorsRef.current.has(e.pointerId)) {
        const cursor = activeCursorsRef.current.get(e.pointerId)!;

        // Stop Pitch Bend Voice if it exists (only for Held notes)
        if (cursor.originNodeId && latchMode !== 1) {
            audioEngine.stopVoice(`cursor-${e.pointerId}`);
            if (settings.midiEnabled) midiService.noteOff(`cursor-${e.pointerId}`);
        }

        cursorPositionsRef.current.delete(e.pointerId);

        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            return next;
        });
    }
  };

  // --- Animation Loop ---
  useEffect(() => {
    const canvas = dynamicCanvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: true });
    if (!ctx) return;

    const dpr = window.devicePixelRatio || 1;

    const render = (time: number) => {
        const currentSettings = settingsRef.current;
        const currentLatched = effectiveLatchedRef.current;
        const currentActiveLines = activeLinesRef.current;
        const currentBrightenedLines = brightenedLinesRef.current;
        const size = dynamicSizeRef.current;
        const cursors = activeCursorsRef.current;

        if (canvas.width !== size * dpr || canvas.height !== size * dpr) {
            canvas.width = size * dpr;
            canvas.height = size * dpr;
            ctx.scale(dpr, dpr);
        }

        let viewX = 0, viewY = 0, viewW = size, viewH = size;
        if (scrollContainerRef.current) {
            viewX = scrollContainerRef.current.scrollLeft;
            viewY = scrollContainerRef.current.scrollTop;
            viewW = scrollContainerRef.current.clientWidth;
            viewH = scrollContainerRef.current.clientHeight;
        }

        ctx.clearRect(viewX, viewY, viewW, viewH);

        const centerOffset = size / 2;
        const spacing = currentSettings.buttonSpacingScale;
        const baseRadius = (60 * currentSettings.buttonSizeScale) / 2;
        const isDiamond = currentSettings.buttonShape === ButtonShape.DIAMOND;
        const colorCache = currentSettings.colors;

        const animationSpeed = (currentSettings.voiceLeadingAnimationSpeed || 2.0) * 0.33;
        const rawPhase = (time * 0.001 * animationSpeed);
        const flowPhase = currentSettings.voiceLeadingReverseDir ? (1.0 - (rawPhase % 1.0)) : (rawPhase % 1.0);

        ctx.lineCap = 'round';

        const viewPad = 100;
        const leftBound = viewX - viewPad;
        const rightBound = viewX + viewW + viewPad;
        const topBound = viewY - viewPad;
        const bottomBound = viewY + viewH + viewPad;

        // --- DRAW BRIGHTENED LINES (Held Notes Reach) ---
        if (currentBrightenedLines.length > 0) {
            ctx.setLineDash([]);
            for (const line of currentBrightenedLines) {
                const x1 = line.x1 * spacing + centerOffset;
                const y1 = line.y1 * spacing + centerOffset;
                const x2 = line.x2 * spacing + centerOffset;
                const y2 = line.y2 * spacing + centerOffset;

                if (Math.max(x1, x2) < leftBound || Math.min(x1, x2) > rightBound || Math.max(y1, y2) < topBound || Math.min(y1, y2) > bottomBound) continue;

                const limitColor = colorCache[line.limit] || '#666';

                ctx.beginPath();
                ctx.moveTo(x1, y1);
                ctx.lineTo(x2, y2);
                ctx.lineWidth = 2;
                ctx.strokeStyle = limitColor;
                ctx.globalAlpha = 0.8; // Bright but static
                ctx.stroke();
            }
        }

        // --- DRAW ACTIVE VOICE LEADING LINES ---
        ctx.setLineDash([]); 
        for (const line of currentActiveLines) {
            const x1 = line.x1 * spacing + centerOffset;
            const y1 = line.y1 * spacing + centerOffset;
            const x2 = line.x2 * spacing + centerOffset;
            const y2 = line.y2 * spacing + centerOffset;

            if (Math.max(x1, x2) < leftBound || Math.min(x1, x2) > rightBound || Math.max(y1, y2) < topBound || Math.min(y1, y2) > bottomBound) continue;

            const limitColor = colorCache[line.limit] || '#666';

            ctx.beginPath();
            ctx.moveTo(x1, y1);
            ctx.lineTo(x2, y2);
            ctx.lineWidth = 4;
            ctx.strokeStyle = limitColor;
            ctx.globalAlpha = 1.0;
            ctx.stroke();

            if (currentSettings.isVoiceLeadingAnimationEnabled) {
                const grad = ctx.createLinearGradient(x1, y1, x2, y2);
                const p = flowPhase;

                grad.addColorStop(0, 'rgba(255,255,255,0)');
                const pulseWidth = 0.2;
                const start = Math.max(0, p - pulseWidth);
                const end = Math.min(1, p + pulseWidth);
                if (start > 0) grad.addColorStop(start, 'rgba(255,255,255,0)');
                grad.addColorStop(p, 'rgba(255,255,255,0.7)'); 
                if (end < 1) grad.addColorStop(end, 'rgba(255,255,255,0)');
                grad.addColorStop(1, 'rgba(255,255,255,0)');

                ctx.strokeStyle = grad;

                ctx.lineWidth = 10 * (0.5 + currentSettings.voiceLeadingGlowAmount);
                ctx.globalAlpha = 0.3; 
                ctx.stroke();

                ctx.lineWidth = 4;
                ctx.globalAlpha = 1.0;
                ctx.stroke();
            }
        }

        // --- DRAW ACTIVE NODES ---
        for (const id of currentLatched.keys()) {
             const node = nodeMapRef.current.get(id);
             if (!node) continue;

             const x = node.x * spacing + centerOffset;
             const y = node.y * spacing + centerOffset;

             if (x < leftBound || x > rightBound || y < topBound || y > bottomBound) continue;

             const cTop = colorCache[node.limitTop] || '#666';
             const cBottom = colorCache[node.limitBottom] || '#666';

             const vis = currentSettings.limitVisuals?.[node.limitTop] || { size: 1 };
             const limitScale = vis.size;
             const zoomScale = currentSettings.latchedZoomScale;
             const radius = baseRadius * limitScale * zoomScale;

             ctx.globalAlpha = 1.0; 
             ctx.beginPath();
             if (isDiamond) {
                ctx.moveTo(x, y - radius);
                ctx.lineTo(x + radius, y);
                ctx.lineTo(x, y + radius);
                ctx.lineTo(x - radius, y);
             } else {
                ctx.arc(x, y, radius, 0, Math.PI * 2);
             }
             ctx.closePath();

             const grad = ctx.createLinearGradient(x, y - radius, x, y + radius);
             grad.addColorStop(0.45, cTop);
             grad.addColorStop(0.55, cBottom);
             ctx.fillStyle = grad;
             ctx.fill();

             if (currentSettings.isColoredIlluminationEnabled) {
                 const rainbowPeriod = getRainbowPeriod(spacing); // Use Helper
                 const phase = (y % rainbowPeriod) / rainbowPeriod;
                 const hue = (currentSettings.rainbowOffset + phase * 360) % 360;
                 const sat = currentSettings.isRainbowModeEnabled ? currentSettings.rainbowSaturation : 100;
                 ctx.strokeStyle = `hsl(${hue}, ${sat}%, 60%)`;
                 ctx.lineWidth = 4;
                 ctx.stroke();
             } else {
                 ctx.strokeStyle = 'white';
                 ctx.lineWidth = 3;
                 ctx.stroke();
             }

             const combinedScale = currentSettings.buttonSizeScale * limitScale * zoomScale;
             if (combinedScale > 0.4) {
                ctx.fillStyle = 'white';
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                let fontSize = Math.max(12, Math.min(22, 16 * combinedScale)) * currentSettings.nodeTextSizeScale;
                ctx.font = `bold ${fontSize}px sans-serif`; 
                const spacingY = currentSettings.showFractionBar ? 0.55 : 0.50;
                ctx.fillText(node.n.toString(), x, y - (radius * spacingY));
                if (currentSettings.showFractionBar) {
                    ctx.beginPath();
                    ctx.moveTo(x - (radius * 0.4), y);
                    ctx.lineTo(x + (radius * 0.4), y);
                    ctx.lineWidth = 1;
                    ctx.strokeStyle = 'white';
                    ctx.stroke();
                }
                ctx.fillText(node.d.toString(), x, y + (radius * spacingY));
             }
        }

        // Draw drag lines for PITCH BEND (Only held notes)
        cursors.forEach(c => {
            if (c.originNodeId) { // If held
                const node = nodeMapRef.current.get(c.originNodeId);
                if(node) {
                     const nx = node.x * spacing + centerOffset;
                     const ny = node.y * spacing + centerOffset;
                     const pos = cursorPositionsRef.current.get(c.pointerId);
                     if (!pos) return;

                     let cx = 0, cy = 0;
                     if (scrollContainerRef.current) {
                         const r = scrollContainerRef.current.getBoundingClientRect();
                         cx = (pos.x - r.left) + scrollContainerRef.current.scrollLeft;
                         cy = (pos.y - r.top) + scrollContainerRef.current.scrollTop;
                     }

                     ctx.beginPath();
                     ctx.moveTo(nx, ny);
                     ctx.lineTo(cx, cy);
                     ctx.strokeStyle = 'white';
                     ctx.lineWidth = 2;
                     ctx.globalAlpha = 0.5;
                     ctx.stroke();
                }
            }
        });

        animationFrameRef.current = requestAnimationFrame(render);
    };

    animationFrameRef.current = requestAnimationFrame(render);
    return () => cancelAnimationFrame(animationFrameRef.current);
  }, []); 

  const rainbowPeriod = getRainbowPeriod(settings.buttonSpacingScale);

  const rainbowBackgroundFixed = useMemo(() => {
    if (settings.isRainbowModeEnabled) {
        const stops: string[] = [];
        const steps = 6;
        for (let i = 0; i <= steps; i++) {
            const pct = (i / steps) * 100;
            const hue = (settings.rainbowOffset + i * 60); 
            stops.push(`hsl(${hue}, ${settings.rainbowSaturation}%, ${settings.rainbowBrightness}%) ${pct}%`);
        }
        return `linear-gradient(to bottom, ${stops.join(', ')})`;
    }
    return undefined;
  }, [settings.isRainbowModeEnabled, settings.rainbowOffset, settings.rainbowSaturation, settings.rainbowBrightness]);

  const bgOffsetY = (dynamicSize / 2) - (rainbowPeriod / 3);

  return (
    <div 
        ref={scrollContainerRef}
        className="w-full h-full overflow-auto bg-slate-950 relative"
        style={{ touchAction: 'none' }}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerLeave={handlePointerUp}
        onPointerCancel={handlePointerUp}
    >
        <div 
            className="relative"
            style={{ 
                width: dynamicSize, 
                height: dynamicSize,
                backgroundImage: rainbowBackgroundFixed,
                backgroundSize: `100% ${rainbowPeriod}px`,
                backgroundRepeat: 'repeat',
                backgroundPosition: `0px ${bgOffsetY}px`,
                pointerEvents: uiUnlocked ? 'none' : 'auto',
            }}
        >
           <canvas 
             ref={staticCanvasRef}
             className="absolute top-0 left-0 z-0 pointer-events-none"
             style={{ width: '100%', height: '100%' }}
           />
           <canvas 
             ref={dynamicCanvasRef}
             className="absolute top-0 left-0 z-10"
             style={{ width: '100%', height: '100%' }}
           />

           {isGenerating && (
             <div className="absolute top-4 right-4 z-50 flex items-center gap-2 bg-slate-900/80 p-2 rounded-full backdrop-blur-sm border border-white/10 shadow-xl">
                 <svg className="animate-spin h-5 w-5 text-blue-500" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                   <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                   <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                 </svg>
                 <span className="text-xs font-bold text-slate-300 pr-2">Calculating...</span>
             </div>
           )}
        </div>
    </div>
  );
});

export default React.memo(TonalityDiamond);

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine, ButtonShape } from '../types';
import { getHarmonicDistance, generateLattice } from '../services/LatticeService';
import { getPitchRatioFromScreenDelta, getRainbowPeriod } from '../services/ProjectionService';
import AudioEngine from '../services/AudioEngine';
import { midiService } from '../services/MidiService';

export interface TonalityDiamondHandle {
  clearLatches: () => void;
  centerView: () => void;
  increaseDepth: () => void;
  decreaseDepth: () => void;
  getLatchedNodes: () => LatticeNode[];
}

interface Props {
  settings: AppSettings;
  updateSettings: (s: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) => void;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
  latchMode: 0 | 1 | 2; // 0=Off, 1=LatchAll, 2=Sustain
}

interface ActiveCursor {
  pointerId: number;
  currentX: number;
  currentY: number;
  originNodeId: string | null; // ID if started on a node (Held), Null if started on background (Strum)
  hoverNodeId: string | null;  // Current node under pointer
}

// Spatial Grid Constants
const GRID_CELL_SIZE = 100; // Pixel size of spatial buckets

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, updateSettings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked, latchMode } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);

  // Dual Canvas Strategy
  const staticCanvasRef = useRef<HTMLCanvasElement>(null); 
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null); 

  const animationFrameRef = useRef<number>(0);

  // Data State
  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });
  const [isGenerating, setIsGenerating] = useState(false);

  // Auto-calculated Dimensions
  const [dynamicSize, setDynamicSize] = useState(2000);
  const prevDynamicSizeRef = useRef(2000);

  // Optimization: Memoized Lookups & Spatial Grid
  const nodeMap = useMemo(() => {
      return new Map(data.nodes.map(n => [n.id, n]));
  }, [data.nodes]);

  const spatialGrid = useMemo(() => {
      const grid = new Map<string, LatticeNode[]>();
      const centerOffset = dynamicSize / 2;
      const spacing = settings.buttonSpacingScale;

      data.nodes.forEach(node => {
          const x = node.x * spacing + centerOffset;
          const y = node.y * spacing + centerOffset;

          const col = Math.floor(x / GRID_CELL_SIZE);
          const row = Math.floor(y / GRID_CELL_SIZE);
          const key = `${col},${row}`;

          if (!grid.has(key)) grid.set(key, []);
          grid.get(key)!.push(node);
      });
      return grid;
  }, [data.nodes, settings.buttonSpacingScale, dynamicSize]);

  // Interaction State
  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  const [persistentLatches, setPersistentLatches] = useState<Map<string, string>>(new Map());

  // Computed Effective Latched Nodes
  // This is the source of truth for audio and visuals
  const effectiveLatchedNodes = useMemo(() => {
      const effective = new Map<string, string>(persistentLatches);

      // Add Chords
      activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                if (!effective.has(n.id)) effective.set(n.id, n.id);
            });
        }
      });

      // Add Active Cursors
      activeCursors.forEach(cursor => {
          // Held Note
          if (cursor.originNodeId) {
              effective.set(cursor.originNodeId, cursor.originNodeId);
          } 
          // Strummed Note (Only if NOT in Latch Mode 1)
          // In Latch Mode 1, mouse-over adds to persistent, so we don't need this temporary state.
          else if (cursor.hoverNodeId && latchMode !== 1) {
              effective.set(cursor.hoverNodeId, cursor.hoverNodeId);
          }
      });

      return effective;
  }, [persistentLatches, activeChordIds, settings.savedChords, activeCursors, latchMode]);

  // --- ACTIVE GRID LINES (Direct Neighbors) ---
  const activeLines = useMemo(() => {
    const latched = effectiveLatchedNodes;
    const cursors = activeCursors;
    const lines = data.lines;
    const active: LatticeLine[] = [];

    // Filter out purely strummed notes to avoid visual clutter during rapid movement
    const isStable = (id: string) => {
        if (persistentLatches.has(id)) return true;
        // Check Chords
        const inChord = activeChordIds.some(cid => {
            const c = settings.savedChords.find(ch => ch.id === cid);
            return c?.nodes.some(n => n.id === id);
        });
        if (inChord) return true;
        // Check Held Cursors
        for (const c of cursors.values()) {
            if (c.originNodeId === id) return true;
        }
        // In Latch Mode 1, everything in effective is stable
        if (latchMode === 1) return true;

        return false;
    };

    if (latched.size > 0) {
        for (const line of lines) {
            const s = line.sourceId;
            const t = line.targetId;
            if (latched.has(s) && latched.has(t)) {
                if (isStable(s) && isStable(t)) {
                    active.push(line);
                }
            }
        }
    }
    return active;
  }, [data.lines, effectiveLatchedNodes, activeCursors, persistentLatches, activeChordIds, latchMode]);

  // --- LINE BRIGHTENING LOGIC (Neighbors of Active) ---
  // Now includes ALL active nodes, not just held cursors.
  const brightenedLines = useMemo(() => {
      if (!settings.lineBrighteningEnabled || effectiveLatchedNodes.size === 0) return [];

      const activeIds = new Set(effectiveLatchedNodes.keys());
      const resultLines = new Set<LatticeLine>();
      const step1Neighbors = new Set<string>();

      // Step 1: Lines connected to any active node
      data.lines.forEach(line => {
          const sActive = activeIds.has(line.sourceId);
          const tActive = activeIds.has(line.targetId);

          if (sActive || tActive) {
              resultLines.add(line);
              if (sActive) step1Neighbors.add(line.targetId);
              if (tActive) step1Neighbors.add(line.sourceId);
          }
      });

      // Step 2: Lines connected to Step 1 neighbors
      if (settings.lineBrighteningSteps === 2) {
          data.lines.forEach(line => {
              if (resultLines.has(line)) return;
              const sNeighbor = step1Neighbors.has(line.sourceId);
              const tNeighbor = step1Neighbors.has(line.targetId);
              if (sNeighbor || tNeighbor) {
                  resultLines.add(line);
              }
          });
      }

      return Array.from(resultLines);
  }, [effectiveLatchedNodes, data.lines, settings.lineBrighteningEnabled, settings.lineBrighteningSteps]);

  // --- DYNAMIC HARMONIC LINES (Partials Recognition) ---
  // Calculates non-grid connections between active nodes based on harmonic relationships
  const dynamicHarmonicLines = useMemo(() => {
      if (effectiveLatchedNodes.size < 2) return [];

      const nodes = Array.from(effectiveLatchedNodes.keys()).map(id => nodeMap.get(id)).filter(n => n !== undefined) as LatticeNode[];
      const dynamicLines: { x1: number, y1: number, x2: number, y2: number, color: string, reverse: boolean }[] = [];
      const processedPairs = new Set<string>();

      for (let i = 0; i < nodes.length; i++) {
          for (let j = i + 1; j < nodes.length; j++) {
              const A = nodes[i];
              const B = nodes[j];

              // Sort by frequency to simplify Otonal/Utonal logic (Source -> Target)
              // We treat the Lower Pitch as the potential "Fundamental"
              const [Low, High] = A.ratio <= B.ratio ? [A, B] : [B, A];

              // Calculate Interval Ratio (High / Low)
              // Note: We need integer ratio components to detect primes.
              // A.n/A.d and B.n/B.d. Ratio = (B.n * A.d) / (B.d * A.n)
              const num = High.n * Low.d;
              const den = High.d * Low.n;

              // Simplify fraction to finding prime factors
              // We don't need to fully reduce if we check divisibility, but reducing helps avoid composites
              // Helper to check prime factors
              const checkPrime = (val: number, p: number) => {
                  let v = val;
                  if (v % p !== 0) return false;
                  // Must not be just a power of p mixed with others, simply containing p is enough for "coloring"
                  return true;
              };

              [3, 5, 7, 11, 13].forEach(prime => {
                  const color = settings.colors[prime];

                  // OTONAL RELATIONSHIP (Generation)
                  // If Numerator contains Prime: The interval has generated 'up' via that prime.
                  // Flow: Low -> High
                  if (checkPrime(num, prime)) {
                      dynamicLines.push({
                          x1: Low.x, y1: Low.y,
                          x2: High.x, y2: High.y,
                          color: color,
                          reverse: false // Forward flow
                      });
                  }

                  // UTONAL RELATIONSHIP (Return/Undertone)
                  // If Denominator contains Prime: The interval suggests High is a 'reciprocal' or Low is generated 'down'.
                  // Flow: High -> Low
                  if (checkPrime(den, prime)) {
                      dynamicLines.push({
                          x1: Low.x, y1: Low.y,
                          x2: High.x, y2: High.y,
                          color: color,
                          reverse: true // Backward flow (High to Low)
                      });
                  }
              });
          }
      }
      return dynamicLines;
  }, [effectiveLatchedNodes, nodeMap, settings.colors]);

  // Refs for Render Loop
  const settingsRef = useRef(settings);
  const dataRef = useRef(data);
  const activeCursorsRef = useRef<Map<number, ActiveCursor>>(activeCursors);
  const effectiveLatchedRef = useRef(effectiveLatchedNodes);
  const nodeMapRef = useRef(nodeMap);
  const activeLinesRef = useRef(activeLines);
  const brightenedLinesRef = useRef(brightenedLines);
  const dynamicHarmonicLinesRef = useRef(dynamicHarmonicLines);
  const spatialGridRef = useRef(spatialGrid);
  const dynamicSizeRef = useRef(dynamicSize);

  const cursorPositionsRef = useRef<Map<number, {x: number, y: number}>>(new Map());

  // Sync Refs
  useEffect(() => { settingsRef.current = settings; }, [settings]);
  useEffect(() => { dataRef.current = data; }, [data]);
  useEffect(() => { activeCursorsRef.current = activeCursors; }, [activeCursors]);
  useEffect(() => { effectiveLatchedRef.current = effectiveLatchedNodes; }, [effectiveLatchedNodes]);
  useEffect(() => { nodeMapRef.current = nodeMap; }, [nodeMap]);
  useEffect(() => { activeLinesRef.current = activeLines; }, [activeLines]);
  useEffect(() => { brightenedLinesRef.current = brightenedLines; }, [brightenedLines]);
  useEffect(() => { dynamicHarmonicLinesRef.current = dynamicHarmonicLines; }, [dynamicHarmonicLines]);
  useEffect(() => { spatialGridRef.current = spatialGrid; }, [spatialGrid]);
  useEffect(() => { dynamicSizeRef.current = dynamicSize; }, [dynamicSize]);

  // Interaction State
  const lastTouchedLimitRef = useRef<number | null>(null);
  const depthHistoryRef = useRef<number[]>([]);
  const [hasCentered, setHasCentered] = useState(false);
  const prevActiveChordIds = useRef<string[]>([]);

  // --- External API ---
  useImperativeHandle(ref, () => ({
    clearLatches: () => setPersistentLatches(new Map()),
    centerView: () => { centerScroll(); },
    increaseDepth: () => {
        const limit = lastTouchedLimitRef.current;
        if (limit && limit > 1) {
             updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: currentDepth + 1 } };
             });
             depthHistoryRef.current.push(limit);
        }
    },
    decreaseDepth: () => {
        const limit = depthHistoryRef.current.pop();
        if (limit) {
            updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: Math.max(0, currentDepth - 1) } };
             });
        }
    },
    getLatchedNodes: () => {
        const result: LatticeNode[] = [];
        effectiveLatchedNodes.forEach((_, id) => {
            const n = nodeMap.get(id);
            if (n) result.push(n);
        });
        return result;
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const center = dynamicSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
      }
  };

  useLayoutEffect(() => {
    const container = scrollContainerRef.current;
    if (!container) return;
    if (!hasCentered && dynamicSize > 0) {
        centerScroll();
        setHasCentered(true);
    } else if (dynamicSize !== prevDynamicSizeRef.current) {
        const diff = (dynamicSize - prevDynamicSizeRef.current) / 2;
        container.scrollLeft += diff;
        container.scrollTop += diff;
    }
    prevDynamicSizeRef.current = dynamicSize;
  }, [dynamicSize]);

  // --- Data Generation ---
  const generationDeps = useMemo(() => {
      return JSON.stringify({
          depths: settings.limitDepths,
          complexities: settings.limitComplexities,
          hidden: settings.hiddenLimits,
          ratio: settings.latticeAspectRatio
      });
  }, [settings.limitDepths, settings.limitComplexities, settings.hiddenLimits, settings.latticeAspectRatio]);

  useEffect(() => {
    setIsGenerating(true);
    const timerId = setTimeout(() => {
        const effectiveSettings: AppSettings = JSON.parse(JSON.stringify(settings));
        const hiddenLimits = effectiveSettings.hiddenLimits || [];
        hiddenLimits.forEach((limit: number) => {
            // @ts-ignore
            if (effectiveSettings.limitDepths[limit] !== undefined) effectiveSettings.limitDepths[limit] = 0;
        });

        const result = generateLattice(effectiveSettings);
        const visibleNodeIds = new Set(result.nodes.map(n => n.id));
        const visibleLines = result.lines.filter(l => {
            if (hiddenLimits.includes(l.limit)) return false;
            if (!visibleNodeIds.has(l.sourceId) || !visibleNodeIds.has(l.targetId)) return false;
            return true;
        });

        let maxExtent = 0;
        for (const n of result.nodes) {
            const absX = Math.abs(n.x);
            const absY = Math.abs(n.y);
            if (absX > maxExtent) maxExtent = absX;
            if (absY > maxExtent) maxExtent = absY;
        }

        const padding = 600; 
        const spacing = settingsRef.current.buttonSpacingScale; 
        const calculatedSize = (maxExtent * spacing * 2) + padding;
        const finalSize = Math.max(calculatedSize, window.innerWidth, window.innerHeight);

        if (Math.abs(finalSize - dynamicSizeRef.current) > 50) {
            setDynamicSize(finalSize);
        }

        setData({ nodes: result.nodes, lines: visibleLines });
        setIsGenerating(false);
    }, 10);
    return () => clearTimeout(timerId);
  }, [generationDeps]); 

  useEffect(() => {
      let maxExtent = 0;
      for (const n of data.nodes) {
          const absX = Math.abs(n.x);
          const absY = Math.abs(n.y);
          if (absX > maxExtent) maxExtent = absX;
          if (absY > maxExtent) maxExtent = absY;
      }
      const padding = 600; 
      const spacing = settings.buttonSpacingScale;
      const calculatedSize = (maxExtent * spacing * 2) + padding;
      const finalSize = Math.max(calculatedSize, window.innerWidth, window.innerHeight);
      if (Math.abs(finalSize - dynamicSize) > 50) setDynamicSize(finalSize);
  }, [settings.buttonSpacingScale]);


  // --- STATIC CANVAS RENDERER ---
  const visualDeps = useMemo(() => JSON.stringify({
      size: settings.buttonSizeScale,
      spacing: settings.buttonSpacingScale,
      colors: settings.colors,
      visuals: settings.limitVisuals,
      shape: settings.buttonShape,
      textScale: settings.nodeTextSizeScale,
      fractionBar: settings.showFractionBar,
      canvasSize: dynamicSize 
  }), [settings.buttonSizeScale, settings.buttonSpacingScale, settings.colors, settings.limitVisuals, settings.buttonShape, settings.nodeTextSizeScale, settings.showFractionBar, dynamicSize]);

  useEffect(() => {
      const canvas = staticCanvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d', { alpha: true });
      if (!ctx) return;

      const dpr = window.devicePixelRatio || 1;
      const size = dynamicSize;

      if (canvas.width !== size * dpr || canvas.height !== size * dpr) {
          canvas.width = size * dpr;
          canvas.height = size * dpr;
      }

      ctx.setTransform(1, 0, 0, 1, 0, 0);
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.scale(dpr, dpr);

      const centerOffset = size / 2;
      const spacing = settings.buttonSpacingScale;
      const baseRadius = (60 * settings.buttonSizeScale) / 2;
      const isDiamond = settings.buttonShape === ButtonShape.DIAMOND;

      const linesByLimit: Record<number, number[]> = {};
      for (const line of data.lines) {
          if (!linesByLimit[line.limit]) linesByLimit[line.limit] = [];
          const arr = linesByLimit[line.limit];
          arr.push(line.x1 * spacing + centerOffset, line.y1 * spacing + centerOffset, line.x2 * spacing + centerOffset, line.y2 * spacing + centerOffset);
      }

      ctx.lineCap = 'round';
      for (const limitStr in linesByLimit) {
          const limit = parseInt(limitStr);
          const coords = linesByLimit[limit];
          const color = settings.colors[limit] || '#666';
          const visualSettings = settings.limitVisuals?.[limit] || { size: 1, opacity: 1 };

          ctx.beginPath();
          for(let i=0; i<coords.length; i+=4) {
              ctx.moveTo(coords[i], coords[i+1]);
              ctx.lineTo(coords[i+2], coords[i+3]);
          }
          ctx.lineWidth = (limit === 1 ? 4 : 2) * visualSettings.size;
          ctx.strokeStyle = color;
          ctx.globalAlpha = 0.3 * visualSettings.opacity; 

          if (limit === 1) ctx.setLineDash([5, 5]);
          else ctx.setLineDash([]);
          ctx.stroke();
      }
      ctx.setLineDash([]); 

      for (const node of data.nodes) {
          const x = node.x * spacing + centerOffset;
          const y = node.y * spacing + centerOffset;
          const cTop = settings.colors[node.limitTop] || '#666';
          const cBottom = settings.colors[node.limitBottom] || '#666';
          const topVis = settings.limitVisuals?.[node.limitTop] || { size: 1, opacity: 1 };
          const limitScale = topVis.size;
          const limitOpacity = topVis.opacity;
          const radius = baseRadius * limitScale;

          ctx.globalAlpha = 1.0 * limitOpacity;

          ctx.beginPath();
          if (isDiamond) {
              ctx.moveTo(x, y - radius);
              ctx.lineTo(x + radius, y);
              ctx.lineTo(x, y + radius);
              ctx.lineTo(x - radius, y);
          } else {
              ctx.arc(x, y, radius, 0, Math.PI * 2);
          }
          ctx.closePath();

          const grad = ctx.createLinearGradient(x, y - radius, x, y + radius);
          grad.addColorStop(0.45, cTop);
          grad.addColorStop(0.55, cBottom);
          ctx.fillStyle = grad;
          ctx.fill();

          const combinedScale = settings.buttonSizeScale * limitScale;
          if (combinedScale > 0.4) {
              ctx.fillStyle = 'white';
              ctx.textAlign = 'center';
              ctx.textBaseline = 'middle';
              let fontSize = Math.max(10, Math.min(18, 14 * combinedScale)) * settings.nodeTextSizeScale;
              ctx.font = `bold ${fontSize}px sans-serif`; 

              const spacingY = settings.showFractionBar ? 0.55 : 0.50;
              ctx.fillText(node.n.toString(), x, y - (radius * spacingY));
              if (settings.showFractionBar) {
                  ctx.beginPath();
                  ctx.moveTo(x - (radius * 0.4), y);
                  ctx.lineTo(x + (radius * 0.4), y);
                  ctx.lineWidth = 1;
                  ctx.strokeStyle = `rgba(255,255,255,${0.8 * limitOpacity})`;
                  ctx.stroke();
              }
              ctx.fillText(node.d.toString(), x, y + (radius * spacingY));
          }
      }
  }, [data, visualDeps]); 


  // --- Logic: Latches & Audio Sync ---
  useEffect(() => {
    if (settings.chordsAlwaysRelatch) {
         const newChords = activeChordIds.filter(id => !prevActiveChordIds.current.includes(id));
         if (newChords.length > 0) {
             const nodes = nodeMap;
             newChords.forEach(chordId => {
                 const chordDef = settings.savedChords.find(c => c.id === chordId);
                 if (chordDef) {
                     chordDef.nodes.forEach(n => {
                        const fullNode = nodes.get(n.id);
                        if (fullNode) {
                            audioEngine.startVoice(`node-${n.id}`, fullNode.ratio, settings.baseFrequency);
                            if (settings.midiEnabled) midiService.noteOn(`node-${n.id}`, fullNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
                        }
                     });
                 }
             });
         }
    }
    prevActiveChordIds.current = activeChordIds;
  }, [activeChordIds, settings.savedChords, settings.chordsAlwaysRelatch, nodeMap]);

  const prevEffectiveRef = useRef<Map<string, string>>(new Map());
  useEffect(() => {
      const current = effectiveLatchedNodes;
      const prev = prevEffectiveRef.current;
      const nodes = nodeMap;

      current.forEach((originId, nodeId) => {
          if (!prev.has(nodeId)) {
               const node = nodes.get(nodeId); 
               if (node) {
                   audioEngine.startVoice(`node-${nodeId}`, node.ratio, settings.baseFrequency);
                   if (settings.midiEnabled) midiService.noteOn(`node-${nodeId}`, node.ratio, settings.baseFrequency, settings.midiPitchBendRange);
               }
          }
      });
      prev.forEach((_, nodeId) => {
          if (!current.has(nodeId)) {
              audioEngine.stopVoice(`node-${nodeId}`);
              if (settings.midiEnabled) midiService.noteOff(`node-${nodeId}`);
          }
      });

      prevEffectiveRef.current = current;
  }, [effectiveLatchedNodes, nodeMap, settings.baseFrequency]);

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony]);

  // Helper for Hit Testing
  const getHitNode = (clientX: number, clientY: number): LatticeNode | null => {
      if (!dynamicCanvasRef.current) return null;
      const rect = dynamicCanvasRef.current.getBoundingClientRect();
      const x = clientX - rect.left;
      const y = clientY - rect.top;

      const centerOffset = dynamicSizeRef.current / 2;
      const spacing = settings.buttonSpacingScale;
      const baseRadius = (60 * settings.buttonSizeScale) / 2;

      const col = Math.floor(x / GRID_CELL_SIZE);
      const row = Math.floor(y / GRID_CELL_SIZE);

      const cellsToCheck = [
          `${col},${row}`, `${col+1},${row}`, `${col-1},${row}`,
          `${col},${row+1}`, `${col},${row-1}`,
          `${col+1},${row+1}`, `${col-1},${row-1}`,
          `${col+1},${row-1}`, `${col-1},${row+1}`
      ];

      const grid = spatialGridRef.current;

      for(const key of cellsToCheck) {
          const nodesInCell = grid.get(key);
          if (nodesInCell) {
              for (const node of nodesInCell) {
                  const nx = node.x * spacing + centerOffset;
                  const ny = node.y * spacing + centerOffset;
                  const vis = settings.limitVisuals?.[node.limitTop] || { size: 1 };
                  const r = baseRadius * vis.size;

                  if (x < nx - r || x > nx + r || y < ny - r || y > ny + r) continue;

                  const dx = x - nx;
                  const dy = y - ny;
                  if (dx*dx + dy*dy < r*r) return node;
              }
          }
      }
      return null;
  };

  // --- Interaction Handlers ---
  const handlePointerDown = (e: React.PointerEvent) => {
      if (uiUnlocked || !dynamicCanvasRef.current) return;
      e.preventDefault();
      (e.target as HTMLElement).setPointerCapture(e.pointerId);

      cursorPositionsRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });

      const hitNode = getHitNode(e.clientX, e.clientY);
      const nodeId = hitNode ? hitNode.id : null;

      // Stop Strumming (Empty Space Click) if in Latch Mode 1
      if (!hitNode && latchMode === 1) {
          return;
      }

      // Track cursor logic
      setActiveCursors(prev => {
          const next = new Map(prev);
          next.set(e.pointerId, {
              pointerId: e.pointerId,
              currentX: e.clientX,
              currentY: e.clientY,
              originNodeId: nodeId, 
              hoverNodeId: nodeId   
          });
          return next;
      });

      if (hitNode) {
        // Limit expansion
        const topLayer = settings.layerOrder[settings.layerOrder.length - 1];
        if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);
        lastTouchedLimitRef.current = hitNode.maxPrime;

        // Latch Mode Logic (Persistent Toggles)
        if (latchMode === 1) {
             setPersistentLatches(prev => {
                 const next = new Map(prev);
                 if (next.has(hitNode.id)) next.delete(hitNode.id);
                 else next.set(hitNode.id, hitNode.id);
                 return next;
             });
        }

        // Audio Triggers (Modes 0 and 2)
        if (settings.isPitchBendEnabled && latchMode !== 1) {
            audioEngine.startVoice(`cursor-${e.pointerId}`, hitNode.ratio, settings.baseFrequency);
            if (settings.midiEnabled) midiService.noteOn(`cursor-${e.pointerId}`, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
        }
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (uiUnlocked) return;
    if (!activeCursorsRef.current.has(e.pointerId)) return;

    cursorPositionsRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });

    const cursor = activeCursorsRef.current.get(e.pointerId)!;

    // DECISION: Are we Holding (Pitch Bending) or Strumming/Painting?
    if (cursor.originNodeId) {
        // --- HELD NOTE (Started on Node) ---
        // Logic: Calculate Pitch Bend (Mode 0/2) or Ignore (Mode 1)
        if (settings.isPitchBendEnabled && latchMode !== 1 && scrollContainerRef.current) {
             const centerOffset = dynamicSizeRef.current / 2;
             const rect = scrollContainerRef.current.getBoundingClientRect();
             const originNode = nodeMapRef.current.get(cursor.originNodeId);
             if (originNode) {
                 const spacing = settings.buttonSpacingScale;
                 const originScreenY = (originNode.y * spacing + centerOffset) + rect.top - scrollContainerRef.current.scrollTop;
                 const deltaY = e.clientY - originScreenY;
                 const bentRatio = getPitchRatioFromScreenDelta(deltaY, settings.buttonSpacingScale);
                 const finalRatio = originNode.ratio * bentRatio;
                 audioEngine.glideVoice(`cursor-${e.pointerId}`, finalRatio, settings.baseFrequency, 0.05);
                 if (settings.midiEnabled) midiService.pitchBend(`cursor-${e.pointerId}`, finalRatio, settings.baseFrequency, settings.midiPitchBendRange);
             }
        }
    } else {
        // --- STRUMMING / PAINTING (Started on Empty) ---
        const hitNode = getHitNode(e.clientX, e.clientY);
        const hitId = hitNode ? hitNode.id : null;

        if (cursor.hoverNodeId !== hitId) {
            // New node entered
            if (hitNode) {
                 const topLayer = settingsRef.current.layerOrder[settingsRef.current.layerOrder.length - 1];
                 if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);
            }

            // MODE 1: Paint Latch (Chord Draw)
            if (latchMode === 1 && hitId) {
                setPersistentLatches(prev => {
                    const next = new Map(prev);
                    // Simply toggle on enter. This allows drawing a chord by swiping.
                    if (next.has(hitId)) next.delete(hitId);
                    else next.set(hitId, hitId);
                    return next;
                });
            }

            // Update Cursor State
            setActiveCursors((prev: Map<number, ActiveCursor>) => {
                const next = new Map(prev);
                const existing = next.get(e.pointerId);
                if (existing) {
                    const c = { ...existing };
                    c.hoverNodeId = hitId;
                    next.set(e.pointerId, c);
                    return next;
                }
                return prev;
            });
        }
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursorsRef.current.has(e.pointerId)) {
        const cursor = activeCursorsRef.current.get(e.pointerId)!;

        // Stop Pitch Bend Voice if it exists (only for Held notes in Mode 0/2)
        if (cursor.originNodeId && latchMode !== 1) {
            audioEngine.stopVoice(`cursor-${e.pointerId}`);
            if (settings.midiEnabled) midiService.noteOff(`cursor-${e.pointerId}`);
        }

        cursorPositionsRef.current.delete(e.pointerId);
        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            return next;
        });
    }
  };

  // --- Animation Loop ---
  useEffect(() => {
    const canvas = dynamicCanvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: true });
    if (!ctx) return;

    const dpr = window.devicePixelRatio || 1;

    const render = (time: number) => {
        const currentSettings = settingsRef.current;
        const currentLatched = effectiveLatchedRef.current;
        const currentActiveLines = activeLinesRef.current;
        const currentBrightenedLines = brightenedLinesRef.current;
        const currentDynamicLines = dynamicHarmonicLinesRef.current;
        const size = dynamicSizeRef.current;
        const cursors = activeCursorsRef.current;

        if (canvas.width !== size * dpr || canvas.height !== size * dpr) {
            canvas.width = size * dpr;
            canvas.height = size * dpr;
            ctx.scale(dpr, dpr);
        }

        let viewX = 0, viewY = 0, viewW = size, viewH = size;
        if (scrollContainerRef.current) {
            viewX = scrollContainerRef.current.scrollLeft;
            viewY = scrollContainerRef.current.scrollTop;
            viewW = scrollContainerRef.current.clientWidth;
            viewH = scrollContainerRef.current.clientHeight;
        }

        ctx.clearRect(viewX, viewY, viewW, viewH);

        const centerOffset = size / 2;
        const spacing = currentSettings.buttonSpacingScale;
        const baseRadius = (60 * currentSettings.buttonSizeScale) / 2;
        const isDiamond = currentSettings.buttonShape === ButtonShape.DIAMOND;
        const colorCache = currentSettings.colors;

        const animationSpeed = (currentSettings.voiceLeadingAnimationSpeed || 2.0) * 0.33;
        const rawPhase = (time * 0.001 * animationSpeed);
        const flowPhase = currentSettings.voiceLeadingReverseDir ? (1.0 - (rawPhase % 1.0)) : (rawPhase % 1.0);

        ctx.lineCap = 'round';

        const viewPad = 100;
        const leftBound = viewX - viewPad;
        const rightBound = viewX + viewW + viewPad;
        const topBound = viewY - viewPad;
        const bottomBound = viewY + viewH + viewPad;

        // --- LAYER 1: BRIGHTENED LINES (Active Neighborhood) ---
        if (currentBrightenedLines.length > 0) {
            ctx.setLineDash([]);
            for (const line of currentBrightenedLines) {
                const x1 = line.x1 * spacing + centerOffset;
                const y1 = line.y1 * spacing + centerOffset;
                const x2 = line.x2 * spacing + centerOffset;
                const y2 = line.y2 * spacing + centerOffset;

                if (Math.max(x1, x2) < leftBound || Math.min(x1, x2) > rightBound || Math.max(y1, y2) < topBound || Math.min(y1, y2) > bottomBound) continue;

                const limitColor = colorCache[line.limit] || '#666';

                ctx.beginPath();
                ctx.moveTo(x1, y1);
                ctx.lineTo(x2, y2);
                ctx.lineWidth = 2;
                ctx.strokeStyle = limitColor;
                ctx.globalAlpha = 0.8; // Bright but static
                ctx.stroke();
            }
        }

        // --- LAYER 2: ACTIVE VOICE LEADING GRID LINES ---
        ctx.setLineDash([]); 
        for (const line of currentActiveLines) {
            const x1 = line.x1 * spacing + centerOffset;
            const y1 = line.y1 * spacing + centerOffset;
            const x2 = line.x2 * spacing + centerOffset;
            const y2 = line.y2 * spacing + centerOffset;

            if (Math.max(x1, x2) < leftBound || Math.min(x1, x2) > rightBound || Math.max(y1, y2) < topBound || Math.min(y1, y2) > bottomBound) continue;

            const limitColor = colorCache[line.limit] || '#666';

            // Solid Base
            ctx.beginPath();
            ctx.moveTo(x1, y1);
            ctx.lineTo(x2, y2);
            ctx.lineWidth = 4;
            ctx.strokeStyle = limitColor;
            ctx.globalAlpha = 1.0;
            ctx.stroke();

            // Animated Pulse
            if (currentSettings.isVoiceLeadingAnimationEnabled) {
                const grad = ctx.createLinearGradient(x1, y1, x2, y2);
                const p = flowPhase;

                grad.addColorStop(0, 'rgba(255,255,255,0)');
                const pulseWidth = 0.2;
                const start = Math.max(0, p - pulseWidth);
                const end = Math.min(1, p + pulseWidth);
                if (start > 0) grad.addColorStop(start, 'rgba(255,255,255,0)');
                grad.addColorStop(p, 'rgba(255,255,255,0.7)'); 
                if (end < 1) grad.addColorStop(end, 'rgba(255,255,255,0)');
                grad.addColorStop(1, 'rgba(255,255,255,0)');

                ctx.strokeStyle = grad;
                ctx.lineWidth = 10 * (0.5 + currentSettings.voiceLeadingGlowAmount);
                ctx.globalAlpha = 0.3; 
                ctx.stroke();

                ctx.lineWidth = 4;
                ctx.globalAlpha = 1.0;
                ctx.stroke();
            }
        }

        // --- LAYER 3: DYNAMIC HARMONIC LINES (Partials) ---
        for (const line of currentDynamicLines) {
            const x1 = line.x1 * spacing + centerOffset;
            const y1 = line.y1 * spacing + centerOffset;
            const x2 = line.x2 * spacing + centerOffset;
            const y2 = line.y2 * spacing + centerOffset;

            if (Math.max(x1, x2) < leftBound || Math.min(x1, x2) > rightBound || Math.max(y1, y2) < topBound || Math.min(y1, y2) > bottomBound) continue;

            ctx.beginPath();
            ctx.moveTo(x1, y1);
            ctx.lineTo(x2, y2);
            ctx.lineWidth = 3;
            ctx.strokeStyle = line.color;
            ctx.globalAlpha = 0.9;
            ctx.stroke();

            // Animation for Dynamic Lines
            if (currentSettings.isVoiceLeadingAnimationEnabled) {
                const grad = ctx.createLinearGradient(x1, y1, x2, y2);
                // Reverse phase logic specific to line direction
                const linePhase = line.reverse 
                    ? (1.0 - (rawPhase % 1.0)) 
                    : (rawPhase % 1.0);

                grad.addColorStop(0, 'rgba(255,255,255,0)');
                const pulseWidth = 0.15;
                const start = Math.max(0, linePhase - pulseWidth);
                const end = Math.min(1, linePhase + pulseWidth);
                if (start > 0) grad.addColorStop(start, 'rgba(255,255,255,0)');
                grad.addColorStop(linePhase, 'rgba(255,255,255,0.9)'); 
                if (end < 1) grad.addColorStop(end, 'rgba(255,255,255,0)');
                grad.addColorStop(1, 'rgba(255,255,255,0)');

                ctx.strokeStyle = grad;
                ctx.lineWidth = 6; // Distinct thickness
                ctx.globalAlpha = 0.6;
                ctx.stroke();
            }
        }

        // --- LAYER 4: NODES (Always on Top) ---
        for (const id of currentLatched.keys()) {
             const node = nodeMapRef.current.get(id);
             if (!node) continue;

             const x = node.x * spacing + centerOffset;
             const y = node.y * spacing + centerOffset;

             if (x < leftBound || x > rightBound || y < topBound || y > bottomBound) continue;

             const cTop = colorCache[node.limitTop] || '#666';
             const cBottom = colorCache[node.limitBottom] || '#666';

             const vis = currentSettings.limitVisuals?.[node.limitTop] || { size: 1 };
             const limitScale = vis.size;
             const zoomScale = currentSettings.latchedZoomScale;
             const radius = baseRadius * limitScale * zoomScale;

             ctx.globalAlpha = 1.0; 
             ctx.beginPath();
             if (isDiamond) {
                ctx.moveTo(x, y - radius);
                ctx.lineTo(x + radius, y);
                ctx.lineTo(x, y + radius);
                ctx.lineTo(x - radius, y);
             } else {
                ctx.arc(x, y, radius, 0, Math.PI * 2);
             }
             ctx.closePath();

             const grad = ctx.createLinearGradient(x, y - radius, x, y + radius);
             grad.addColorStop(0.45, cTop);
             grad.addColorStop(0.55, cBottom);
             ctx.fillStyle = grad;
             ctx.fill();

             if (currentSettings.isColoredIlluminationEnabled) {
                 const rainbowPeriod = getRainbowPeriod(spacing); 
                 const phase = (y % rainbowPeriod) / rainbowPeriod;
                 const hue = (currentSettings.rainbowOffset + phase * 360) % 360;
                 const sat = currentSettings.isRainbowModeEnabled ? currentSettings.rainbowSaturation : 100;
                 ctx.strokeStyle = `hsl(${hue}, ${sat}%, 60%)`;
                 ctx.lineWidth = 4;
                 ctx.stroke();
             } else {
                 ctx.strokeStyle = 'white';
                 ctx.lineWidth = 3;
                 ctx.stroke();
             }

             const combinedScale = currentSettings.buttonSizeScale * limitScale * zoomScale;
             if (combinedScale > 0.4) {
                ctx.fillStyle = 'white';
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                let fontSize = Math.max(12, Math.min(22, 16 * combinedScale)) * currentSettings.nodeTextSizeScale;
                ctx.font = `bold ${fontSize}px sans-serif`; 
                const spacingY = currentSettings.showFractionBar ? 0.55 : 0.50;
                ctx.fillText(node.n.toString(), x, y - (radius * spacingY));
                if (currentSettings.showFractionBar) {
                    ctx.beginPath();
                    ctx.moveTo(x - (radius * 0.4), y);
                    ctx.lineTo(x + (radius * 0.4), y);
                    ctx.lineWidth = 1;
                    ctx.strokeStyle = 'white';
                    ctx.stroke();
                }
                ctx.fillText(node.d.toString(), x, y + (radius * spacingY));
             }
        }

        // Draw drag lines for PITCH BEND (Only held notes)
        cursors.forEach(c => {
            if (c.originNodeId) { 
                const node = nodeMapRef.current.get(c.originNodeId);
                if(node) {
                     const nx = node.x * spacing + centerOffset;
                     const ny = node.y * spacing + centerOffset;
                     const pos = cursorPositionsRef.current.get(c.pointerId);
                     if (!pos) return;

                     let cx = 0, cy = 0;
                     if (scrollContainerRef.current) {
                         const r = scrollContainerRef.current.getBoundingClientRect();
                         cx = (pos.x - r.left) + scrollContainerRef.current.scrollLeft;
                         cy = (pos.y - r.top) + scrollContainerRef.current.scrollTop;
                     }

                     ctx.beginPath();
                     ctx.moveTo(nx, ny);
                     ctx.lineTo(cx, cy);
                     ctx.strokeStyle = 'white';
                     ctx.lineWidth = 2;
                     ctx.globalAlpha = 0.5;
                     ctx.stroke();
                }
            }
        });

        animationFrameRef.current = requestAnimationFrame(render);
    };

    animationFrameRef.current = requestAnimationFrame(render);
    return () => cancelAnimationFrame(animationFrameRef.current);
  }, []); 

  const rainbowPeriod = getRainbowPeriod(settings.buttonSpacingScale);

  const rainbowBackgroundFixed = useMemo(() => {
    if (settings.isRainbowModeEnabled) {
        const stops: string[] = [];
        const steps = 6;
        for (let i = 0; i <= steps; i++) {
            const pct = (i / steps) * 100;
            const hue = (settings.rainbowOffset + i * 60); 
            stops.push(`hsl(${hue}, ${settings.rainbowSaturation}%, ${settings.rainbowBrightness}%) ${pct}%`);
        }
        return `linear-gradient(to bottom, ${stops.join(', ')})`;
    }
    return undefined;
  }, [settings.isRainbowModeEnabled, settings.rainbowOffset, settings.rainbowSaturation, settings.rainbowBrightness]);

  const bgOffsetY = (dynamicSize / 2) - (rainbowPeriod / 3);

  return (
    <div 
        ref={scrollContainerRef}
        className="w-full h-full overflow-auto bg-slate-950 relative"
        style={{ touchAction: 'none' }}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerLeave={handlePointerUp}
        onPointerCancel={handlePointerUp}
    >
        <div 
            className="relative"
            style={{ 
                width: dynamicSize, 
                height: dynamicSize,
                backgroundImage: rainbowBackgroundFixed,
                backgroundSize: `100% ${rainbowPeriod}px`,
                backgroundRepeat: 'repeat',
                backgroundPosition: `0px ${bgOffsetY}px`,
                pointerEvents: uiUnlocked ? 'none' : 'auto',
            }}
        >
           <canvas 
             ref={staticCanvasRef}
             className="absolute top-0 left-0 z-0 pointer-events-none"
             style={{ width: '100%', height: '100%' }}
           />
           <canvas 
             ref={dynamicCanvasRef}
             className="absolute top-0 left-0 z-10"
             style={{ width: '100%', height: '100%' }}
           />

           {isGenerating && (
             <div className="absolute top-4 right-4 z-50 flex items-center gap-2 bg-slate-900/80 p-2 rounded-full backdrop-blur-sm border border-white/10 shadow-xl">
                 <svg className="animate-spin h-5 w-5 text-blue-500" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                   <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                   <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                 </svg>
                 <span className="text-xs font-bold text-slate-300 pr-2">Calculating...</span>
             </div>
           )}
        </div>
    </div>
  );
});

export default React.memo(TonalityDiamond);

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine, ButtonShape } from '../types';
import { getHarmonicDistance, generateLattice } from '../services/LatticeService';
import { getPitchRatioFromScreenDelta, getRainbowPeriod } from '../services/ProjectionService';
import AudioEngine from '../services/AudioEngine';
import { midiService } from '../services/MidiService';

export interface TonalityDiamondHandle {
  clearLatches: () => void;
  centerView: () => void;
  increaseDepth: () => void;
  decreaseDepth: () => void;
  getLatchedNodes: () => LatticeNode[];
}

interface Props {
  settings: AppSettings;
  updateSettings: (s: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) => void;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
  latchMode: 0 | 1 | 2; // 0=Off, 1=LatchAll, 2=Sustain
}

interface ActiveCursor {
  pointerId: number;
  currentX: number;
  currentY: number;
  originNodeId: string | null; // ID if started on a node (Held), Null if started on background (Strum)
  hoverNodeId: string | null;  // Current node under pointer
}

// Spatial Grid Constants
const GRID_CELL_SIZE = 100; // Pixel size of spatial buckets

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, updateSettings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked, latchMode } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);

  // Dual Canvas Strategy
  const staticCanvasRef = useRef<HTMLCanvasElement>(null); 
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null); 

  const animationFrameRef = useRef<number>(0);

  // Data State
  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });
  const [isGenerating, setIsGenerating] = useState(false);

  // Auto-calculated Dimensions
  const [dynamicSize, setDynamicSize] = useState(2000);
  const prevDynamicSizeRef = useRef(2000);

  // Optimization: Memoized Lookups & Spatial Grid
  const nodeMap = useMemo(() => {
      return new Map(data.nodes.map(n => [n.id, n]));
  }, [data.nodes]);

  const spatialGrid = useMemo(() => {
      const grid = new Map<string, LatticeNode[]>();
      const centerOffset = dynamicSize / 2;
      const spacing = settings.buttonSpacingScale;

      data.nodes.forEach(node => {
          const x = node.x * spacing + centerOffset;
          const y = node.y * spacing + centerOffset;

          const col = Math.floor(x / GRID_CELL_SIZE);
          const row = Math.floor(y / GRID_CELL_SIZE);
          const key = `${col},${row}`;

          if (!grid.has(key)) grid.set(key, []);
          grid.get(key)!.push(node);
      });
      return grid;
  }, [data.nodes, settings.buttonSpacingScale, dynamicSize]);

  // Interaction State
  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  const [persistentLatches, setPersistentLatches] = useState<Map<string, string>>(new Map());

  // Computed Effective Latched Nodes
  // This is the source of truth for audio and visuals
  const effectiveLatchedNodes = useMemo(() => {
      const effective = new Map<string, string>(persistentLatches);

      // Add Chords
      activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                if (!effective.has(n.id)) effective.set(n.id, n.id);
            });
        }
      });

      // Add Active Cursors
      activeCursors.forEach(cursor => {
          // Held Note (Pitch Bend Active)
          if (cursor.originNodeId) {
              effective.set(cursor.originNodeId, cursor.originNodeId);
          } 
          // Strummed Note (Only if NOT in Latch Mode 1)
          // In Latch Mode 1, mouse-over adds to persistent, so we don't need this temporary state.
          else if (cursor.hoverNodeId && latchMode !== 1) {
              effective.set(cursor.hoverNodeId, cursor.hoverNodeId);
          }
      });

      return effective;
  }, [persistentLatches, activeChordIds, settings.savedChords, activeCursors, latchMode]);

  // --- ACTIVE GRID LINES (Direct Neighbors) ---
  const activeLines = useMemo(() => {
    const latched = effectiveLatchedNodes;
    const cursors = activeCursors;
    const lines = data.lines;
    const active: LatticeLine[] = [];

    const isStable = (id: string) => {
        if (persistentLatches.has(id)) return true;
        const inChord = activeChordIds.some(cid => {
            const c = settings.savedChords.find(ch => ch.id === cid);
            return c?.nodes.some(n => n.id === id);
        });
        if (inChord) return true;
        for (const c of cursors.values()) {
            if (c.originNodeId === id) return true;
        }
        if (latchMode === 1) return true;
        return false;
    };

    if (latched.size > 0) {
        for (const line of lines) {
            const s = line.sourceId;
            const t = line.targetId;
            if (latched.has(s) && latched.has(t)) {
                if (isStable(s) && isStable(t)) {
                    active.push(line);
                }
            }
        }
    }
    return active;
  }, [data.lines, effectiveLatchedNodes, activeCursors, persistentLatches, activeChordIds, latchMode]);

  // --- LINE BRIGHTENING LOGIC (Neighbors of Active) ---
  const brightenedLines = useMemo(() => {
      if (!settings.lineBrighteningEnabled || effectiveLatchedNodes.size === 0) return [];

      const activeIds = new Set(effectiveLatchedNodes.keys());
      const resultLines = new Set<LatticeLine>();
      const step1Neighbors = new Set<string>();

      // Step 1: Lines connected to any active node
      data.lines.forEach(line => {
          const sActive = activeIds.has(line.sourceId);
          const tActive = activeIds.has(line.targetId);

          if (sActive || tActive) {
              resultLines.add(line);
              if (sActive) step1Neighbors.add(line.targetId);
              if (tActive) step1Neighbors.add(line.sourceId);
          }
      });

      // Step 2: Lines connected to Step 1 neighbors
      if (settings.lineBrighteningSteps === 2) {
          data.lines.forEach(line => {
              if (resultLines.has(line)) return;
              const sNeighbor = step1Neighbors.has(line.sourceId);
              const tNeighbor = step1Neighbors.has(line.targetId);
              if (sNeighbor || tNeighbor) {
                  resultLines.add(line);
              }
          });
      }

      return Array.from(resultLines);
  }, [effectiveLatchedNodes, data.lines, settings.lineBrighteningEnabled, settings.lineBrighteningSteps]);

  // Refs for Render Loop
  const settingsRef = useRef(settings);
  const dataRef = useRef(data);
  const activeCursorsRef = useRef<Map<number, ActiveCursor>>(activeCursors);
  const effectiveLatchedRef = useRef(effectiveLatchedNodes);
  const nodeMapRef = useRef(nodeMap);
  const activeLinesRef = useRef(activeLines);
  const brightenedLinesRef = useRef(brightenedLines);
  const spatialGridRef = useRef(spatialGrid);
  const dynamicSizeRef = useRef(dynamicSize);

  const cursorPositionsRef = useRef<Map<number, {x: number, y: number}>>(new Map());

  // Sync Refs
  useEffect(() => { settingsRef.current = settings; }, [settings]);
  useEffect(() => { dataRef.current = data; }, [data]);
  useEffect(() => { activeCursorsRef.current = activeCursors; }, [activeCursors]);
  useEffect(() => { effectiveLatchedRef.current = effectiveLatchedNodes; }, [effectiveLatchedNodes]);
  useEffect(() => { nodeMapRef.current = nodeMap; }, [nodeMap]);
  useEffect(() => { activeLinesRef.current = activeLines; }, [activeLines]);
  useEffect(() => { brightenedLinesRef.current = brightenedLines; }, [brightenedLines]);
  useEffect(() => { spatialGridRef.current = spatialGrid; }, [spatialGrid]);
  useEffect(() => { dynamicSizeRef.current = dynamicSize; }, [dynamicSize]);

  // Interaction State
  const lastTouchedLimitRef = useRef<number | null>(null);
  const depthHistoryRef = useRef<number[]>([]);
  const [hasCentered, setHasCentered] = useState(false);
  const prevActiveChordIds = useRef<string[]>([]);

  // --- External API ---
  useImperativeHandle(ref, () => ({
    clearLatches: () => setPersistentLatches(new Map()),
    centerView: () => { centerScroll(); },
    increaseDepth: () => {
        const limit = lastTouchedLimitRef.current;
        if (limit && limit > 1) {
             updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: currentDepth + 1 } };
             });
             depthHistoryRef.current.push(limit);
        }
    },
    decreaseDepth: () => {
        const limit = depthHistoryRef.current.pop();
        if (limit) {
            updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: Math.max(0, currentDepth - 1) } };
             });
        }
    },
    getLatchedNodes: () => {
        const result: LatticeNode[] = [];
        effectiveLatchedNodes.forEach((_, id) => {
            const n = nodeMap.get(id);
            if (n) result.push(n);
        });
        return result;
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const center = dynamicSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
      }
  };

  useLayoutEffect(() => {
    const container = scrollContainerRef.current;
    if (!container) return;
    if (!hasCentered && dynamicSize > 0) {
        centerScroll();
        setHasCentered(true);
    } else if (dynamicSize !== prevDynamicSizeRef.current) {
        const diff = (dynamicSize - prevDynamicSizeRef.current) / 2;
        container.scrollLeft += diff;
        container.scrollTop += diff;
    }
    prevDynamicSizeRef.current = dynamicSize;
  }, [dynamicSize]);

  // --- Data Generation ---
  const generationDeps = useMemo(() => {
      return JSON.stringify({
          depths: settings.limitDepths,
          complexities: settings.limitComplexities,
          hidden: settings.hiddenLimits,
          ratio: settings.latticeAspectRatio
      });
  }, [settings.limitDepths, settings.limitComplexities, settings.hiddenLimits, settings.latticeAspectRatio]);

  useEffect(() => {
    setIsGenerating(true);
    const timerId = setTimeout(() => {
        const effectiveSettings: AppSettings = JSON.parse(JSON.stringify(settings));
        const hiddenLimits = effectiveSettings.hiddenLimits || [];
        hiddenLimits.forEach((limit: number) => {
            // @ts-ignore
            if (effectiveSettings.limitDepths[limit] !== undefined) effectiveSettings.limitDepths[limit] = 0;
        });

        const result = generateLattice(effectiveSettings);
        const visibleNodeIds = new Set(result.nodes.map(n => n.id));
        const visibleLines = result.lines.filter(l => {
            if (hiddenLimits.includes(l.limit)) return false;
            if (!visibleNodeIds.has(l.sourceId) || !visibleNodeIds.has(l.targetId)) return false;
            return true;
        });

        let maxExtent = 0;
        for (const n of result.nodes) {
            const absX = Math.abs(n.x);
            const absY = Math.abs(n.y);
            if (absX > maxExtent) maxExtent = absX;
            if (absY > maxExtent) maxExtent = absY;
        }

        const padding = 600; 
        const spacing = settingsRef.current.buttonSpacingScale; 
        const calculatedSize = (maxExtent * spacing * 2) + padding;
        const finalSize = Math.max(calculatedSize, window.innerWidth, window.innerHeight);

        if (Math.abs(finalSize - dynamicSizeRef.current) > 50) {
            setDynamicSize(finalSize);
        }

        setData({ nodes: result.nodes, lines: visibleLines });
        setIsGenerating(false);
    }, 10);
    return () => clearTimeout(timerId);
  }, [generationDeps]); 

  useEffect(() => {
      let maxExtent = 0;
      for (const n of data.nodes) {
          const absX = Math.abs(n.x);
          const absY = Math.abs(n.y);
          if (absX > maxExtent) maxExtent = absX;
          if (absY > maxExtent) maxExtent = absY;
      }
      const padding = 600; 
      const spacing = settings.buttonSpacingScale;
      const calculatedSize = (maxExtent * spacing * 2) + padding;
      const finalSize = Math.max(calculatedSize, window.innerWidth, window.innerHeight);
      if (Math.abs(finalSize - dynamicSize) > 50) setDynamicSize(finalSize);
  }, [settings.buttonSpacingScale]);


  // --- STATIC CANVAS RENDERER ---
  const visualDeps = useMemo(() => JSON.stringify({
      size: settings.buttonSizeScale,
      spacing: settings.buttonSpacingScale,
      colors: settings.colors,
      visuals: settings.limitVisuals,
      shape: settings.buttonShape,
      textScale: settings.nodeTextSizeScale,
      fractionBar: settings.showFractionBar,
      canvasSize: dynamicSize 
  }), [settings.buttonSizeScale, settings.buttonSpacingScale, settings.colors, settings.limitVisuals, settings.buttonShape, settings.nodeTextSizeScale, settings.showFractionBar, dynamicSize]);

  useEffect(() => {
      const canvas = staticCanvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d', { alpha: true });
      if (!ctx) return;

      const dpr = window.devicePixelRatio || 1;
      const size = dynamicSize;

      if (canvas.width !== size * dpr || canvas.height !== size * dpr) {
          canvas.width = size * dpr;
          canvas.height = size * dpr;
      }

      ctx.setTransform(1, 0, 0, 1, 0, 0);
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.scale(dpr, dpr);

      const centerOffset = size / 2;
      const spacing = settings.buttonSpacingScale;
      const baseRadius = (60 * settings.buttonSizeScale) / 2;
      const isDiamond = settings.buttonShape === ButtonShape.DIAMOND;

      const linesByLimit: Record<number, number[]> = {};
      for (const line of data.lines) {
          if (!linesByLimit[line.limit]) linesByLimit[line.limit] = [];
          const arr = linesByLimit[line.limit];
          arr.push(line.x1 * spacing + centerOffset, line.y1 * spacing + centerOffset, line.x2 * spacing + centerOffset, line.y2 * spacing + centerOffset);
      }

      ctx.lineCap = 'round';
      for (const limitStr in linesByLimit) {
          const limit = parseInt(limitStr);
          const coords = linesByLimit[limit];
          const color = settings.colors[limit] || '#666';
          const visualSettings = settings.limitVisuals?.[limit] || { size: 1, opacity: 1 };

          ctx.beginPath();
          for(let i=0; i<coords.length; i+=4) {
              ctx.moveTo(coords[i], coords[i+1]);
              ctx.lineTo(coords[i+2], coords[i+3]);
          }
          ctx.lineWidth = (limit === 1 ? 4 : 2) * visualSettings.size;
          ctx.strokeStyle = color;
          ctx.globalAlpha = 0.3 * visualSettings.opacity; 

          if (limit === 1) ctx.setLineDash([5, 5]);
          else ctx.setLineDash([]);
          ctx.stroke();
      }
      ctx.setLineDash([]); 

      for (const node of data.nodes) {
          const x = node.x * spacing + centerOffset;
          const y = node.y * spacing + centerOffset;
          const cTop = settings.colors[node.limitTop] || '#666';
          const cBottom = settings.colors[node.limitBottom] || '#666';
          const topVis = settings.limitVisuals?.[node.limitTop] || { size: 1, opacity: 1 };
          const limitScale = topVis.size;
          const limitOpacity = topVis.opacity;
          const radius = baseRadius * limitScale;

          ctx.globalAlpha = 1.0 * limitOpacity;

          ctx.beginPath();
          if (isDiamond) {
              ctx.moveTo(x, y - radius);
              ctx.lineTo(x + radius, y);
              ctx.lineTo(x, y + radius);
              ctx.lineTo(x - radius, y);
          } else {
              ctx.arc(x, y, radius, 0, Math.PI * 2);
          }
          ctx.closePath();

          const grad = ctx.createLinearGradient(x, y - radius, x, y + radius);
          grad.addColorStop(0.45, cTop);
          grad.addColorStop(0.55, cBottom);
          ctx.fillStyle = grad;
          ctx.fill();

          const combinedScale = settings.buttonSizeScale * limitScale;
          if (combinedScale > 0.4) {
              ctx.fillStyle = 'white';
              ctx.textAlign = 'center';
              ctx.textBaseline = 'middle';
              let fontSize = Math.max(10, Math.min(18, 14 * combinedScale)) * settings.nodeTextSizeScale;
              ctx.font = `bold ${fontSize}px sans-serif`; 

              const spacingY = settings.showFractionBar ? 0.55 : 0.50;
              ctx.fillText(node.n.toString(), x, y - (radius * spacingY));
              if (settings.showFractionBar) {
                  ctx.beginPath();
                  ctx.moveTo(x - (radius * 0.4), y);
                  ctx.lineTo(x + (radius * 0.4), y);
                  ctx.lineWidth = 1;
                  ctx.strokeStyle = `rgba(255,255,255,${0.8 * limitOpacity})`;
                  ctx.stroke();
              }
              ctx.fillText(node.d.toString(), x, y + (radius * spacingY));
          }
      }
  }, [data, visualDeps]); 


  // --- Logic: Latches & Audio Sync ---
  useEffect(() => {
    if (settings.chordsAlwaysRelatch) {
         const newChords = activeChordIds.filter(id => !prevActiveChordIds.current.includes(id));
         if (newChords.length > 0) {
             const nodes = nodeMap;
             newChords.forEach(chordId => {
                 const chordDef = settings.savedChords.find(c => c.id === chordId);
                 if (chordDef) {
                     chordDef.nodes.forEach(n => {
                        const fullNode = nodes.get(n.id);
                        if (fullNode) {
                            audioEngine.startVoice(`node-${n.id}`, fullNode.ratio, settings.baseFrequency);
                            if (settings.midiEnabled) midiService.noteOn(`node-${n.id}`, fullNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
                        }
                     });
                 }
             });
         }
    }
    prevActiveChordIds.current = activeChordIds;
  }, [activeChordIds, settings.savedChords, settings.chordsAlwaysRelatch, nodeMap]);

  const prevEffectiveRef = useRef<Map<string, string>>(new Map());
  useEffect(() => {
      const current = effectiveLatchedNodes;
      const prev = prevEffectiveRef.current;
      const nodes = nodeMap;

      current.forEach((originId, nodeId) => {
          if (!prev.has(nodeId)) {
               const node = nodes.get(nodeId); 
               if (node) {
                   audioEngine.startVoice(`node-${nodeId}`, node.ratio, settings.baseFrequency);
                   if (settings.midiEnabled) midiService.noteOn(`node-${nodeId}`, node.ratio, settings.baseFrequency, settings.midiPitchBendRange);
               }
          }
      });
      prev.forEach((_, nodeId) => {
          if (!current.has(nodeId)) {
              audioEngine.stopVoice(`node-${nodeId}`);
              if (settings.midiEnabled) midiService.noteOff(`node-${nodeId}`);
          }
      });

      prevEffectiveRef.current = current;
  }, [effectiveLatchedNodes, nodeMap, settings.baseFrequency]);

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony]);

  // Helper for Hit Testing
  const getHitNode = (clientX: number, clientY: number): LatticeNode | null => {
      if (!dynamicCanvasRef.current) return null;
      const rect = dynamicCanvasRef.current.getBoundingClientRect();
      const x = clientX - rect.left;
      const y = clientY - rect.top;

      const centerOffset = dynamicSizeRef.current / 2;
      const spacing = settings.buttonSpacingScale;
      const baseRadius = (60 * settings.buttonSizeScale) / 2;

      const col = Math.floor(x / GRID_CELL_SIZE);
      const row = Math.floor(y / GRID_CELL_SIZE);

      const cellsToCheck = [
          `${col},${row}`, `${col+1},${row}`, `${col-1},${row}`,
          `${col},${row+1}`, `${col},${row-1}`,
          `${col+1},${row+1}`, `${col-1},${row-1}`,
          `${col+1},${row-1}`, `${col-1},${row+1}`
      ];

      const grid = spatialGridRef.current;

      for(const key of cellsToCheck) {
          const nodesInCell = grid.get(key);
          if (nodesInCell) {
              for (const node of nodesInCell) {
                  const nx = node.x * spacing + centerOffset;
                  const ny = node.y * spacing + centerOffset;
                  const vis = settings.limitVisuals?.[node.limitTop] || { size: 1 };
                  const r = baseRadius * vis.size;

                  if (x < nx - r || x > nx + r || y < ny - r || y > ny + r) continue;

                  const dx = x - nx;
                  const dy = y - ny;
                  if (dx*dx + dy*dy < r*r) return node;
              }
          }
      }
      return null;
  };

  // --- Interaction Handlers ---
  const handlePointerDown = (e: React.PointerEvent) => {
      if (uiUnlocked || !dynamicCanvasRef.current) return;
      e.preventDefault();
      (e.target as HTMLElement).setPointerCapture(e.pointerId);

      cursorPositionsRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });

      const hitNode = getHitNode(e.clientX, e.clientY);
      const nodeId = hitNode ? hitNode.id : null;

      // Stop Strumming (Empty Space Click) if in Latch Mode 1
      if (!hitNode && latchMode === 1) {
          return;
      }

      // Track cursor logic
      setActiveCursors(prev => {
          const next = new Map(prev);
          next.set(e.pointerId, {
              pointerId: e.pointerId,
              currentX: e.clientX,
              currentY: e.clientY,
              originNodeId: nodeId, 
              hoverNodeId: nodeId   
          });
          return next;
      });

      if (hitNode) {
        // Limit expansion
        const topLayer = settings.layerOrder[settings.layerOrder.length - 1];
        if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);
        lastTouchedLimitRef.current = hitNode.maxPrime;

        // Latch Mode Logic (Persistent Toggles)
        if (latchMode === 1) {
             setPersistentLatches(prev => {
                 const next = new Map(prev);
                 if (next.has(hitNode.id)) next.delete(hitNode.id);
                 else next.set(hitNode.id, hitNode.id);
                 return next;
             });
        }

        // Audio Triggers (Modes 0 and 2)
        if (settings.isPitchBendEnabled && latchMode !== 1) {
            audioEngine.startVoice(`cursor-${e.pointerId}`, hitNode.ratio, settings.baseFrequency);
            if (settings.midiEnabled) midiService.noteOn(`cursor-${e.pointerId}`, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
        }
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (uiUnlocked) return;
    if (!activeCursorsRef.current.has(e.pointerId)) return;

    cursorPositionsRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });

    const cursor = activeCursorsRef.current.get(e.pointerId)!;
    const hitNode = getHitNode(e.clientX, e.clientY);
    const hitId = hitNode ? hitNode.id : null;

    // --- LATCH MODE 1: CHORD DRAWING (PAINT) ---
    // Takes precedence over Held/Strum logic to allow drawing even if started on a node
    if (latchMode === 1) {
        if (cursor.hoverNodeId !== hitId) {
            if (hitNode) {
                 const topLayer = settingsRef.current.layerOrder[settingsRef.current.layerOrder.length - 1];
                 if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);
            }
            if (hitId) {
                setPersistentLatches(prev => {
                    const next = new Map(prev);
                    // Simply toggle on enter. This allows drawing a chord by swiping.
                    if (next.has(hitId)) next.delete(hitId);
                    else next.set(hitId, hitId);
                    return next;
                });
            }
            // Update tracking
            setActiveCursors(prev => {
                const next = new Map(prev);
                const c = next.get(e.pointerId);
                if(c) { c.hoverNodeId = hitId; next.set(e.pointerId, c); }
                return next;
            });
        }
        return;
    }

    // DECISION: Are we Holding (Pitch Bending) or Strumming?
    if (cursor.originNodeId) {
        // --- HELD NOTE (Started on Node) ---
        // Logic: Calculate Pitch Bend (Mode 0/2)
        if (settings.isPitchBendEnabled && latchMode !== 1 && scrollContainerRef.current) {
             const centerOffset = dynamicSizeRef.current / 2;
             const rect = scrollContainerRef.current.getBoundingClientRect();
             const originNode = nodeMapRef.current.get(cursor.originNodeId);
             if (originNode) {
                 const spacing = settings.buttonSpacingScale;
                 const originScreenY = (originNode.y * spacing + centerOffset) + rect.top - scrollContainerRef.current.scrollTop;
                 const deltaY = e.clientY - originScreenY;
                 const bentRatio = getPitchRatioFromScreenDelta(deltaY, settings.buttonSpacingScale);
                 const finalRatio = originNode.ratio * bentRatio;
                 audioEngine.glideVoice(`cursor-${e.pointerId}`, finalRatio, settings.baseFrequency, 0.05);
                 if (settings.midiEnabled) midiService.pitchBend(`cursor-${e.pointerId}`, finalRatio, settings.baseFrequency, settings.midiPitchBendRange);
             }
        }
    } else {
        // --- STRUMMING (Started on Empty) ---
        if (cursor.hoverNodeId !== hitId) {
            if (hitNode) {
                 const topLayer = settingsRef.current.layerOrder[settingsRef.current.layerOrder.length - 1];
                 if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);
            }
            // Update Cursor State
            setActiveCursors((prev: Map<number, ActiveCursor>) => {
                const next = new Map(prev);
                const existing = next.get(e.pointerId);
                if (existing) {
                    const c = { ...existing };
                    c.hoverNodeId = hitId;
                    next.set(e.pointerId, c);
                    return next;
                }
                return prev;
            });
        }
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursorsRef.current.has(e.pointerId)) {
        const cursor = activeCursorsRef.current.get(e.pointerId)!;

        // Stop Pitch Bend Voice if it exists (only for Held notes in Mode 0/2)
        if (cursor.originNodeId && latchMode !== 1) {
            audioEngine.stopVoice(`cursor-${e.pointerId}`);
            if (settings.midiEnabled) midiService.noteOff(`cursor-${e.pointerId}`);
        }

        cursorPositionsRef.current.delete(e.pointerId);
        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            return next;
        });
    }
  };

  // --- Animation Loop ---
  useEffect(() => {
    const canvas = dynamicCanvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: true });
    if (!ctx) return;

    const dpr = window.devicePixelRatio || 1;

    const render = (time: number) => {
        const currentSettings = settingsRef.current;
        const currentLatched = effectiveLatchedRef.current;
        const currentActiveLines = activeLinesRef.current;
        const currentBrightenedLines = brightenedLinesRef.current;
        const size = dynamicSizeRef.current;
        const cursors = activeCursorsRef.current;

        if (canvas.width !== size * dpr || canvas.height !== size * dpr) {
            canvas.width = size * dpr;
            canvas.height = size * dpr;
            ctx.scale(dpr, dpr);
        }

        let viewX = 0, viewY = 0, viewW = size, viewH = size;
        if (scrollContainerRef.current) {
            viewX = scrollContainerRef.current.scrollLeft;
            viewY = scrollContainerRef.current.scrollTop;
            viewW = scrollContainerRef.current.clientWidth;
            viewH = scrollContainerRef.current.clientHeight;
        }

        ctx.clearRect(viewX, viewY, viewW, viewH);

        const centerOffset = size / 2;
        const spacing = currentSettings.buttonSpacingScale;
        const baseRadius = (60 * currentSettings.buttonSizeScale) / 2;
        const isDiamond = currentSettings.buttonShape === ButtonShape.DIAMOND;
        const colorCache = currentSettings.colors;

        const animationSpeed = (currentSettings.voiceLeadingAnimationSpeed || 2.0) * 0.33;
        const rawPhase = (time * 0.001 * animationSpeed);
        const flowPhase = currentSettings.voiceLeadingReverseDir ? (1.0 - (rawPhase % 1.0)) : (rawPhase % 1.0);

        ctx.lineCap = 'round';

        const viewPad = 100;
        const leftBound = viewX - viewPad;
        const rightBound = viewX + viewW + viewPad;
        const topBound = viewY - viewPad;
        const bottomBound = viewY + viewH + viewPad;

        // --- LAYER 1: BRIGHTENED LINES (Active Neighborhood) ---
        // Draw these first so they are behind nodes
        if (currentBrightenedLines.length > 0) {
            ctx.setLineDash([]);
            for (const line of currentBrightenedLines) {
                const x1 = line.x1 * spacing + centerOffset;
                const y1 = line.y1 * spacing + centerOffset;
                const x2 = line.x2 * spacing + centerOffset;
                const y2 = line.y2 * spacing + centerOffset;

                if (Math.max(x1, x2) < leftBound || Math.min(x1, x2) > rightBound || Math.max(y1, y2) < topBound || Math.min(y1, y2) > bottomBound) continue;

                const limitColor = colorCache[line.limit] || '#666';

                ctx.beginPath();
                ctx.moveTo(x1, y1);
                ctx.lineTo(x2, y2);
                ctx.lineWidth = 2;
                ctx.strokeStyle = limitColor;
                ctx.globalAlpha = 0.8; 
                ctx.stroke();
            }
        }

        // --- LAYER 2: ACTIVE VOICE LEADING GRID LINES ---
        ctx.setLineDash([]); 
        for (const line of currentActiveLines) {
            const x1 = line.x1 * spacing + centerOffset;
            const y1 = line.y1 * spacing + centerOffset;
            const x2 = line.x2 * spacing + centerOffset;
            const y2 = line.y2 * spacing + centerOffset;

            if (Math.max(x1, x2) < leftBound || Math.min(x1, x2) > rightBound || Math.max(y1, y2) < topBound || Math.min(y1, y2) > bottomBound) continue;

            const limitColor = colorCache[line.limit] || '#666';

            ctx.beginPath();
            ctx.moveTo(x1, y1);
            ctx.lineTo(x2, y2);
            ctx.lineWidth = 4;
            ctx.strokeStyle = limitColor;
            ctx.globalAlpha = 1.0;
            ctx.stroke();

            if (currentSettings.isVoiceLeadingAnimationEnabled) {
                const grad = ctx.createLinearGradient(x1, y1, x2, y2);
                const p = flowPhase;

                grad.addColorStop(0, 'rgba(255,255,255,0)');
                const pulseWidth = 0.2;
                const start = Math.max(0, p - pulseWidth);
                const end = Math.min(1, p + pulseWidth);
                if (start > 0) grad.addColorStop(start, 'rgba(255,255,255,0)');
                grad.addColorStop(p, 'rgba(255,255,255,0.7)'); 
                if (end < 1) grad.addColorStop(end, 'rgba(255,255,255,0)');
                grad.addColorStop(1, 'rgba(255,255,255,0)');

                ctx.strokeStyle = grad;
                ctx.lineWidth = 10 * (0.5 + currentSettings.voiceLeadingGlowAmount);
                ctx.globalAlpha = 0.3; 
                ctx.stroke();

                ctx.lineWidth = 4;
                ctx.globalAlpha = 1.0;
                ctx.stroke();
            }
        }

        // --- LAYER 4: NODES (Always on Top) ---
        // Collect ALL nodes that need to be drawn on the dynamic layer to cover the lines.
        // This includes Latched nodes AND any node touched by an active/brightened line.
        const nodesToDraw = new Set(currentLatched.keys());

        currentActiveLines.forEach(l => { nodesToDraw.add(l.sourceId); nodesToDraw.add(l.targetId); });
        currentBrightenedLines.forEach(l => { nodesToDraw.add(l.sourceId); nodesToDraw.add(l.targetId); });

        for (const id of nodesToDraw) {
             const node = nodeMapRef.current.get(id);
             if (!node) continue;

             const isLatched = currentLatched.has(id);

             const x = node.x * spacing + centerOffset;
             const y = node.y * spacing + centerOffset;

             if (x < leftBound || x > rightBound || y < topBound || y > bottomBound) continue;

             const cTop = colorCache[node.limitTop] || '#666';
             const cBottom = colorCache[node.limitBottom] || '#666';

             const vis = currentSettings.limitVisuals?.[node.limitTop] || { size: 1 };

             // Scale Logic: Latched gets Zoom, Unlatched gets standard size
             const limitScale = vis.size;
             const zoomScale = isLatched ? currentSettings.latchedZoomScale : 1.0;
             const radius = baseRadius * limitScale * zoomScale;

             ctx.globalAlpha = 1.0; 
             ctx.beginPath();
             if (isDiamond) {
                ctx.moveTo(x, y - radius);
                ctx.lineTo(x + radius, y);
                ctx.lineTo(x, y + radius);
                ctx.lineTo(x - radius, y);
             } else {
                ctx.arc(x, y, radius, 0, Math.PI * 2);
             }
             ctx.closePath();

             const grad = ctx.createLinearGradient(x, y - radius, x, y + radius);
             grad.addColorStop(0.45, cTop);
             grad.addColorStop(0.55, cBottom);
             ctx.fillStyle = grad;
             ctx.fill();

             // Outline Logic
             if (isLatched) {
                 if (currentSettings.isColoredIlluminationEnabled) {
                     const rainbowPeriod = getRainbowPeriod(spacing); 
                     const phase = (y % rainbowPeriod) / rainbowPeriod;
                     const hue = (currentSettings.rainbowOffset + phase * 360) % 360;
                     const sat = currentSettings.isRainbowModeEnabled ? currentSettings.rainbowSaturation : 100;
                     ctx.strokeStyle = `hsl(${hue}, ${sat}%, 60%)`;
                     ctx.lineWidth = 4;
                 } else {
                     ctx.strokeStyle = 'white';
                     ctx.lineWidth = 3;
                 }
                 ctx.stroke();
             } 
             // Unlatched nodes don't need a stroke unless desired for visibility, 
             // but usually they just cover the line ends.

             const combinedScale = currentSettings.buttonSizeScale * limitScale * zoomScale;
             if (combinedScale > 0.4) {
                ctx.fillStyle = 'white';
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                let fontSize = Math.max(12, Math.min(22, 16 * combinedScale)) * currentSettings.nodeTextSizeScale;
                ctx.font = `bold ${fontSize}px sans-serif`; 
                const spacingY = currentSettings.showFractionBar ? 0.55 : 0.50;
                ctx.fillText(node.n.toString(), x, y - (radius * spacingY));
                if (currentSettings.showFractionBar) {
                    ctx.beginPath();
                    ctx.moveTo(x - (radius * 0.4), y);
                    ctx.lineTo(x + (radius * 0.4), y);
                    ctx.lineWidth = 1;
                    ctx.strokeStyle = isLatched ? 'white' : `rgba(255,255,255,0.8)`;
                    ctx.stroke();
                }
                ctx.fillText(node.d.toString(), x, y + (radius * spacingY));
             }
        }

        // Draw drag lines for PITCH BEND (Only held notes)
        cursors.forEach(c => {
            if (c.originNodeId) { 
                const node = nodeMapRef.current.get(c.originNodeId);
                if(node) {
                     const nx = node.x * spacing + centerOffset;
                     const ny = node.y * spacing + centerOffset;
                     const pos = cursorPositionsRef.current.get(c.pointerId);
                     if (!pos) return;

                     let cx = 0, cy = 0;
                     if (scrollContainerRef.current) {
                         const r = scrollContainerRef.current.getBoundingClientRect();
                         cx = (pos.x - r.left) + scrollContainerRef.current.scrollLeft;
                         cy = (pos.y - r.top) + scrollContainerRef.current.scrollTop;
                     }

                     ctx.beginPath();
                     ctx.moveTo(nx, ny);
                     ctx.lineTo(cx, cy);
                     ctx.strokeStyle = 'white';
                     ctx.lineWidth = 2;
                     ctx.globalAlpha = 0.5;
                     ctx.stroke();
                }
            }
        });

        animationFrameRef.current = requestAnimationFrame(render);
    };

    animationFrameRef.current = requestAnimationFrame(render);
    return () => cancelAnimationFrame(animationFrameRef.current);
  }, []); 

  const rainbowPeriod = getRainbowPeriod(settings.buttonSpacingScale);

  const rainbowBackgroundFixed = useMemo(() => {
    if (settings.isRainbowModeEnabled) {
        const stops: string[] = [];
        const steps = 6;
        for (let i = 0; i <= steps; i++) {
            const pct = (i / steps) * 100;
            const hue = (settings.rainbowOffset + i * 60); 
            stops.push(`hsl(${hue}, ${settings.rainbowSaturation}%, ${settings.rainbowBrightness}%) ${pct}%`);
        }
        return `linear-gradient(to bottom, ${stops.join(', ')})`;
    }
    return undefined;
  }, [settings.isRainbowModeEnabled, settings.rainbowOffset, settings.rainbowSaturation, settings.rainbowBrightness]);

  const bgOffsetY = (dynamicSize / 2) - (rainbowPeriod / 3);

  return (
    <div 
        ref={scrollContainerRef}
        className="w-full h-full overflow-auto bg-slate-950 relative"
        style={{ touchAction: 'none' }}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerLeave={handlePointerUp}
        onPointerCancel={handlePointerUp}
    >
        <div 
            className="relative"
            style={{ 
                width: dynamicSize, 
                height: dynamicSize,
                backgroundImage: rainbowBackgroundFixed,
                backgroundSize: `100% ${rainbowPeriod}px`,
                backgroundRepeat: 'repeat',
                backgroundPosition: `0px ${bgOffsetY}px`,
                pointerEvents: uiUnlocked ? 'none' : 'auto',
            }}
        >
           <canvas 
             ref={staticCanvasRef}
             className="absolute top-0 left-0 z-0 pointer-events-none"
             style={{ width: '100%', height: '100%' }}
           />
           <canvas 
             ref={dynamicCanvasRef}
             className="absolute top-0 left-0 z-10"
             style={{ width: '100%', height: '100%' }}
           />

           {isGenerating && (
             <div className="absolute top-4 right-4 z-50 flex items-center gap-2 bg-slate-900/80 p-2 rounded-full backdrop-blur-sm border border-white/10 shadow-xl">
                 <svg className="animate-spin h-5 w-5 text-blue-500" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                   <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                   <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                 </svg>
                 <span className="text-xs font-bold text-slate-300 pr-2">Calculating...</span>
             </div>
           )}
        </div>
    </div>
  );
});

export default React.memo(TonalityDiamond);

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine, ButtonShape } from '../types';
import { getHarmonicDistance, generateLattice } from '../services/LatticeService';
import { getPitchRatioFromScreenDelta, getRainbowPeriod } from '../services/ProjectionService';
import AudioEngine from '../services/AudioEngine';
import { midiService } from '../services/MidiService';

export interface TonalityDiamondHandle {
  clearLatches: () => void;
  centerView: () => void;
  increaseDepth: () => void;
  decreaseDepth: () => void;
  getLatchedNodes: () => LatticeNode[];
}

interface Props {
  settings: AppSettings;
  updateSettings: (s: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) => void;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
  latchMode: 0 | 1 | 2; // 0=Off, 1=LatchAll, 2=Sustain
}

interface ActiveCursor {
  pointerId: number;
  currentX: number;
  currentY: number;
  originNodeId: string | null; // ID if started on a node (Held), Null if started on background (Strum)
  hoverNodeId: string | null;  // Current node under pointer
}

// Spatial Grid Constants
const GRID_CELL_SIZE = 100; // Pixel size of spatial buckets

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, updateSettings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked, latchMode } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);

  // Dual Canvas Strategy
  const staticCanvasRef = useRef<HTMLCanvasElement>(null); 
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null); 

  const animationFrameRef = useRef<number>(0);

  // Data State
  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });
  const [isGenerating, setIsGenerating] = useState(false);

  // Auto-calculated Dimensions
  const [dynamicSize, setDynamicSize] = useState(2000);
  const prevDynamicSizeRef = useRef(2000);

  // Optimization: Memoized Lookups & Spatial Grid
  const nodeMap = useMemo(() => {
      return new Map(data.nodes.map(n => [n.id, n]));
  }, [data.nodes]);

  const spatialGrid = useMemo(() => {
      const grid = new Map<string, LatticeNode[]>();
      const centerOffset = dynamicSize / 2;
      const spacing = settings.buttonSpacingScale;

      data.nodes.forEach(node => {
          const x = node.x * spacing + centerOffset;
          const y = node.y * spacing + centerOffset;

          const col = Math.floor(x / GRID_CELL_SIZE);
          const row = Math.floor(y / GRID_CELL_SIZE);
          const key = `${col},${row}`;

          if (!grid.has(key)) grid.set(key, []);
          grid.get(key)!.push(node);
      });
      return grid;
  }, [data.nodes, settings.buttonSpacingScale, dynamicSize]);

  // Interaction State
  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  const [persistentLatches, setPersistentLatches] = useState<Map<string, string>>(new Map());

  // Computed Effective Latched Nodes
  // This is the source of truth for audio and visuals
  const effectiveLatchedNodes = useMemo(() => {
      const effective = new Map<string, string>(persistentLatches);

      // Add Chords
      activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                if (!effective.has(n.id)) effective.set(n.id, n.id);
            });
        }
      });

      // Add Active Cursors
      activeCursors.forEach(cursor => {
          // Held Note (Pitch Bend Active)
          if (cursor.originNodeId) {
              effective.set(cursor.originNodeId, cursor.originNodeId);
          } 
          // Strummed Note (Only if NOT in Latch Mode 1)
          // In Latch Mode 1, mouse-over adds to persistent, so we don't need this temporary state.
          else if (cursor.hoverNodeId && latchMode !== 1) {
              effective.set(cursor.hoverNodeId, cursor.hoverNodeId);
          }
      });

      return effective;
  }, [persistentLatches, activeChordIds, settings.savedChords, activeCursors, latchMode]);

  // --- ACTIVE GRID LINES (Direct Neighbors) ---
  const activeLines = useMemo(() => {
    const latched = effectiveLatchedNodes;
    const cursors = activeCursors;
    const lines = data.lines;
    const active: LatticeLine[] = [];

    const isStable = (id: string) => {
        if (persistentLatches.has(id)) return true;
        const inChord = activeChordIds.some(cid => {
            const c = settings.savedChords.find(ch => ch.id === cid);
            return c?.nodes.some(n => n.id === id);
        });
        if (inChord) return true;
        for (const c of cursors.values()) {
            if (c.originNodeId === id) return true;
        }
        if (latchMode === 1) return true;
        return false;
    };

    if (latched.size > 0) {
        for (const line of lines) {
            const s = line.sourceId;
            const t = line.targetId;
            if (latched.has(s) && latched.has(t)) {
                if (isStable(s) && isStable(t)) {
                    active.push(line);
                }
            }
        }
    }
    return active;
  }, [data.lines, effectiveLatchedNodes, activeCursors, persistentLatches, activeChordIds, latchMode]);

  // --- LINE BRIGHTENING LOGIC (Neighbors of Active) ---
  const brightenedLines = useMemo(() => {
      if (!settings.lineBrighteningEnabled || effectiveLatchedNodes.size === 0) return [];

      const activeIds = new Set(effectiveLatchedNodes.keys());
      const resultLines = new Set<LatticeLine>();
      const step1Neighbors = new Set<string>();

      // Step 1: Lines connected to any active node
      data.lines.forEach(line => {
          const sActive = activeIds.has(line.sourceId);
          const tActive = activeIds.has(line.targetId);

          if (sActive || tActive) {
              resultLines.add(line);
              if (sActive) step1Neighbors.add(line.targetId);
              if (tActive) step1Neighbors.add(line.sourceId);
          }
      });

      // Step 2: Lines connected to Step 1 neighbors
      if (settings.lineBrighteningSteps === 2) {
          data.lines.forEach(line => {
              if (resultLines.has(line)) return;
              const sNeighbor = step1Neighbors.has(line.sourceId);
              const tNeighbor = step1Neighbors.has(line.targetId);
              if (sNeighbor || tNeighbor) {
                  resultLines.add(line);
              }
          });
      }

      return Array.from(resultLines);
  }, [effectiveLatchedNodes, data.lines, settings.lineBrighteningEnabled, settings.lineBrighteningSteps]);

  // Refs for Render Loop
  const settingsRef = useRef(settings);
  const dataRef = useRef(data);
  const activeCursorsRef = useRef<Map<number, ActiveCursor>>(activeCursors);
  const effectiveLatchedRef = useRef(effectiveLatchedNodes);
  const nodeMapRef = useRef(nodeMap);
  const activeLinesRef = useRef(activeLines);
  const brightenedLinesRef = useRef(brightenedLines);
  const spatialGridRef = useRef(spatialGrid);
  const dynamicSizeRef = useRef(dynamicSize);

  const cursorPositionsRef = useRef<Map<number, {x: number, y: number}>>(new Map());

  // Sync Refs
  useEffect(() => { settingsRef.current = settings; }, [settings]);
  useEffect(() => { dataRef.current = data; }, [data]);
  useEffect(() => { activeCursorsRef.current = activeCursors; }, [activeCursors]);
  useEffect(() => { effectiveLatchedRef.current = effectiveLatchedNodes; }, [effectiveLatchedNodes]);
  useEffect(() => { nodeMapRef.current = nodeMap; }, [nodeMap]);
  useEffect(() => { activeLinesRef.current = activeLines; }, [activeLines]);
  useEffect(() => { brightenedLinesRef.current = brightenedLines; }, [brightenedLines]);
  useEffect(() => { spatialGridRef.current = spatialGrid; }, [spatialGrid]);
  useEffect(() => { dynamicSizeRef.current = dynamicSize; }, [dynamicSize]);

  // Interaction State
  const lastTouchedLimitRef = useRef<number | null>(null);
  const depthHistoryRef = useRef<number[]>([]);
  const [hasCentered, setHasCentered] = useState(false);
  const prevActiveChordIds = useRef<string[]>([]);

  // --- External API ---
  useImperativeHandle(ref, () => ({
    clearLatches: () => setPersistentLatches(new Map()),
    centerView: () => { centerScroll(); },
    increaseDepth: () => {
        const limit = lastTouchedLimitRef.current;
        if (limit && limit > 1) {
             updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: currentDepth + 1 } };
             });
             depthHistoryRef.current.push(limit);
        }
    },
    decreaseDepth: () => {
        const limit = depthHistoryRef.current.pop();
        if (limit) {
            updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: Math.max(0, currentDepth - 1) } };
             });
        }
    },
    getLatchedNodes: () => {
        const result: LatticeNode[] = [];
        effectiveLatchedNodes.forEach((_, id) => {
            const n = nodeMap.get(id);
            if (n) result.push(n);
        });
        return result;
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const center = dynamicSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
      }
  };

  useLayoutEffect(() => {
    const container = scrollContainerRef.current;
    if (!container) return;
    if (!hasCentered && dynamicSize > 0) {
        centerScroll();
        setHasCentered(true);
    } else if (dynamicSize !== prevDynamicSizeRef.current) {
        const diff = (dynamicSize - prevDynamicSizeRef.current) / 2;
        container.scrollLeft += diff;
        container.scrollTop += diff;
    }
    prevDynamicSizeRef.current = dynamicSize;
  }, [dynamicSize]);

  // --- Data Generation ---
  const generationDeps = useMemo(() => {
      return JSON.stringify({
          depths: settings.limitDepths,
          complexities: settings.limitComplexities,
          hidden: settings.hiddenLimits,
          ratio: settings.latticeAspectRatio
      });
  }, [settings.limitDepths, settings.limitComplexities, settings.hiddenLimits, settings.latticeAspectRatio]);

  useEffect(() => {
    setIsGenerating(true);
    const timerId = setTimeout(() => {
        const effectiveSettings: AppSettings = JSON.parse(JSON.stringify(settings));
        const hiddenLimits = effectiveSettings.hiddenLimits || [];
        hiddenLimits.forEach((limit: number) => {
            // @ts-ignore
            if (effectiveSettings.limitDepths[limit] !== undefined) effectiveSettings.limitDepths[limit] = 0;
        });

        const result = generateLattice(effectiveSettings);
        const visibleNodeIds = new Set(result.nodes.map(n => n.id));
        const visibleLines = result.lines.filter(l => {
            if (hiddenLimits.includes(l.limit)) return false;
            if (!visibleNodeIds.has(l.sourceId) || !visibleNodeIds.has(l.targetId)) return false;
            return true;
        });

        let maxExtent = 0;
        for (const n of result.nodes) {
            const absX = Math.abs(n.x);
            const absY = Math.abs(n.y);
            if (absX > maxExtent) maxExtent = absX;
            if (absY > maxExtent) maxExtent = absY;
        }

        const padding = 600; 
        const spacing = settingsRef.current.buttonSpacingScale; 
        const calculatedSize = (maxExtent * spacing * 2) + padding;
        const finalSize = Math.max(calculatedSize, window.innerWidth, window.innerHeight);

        if (Math.abs(finalSize - dynamicSizeRef.current) > 50) {
            setDynamicSize(finalSize);
        }

        setData({ nodes: result.nodes, lines: visibleLines });
        setIsGenerating(false);
    }, 10);
    return () => clearTimeout(timerId);
  }, [generationDeps]); 

  useEffect(() => {
      let maxExtent = 0;
      for (const n of data.nodes) {
          const absX = Math.abs(n.x);
          const absY = Math.abs(n.y);
          if (absX > maxExtent) maxExtent = absX;
          if (absY > maxExtent) maxExtent = absY;
      }
      const padding = 600; 
      const spacing = settings.buttonSpacingScale;
      const calculatedSize = (maxExtent * spacing * 2) + padding;
      const finalSize = Math.max(calculatedSize, window.innerWidth, window.innerHeight);
      if (Math.abs(finalSize - dynamicSize) > 50) setDynamicSize(finalSize);
  }, [settings.buttonSpacingScale]);


  // --- STATIC CANVAS RENDERER ---
  const visualDeps = useMemo(() => JSON.stringify({
      size: settings.buttonSizeScale,
      spacing: settings.buttonSpacingScale,
      colors: settings.colors,
      visuals: settings.limitVisuals,
      shape: settings.buttonShape,
      textScale: settings.nodeTextSizeScale,
      fractionBar: settings.showFractionBar,
      canvasSize: dynamicSize 
  }), [settings.buttonSizeScale, settings.buttonSpacingScale, settings.colors, settings.limitVisuals, settings.buttonShape, settings.nodeTextSizeScale, settings.showFractionBar, dynamicSize]);

  useEffect(() => {
      const canvas = staticCanvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d', { alpha: true });
      if (!ctx) return;

      const dpr = window.devicePixelRatio || 1;
      const size = dynamicSize;

      if (canvas.width !== size * dpr || canvas.height !== size * dpr) {
          canvas.width = size * dpr;
          canvas.height = size * dpr;
      }

      ctx.setTransform(1, 0, 0, 1, 0, 0);
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.scale(dpr, dpr);

      const centerOffset = size / 2;
      const spacing = settings.buttonSpacingScale;
      const baseRadius = (60 * settings.buttonSizeScale) / 2;
      const isDiamond = settings.buttonShape === ButtonShape.DIAMOND;

      const linesByLimit: Record<number, number[]> = {};
      for (const line of data.lines) {
          if (!linesByLimit[line.limit]) linesByLimit[line.limit] = [];
          const arr = linesByLimit[line.limit];
          arr.push(line.x1 * spacing + centerOffset, line.y1 * spacing + centerOffset, line.x2 * spacing + centerOffset, line.y2 * spacing + centerOffset);
      }

      ctx.lineCap = 'round';
      for (const limitStr in linesByLimit) {
          const limit = parseInt(limitStr);
          const coords = linesByLimit[limit];
          const color = settings.colors[limit] || '#666';
          const visualSettings = settings.limitVisuals?.[limit] || { size: 1, opacity: 1 };

          ctx.beginPath();
          for(let i=0; i<coords.length; i+=4) {
              ctx.moveTo(coords[i], coords[i+1]);
              ctx.lineTo(coords[i+2], coords[i+3]);
          }
          ctx.lineWidth = (limit === 1 ? 4 : 2) * visualSettings.size;
          ctx.strokeStyle = color;
          ctx.globalAlpha = 0.3 * visualSettings.opacity; 

          if (limit === 1) ctx.setLineDash([5, 5]);
          else ctx.setLineDash([]);
          ctx.stroke();
      }
      ctx.setLineDash([]); 

      for (const node of data.nodes) {
          const x = node.x * spacing + centerOffset;
          const y = node.y * spacing + centerOffset;
          const cTop = settings.colors[node.limitTop] || '#666';
          const cBottom = settings.colors[node.limitBottom] || '#666';
          const topVis = settings.limitVisuals?.[node.limitTop] || { size: 1, opacity: 1 };
          const limitScale = topVis.size;
          const limitOpacity = topVis.opacity;
          const radius = baseRadius * limitScale;

          ctx.globalAlpha = 1.0 * limitOpacity;

          ctx.beginPath();
          if (isDiamond) {
              ctx.moveTo(x, y - radius);
              ctx.lineTo(x + radius, y);
              ctx.lineTo(x, y + radius);
              ctx.lineTo(x - radius, y);
          } else {
              ctx.arc(x, y, radius, 0, Math.PI * 2);
          }
          ctx.closePath();

          const grad = ctx.createLinearGradient(x, y - radius, x, y + radius);
          grad.addColorStop(0.45, cTop);
          grad.addColorStop(0.55, cBottom);
          ctx.fillStyle = grad;
          ctx.fill();

          const combinedScale = settings.buttonSizeScale * limitScale;
          if (combinedScale > 0.4) {
              ctx.fillStyle = 'white';
              ctx.textAlign = 'center';
              ctx.textBaseline = 'middle';
              let fontSize = Math.max(10, Math.min(18, 14 * combinedScale)) * settings.nodeTextSizeScale;
              ctx.font = `bold ${fontSize}px sans-serif`; 

              const spacingY = settings.showFractionBar ? 0.55 : 0.50;
              ctx.fillText(node.n.toString(), x, y - (radius * spacingY));
              if (settings.showFractionBar) {
                  ctx.beginPath();
                  ctx.moveTo(x - (radius * 0.4), y);
                  ctx.lineTo(x + (radius * 0.4), y);
                  ctx.lineWidth = 1;
                  ctx.strokeStyle = `rgba(255,255,255,${0.8 * limitOpacity})`;
                  ctx.stroke();
              }
              ctx.fillText(node.d.toString(), x, y + (radius * spacingY));
          }
      }
  }, [data, visualDeps]); 


  // --- Logic: Latches & Audio Sync ---
  useEffect(() => {
    if (settings.chordsAlwaysRelatch) {
         const newChords = activeChordIds.filter(id => !prevActiveChordIds.current.includes(id));
         if (newChords.length > 0) {
             const nodes = nodeMap;
             newChords.forEach(chordId => {
                 const chordDef = settings.savedChords.find(c => c.id === chordId);
                 if (chordDef) {
                     chordDef.nodes.forEach(n => {
                        const fullNode = nodes.get(n.id);
                        if (fullNode) {
                            audioEngine.startVoice(`node-${n.id}`, fullNode.ratio, settings.baseFrequency);
                            if (settings.midiEnabled) midiService.noteOn(`node-${n.id}`, fullNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
                        }
                     });
                 }
             });
         }
    }
    prevActiveChordIds.current = activeChordIds;
  }, [activeChordIds, settings.savedChords, settings.chordsAlwaysRelatch, nodeMap]);

  const prevEffectiveRef = useRef<Map<string, string>>(new Map());
  useEffect(() => {
      const current = effectiveLatchedNodes;
      const prev = prevEffectiveRef.current;
      const nodes = nodeMap;

      current.forEach((originId, nodeId) => {
          if (!prev.has(nodeId)) {
               const node = nodes.get(nodeId); 
               if (node) {
                   audioEngine.startVoice(`node-${nodeId}`, node.ratio, settings.baseFrequency);
                   if (settings.midiEnabled) midiService.noteOn(`node-${nodeId}`, node.ratio, settings.baseFrequency, settings.midiPitchBendRange);
               }
          }
      });
      prev.forEach((_, nodeId) => {
          if (!current.has(nodeId)) {
              audioEngine.stopVoice(`node-${nodeId}`);
              if (settings.midiEnabled) midiService.noteOff(`node-${nodeId}`);
          }
      });

      prevEffectiveRef.current = current;
  }, [effectiveLatchedNodes, nodeMap, settings.baseFrequency]);

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony]);

  // Helper for Hit Testing
  const getHitNode = (clientX: number, clientY: number): LatticeNode | null => {
      if (!dynamicCanvasRef.current) return null;
      const rect = dynamicCanvasRef.current.getBoundingClientRect();
      const x = clientX - rect.left;
      const y = clientY - rect.top;

      const centerOffset = dynamicSizeRef.current / 2;
      const spacing = settings.buttonSpacingScale;
      const baseRadius = (60 * settings.buttonSizeScale) / 2;

      const col = Math.floor(x / GRID_CELL_SIZE);
      const row = Math.floor(y / GRID_CELL_SIZE);

      const cellsToCheck = [
          `${col},${row}`, `${col+1},${row}`, `${col-1},${row}`,
          `${col},${row+1}`, `${col},${row-1}`,
          `${col+1},${row+1}`, `${col-1},${row-1}`,
          `${col+1},${row-1}`, `${col-1},${row+1}`
      ];

      const grid = spatialGridRef.current;

      for(const key of cellsToCheck) {
          const nodesInCell = grid.get(key);
          if (nodesInCell) {
              for (const node of nodesInCell) {
                  const nx = node.x * spacing + centerOffset;
                  const ny = node.y * spacing + centerOffset;
                  const vis = settings.limitVisuals?.[node.limitTop] || { size: 1 };
                  const r = baseRadius * vis.size;

                  if (x < nx - r || x > nx + r || y < ny - r || y > ny + r) continue;

                  const dx = x - nx;
                  const dy = y - ny;
                  if (dx*dx + dy*dy < r*r) return node;
              }
          }
      }
      return null;
  };

  // --- Interaction Handlers ---
  const handlePointerDown = (e: React.PointerEvent) => {
      if (uiUnlocked || !dynamicCanvasRef.current) return;
      e.preventDefault();
      (e.target as HTMLElement).setPointerCapture(e.pointerId);

      cursorPositionsRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });

      const hitNode = getHitNode(e.clientX, e.clientY);
      const nodeId = hitNode ? hitNode.id : null;

      // Stop Strumming (Empty Space Click) if in Latch Mode 1
      if (!hitNode && latchMode === 1) {
          return;
      }

      // Track cursor logic
      setActiveCursors(prev => {
          const next = new Map(prev);
          next.set(e.pointerId, {
              pointerId: e.pointerId,
              currentX: e.clientX,
              currentY: e.clientY,
              originNodeId: nodeId, 
              hoverNodeId: nodeId   
          });
          return next;
      });

      if (hitNode) {
        // Limit expansion
        const topLayer = settings.layerOrder[settings.layerOrder.length - 1];
        if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);
        lastTouchedLimitRef.current = hitNode.maxPrime;

        // Latch Mode Logic (Persistent Toggles)
        if (latchMode === 1) {
             setPersistentLatches(prev => {
                 const next = new Map(prev);
                 if (next.has(hitNode.id)) next.delete(hitNode.id);
                 else next.set(hitNode.id, hitNode.id);
                 return next;
             });
        }

        // Audio Triggers (Modes 0 and 2)
        if (settings.isPitchBendEnabled && latchMode !== 1) {
            audioEngine.startVoice(`cursor-${e.pointerId}`, hitNode.ratio, settings.baseFrequency);
            if (settings.midiEnabled) midiService.noteOn(`cursor-${e.pointerId}`, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
        }
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (uiUnlocked) return;
    if (!activeCursorsRef.current.has(e.pointerId)) return;

    cursorPositionsRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });

    const cursor = activeCursorsRef.current.get(e.pointerId)!;
    const hitNode = getHitNode(e.clientX, e.clientY);
    const hitId = hitNode ? hitNode.id : null;

    // --- LATCH MODE 1: CHORD DRAWING (PAINT) ---
    // Takes precedence over Held/Strum logic to allow drawing even if started on a node
    if (latchMode === 1) {
        if (cursor.hoverNodeId !== hitId) {
            if (hitNode) {
                 const topLayer = settingsRef.current.layerOrder[settingsRef.current.layerOrder.length - 1];
                 if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);
            }
            if (hitId) {
                setPersistentLatches(prev => {
                    const next = new Map(prev);
                    // Simply toggle on enter. This allows drawing a chord by swiping.
                    if (next.has(hitId)) next.delete(hitId);
                    else next.set(hitId, hitId);
                    return next;
                });
            }
            // Update tracking
            setActiveCursors((prev: Map<number, ActiveCursor>) => {
                const next = new Map(prev);
                const c = next.get(e.pointerId);
                if(c) { 
                    const updatedCursor = { ...c, hoverNodeId: hitId };
                    next.set(e.pointerId, updatedCursor); 
                }
                return next;
            });
        }
        return;
    }

    // DECISION: Are we Holding (Pitch Bending) or Strumming?
    if (cursor.originNodeId) {
        // --- HELD NOTE (Started on Node) ---
        // Logic: Calculate Pitch Bend (Mode 0/2)
        if (settings.isPitchBendEnabled && latchMode !== 1 && scrollContainerRef.current) {
             const centerOffset = dynamicSizeRef.current / 2;
             const rect = scrollContainerRef.current.getBoundingClientRect();
             const originNode = nodeMapRef.current.get(cursor.originNodeId);
             if (originNode) {
                 const spacing = settings.buttonSpacingScale;
                 const originScreenY = (originNode.y * spacing + centerOffset) + rect.top - scrollContainerRef.current.scrollTop;
                 const deltaY = e.clientY - originScreenY;
                 const bentRatio = getPitchRatioFromScreenDelta(deltaY, settings.buttonSpacingScale);
                 const finalRatio = originNode.ratio * bentRatio;
                 audioEngine.glideVoice(`cursor-${e.pointerId}`, finalRatio, settings.baseFrequency, 0.05);
                 if (settings.midiEnabled) midiService.pitchBend(`cursor-${e.pointerId}`, finalRatio, settings.baseFrequency, settings.midiPitchBendRange);
             }
        }
    } else {
        // --- STRUMMING (Started on Empty) ---
        if (cursor.hoverNodeId !== hitId) {
            if (hitNode) {
                 const topLayer = settingsRef.current.layerOrder[settingsRef.current.layerOrder.length - 1];
                 if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);
            }
            // Update Cursor State
            setActiveCursors((prev: Map<number, ActiveCursor>) => {
                const next = new Map(prev);
                const existing = next.get(e.pointerId);
                if (existing) {
                    const c = { ...existing };
                    c.hoverNodeId = hitId;
                    next.set(e.pointerId, c);
                    return next;
                }
                return prev;
            });
        }
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursorsRef.current.has(e.pointerId)) {
        const cursor = activeCursorsRef.current.get(e.pointerId)!;

        // Stop Pitch Bend Voice if it exists (only for Held notes in Mode 0/2)
        if (cursor.originNodeId && latchMode !== 1) {
            audioEngine.stopVoice(`cursor-${e.pointerId}`);
            if (settings.midiEnabled) midiService.noteOff(`cursor-${e.pointerId}`);
        }

        cursorPositionsRef.current.delete(e.pointerId);
        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            return next;
        });
    }
  };

  // --- Animation Loop ---
  useEffect(() => {
    const canvas = dynamicCanvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d', { alpha: true });
    if (!ctx) return;

    const dpr = window.devicePixelRatio || 1;

    const render = (time: number) => {
        const currentSettings = settingsRef.current;
        const currentLatched = effectiveLatchedRef.current;
        const currentActiveLines = activeLinesRef.current;
        const currentBrightenedLines = brightenedLinesRef.current;
        const size = dynamicSizeRef.current;
        const cursors = activeCursorsRef.current;

        if (canvas.width !== size * dpr || canvas.height !== size * dpr) {
            canvas.width = size * dpr;
            canvas.height = size * dpr;
            ctx.scale(dpr, dpr);
        }

        let viewX = 0, viewY = 0, viewW = size, viewH = size;
        if (scrollContainerRef.current) {
            viewX = scrollContainerRef.current.scrollLeft;
            viewY = scrollContainerRef.current.scrollTop;
            viewW = scrollContainerRef.current.clientWidth;
            viewH = scrollContainerRef.current.clientHeight;
        }

        ctx.clearRect(viewX, viewY, viewW, viewH);

        const centerOffset = size / 2;
        const spacing = currentSettings.buttonSpacingScale;
        const baseRadius = (60 * currentSettings.buttonSizeScale) / 2;
        const isDiamond = currentSettings.buttonShape === ButtonShape.DIAMOND;
        const colorCache = currentSettings.colors;

        const animationSpeed = (currentSettings.voiceLeadingAnimationSpeed || 2.0) * 0.33;
        const rawPhase = (time * 0.001 * animationSpeed);
        const flowPhase = currentSettings.voiceLeadingReverseDir ? (1.0 - (rawPhase % 1.0)) : (rawPhase % 1.0);

        ctx.lineCap = 'round';

        const viewPad = 100;
        const leftBound = viewX - viewPad;
        const rightBound = viewX + viewW + viewPad;
        const topBound = viewY - viewPad;
        const bottomBound = viewY + viewH + viewPad;

        // --- LAYER 1: BRIGHTENED LINES (Active Neighborhood) ---
        // Draw these first so they are behind nodes
        if (currentBrightenedLines.length > 0) {
            ctx.setLineDash([]);
            for (const line of currentBrightenedLines) {
                const x1 = line.x1 * spacing + centerOffset;
                const y1 = line.y1 * spacing + centerOffset;
                const x2 = line.x2 * spacing + centerOffset;
                const y2 = line.y2 * spacing + centerOffset;

                if (Math.max(x1, x2) < leftBound || Math.min(x1, x2) > rightBound || Math.max(y1, y2) < topBound || Math.min(y1, y2) > bottomBound) continue;

                const limitColor = colorCache[line.limit] || '#666';

                ctx.beginPath();
                ctx.moveTo(x1, y1);
                ctx.lineTo(x2, y2);
                ctx.lineWidth = 2;
                ctx.strokeStyle = limitColor;
                ctx.globalAlpha = 0.8; 
                ctx.stroke();
            }
        }

        // --- LAYER 2: ACTIVE VOICE LEADING GRID LINES ---
        ctx.setLineDash([]); 
        for (const line of currentActiveLines) {
            const x1 = line.x1 * spacing + centerOffset;
            const y1 = line.y1 * spacing + centerOffset;
            const x2 = line.x2 * spacing + centerOffset;
            const y2 = line.y2 * spacing + centerOffset;

            if (Math.max(x1, x2) < leftBound || Math.min(x1, x2) > rightBound || Math.max(y1, y2) < topBound || Math.min(y1, y2) > bottomBound) continue;

            const limitColor = colorCache[line.limit] || '#666';

            ctx.beginPath();
            ctx.moveTo(x1, y1);
            ctx.lineTo(x2, y2);
            ctx.lineWidth = 4;
            ctx.strokeStyle = limitColor;
            ctx.globalAlpha = 1.0;
            ctx.stroke();

            if (currentSettings.isVoiceLeadingAnimationEnabled) {
                const grad = ctx.createLinearGradient(x1, y1, x2, y2);
                const p = flowPhase;

                grad.addColorStop(0, 'rgba(255,255,255,0)');
                const pulseWidth = 0.2;
                const start = Math.max(0, p - pulseWidth);
                const end = Math.min(1, p + pulseWidth);
                if (start > 0) grad.addColorStop(start, 'rgba(255,255,255,0)');
                grad.addColorStop(p, 'rgba(255,255,255,0.7)'); 
                if (end < 1) grad.addColorStop(end, 'rgba(255,255,255,0)');
                grad.addColorStop(1, 'rgba(255,255,255,0)');

                ctx.strokeStyle = grad;
                ctx.lineWidth = 10 * (0.5 + currentSettings.voiceLeadingGlowAmount);
                ctx.globalAlpha = 0.3; 
                ctx.stroke();

                ctx.lineWidth = 4;
                ctx.globalAlpha = 1.0;
                ctx.stroke();
            }
        }

        // --- LAYER 4: NODES (Always on Top) ---
        // Collect ALL nodes that need to be drawn on the dynamic layer to cover the lines.
        // This includes Latched nodes AND any node touched by an active/brightened line.
        const nodesToDraw = new Set(currentLatched.keys());

        currentActiveLines.forEach(l => { nodesToDraw.add(l.sourceId); nodesToDraw.add(l.targetId); });
        currentBrightenedLines.forEach(l => { nodesToDraw.add(l.sourceId); nodesToDraw.add(l.targetId); });

        for (const id of nodesToDraw) {
             const node = nodeMapRef.current.get(id);
             if (!node) continue;

             const isLatched = currentLatched.has(id);

             const x = node.x * spacing + centerOffset;
             const y = node.y * spacing + centerOffset;

             if (x < leftBound || x > rightBound || y < topBound || y > bottomBound) continue;

             const cTop = colorCache[node.limitTop] || '#666';
             const cBottom = colorCache[node.limitBottom] || '#666';

             const vis = currentSettings.limitVisuals?.[node.limitTop] || { size: 1 };

             // Scale Logic: Latched gets Zoom, Unlatched gets standard size
             const limitScale = vis.size;
             const zoomScale = isLatched ? currentSettings.latchedZoomScale : 1.0;
             const radius = baseRadius * limitScale * zoomScale;

             ctx.globalAlpha = 1.0; 
             ctx.beginPath();
             if (isDiamond) {
                ctx.moveTo(x, y - radius);
                ctx.lineTo(x + radius, y);
                ctx.lineTo(x, y + radius);
                ctx.lineTo(x - radius, y);
             } else {
                ctx.arc(x, y, radius, 0, Math.PI * 2);
             }
             ctx.closePath();

             const grad = ctx.createLinearGradient(x, y - radius, x, y + radius);
             grad.addColorStop(0.45, cTop);
             grad.addColorStop(0.55, cBottom);
             ctx.fillStyle = grad;
             ctx.fill();

             // Outline Logic
             if (isLatched) {
                 if (currentSettings.isColoredIlluminationEnabled) {
                     const rainbowPeriod = getRainbowPeriod(spacing); 
                     const phase = (y % rainbowPeriod) / rainbowPeriod;
                     const hue = (currentSettings.rainbowOffset + phase * 360) % 360;
                     const sat = currentSettings.isRainbowModeEnabled ? currentSettings.rainbowSaturation : 100;
                     ctx.strokeStyle = `hsl(${hue}, ${sat}%, 60%)`;
                     ctx.lineWidth = 4;
                 } else {
                     ctx.strokeStyle = 'white';
                     ctx.lineWidth = 3;
                 }
                 ctx.stroke();
             } 
             // Unlatched nodes don't need a stroke unless desired for visibility, 
             // but usually they just cover the line ends.

             const combinedScale = currentSettings.buttonSizeScale * limitScale * zoomScale;
             if (combinedScale > 0.4) {
                ctx.fillStyle = 'white';
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                let fontSize = Math.max(12, Math.min(22, 16 * combinedScale)) * currentSettings.nodeTextSizeScale;
                ctx.font = `bold ${fontSize}px sans-serif`; 
                const spacingY = currentSettings.showFractionBar ? 0.55 : 0.50;
                ctx.fillText(node.n.toString(), x, y - (radius * spacingY));
                if (currentSettings.showFractionBar) {
                    ctx.beginPath();
                    ctx.moveTo(x - (radius * 0.4), y);
                    ctx.lineTo(x + (radius * 0.4), y);
                    ctx.lineWidth = 1;
                    ctx.strokeStyle = isLatched ? 'white' : `rgba(255,255,255,0.8)`;
                    ctx.stroke();
                }
                ctx.fillText(node.d.toString(), x, y + (radius * spacingY));
             }
        }

        // Draw drag lines for PITCH BEND (Only held notes)
        cursors.forEach(c => {
            if (c.originNodeId) { 
                const node = nodeMapRef.current.get(c.originNodeId);
                if(node) {
                     const nx = node.x * spacing + centerOffset;
                     const ny = node.y * spacing + centerOffset;
                     const pos = cursorPositionsRef.current.get(c.pointerId);
                     if (!pos) return;

                     let cx = 0, cy = 0;
                     if (scrollContainerRef.current) {
                         const r = scrollContainerRef.current.getBoundingClientRect();
                         cx = (pos.x - r.left) + scrollContainerRef.current.scrollLeft;
                         cy = (pos.y - r.top) + scrollContainerRef.current.scrollTop;
                     }

                     ctx.beginPath();
                     ctx.moveTo(nx, ny);
                     ctx.lineTo(cx, cy);
                     ctx.strokeStyle = 'white';
                     ctx.lineWidth = 2;
                     ctx.globalAlpha = 0.5;
                     ctx.stroke();
                }
            }
        });

        animationFrameRef.current = requestAnimationFrame(render);
    };

    animationFrameRef.current = requestAnimationFrame(render);
    return () => cancelAnimationFrame(animationFrameRef.current);
  }, []); 

  const rainbowPeriod = getRainbowPeriod(settings.buttonSpacingScale);

  const rainbowBackgroundFixed = useMemo(() => {
    if (settings.isRainbowModeEnabled) {
        const stops: string[] = [];
        const steps = 6;
        for (let i = 0; i <= steps; i++) {
            const pct = (i / steps) * 100;
            const hue = (settings.rainbowOffset + i * 60); 
            stops.push(`hsl(${hue}, ${settings.rainbowSaturation}%, ${settings.rainbowBrightness}%) ${pct}%`);
        }
        return `linear-gradient(to bottom, ${stops.join(', ')})`;
    }
    return undefined;
  }, [settings.isRainbowModeEnabled, settings.rainbowOffset, settings.rainbowSaturation, settings.rainbowBrightness]);

  const bgOffsetY = (dynamicSize / 2) - (rainbowPeriod / 3);

  return (
    <div 
        ref={scrollContainerRef}
        className="w-full h-full overflow-auto bg-slate-950 relative"
        style={{ touchAction: 'none' }}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerLeave={handlePointerUp}
        onPointerCancel={handlePointerUp}
    >
        <div 
            className="relative"
            style={{ 
                width: dynamicSize, 
                height: dynamicSize,
                backgroundImage: rainbowBackgroundFixed,
                backgroundSize: `100% ${rainbowPeriod}px`,
                backgroundRepeat: 'repeat',
                backgroundPosition: `0px ${bgOffsetY}px`,
                pointerEvents: uiUnlocked ? 'none' : 'auto',
            }}
        >
           <canvas 
             ref={staticCanvasRef}
             className="absolute top-0 left-0 z-0 pointer-events-none"
             style={{ width: '100%', height: '100%' }}
           />
           <canvas 
             ref={dynamicCanvasRef}
             className="absolute top-0 left-0 z-10"
             style={{ width: '100%', height: '100%' }}
           />

           {isGenerating && (
             <div className="absolute top-4 right-4 z-50 flex items-center gap-2 bg-slate-900/80 p-2 rounded-full backdrop-blur-sm border border-white/10 shadow-xl">
                 <svg className="animate-spin h-5 w-5 text-blue-500" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                   <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                   <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                 </svg>
                 <span className="text-xs font-bold text-slate-300 pr-2">Calculating...</span>
             </div>
           )}
        </div>
    </div>
  );
});

