export enum LimitType {
  LIMIT_3 = 3,
  LIMIT_5 = 5,
  LIMIT_7 = 7,
  LIMIT_11 = 11,
  LIMIT_13 = 13,
}

export enum WaveformType {
  SINE = 'sine',
  SQUARE = 'square',
  SAWTOOTH = 'sawtooth',
  TRIANGLE = 'triangle',
}

export enum ButtonShape {
  CIRCLE = '50%',
  DIAMOND = '0%',
}

export interface LimitColorMap {
  [key: number]: string;
}

export interface LimitVisualSetting {
    size: number;   // 0.1 to 2.0 (Multiplier of base size)
    opacity: number; // 0.0 to 1.0
}

export interface LimitVisualsMap {
    [key: number]: LimitVisualSetting;
}

export interface ChordNode {
  id: string; // Coordinate key
  n: number;
  d: number;
}

export interface ChordDefinition {
  id: string; // "A", "B", etc.
  label: string;
  color: string;
  nodes: ChordNode[];
  visible: boolean; // Is shortcut on screen?
  position: { x: number; y: number }; // Relative position or legacy absolute
}

export interface XYPos {
  x: number;
  y: number;
}

export interface AppSettings {
  // Individual depths (Steps from center)
  limitDepths: {
    3: number;
    5: number;
    7: number;
    11: number;
    13: number;
  };

  // Individual complexity limits (Max Numerator/Denominator per axis)
  limitComplexities: {
    3: number;
    5: number;
    7: number;
    11: number;
    13: number;
  };

  // Increase Depth Settings
  showIncreaseDepthButton: boolean;
  centerResetsDepth: boolean;

  // Chords
  savedChords: ChordDefinition[];
  chordShortcutSizeScale: number; // 0.33 to 1.0 relative to main buttons
  chordsAlwaysRelatch: boolean; // If true, activating a chord re-triggers notes even if playing

  // Visible toggle for lower limits (View only)
  hiddenLimits: number[]; 

  layerOrder: number[]; // Array of limit numbers, index 0 = back, last index = front

  // Audio Settings
  baseFrequency: number; // Hz for 1/1

  // Voice Leading / Focus Mode
  isVoiceLeadingEnabled: boolean;
  voiceLeadingStrength: number; // 0 to 1, higher means stricter falloff

  // Voice Leading Visuals
  isVoiceLeadingAnimationEnabled: boolean;
  voiceLeadingAnimationSpeed: number; // seconds
  voiceLeadingReverseDir: boolean; // Reverse the direction of the flow animation
  voiceLeadingGlowAmount: number; // 0.0 to 1.0 (Controls width/intensity of the lobe)
  voiceLeadingSteps: number; // 1 or 2 (Reach for active voice leading lines)

  // Line Brightening
  lineBrighteningEnabled: boolean;
  lineBrighteningSteps: number; // 1 or 2

  // Momentum is deprecated/greyed out in favor of Latch Mode
  isMomentumEnabled: boolean; 

  // Latch Settings
  latchedZoomScale: number; // Scale factor for active nodes (1.0 to 2.0)

  // Appearance
  buttonSizeScale: number; // Global Scalar 0.5 to 2.0
  buttonSpacingScale: number; // 0.5 to 5.0
  latticeAspectRatio: number; // 0.5 (Stretched X) to 2.0 (Squished X)
  canvasSize: number; // Width/Height of the scrollable area in pixels (e.g. 3000, 5000)
  buttonShape: ButtonShape;
  colors: LimitColorMap;

  // Per-Limit Visuals (Size/Opacity)
  limitVisuals: LimitVisualsMap;

  // Text Appearance
  nodeTextSizeScale: number; // 0.5 to 2.0
  showFractionBar: boolean;

  isPitchBendEnabled: boolean;
  isPitchSnapEnabled: boolean;
  polyphony: number;
  pitchOffLocked: boolean;
  volumeLocked: boolean;

  // Visuals - Rainbow
  isRainbowModeEnabled: boolean;
  rainbowSaturation: number; // 0-100
  rainbowBrightness: number; // 0-100
  rainbowOffset: number; // 0-360 (Hue shift)
  isColoredIlluminationEnabled: boolean;

  // MIDI Settings
  midiEnabled: boolean;
  midiOutputId: string | null;
  midiPitchBendRange: number; // Semitones (typically 2, 12, 24, or 48)

  // UI Relocation
  uiUnlocked: boolean;
  uiPositions: {
    volume: XYPos;
    space: XYPos;
    panic: XYPos;
    off: XYPos;
    latch: XYPos;
    bend: XYPos;
    center: XYPos;
    depth: XYPos;
    decreaseDepth: XYPos;
    chords: XYPos;
    layers: XYPos;
  };
}

export interface OscillatorConfig {
  enabled: boolean;
  waveform: WaveformType;
  coarseDetune: number; // Cents -1200 to 1200
  fineDetune: number; // Cents -50 to 50
  gain: number; // 0 to 1 (Mix)

  // Envelope
  attack: number;
  decay: number;
  sustain: number;
  release: number;

  // Filter
  filterCutoff: number; // Hz
  filterResonance: number; // Q factor

  // LFO
  lfoRate: number; // Hz
  lfoDepth: number; // Amount 0-100
  lfoTarget: 'none' | 'pitch' | 'filter' | 'tremolo';
}

export type ModSource = 'lfo1' | 'lfo2' | 'lfo3' | 'env1' | 'env2' | 'env3';
export type ModTarget = 
    'osc1_pitch' | 'osc1_gain' | 'osc1_cutoff' | 'osc1_res' |
    'osc2_pitch' | 'osc2_gain' | 'osc2_cutoff' | 'osc2_res' |
    'osc3_pitch' | 'osc3_gain' | 'osc3_cutoff' | 'osc3_res';

export interface ModulationRow {
    id: string;
    enabled: boolean;
    source: ModSource;
    target: ModTarget;
    amount: number; // -100 to 100
}

export type ReverbType = 'room' | 'hall' | 'cathedral' | 'plate' | 'shimmer';

export interface SynthPreset {
  id: number | string;
  name: string;

  osc1: OscillatorConfig;
  osc2: OscillatorConfig;
  osc3: OscillatorConfig;

  // Modulation Matrix
  modMatrix: ModulationRow[];

  // Master Gain for the preset
  gain: number; 

  // Stereo Settings (New)
  spread?: number; // 0 to 1 (Width)
  stereoPanSpeed?: number; // Hz
  stereoPanDepth?: number; // 0 to 1 (Auto-Pan amount)
  reverbType?: ReverbType; // Convolution Preset

  // Effects (Global)
  reverbMix: number; // 0 to 1
  delayMix: number; // 0 to 1
  delayTime: number; // Seconds
  delayFeedback: number; // 0 to 0.95

  // Dynamics (Compressor/Limiter) (Global)
  compressorThreshold: number; // dB (-60 to 0)
  compressorRatio: number; // 1 to 20
  compressorRelease: number; // seconds
}

export interface LatticeNode {
  id: string; // Coordinate key "0,0,0,0,0:oct"
  ratio: number; // Absolute Frequency multiplier (including octave)
  n: number; // Numerator (adjusted for octave)
  d: number; // Denominator (adjusted for octave)
  label: string; 
  x: number; // Screen X
  y: number; // Screen Y
  limitTop: number; 
  limitBottom: number;
  maxPrime: number; // For Z-sorting
  coords: number[]; // [p3, p5, p7, p11, p13]
  octave: number; // -2, -1, 0, 1, 2
}

export interface LatticeLine {
  id: string;
  x1: number;
  y1: number;
  x2: number;
  y2: number;
  limit: number;
  sourceId: string;
  targetId: string;
}

export interface ActiveVoice {
  id: string; // Pointer ID or Node ID
  nodeId?: string;
  stop: () => void;
  setDetune: (cents: number) => void;
}

export interface GenerationOrigin {
  coords: number[];
  octave: number;
}

import { SynthPreset, WaveformType, OscillatorConfig, AppSettings, ReverbType } from '../types';
import { store } from './Store';
import { DEFAULT_PRESET } from '../constants';
import { AUDIO_PROCESSOR_CODE } from './AudioProcessorCode';

class AudioEngine {
  private ctx: AudioContext | null = null;
  private workletNode: AudioWorkletNode | null = null;
  private initPromise: Promise<void> | null = null;

  // FX Chain
  private limiter: DynamicsCompressorNode | null = null;
  private dryGain: GainNode | null = null;
  private reverbNode: ConvolverNode | null = null;
  private reverbGain: GainNode | null = null;
  private delayNode: DelayNode | null = null;
  private delayFeedbackGain: GainNode | null = null;
  private delayOutputGain: GainNode | null = null;

  private currentMasterVol: number = 0.8;
  private globalSpatialScale: number = 1.0;
  private activePreset: SynthPreset;

  constructor() {
    // Initialize Preset safely to prevent NaN in Worklet
    const rawPreset = store.getSnapshot().preset;
    this.activePreset = this.ensurePresetSafety(rawPreset);

    store.subscribe(() => {
        const newPreset = store.getSnapshot().preset;
        const safePreset = this.ensurePresetSafety(newPreset);
        this.setPreset(safePreset);
    });
  }

  private ensurePresetSafety(p: any): SynthPreset {
     if (!p) return DEFAULT_PRESET;
     const safe = { ...DEFAULT_PRESET, ...p };
     safe.osc1 = { ...DEFAULT_PRESET.osc1, ...(p.osc1 || {}) };
     safe.osc2 = { ...DEFAULT_PRESET.osc2, ...(p.osc2 || {}) };
     safe.osc3 = { ...DEFAULT_PRESET.osc3, ...(p.osc3 || {}) };
     safe.modMatrix = p.modMatrix || [];
     safe.reverbType = p.reverbType || 'hall'; // Default to hall for backward compat
     return safe;
  }

  public async init() {
    if (this.initPromise) return this.initPromise;

    this.initPromise = (async () => {
        if (!this.ctx) {
            this.ctx = new (window.AudioContext || (window as any).webkitAudioContext)({
                latencyHint: 'interactive',
            });

            try {
                // Load AudioWorklet from Blob to guarantee no 404s in any environment
                const blob = new Blob([AUDIO_PROCESSOR_CODE], { type: 'application/javascript' });
                const workletUrl = URL.createObjectURL(blob);

                await this.ctx.audioWorklet.addModule(workletUrl);

                // Clean up the object URL after loading
                URL.revokeObjectURL(workletUrl);

                this.workletNode = new AudioWorkletNode(this.ctx, 'synth-processor', {
                    numberOfInputs: 0,
                    numberOfOutputs: 1,
                    outputChannelCount: [2]
                });

                // Initial preset send
                this.workletNode.port.postMessage({ type: 'preset', data: this.activePreset });
                this.workletNode.port.postMessage({ type: 'config', polyphony: store.getSnapshot().settings.polyphony });

                // Connect logic
                this.setupFX();

                if (this.workletNode && this.dryGain && this.reverbGain && this.delayOutputGain) {
                     this.workletNode.connect(this.dryGain);
                     this.workletNode.connect(this.reverbGain);
                     this.workletNode.connect(this.delayOutputGain);
                }

            } catch (e) {
                console.error("Failed to load AudioWorklet", e);
                this.initPromise = null; 
                return;
            }
        }

        if (this.ctx && this.ctx.state === 'suspended') {
            await this.ctx.resume();
        }
    })();

    return this.initPromise;
  }

  private setupFX() {
    if (!this.ctx) return;

    // Disconnect old nodes if they exist to clear state
    try {
        this.dryGain?.disconnect();
        this.reverbNode?.disconnect();
        this.reverbGain?.disconnect();
        this.delayNode?.disconnect();
        this.delayFeedbackGain?.disconnect();
        this.delayOutputGain?.disconnect();
        this.limiter?.disconnect();
    } catch(e) { /* ignore */ }

    // Rebuild Graph
    this.limiter = this.ctx.createDynamicsCompressor();
    this.limiter.threshold.value = -12.0; 
    this.limiter.ratio.value = 12.0;
    this.limiter.connect(this.ctx.destination);

    this.dryGain = this.ctx.createGain();
    this.dryGain.connect(this.limiter);

    this.reverbNode = this.ctx.createConvolver();
    // Initialize with current preset setting
    this.updateReverbBuffer();

    this.reverbGain = this.ctx.createGain();
    this.reverbGain.connect(this.reverbNode);
    this.reverbNode.connect(this.limiter);

    this.delayNode = this.ctx.createDelay(5.0);
    this.delayFeedbackGain = this.ctx.createGain();
    this.delayOutputGain = this.ctx.createGain();

    this.delayOutputGain.connect(this.delayNode);
    this.delayNode.connect(this.limiter); 
    this.delayNode.connect(this.delayFeedbackGain);
    this.delayFeedbackGain.connect(this.delayNode);

    // Reconnect Worklet to new graph
    if (this.workletNode) {
        this.workletNode.disconnect();
        this.workletNode.connect(this.dryGain);
        this.workletNode.connect(this.reverbGain);
        this.workletNode.connect(this.delayOutputGain);
    }

    this.updateFX();
    this.setMasterVolume(this.currentMasterVol);
  }

  private updateReverbBuffer() {
      if (!this.reverbNode || !this.ctx) return;
      const type = this.activePreset.reverbType || 'hall';

      let duration = 2.5;
      let decay = 2.0;

      // Presets definition
      switch(type) {
          case 'room': duration = 1.0; decay = 4.0; break;
          case 'hall': duration = 2.5; decay = 2.0; break;
          case 'cathedral': duration = 5.0; decay = 1.5; break;
          case 'plate': duration = 1.5; decay = 3.0; break; // Shorter but dense
          case 'shimmer': duration = 8.0; decay = 0.5; break; // Very long
          default: duration = 2.5; decay = 2.0;
      }

      this.reverbNode.buffer = this.createImpulseResponse(duration, decay);
  }

  private updateFX() {
      if (!this.ctx) return;
      const now = this.ctx.currentTime;
      const ramp = 0.1;

      // Apply Global Spatial Scale to Reverb and Delay Mix
      const scaledReverbMix = Math.min(1.0, this.activePreset.reverbMix * this.globalSpatialScale);
      const scaledDelayMix = Math.min(1.0, this.activePreset.delayMix * this.globalSpatialScale);

      if (this.reverbGain) this.reverbGain.gain.setTargetAtTime(scaledReverbMix, now, ramp);
      if (this.delayOutputGain) this.delayOutputGain.gain.setTargetAtTime(scaledDelayMix, now, ramp);

      const scaledFeedback = Math.min(0.95, this.activePreset.delayFeedback * Math.sqrt(this.globalSpatialScale));
      if (this.delayFeedbackGain) this.delayFeedbackGain.gain.setTargetAtTime(scaledFeedback, now, ramp);

      if (this.delayNode) this.delayNode.delayTime.setTargetAtTime(this.activePreset.delayTime, now, ramp);

      if (this.limiter) {
          const thresh = this.activePreset.compressorThreshold ?? -20.0;
          const ratio = this.activePreset.compressorRatio ?? 12;
          const release = this.activePreset.compressorRelease ?? 0.25;

          this.limiter.threshold.setTargetAtTime(thresh, now, ramp);
          this.limiter.ratio.setTargetAtTime(ratio, now, ramp);
          this.limiter.release.setTargetAtTime(release, now, ramp);
      }

      if (this.dryGain) {
          const dryLevel = Math.max(0.5, 1.0 - (scaledReverbMix * 0.4));
          this.dryGain.gain.setTargetAtTime(dryLevel * this.currentMasterVol, now, ramp);
      }
  }

  private createImpulseResponse(duration: number, decay: number): AudioBuffer {
    if (!this.ctx) throw new Error("No Context");
    const sampleRate = this.ctx.sampleRate;
    const length = sampleRate * duration;
    const impulse = this.ctx.createBuffer(2, length, sampleRate);
    const left = impulse.getChannelData(0);
    const right = impulse.getChannelData(1);

    let maxVal = 0;
    for (let i = 0; i < length; i++) {
        const n = i / length;
        const amp = Math.pow(1 - n, decay);
        left[i] = (Math.random() * 2 - 1) * amp;
        right[i] = (Math.random() * 2 - 1) * amp;
        if (Math.abs(left[i]) > maxVal) maxVal = Math.abs(left[i]);
        if (Math.abs(right[i]) > maxVal) maxVal = Math.abs(right[i]);
    }

    const scale = 0.1 / Math.max(0.001, maxVal); 
    for (let i = 0; i < length; i++) {
        left[i] *= scale;
        right[i] *= scale;
    }

    return impulse;
  }

  public setPolyphony(count: number) {
      if (this.workletNode) {
          this.workletNode.port.postMessage({ type: 'config', polyphony: count });
      }
  }

  public setMasterVolume(val: number) {
    this.currentMasterVol = val;
    this.updateFX();
  }

  public setGlobalSpatialScale(val: number) {
      this.globalSpatialScale = val;
      this.updateFX();
  }

  public setPreset(preset: SynthPreset) {
    const prevType = this.activePreset.reverbType;
    this.activePreset = preset;

    // Check if reverb type changed
    if (this.ctx && prevType !== preset.reverbType) {
        this.updateReverbBuffer();
    }

    this.updateFX();
    if (this.workletNode) {
        this.workletNode.port.postMessage({ type: 'preset', data: preset });
    }
  }

  public async startVoice(id: string, ratio: number, baseFrequency: number) {
    await this.init();
    if (!this.workletNode) return;

    const freq = baseFrequency * ratio;
    this.workletNode.port.postMessage({ 
        type: 'note_on', 
        id: id, 
        freq: freq 
    });
  }

  public stopVoice(id: string, immediate: boolean = false) {
    if (!this.workletNode) return;
    this.workletNode.port.postMessage({ 
        type: 'note_off', 
        id: id 
    });
  }

  public glideVoice(id: string, newRatio: number, baseFrequency: number, glideTime: number = 0.1) {
    if (!this.workletNode) return;
    const freq = baseFrequency * newRatio;
    this.workletNode.port.postMessage({ 
        type: 'glide', 
        id: id, 
        freq: freq 
    });
  }

  public stopAll() {
    if (!this.workletNode) return;
    this.workletNode.port.postMessage({ type: 'stop_all' });
    this.setupFX();
  }
}

