        { enabled: true, waveform: WaveformType.SINE, coarseDetune: 1900, attack: 0.5, decay: 1.5, gain: 0.3 },
        { spread: 0.7, stereoPanSpeed: 0.3, stereoPanDepth: 0.7, reverbType: 'shimmer', reverbMix: 0.6 }
    ),
