          return `${base} ${unlocked} bg-green-600/20 border-2 border-green-500 text-green-500 hover:bg-green-600/40 active:bg-green-600 active:text-white shadow-[0_0_15px_rgba(34,197,94,0.4)]`;
      }
  };

  return (
    <>
      {/* Volume Slider */}
      <div 
        className={`absolute bg-slate-900/30 p-2 rounded-full flex items-center gap-2 backdrop-blur-sm border border-white/5 transition-colors z-[150] ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : ''}`}
