export const DEFAULT_PRESET = PRESETS[0]; // Noise Wash is Default

import { SynthPreset, WaveformType, OscillatorConfig, AppSettings, ReverbType } from '../types';
import { store } from './Store';
import { DEFAULT_PRESET, REVERB_DEFAULTS } from '../constants';
import { AUDIO_PROCESSOR_CODE } from './AudioProcessorCode';

class AudioEngine {
  private ctx: AudioContext | null = null;
  private workletNode: AudioWorkletNode | null = null;
  private initPromise: Promise<void> | null = null;

  // FX Chain
  private limiter: DynamicsCompressorNode | null = null;
  private dryGain: GainNode | null = null;
  private reverbNode: ConvolverNode | null = null;
  private reverbGain: GainNode | null = null;
  private delayNode: DelayNode | null = null;
  private delayFeedbackGain: GainNode | null = null;
  private delayOutputGain: GainNode | null = null;

  private currentMasterVol: number = 0.8;
  private globalSpatialScale: number = 1.0;
  private activePreset: SynthPreset;

  constructor() {
    // Initialize Preset safely to prevent NaN in Worklet
    const rawPreset = store.getSnapshot().preset;
    this.activePreset = this.ensurePresetSafety(rawPreset);

    store.subscribe(() => {
        const newPreset = store.getSnapshot().preset;
        const safePreset = this.ensurePresetSafety(newPreset);
        this.setPreset(safePreset);
    });
  }

  private ensurePresetSafety(p: any): SynthPreset {
     if (!p) return DEFAULT_PRESET;
     const safe = { ...DEFAULT_PRESET, ...p };
     safe.osc1 = { ...DEFAULT_PRESET.osc1, ...(p.osc1 || {}) };
     safe.osc2 = { ...DEFAULT_PRESET.osc2, ...(p.osc2 || {}) };
     safe.osc3 = { ...DEFAULT_PRESET.osc3, ...(p.osc3 || {}) };
     safe.modMatrix = p.modMatrix || [];
     safe.reverbType = p.reverbType || 'hall'; 
     if (safe.reverbSize === undefined) safe.reverbSize = REVERB_DEFAULTS[safe.reverbType || 'hall'].size;
     if (safe.reverbDamping === undefined) safe.reverbDamping = REVERB_DEFAULTS[safe.reverbType || 'hall'].damping;
     if (safe.reverbDiffusion === undefined) safe.reverbDiffusion = REVERB_DEFAULTS[safe.reverbType || 'hall'].diffusion;
     return safe;
  }

  public async init() {
    if (this.initPromise) return this.initPromise;

    this.initPromise = (async () => {
        if (!this.ctx) {
            this.ctx = new (window.AudioContext || (window as any).webkitAudioContext)({
                latencyHint: 'interactive',
            });

            try {
                // Load AudioWorklet from Blob to guarantee no 404s in any environment
                const blob = new Blob([AUDIO_PROCESSOR_CODE], { type: 'application/javascript' });
                const workletUrl = URL.createObjectURL(blob);

                await this.ctx.audioWorklet.addModule(workletUrl);

                // Clean up the object URL after loading
                URL.revokeObjectURL(workletUrl);

                this.workletNode = new AudioWorkletNode(this.ctx, 'synth-processor', {
                    numberOfInputs: 0,
                    numberOfOutputs: 1,
                    outputChannelCount: [2]
                });

                // Initial preset send
                this.workletNode.port.postMessage({ type: 'preset', data: this.activePreset });
                this.workletNode.port.postMessage({ type: 'config', polyphony: store.getSnapshot().settings.polyphony });

                // Connect logic
                this.setupFX();

                if (this.workletNode && this.dryGain && this.reverbGain && this.delayOutputGain) {
                     this.workletNode.connect(this.dryGain);
                     this.workletNode.connect(this.reverbGain);
                     this.workletNode.connect(this.delayOutputGain);
                }

            } catch (e) {
                console.error("Failed to load AudioWorklet", e);
                this.initPromise = null; 
                return;
            }
        }

        if (this.ctx && this.ctx.state === 'suspended') {
            await this.ctx.resume();
        }
    })();

    return this.initPromise;
  }

  private setupFX() {
    if (!this.ctx) return;

    // Disconnect old nodes if they exist to clear state
    try {
        this.dryGain?.disconnect();
        this.reverbNode?.disconnect();
        this.reverbGain?.disconnect();
        this.delayNode?.disconnect();
        this.delayFeedbackGain?.disconnect();
        this.delayOutputGain?.disconnect();
        this.limiter?.disconnect();
    } catch(e) { /* ignore */ }

    // Rebuild Graph
    this.limiter = this.ctx.createDynamicsCompressor();
    this.limiter.threshold.value = -12.0; 
    this.limiter.ratio.value = 12.0;
    this.limiter.connect(this.ctx.destination);

    this.dryGain = this.ctx.createGain();
    this.dryGain.connect(this.limiter);

    this.reverbNode = this.ctx.createConvolver();
    // Initialize with current preset setting
    this.updateReverbBuffer();

    this.reverbGain = this.ctx.createGain();
    this.reverbGain.connect(this.reverbNode);
    this.reverbNode.connect(this.limiter);

    this.delayNode = this.ctx.createDelay(5.0);
    this.delayFeedbackGain = this.ctx.createGain();
    this.delayOutputGain = this.ctx.createGain();

    this.delayOutputGain.connect(this.delayNode);
    this.delayNode.connect(this.limiter); 
    this.delayNode.connect(this.delayFeedbackGain);
    this.delayFeedbackGain.connect(this.delayNode);

    // Reconnect Worklet to new graph
    if (this.workletNode) {
        this.workletNode.disconnect();
        this.workletNode.connect(this.dryGain);
        this.workletNode.connect(this.reverbGain);
        this.workletNode.connect(this.delayOutputGain);
    }

    this.updateFX();
    this.setMasterVolume(this.currentMasterVol);
  }

  private updateReverbBuffer() {
      if (!this.reverbNode || !this.ctx) return;

      const type = this.activePreset.reverbType || 'hall';

      // Use explicit parameters if available, otherwise default to type-based values (legacy fallback)
      const duration = this.activePreset.reverbSize ?? REVERB_DEFAULTS[type].size;
      const damping = this.activePreset.reverbDamping ?? REVERB_DEFAULTS[type].damping;
      const diffusion = this.activePreset.reverbDiffusion ?? REVERB_DEFAULTS[type].diffusion;

      // Convert damping (0-1) to brightness (1-0) for internal algorithm
      // High damping = Low brightness
      let brightness = 1.0 - damping; 

      let preDelay = 0.0;
      let decay = 2.0;
      let density = 0.5;

      switch(type) {
          case 'room': 
              decay = 3.0; density = 0.8; 
              break;
          case 'hall': 
              decay = 2.0; density = 0.6; preDelay = 0.02;
              break;
          case 'cathedral': 
              decay = 1.5; density = 0.4; preDelay = 0.04;
              break;
          case 'plate': 
              decay = 4.0; density = 1.0; 
              break;
          case 'shimmer': 
              decay = 0.8; density = 0.2; 
              break;
          default: 
              decay = 2.0; density = 0.5;
      }

      this.reverbNode.buffer = this.createImpulseResponse(duration, decay, brightness, density, preDelay, diffusion);
  }

  private updateFX() {
      if (!this.ctx) return;
      const now = this.ctx.currentTime;
      const ramp = 0.1;

      // Apply Global Spatial Scale to Reverb and Delay Mix
      const scaledReverbMix = Math.min(1.0, this.activePreset.reverbMix * this.globalSpatialScale);
      const scaledDelayMix = Math.min(1.0, this.activePreset.delayMix * this.globalSpatialScale);

      if (this.reverbGain) this.reverbGain.gain.setTargetAtTime(scaledReverbMix, now, ramp);
      if (this.delayOutputGain) this.delayOutputGain.gain.setTargetAtTime(scaledDelayMix, now, ramp);

      const scaledFeedback = Math.min(0.95, this.activePreset.delayFeedback * Math.sqrt(this.globalSpatialScale));
      if (this.delayFeedbackGain) this.delayFeedbackGain.gain.setTargetAtTime(scaledFeedback, now, ramp);

      if (this.delayNode) this.delayNode.delayTime.setTargetAtTime(this.activePreset.delayTime, now, ramp);

      if (this.limiter) {
          const thresh = this.activePreset.compressorThreshold ?? -20.0;
          const ratio = this.activePreset.compressorRatio ?? 12;
          const release = this.activePreset.compressorRelease ?? 0.25;

          this.limiter.threshold.setTargetAtTime(thresh, now, ramp);
          this.limiter.ratio.setTargetAtTime(ratio, now, ramp);
          this.limiter.release.setTargetAtTime(release, now, ramp);
      }

      if (this.dryGain) {
          const dryLevel = Math.max(0.5, 1.0 - (scaledReverbMix * 0.4));
          this.dryGain.gain.setTargetAtTime(dryLevel * this.currentMasterVol, now, ramp);
      }
  }

  /**
   * Generates a high-quality stereo impulse response with frequency damping, early reflections and variable diffusion.
   */
  private createImpulseResponse(duration: number, baseDecayCurve: number, brightness: number, density: number, preDelay: number, diffusion: number): AudioBuffer {
    if (!this.ctx) throw new Error("No Context");
    const sampleRate = this.ctx.sampleRate;
    const length = Math.floor(sampleRate * duration);
    const impulse = this.ctx.createBuffer(2, length, sampleRate);
    const left = impulse.getChannelData(0);
    const right = impulse.getChannelData(1);

    // Pre-delay in samples
    const startSample = Math.floor(preDelay * sampleRate);

    // Damping setup (Lowpass filter state)
    let lpL = 0;
    let lpR = 0;

    // Scale smoothing factor to be much more aggressive based on brightness/damping
    // Low brightness (high damping) now creates a much stronger lowpass effect
    // 0 brightness => 0.99 smoothing (Almost no high freq passes, energy dies fast)
    // 1 brightness => 0.01 smoothing (Full spectrum)
    const baseSmoothing = 0.01 + (1.0 - brightness) * 0.985; 

    // Couple decay to dampening to simulate energy absorption
    // High dampening (Low Brightness) increases the decay exponent, shortening the effective tail
    const decayCurve = baseDecayCurve + (1.0 - brightness) * 4.0;

    for (let i = startSample; i < length; i++) {
        // 1. Generate Stereo Noise (Uncorrelated)
        let nL = (Math.random() * 2 - 1);
        let nR = (Math.random() * 2 - 1);

        // 2. Frequency Damping (Time-Variant Lowpass)
        const progress = (i - startSample) / (length - startSample);

        // Effective smoothing increases over time to simulate air absorption
        const currentSmoothing = baseSmoothing * (0.8 + 0.2 * progress);

        lpL += (nL - lpL) * (1.0 - currentSmoothing);
        lpR += (nR - lpR) * (1.0 - currentSmoothing);

        // 3. Apply Aggressive Exponential Decay Envelope
        const env = Math.pow(1 - progress, decayCurve);

        // 4. Diffusion Logic (Grainy vs Smooth)
        // High diffusion (1.0) = Full noise.
        // Low diffusion (0.0) = Sparse impulses (grainy echoes).
        // We implement this by randomly gating the tail based on diffusion parameter.
        const diffMask = (Math.random() < (0.05 + 0.95 * diffusion)) ? 1 : 0;
        // Normalize gain slightly to compensate for energy loss at low diffusion
        const diffGain = diffMask > 0 ? 1.0 / Math.sqrt(0.05 + 0.95 * diffusion) : 0;

        left[i] = lpL * env * diffMask * diffGain;
        right[i] = lpR * env * diffMask * diffGain;
    }

    // 5. Early Reflections (Discrete Echoes)
    // Early reflections are less affected by diffusion parameter to maintain spatial cue
    const erDuration = Math.floor(0.08 * sampleRate);
    const erCount = Math.floor(8 + density * 12); 

    for (let k = 0; k < erCount; k++) {
        const delay = startSample + Math.floor(Math.random() * erDuration);
        if (delay < length) {
            const erAmp = (1.0 - (k / erCount)) * 0.8; 
            const pan = Math.random() * 2 - 1; 
            const gainL = erAmp * (0.5 - 0.5 * pan);
            const gainR = erAmp * (0.5 + 0.5 * pan);

            // Add raw impulses for clarity
            left[delay] += (Math.random() * 2 - 1) * gainL;
            right[delay] += (Math.random() * 2 - 1) * gainR;
        }
    }

    // 6. Normalize
    let maxVal = 0;
    for (let i = 0; i < length; i++) {
        if (Math.abs(left[i]) > maxVal) maxVal = Math.abs(left[i]);
        if (Math.abs(right[i]) > maxVal) maxVal = Math.abs(right[i]);
    }
    const scale = 0.5 / Math.max(0.001, maxVal); 
    for (let i = 0; i < length; i++) {
        left[i] *= scale;
        right[i] *= scale;
    }

    return impulse;
  }

  public setPolyphony(count: number) {
      if (this.workletNode) {
          this.workletNode.port.postMessage({ type: 'config', polyphony: count });
      }
  }

  public setMasterVolume(val: number) {
    this.currentMasterVol = val;
    this.updateFX();
  }

  public setGlobalSpatialScale(val: number) {
      this.globalSpatialScale = val;
      this.updateFX();
  }

  public setPreset(preset: SynthPreset) {
    const prevType = this.activePreset.reverbType;
    const prevSize = this.activePreset.reverbSize;
    const prevDamping = this.activePreset.reverbDamping;
    const prevDiffusion = this.activePreset.reverbDiffusion;

    this.activePreset = preset;

    // Check if critical reverb parameters changed requiring a buffer regeneration
    if (this.ctx && (
        prevType !== preset.reverbType || 
        prevSize !== preset.reverbSize || 
        prevDamping !== preset.reverbDamping ||
        prevDiffusion !== preset.reverbDiffusion
    )) {
        this.updateReverbBuffer();
    }

    this.updateFX();
    if (this.workletNode) {
        this.workletNode.port.postMessage({ type: 'preset', data: preset });
    }
  }

  public async startVoice(id: string, ratio: number, baseFrequency: number) {
    await this.init();
    if (!this.workletNode) return;

    const freq = baseFrequency * ratio;
    this.workletNode.port.postMessage({ 
        type: 'note_on', 
        id: id, 
        freq: freq 
    });
  }

  public stopVoice(id: string, immediate: boolean = false) {
    if (!this.workletNode) return;
    this.workletNode.port.postMessage({ 
        type: 'note_off', 
        id: id 
    });
  }

  public glideVoice(id: string, newRatio: number, baseFrequency: number, glideTime: number = 0.1) {
    if (!this.workletNode) return;
    const freq = baseFrequency * newRatio;
    this.workletNode.port.postMessage({ 
        type: 'glide', 
        id: id, 
        freq: freq 
    });
  }

  public stopAll() {
    if (!this.workletNode) return;
    this.workletNode.port.postMessage({ type: 'stop_all' });
    this.setupFX();
  }
}

export const audioEngine = new AudioEngine();
export default AudioEngine;

import React, { useState } from 'react';
import { SynthPreset, WaveformType, OscillatorConfig, ModulationRow, ModSource, ModTarget, ReverbType } from '../types';
import { PRESETS, REVERB_DEFAULTS } from '../constants';

interface Props {
  preset: SynthPreset;
  onChange: (p: SynthPreset) => void;
  isOpen: boolean;
  onClose: () => void;
}

const SynthControls: React.FC<Props> = ({ preset, onChange, isOpen, onClose }) => {
  const [activeTab, setActiveTab] = useState<'osc1' | 'osc2' | 'osc3' | 'matrix' | 'fx'>('osc1');

  if (!isOpen) return null;

  const updateGlobal = (key: keyof SynthPreset, val: any) => {
    onChange({ ...preset, [key]: val });
  };

  const updateOsc = (oscKey: 'osc1' | 'osc2' | 'osc3', key: keyof OscillatorConfig, val: any) => {
      const newOsc = { ...preset[oscKey], [key]: val };
      onChange({ ...preset, [oscKey]: newOsc });
  };

  const loadPreset = (p: SynthPreset) => {
      onChange({ ...p });
  };

  const handleReverbTypeChange = (type: ReverbType) => {
      const defaults = REVERB_DEFAULTS[type];
      onChange({
          ...preset,
          reverbType: type,
          reverbSize: defaults.size,
          reverbDamping: defaults.damping,
          reverbDiffusion: defaults.diffusion
      });
  };

  const addModRow = () => {
      const newRow: ModulationRow = {
          id: Math.random().toString(36).substr(2, 9),
          enabled: true,
          source: 'lfo1',
          target: 'osc1_pitch',
          amount: 50
      };
      onChange({ ...preset, modMatrix: [...(preset.modMatrix || []), newRow] });
  };

  const removeModRow = (id: string) => {
      onChange({ ...preset, modMatrix: (preset.modMatrix || []).filter(r => r.id !== id) });
  };

  const updateModRow = (id: string, field: keyof ModulationRow, value: any) => {
      const newMatrix = (preset.modMatrix || []).map(r => {
          if (r.id === id) return { ...r, [field]: value };
          return r;
      });
      onChange({ ...preset, modMatrix: newMatrix });
  };

