import React from 'react';
import { UIRect } from '../types';
import { MARGIN_3MM, SCROLLBAR_WIDTH } from '../constants';

interface Props {
  rect: UIRect;
  onUpdate: (rect: UIRect) => void;
  uiUnlocked: boolean;
  minW?: number;
  minH?: number;
  maxW?: number;
  maxH?: number;
  children: React.ReactNode;
  className?: string;
  style?: React.CSSProperties;
}

const UIElement: React.FC<Props> = ({ 
  rect, onUpdate, uiUnlocked, 
  minW = 20, minH = 20, maxW = 800, maxH = 800,
  children, className = '', style = {} 
}) => {

  const handleDrag = (e: React.PointerEvent) => {
    if (!uiUnlocked) return;

    e.stopPropagation();
    const el = e.currentTarget as HTMLElement;
    el.setPointerCapture(e.pointerId);

    const startX = e.clientX;
    const startY = e.clientY;
    const startLeft = rect.x;
    const startTop = rect.y;

    const onMove = (evt: PointerEvent) => {
        const deltaX = evt.clientX - startX;
        const deltaY = evt.clientY - startY;

        let newX = startLeft + deltaX;
        let newY = startTop + deltaY;

        // Clamp to screen
        const maxX = window.innerWidth - rect.w - MARGIN_3MM;
        const maxY = window.innerHeight - rect.h - MARGIN_3MM;

        newX = Math.max(MARGIN_3MM, Math.min(newX, maxX));
        newY = Math.max(MARGIN_3MM, Math.min(newY, maxY));

        onUpdate({ ...rect, x: newX, y: newY });
    };

    const onUp = () => {
        window.removeEventListener('pointermove', onMove);
        window.removeEventListener('pointerup', onUp);
    };

    window.addEventListener('pointermove', onMove);
    window.addEventListener('pointerup', onUp);
  };

  const handleResize = (e: React.PointerEvent) => {
      if (!uiUnlocked) return;
      e.stopPropagation();
      const el = e.currentTarget as HTMLElement;
      el.setPointerCapture(e.pointerId);

      const startX = e.clientX;
      const startY = e.clientY;
      const startW = rect.w;
      const startH = rect.h;

      const onMove = (evt: PointerEvent) => {
          const deltaX = evt.clientX - startX;
          const deltaY = evt.clientY - startY;

          let newW = Math.max(minW, Math.min(maxW, startW + deltaX));
          let newH = Math.max(minH, Math.min(maxH, startH + deltaY));

          onUpdate({ ...rect, w: newW, h: newH });
      };

      const onUp = () => {
          window.removeEventListener('pointermove', onMove);
          window.removeEventListener('pointerup', onUp);
      };

      window.addEventListener('pointermove', onMove);
      window.addEventListener('pointerup', onUp);
  };

  return (
    <div 
        className={`absolute transition-colors ${className} ${uiUnlocked ? 'ring-2 ring-yellow-500/50 cursor-move bg-slate-900/40 hover:bg-slate-900/60' : ''}`}
        style={{ 
            left: rect.x, 
            top: rect.y, 
            width: rect.w, 
            height: rect.h, 
            touchAction: 'none',
            ...style 
        }}
        onPointerDown={handleDrag}
    >
        {children}

        {/* Resize Handle */}
        {uiUnlocked && (
            <div 
                className="absolute bottom-0 right-0 w-6 h-6 bg-yellow-500/50 cursor-se-resize rounded-tl z-[200] hover:bg-yellow-500 flex items-center justify-center"
                onPointerDown={handleResize}
            >
                <svg className="w-4 h-4 text-black opacity-50" viewBox="0 0 24 24" fill="currentColor">
                    <path d="M22 22H20V20H22V22ZM22 18H20V16H18V18H22V22H18V20H16V22H22V18Z" />
                </svg>
            </div>
        )}
    </div>
  );
};

export default UIElement;

import React from 'react';
import { ChordDefinition, AppSettings, UIRect } from '../types';
import UIElement from './UIElement';

interface Props {
  volume: number;
  setVolume: (v: number) => void;
  spatialScale: number;
  setSpatialScale: (v: number) => void;
  onPanic: () => void;
  onOff: () => void;
  onLatch: () => void;
  latchMode: 0 | 1 | 2;
  onBend: () => void;
  isBendEnabled: boolean;
  onCenter: () => void;
  onIncreaseDepth: () => void;
  onDecreaseDepth: () => void;
  onAddChord: () => void;
  toggleChord: (id: string) => void;
  activeChordIds: string[];
  savedChords: ChordDefinition[];
  chordShortcutSizeScale: number;
  showIncreaseDepthButton: boolean;
  uiUnlocked: boolean;
  uiLayout: AppSettings['uiLayout'];
  updateLayout: (key: keyof AppSettings['uiLayout'], rect: UIRect) => void;
  draggingId: string | null;
  setDraggingId: (id: string | null) => void;
}

const FloatingControls: React.FC<Props> = ({ 
  volume, setVolume, spatialScale, setSpatialScale, 
  onPanic, onOff, onLatch, latchMode, onBend, isBendEnabled, onCenter, onIncreaseDepth, onDecreaseDepth, onAddChord, toggleChord,
  activeChordIds, savedChords, chordShortcutSizeScale,
  showIncreaseDepthButton, uiUnlocked, uiLayout, updateLayout
}) => {

  // Calculate relative sizes for internal elements based on container size
  // Standard sizes for reference: 
  // Vol: 220x50
  // Space: 60x300

  const getFontSize = (w: number, h: number, base: number) => {
      // Crude heuristic to scale font
      return Math.max(10, Math.min(24, Math.min(w, h) * 0.3));
  };

  const getLatchStyle = () => {
      const base = "flex-1 rounded-lg flex items-center justify-center font-bold uppercase tracking-wider backdrop-blur transition-all select-none shadow-lg border-2";
      if (latchMode === 1) { // LATCH_ALL 
          return `${base} bg-green-500 text-white border-green-300 shadow-[0_0_20px_rgba(34,197,94,0.8)]`;
      } else if (latchMode === 2) { // SUSTAIN 
          return `${base} bg-green-900/60 text-green-400 border-green-400 ring-2 ring-green-500/30 animate-pulse shadow-[0_0_15px_rgba(34,197,94,0.4)]`;
      } else { // OFF
          return `${base} bg-green-900/40 border-green-500/50 text-green-500 hover:bg-green-800/60 active:bg-green-600 active:text-white shadow-[0_0_15px_rgba(34,197,94,0.2)]`;
      }
  };

  return (
    <>
      {/* Volume Slider */}
      <UIElement
        rect={uiLayout.volume}
        onUpdate={(r) => updateLayout('volume', r)}
        uiUnlocked={uiUnlocked}
        minW={100} minH={30}
        className="bg-slate-900/80 rounded-full border border-white/20 backdrop-blur-md flex items-center px-4 gap-3 shadow-xl z-[150]"
      >
         <span className="font-bold text-slate-300 select-none" style={{ fontSize: getFontSize(uiLayout.volume.w, uiLayout.volume.h, 12) }}>VOL</span>
         <input 
            type="range" min="0" max="1" step="0.01" 
            value={volume}
            onChange={(e) => setVolume(parseFloat(e.target.value))}
            disabled={uiUnlocked} // Disable interaction when unlocking to prevent conflict
            className={`w-full bg-slate-600/50 rounded-lg appearance-none ${uiUnlocked ? 'pointer-events-none opacity-50' : 'cursor-pointer'}`}
            style={{ height: Math.max(4, uiLayout.volume.h * 0.15) }}
            onPointerDown={(e) => !uiUnlocked && e.stopPropagation()} 
         />
      </UIElement>

      {/* Spatial Slider */}
      <UIElement
        rect={uiLayout.space}
        onUpdate={(r) => updateLayout('space', r)}
        uiUnlocked={uiUnlocked}
        minW={40} minH={100}
        className="bg-slate-900/80 rounded-full border border-white/20 backdrop-blur-md flex flex-col items-center py-4 shadow-xl z-[150]"
      >
         <span className="font-bold text-slate-300 select-none tracking-tighter mb-2" style={{ fontSize: getFontSize(uiLayout.space.w, uiLayout.space.w, 10) }}>SPACE</span>
         <div className="flex-1 flex items-center justify-center w-full relative">
             <div style={{ 
                 width: uiLayout.space.h * 0.8, 
                 height: uiLayout.space.w, // Match container width for touch target
                 transform: 'rotate(-90deg)',
                 display: 'flex', alignItems: 'center', justifyContent: 'center'
             }}>
                <input 
                    type="range" min="0" max="2" step="0.01" 
                    value={spatialScale}
                    onChange={(e) => setSpatialScale(parseFloat(e.target.value))}
                    disabled={uiUnlocked}
                    className={`w-full bg-slate-600/50 rounded-lg appearance-none ${uiUnlocked ? 'pointer-events-none opacity-50' : 'cursor-pointer'}`}
                    style={{ height: Math.max(4, uiLayout.space.w * 0.1) }}
                    onPointerDown={(e) => !uiUnlocked && e.stopPropagation()} 
                />
             </div>
         </div>
      </UIElement>

      {/* Right Group (Bend, Latch, Off, Panic) */}
      <UIElement
        rect={uiLayout.rightGroup}
        onUpdate={(r) => updateLayout('rightGroup', r)}
        uiUnlocked={uiUnlocked}
        minW={60} minH={200}
        className={`flex flex-col justify-between gap-2 z-[150] ${uiUnlocked ? 'p-2' : ''}`}
      >
          {/* Bend */}
          <button
            className={`flex-1 rounded-lg flex items-center justify-center font-bold uppercase tracking-wider backdrop-blur transition-all select-none border-2 shadow-lg ${
                isBendEnabled 
                ? 'bg-purple-600 text-white border-purple-300 shadow-[0_0_15px_rgba(168,85,247,0.6)]' 
                : 'bg-purple-900/40 text-purple-400 border-purple-500/50 hover:bg-purple-800/60'
            }`}
            style={{ fontSize: getFontSize(uiLayout.rightGroup.w, uiLayout.rightGroup.h / 4, 14) }}
            onPointerDown={(e) => { e.stopPropagation(); if(!uiUnlocked) onBend(); }}
          >
            BEND
          </button>

          {/* Latch */}
          <button
            className={getLatchStyle()}
            style={{ fontSize: getFontSize(uiLayout.rightGroup.w, uiLayout.rightGroup.h / 4, 14) }}
            onPointerDown={(e) => { e.stopPropagation(); if(!uiUnlocked) onLatch(); }}
          >
            LATCH
          </button>

          {/* Off */}
          <button
            className="flex-1 rounded-lg bg-yellow-900/40 border-2 border-yellow-500/50 flex items-center justify-center text-yellow-500 font-bold uppercase tracking-wider backdrop-blur hover:bg-yellow-800/60 active:bg-yellow-600 active:text-white transition-all shadow-[0_0_15px_rgba(234,179,8,0.2)] select-none"
            style={{ fontSize: getFontSize(uiLayout.rightGroup.w, uiLayout.rightGroup.h / 4, 14) }}
            onPointerDown={(e) => { e.stopPropagation(); if(!uiUnlocked) onOff(); }}
          >
            OFF
          </button>

          {/* Panic */}
          <button
            className="flex-1 rounded-lg bg-red-900/40 border-2 border-red-500/50 flex items-center justify-center text-red-500 font-bold uppercase tracking-wider backdrop-blur hover:bg-red-800/60 active:bg-red-600 active:text-white transition-all shadow-[0_0_15px_rgba(239,68,68,0.2)] select-none"
            style={{ fontSize: getFontSize(uiLayout.rightGroup.w, uiLayout.rightGroup.h / 4, 14) }}
            onPointerDown={(e) => { e.stopPropagation(); if(!uiUnlocked) onPanic(); }}
          >
            PANIC
          </button>
      </UIElement>

      {/* Bottom Left Group (Center, Depths, Chords) */}
      <UIElement
        rect={uiLayout.bottomLeft}
        onUpdate={(r) => updateLayout('bottomLeft', r)}
        uiUnlocked={uiUnlocked}
        minW={200} minH={40}
        className={`flex items-center gap-2 z-[150] ${uiUnlocked ? 'p-2' : ''}`}
      >
          {/* Center */}
          <button
            className="h-full aspect-square rounded bg-yellow-600/20 border-2 border-yellow-500 flex items-center justify-center text-yellow-500 font-bold backdrop-blur hover:bg-yellow-600/40 active:bg-yellow-600 active:text-white transition-all shadow-[0_0_15px_rgba(234,179,8,0.4)] select-none"
            onPointerDown={(e) => { e.stopPropagation(); if(!uiUnlocked) onCenter(); }}
            title="Center Display"
          >
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-3/4 h-3/4">
              <path strokeLinecap="round" strokeLinejoin="round" d="M3.75 3.75v4.5m0-4.5h4.5m-4.5 0L9 9M3.75 20.25v-4.5m0 4.5h4.5m-4.5 0L9 15M20.25 3.75h-4.5m4.5 0v4.5m0-4.5L15 9m5.25 11.25h-4.5m4.5 0v-4.5m0 4.5L15 15" />
            </svg>
          </button>

          {showIncreaseDepthButton && (
            <>
                <button
                  className="h-full aspect-square rounded bg-blue-600/20 border-2 border-blue-500 flex items-center justify-center text-blue-500 font-bold backdrop-blur hover:bg-blue-600/40 active:bg-blue-600 active:text-white transition-all shadow-[0_0_15px_rgba(59,130,246,0.4)] select-none"
                  onPointerDown={(e) => { e.stopPropagation(); if(!uiUnlocked) onIncreaseDepth(); }}
                  title="Increase Depth"
                >
                  <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-3/4 h-3/4">
                    <path strokeLinecap="round" strokeLinejoin="round" d="M3.75 3.75v4.5m0-4.5h4.5m-4.5 0L9 9M3.75 20.25v-4.5m0 4.5h4.5m-4.5 0L9 15M20.25 3.75h-4.5m4.5 0v4.5m0-4.5L15 9m5.25 11.25h-4.5m4.5 0v-4.5m0 4.5L15 15" />
                    <circle cx="12" cy="12" r="3" stroke="currentColor" strokeWidth="2" fill="none" />
                  </svg>
                </button>
                <button
                  className="h-full aspect-square rounded bg-green-600/20 border-2 border-green-500 flex items-center justify-center text-green-500 font-bold backdrop-blur hover:bg-green-600/40 active:bg-green-600 active:text-white transition-all shadow-[0_0_15px_rgba(34,197,94,0.4)] select-none"
                  onPointerDown={(e) => { e.stopPropagation(); if(!uiUnlocked) onDecreaseDepth(); }}
                  title="Decrease Depth"
                >
                  <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-3/4 h-3/4">
                    <path strokeLinecap="round" strokeLinejoin="round" d="M4 4 L10 10 M10 10 L10 6 M10 10 L6 10" />
                    <path strokeLinecap="round" strokeLinejoin="round" d="M20 4 L14 10 M14 10 L14 6 M14 10 L18 10" />
                    <path strokeLinecap="round" strokeLinejoin="round" d="M4 20 L10 14 M10 14 L10 18 M10 14 L6 14" />
                    <path strokeLinecap="round" strokeLinejoin="round" d="M20 20 L14 14 M14 14 L14 18 M14 14 L18 14" />
                  </svg>
                </button>
            </>
          )}

          {/* Divider */}
          <div className="w-[1px] h-3/4 bg-white/20 mx-1"></div>

          {/* Add Chord */}
          <button
            className="h-full aspect-square rounded border-2 border-slate-500 border-dashed flex items-center justify-center text-slate-500 font-bold backdrop-blur hover:bg-slate-700/40 hover:text-white hover:border-white transition-all select-none"
            onPointerDown={(e) => { e.stopPropagation(); }} 
            onClick={!uiUnlocked ? onAddChord : undefined}
            title="Add Chord"
          >
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-1/2 h-1/2">
              <path strokeLinecap="round" strokeLinejoin="round" d="M12 4.5v15m7.5-7.5h-15" />
            </svg>
          </button>

          {/* Saved Chords List - Scrollable Horizontal */}
          <div className="flex-1 flex gap-2 overflow-x-auto overflow-y-hidden h-full items-center scrollbar-hide mask-gradient-r">
              {savedChords.filter(c => c.visible).map((chord) => {
                  const isActive = activeChordIds.includes(chord.id);
                  const size = uiLayout.bottomLeft.h; 
                  return (
                    <button
                        key={chord.id}
                        className={`flex-shrink-0 h-full aspect-square rounded flex items-center justify-center font-bold backdrop-blur transition-all shadow-lg select-none`}
                        style={{
                            fontSize: size * 0.4,
                            backgroundColor: isActive ? chord.color : `${chord.color}33`, 
                            borderColor: chord.color,
                            borderWidth: 2,
                            color: isActive ? '#fff' : chord.color,
                            boxShadow: isActive ? `0 0 10px ${chord.color}` : 'none'
                        }}
                        onPointerDown={(e) => { e.stopPropagation(); }}
                        onClick={() => !uiUnlocked && toggleChord(chord.id)}
                        title={`Chord ${chord.id}: ${chord.label}`}
                    >
                        {chord.id}
                    </button>
                  );
              })}
          </div>
      </UIElement>
    </>
  );
};

export default FloatingControls;

import React from 'react';
import { AppSettings, UIRect } from '../types';
import UIElement from './UIElement';

interface Props {
  settings: AppSettings;
  updateSettings: (s: AppSettings) => void;
  updateLayout: (key: keyof AppSettings['uiLayout'], rect: UIRect) => void;
  draggingId: string | null;
  setDraggingId: (id: string | null) => void;
}

const LIMITS = [1, 3, 5, 7, 11, 13];

const LimitLayerControls: React.FC<Props> = ({ settings, updateSettings, updateLayout }) => {
  const { uiUnlocked, uiLayout } = settings;
  const rect = uiLayout.layers;

  const isVisible = (limit: number) => {
    // 1-Limit is always visible
    if (limit === 1) return true;
    return !settings.hiddenLimits.includes(limit);
  };

  const toggleVisibility = (limit: number) => {
    if (limit === 1) return;
    const isHidden = settings.hiddenLimits.includes(limit);
    let newHidden = [...settings.hiddenLimits];
    if (isHidden) {
      newHidden = newHidden.filter(l => l !== limit);
    } else {
      newHidden.push(limit);
    }
    updateSettings({ ...settings, hiddenLimits: newHidden });
  };

  const bringToFront = (limit: number) => {
    const newOrder = settings.layerOrder.filter(l => l !== limit);
    newOrder.push(limit);
    updateSettings({ ...settings, layerOrder: newOrder });
  };

  return (
    <UIElement
      rect={rect}
      onUpdate={(r) => updateLayout('layers', r)}
      uiUnlocked={uiUnlocked}
      minW={50} minH={200}
      className={`flex flex-col gap-2 z-[140] bg-slate-900/50 p-2 rounded-xl backdrop-blur-sm border border-slate-700/50 justify-between`}
    >
      {LIMITS.map(limit => {
        const visible = isVisible(limit);
        const color = settings.colors[limit];
        const isTop = settings.layerOrder[settings.layerOrder.length - 1] === limit;
        const isLocked = limit === 1;

        return (
          <div key={limit} className="flex-1 flex items-center gap-2 group w-full">
            {/* Visibility Toggle */}
            <button 
              onClick={(e) => { e.stopPropagation(); !uiUnlocked && toggleVisibility(limit); }}
              disabled={isLocked}
              className={`h-full aspect-square flex items-center justify-center rounded transition-colors ${visible ? (isLocked ? 'text-slate-500 cursor-default opacity-50' : 'text-white') : 'text-slate-600'} hover:bg-white/10 ${uiUnlocked ? 'pointer-events-none' : ''}`}
              onPointerDown={(e) => !uiUnlocked && e.stopPropagation()} 
            >
               {visible ? (
                 <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-3/4 h-3/4">
                   <path d="M10 12.5a2.5 2.5 0 100-5 2.5 2.5 0 000 5z" />
                   <path fillRule="evenodd" d="M.664 10.59a1.651 1.651 0 010-1.186A10.004 10.004 0 0110 3c4.257 0 8.201 2.372 9.336 6.41.147.527.147 1.074 0 1.601C18.201 14.628 14.257 17 10 17c-4.257 0-8.201-2.372-9.336-6.41zM14 10a4 4 0 11-8 0 4 4 0 018 0z" clipRule="evenodd" />
                 </svg>
               ) : (
                 <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-3/4 h-3/4">
                   <path fillRule="evenodd" d="M3.28 2.22a.75.75 0 00-1.06 1.06l14.5 14.5a.75.75 0 101.06-1.06l-1.745-1.745A10.029 10.029 0 0018 10c-1.135-4.038-5.079-6.41-9.336-6.41a9.982 9.982 0 00-4.636 1.135L3.28 2.22zm12.98 12.98l-3.212-3.212a3.003 3.003 0 00-4.244-4.244L5.68 4.62A11.967 11.967 0 00.664 9.41a1.651 1.651 0 010 1.18c1.135 4.038 5.079 6.41 9.336 6.41 2.053 0 4.008-.584 5.688-1.613l.572.572z" clipRule="evenodd" />
                   <path d="M10.983 7.796a1.5 1.5 0 012.122 2.122l-2.122-2.122z" />
                 </svg>
               )}
            </button>

            {/* Color/Select Layer Button */}
            <button 
              onClick={(e) => { e.stopPropagation(); !uiUnlocked && bringToFront(limit); }}
              className={`flex-1 h-full rounded-lg shadow-md border-2 transition-all transform active:scale-95 flex items-center justify-center font-bold text-shadow ${uiUnlocked ? 'pointer-events-none' : ''}`}
              style={{ 
                fontSize: Math.min(rect.w, rect.h / 6) * 0.4,
                backgroundColor: color, 
                borderColor: isTop ? 'white' : 'transparent',
                boxShadow: isTop ? '0 0 10px rgba(255,255,255,0.5)' : 'none',
                opacity: visible ? 1 : 0.2
              }}
              onPointerDown={(e) => !uiUnlocked && e.stopPropagation()}
            >
              {limit}
            </button>
          </div>
        );
      })}
    </UIElement>
  );
};

export default LimitLayerControls;

import React, { useState, useEffect, useRef } from 'react';
import TonalityDiamond, { TonalityDiamondHandle } from './components/TonalityDiamond';
import SettingsModal from './components/SettingsModal';
import SynthControls from './components/SynthControls';
import FloatingControls from './components/FloatingControls';
import LimitLayerControls from './components/LimitLayerControls';
import { audioEngine } from './services/AudioEngine'; // Import singleton
import { useStore } from './services/Store';
import { AppSettings, ChordDefinition, UIRect } from './types';
import { MARGIN_3MM, SCROLLBAR_WIDTH } from './constants';

const App: React.FC = () => {
  const { settings, preset, updateSettings, setPreset } = useStore();

  const [masterVolume, setMasterVolume] = useState(0.8);
  const [spatialScale, setSpatialScale] = useState(1.0); // Global Reverb Slider State
  const [activeChordIds, setActiveChordIds] = useState<string[]>([]);
  const [draggingId, setDraggingId] = useState<string | null>(null);

  // 0 = Off, 1 = Latch All, 2 = Sustain (Partial Latch)
  const [latchMode, setLatchMode] = useState<0 | 1 | 2>(0);

  // Modals
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isSynthOpen, setIsSynthOpen] = useState(false);

  const diamondRef = useRef<TonalityDiamondHandle>(null);

  // Audio Warmup: Pre-initialize audio context on any user interaction
  useEffect(() => {
    const warmup = () => {
        audioEngine.init();

        // Remove listeners once warmed up
        window.removeEventListener('pointerdown', warmup);
        window.removeEventListener('keydown', warmup);
        window.removeEventListener('touchstart', warmup);
    };

    window.addEventListener('pointerdown', warmup);
    window.addEventListener('keydown', warmup);
    window.addEventListener('touchstart', warmup);

    return () => {
        window.removeEventListener('pointerdown', warmup);
        window.removeEventListener('keydown', warmup);
        window.removeEventListener('touchstart', warmup);
    };
  }, []);

  // Initialize Layout based on screen size if needed
  // This logic runs ONCE to set initial adaptive positions
  useEffect(() => {
      // Check if layout needs initialization (e.g. if we migrated from old version or it's empty)
      // Or if we want to enforce standard positions on first load of this version
      // We rely on the fact that if settings were loaded, they might have old data.

      const w = window.innerWidth;
      const h = window.innerHeight;

      // Heuristic: If volume x is default (which is static in constants), it might need centering.
      // But more importantly, we want to scale based on screen size for the first time.
      // Since we want to allow users to save their layout, we shouldn't overwrite it every time.
      // However, the prompt says "When you initially size UI elements, judge the correct size based on... screen real estate"

      updateSettings(prev => {
          // If layout looks default/uninitialized (e.g. Volume is at hardcoded 490), lets recalc
          // Or we can just check if we have a flag. For now, we will recalc if volume.x is exactly default relative to 1200 width?
          // Better: Just check if we are significantly off-screen or if it's a fresh session logic.
          // For this implementation, we will act as if it is responsive init:

          const p = { ...prev.uiLayout };

          // Safety: ensure keys exist (migration)
          if (!p.volume) p.volume = { x: 0, y: 0, w: 220, h: 50 };
          if (!p.space) p.space = { x: 0, y: 0, w: 60, h: 300 };
          if (!p.layers) p.layers = { x: 0, y: 0, w: 70, h: 350 };
          if (!p.rightGroup) p.rightGroup = { x: 0, y: 0, w: 80, h: 300 };
          if (!p.bottomLeft) p.bottomLeft = { x: 0, y: 0, w: 400, h: 50 };

          // Center Volume
          if (p.volume.x === 490) { // Detect Default
             p.volume.x = (w / 2) - (p.volume.w / 2);
          }

          // Anchor Bottom Left
          if (p.bottomLeft.y === 740) {
             p.bottomLeft.y = h - p.bottomLeft.h - MARGIN_3MM - 20;
          }

          // Anchor Right Group
          if (p.rightGroup.x === 1100) {
             p.rightGroup.x = w - p.rightGroup.w - MARGIN_3MM;
             p.rightGroup.y = h - p.rightGroup.h - MARGIN_3MM - 20;
          }

          // Anchor Layers (Between Top and Right Group)
          // Default: Right side
          if (p.layers.x === 1100) {
             p.layers.x = w - p.layers.w - MARGIN_3MM;
             // Calculate ideal Y: Below top bar, above RightGroup
             const topBarH = 60;
             const rightGroupTop = h - p.rightGroup.h - MARGIN_3MM - 20;
             const availH = rightGroupTop - topBarH;
             p.layers.y = topBarH + (availH / 2) - (p.layers.h / 2);
          }

          return { ...prev, uiLayout: p };
      });
  }, []);

  // Resize Handler: Anchoring logic
  // When window resizes, we DO NOT scale elements, we just move them to keep relative position (Anchoring)
  const windowSize = useRef({ w: window.innerWidth, h: window.innerHeight });

  useEffect(() => {
    const handleResize = () => {
      const newW = window.innerWidth;
      const newH = window.innerHeight;
      const oldW = windowSize.current.w;
      const oldH = windowSize.current.h;

      updateSettings(prev => {
        const p = prev.uiLayout;
        const newLayout = { ...p };

        // 1. Volume: Keep centered
        // Delta from center
        const oldCenter = oldW / 2;
        const newCenter = newW / 2;
        const volOffset = p.volume.x - oldCenter;
        newLayout.volume = { ...p.volume, x: newCenter + volOffset };

        // 2. Space: Keep Left anchored (no change to X), Y scaled relative to height? 
        // Or just keep vertical center? Let's keep vertical relative position.
        const spaceRelY = p.space.y / oldH;
        newLayout.space = { ...p.space, y: spaceRelY * newH };

        // 3. Right Group: Anchor Bottom Right
        const rightOffset = oldW - p.rightGroup.x;
        const bottomOffset = oldH - p.rightGroup.y;
        newLayout.rightGroup = { 
            ...p.rightGroup, 
            x: newW - rightOffset,
            y: newH - bottomOffset
        };

        // 4. Layers: Anchor Right Center
        const layerRightOffset = oldW - p.layers.x;
        const layerRelY = p.layers.y / oldH;
        newLayout.layers = {
            ...p.layers,
            x: newW - layerRightOffset,
            y: layerRelY * newH
        };

        // 5. Bottom Left: Anchor Bottom Left
        const botLeftBottomOffset = oldH - p.bottomLeft.y;
        newLayout.bottomLeft = {
            ...p.bottomLeft,
            y: newH - botLeftBottomOffset
        };

        return { ...prev, uiLayout: newLayout };
      });

      windowSize.current = { w: newW, h: newH };
    };

    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, [updateSettings]);

  // Init Engine updates
  useEffect(() => {
    audioEngine.setMasterVolume(masterVolume);
  }, [masterVolume]);

  useEffect(() => {
    audioEngine.setGlobalSpatialScale(spatialScale);
  }, [spatialScale]);

  const handleLimitInteraction = (limit: number) => {
    if (settings.layerOrder[settings.layerOrder.length - 1] !== limit) {
      const newOrder = settings.layerOrder.filter(l => l !== limit);
      newOrder.push(limit);
      updateSettings(prev => ({ ...prev, layerOrder: newOrder }));
    }
  };

  const handlePanic = () => {
    audioEngine.stopAll(); 
    diamondRef.current?.clearLatches(); 
    setActiveChordIds([]); 
    setLatchMode(0);
  };

  const handleOff = () => {
    diamondRef.current?.clearLatches(); 
    setActiveChordIds([]);
    setLatchMode(0);
  };

  const handleLatchToggle = () => {
      setLatchMode(prev => {
          const next = prev + 1;
          if (next > 2) {
              // Transitioning back to OFF clears latches
              diamondRef.current?.clearLatches();
              return 0;
          }
          return next as 0 | 1 | 2;
      });
  };

  const handleBendToggle = () => {
      updateSettings(prev => ({ ...prev, isPitchBendEnabled: !prev.isPitchBendEnabled }));
  };

  const handleCenter = () => {
      diamondRef.current?.centerView();
  };

  const handleIncreaseDepth = () => {
      diamondRef.current?.increaseDepth();
  };

  const handleDecreaseDepth = () => {
      diamondRef.current?.decreaseDepth();
  };

  const handleAddChord = () => {
      if (diamondRef.current) {
          const latchedNodes = diamondRef.current.getLatchedNodes();
          if (latchedNodes.length === 0) return;

          let slotIndex = settings.savedChords.findIndex(c => c.nodes.length === 0);
          if (slotIndex === -1) {
               slotIndex = settings.savedChords.findIndex(c => !c.visible);
          }

          if (slotIndex !== -1) {
              const newChords = [...settings.savedChords];
              const simplifiedNodes = latchedNodes.map(n => ({
                  id: n.id,
                  n: n.n,
                  d: n.d
              }));

              newChords[slotIndex] = {
                  ...newChords[slotIndex],
                  nodes: simplifiedNodes,
                  visible: true,
                  position: { x: 0, y: 0 } 
              };

              updateSettings(prev => ({ ...prev, savedChords: newChords }));
          }
      }
  };

  const toggleChord = (id: string) => {
      setActiveChordIds(prev => {
          if (prev.includes(id)) {
              return prev.filter(c => c !== id);
          } else {
              return [...prev, id];
          }
      });
  };

  const handleUiLayoutUpdate = (key: keyof AppSettings['uiLayout'], rect: UIRect) => {
      updateSettings(prev => ({
          ...prev,
          uiLayout: {
              ...prev.uiLayout,
              [key]: rect
          }
      }));
  };

  return (
    <div className="relative w-screen h-screen overflow-hidden bg-slate-900 font-sans text-white">

      {/* Top Bar - Fixed Position */}
      <div 
        className="absolute w-full flex justify-between items-center z-40 pointer-events-none"
        style={{ 
            top: `${MARGIN_3MM}px`, 
            paddingLeft: `${MARGIN_3MM}px`,
            paddingRight: `${MARGIN_3MM + SCROLLBAR_WIDTH}px` 
        }}
      >
        <h1 className="text-xl font-bold tracking-widest text-slate-500 opacity-50">PRISMATONAL</h1>
        <div className="flex gap-2 pointer-events-auto">
          <button 
            onClick={() => setIsSynthOpen(true)}
