import React, { useState, useEffect, useRef } from 'react';
import TonalityDiamond, { TonalityDiamondHandle } from './components/TonalityDiamond';
import SettingsModal from './components/SettingsModal';
import SynthControls from './components/SynthControls';
import FloatingControls from './components/FloatingControls';
import LimitLayerControls from './components/LimitLayerControls';
import { audioEngine } from './services/AudioEngine'; // Import singleton
import { useStore } from './services/Store';
import { AppSettings, ChordDefinition, XYPos } from './types';
import { MARGIN_3MM, SCROLLBAR_WIDTH, GAP_5MM, PIXELS_PER_MM } from './constants';

const REFERENCE_SHORT_EDGE = 1080; // Baseline resolution for 1.0 scale

const App: React.FC = () => {
  const { settings, preset, updateSettings, setPreset } = useStore();

  const [masterVolume, setMasterVolume] = useState(0.8);
  const [spatialScale, setSpatialScale] = useState(1.0); 
  const [activeChordIds, setActiveChordIds] = useState<string[]>([]);
  const [draggingId, setDraggingId] = useState<string | null>(null);

  // Adaptive Scaling State
  const [autoScaleFactor, setAutoScaleFactor] = useState(1.0);

  // 0 = Off, 1 = Latch All, 2 = Sustain (Partial Latch)
  const [latchMode, setLatchMode] = useState<0 | 1 | 2>(0);

  // Modals
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isSynthOpen, setIsSynthOpen] = useState(false);

  const diamondRef = useRef<TonalityDiamondHandle>(null);

  // Computed Effective Scale (Auto * User Preference)
  const effectiveScale = autoScaleFactor * (settings.uiScale || 1.0);

  // Audio Warmup
  useEffect(() => {
    const warmup = () => {
        audioEngine.init();
        window.removeEventListener('pointerdown', warmup);
        window.removeEventListener('keydown', warmup);
        window.removeEventListener('touchstart', warmup);
    };
    window.addEventListener('pointerdown', warmup);
    window.addEventListener('keydown', warmup);
    window.addEventListener('touchstart', warmup);
    return () => {
        window.removeEventListener('pointerdown', warmup);
        window.removeEventListener('keydown', warmup);
        window.removeEventListener('touchstart', warmup);
    };
  }, []);

  // Update CSS Variable for global usage if needed
  useEffect(() => {
      document.documentElement.style.setProperty('--ui-scale', effectiveScale.toString());
  }, [effectiveScale]);

  // Central Layout Calculation Logic
  const applyLayout = (w: number, h: number, scale: number) => {
      const margin = (settings.uiEdgeMargin || 6) * PIXELS_PER_MM; // Margin is absolute physical mm, usually doesn't scale with UI, but we can adhere to it.
      const scroll = SCROLLBAR_WIDTH;
      const gap = GAP_5MM * scale;

      // Dimensions
      const baseBtn = 48 * scale;
      const largeBtn = 80 * scale;
      const sliderWidth = 220 * scale; 

      const layersW = 90; // Fixed width for layers panel mostly
      const layersH = 310 * scale; 

      const newPos = { ...settings.uiPositions };

      // 1. Volume (Top Center)
      const volX = (w / 2) - (sliderWidth / 2);
      newPos.volume = {
          x: volX,
          y: margin
      };

      // 2. Space (Top, Left of Volume)
      newPos.space = {
          x: volX - sliderWidth - gap,
          y: margin
      };

      // 3. Layers (Limit Controls)
      // Position: Right side, below Header
      const headerClearance = margin + 60; 
      const layersX = w - margin - scroll - layersW;
      newPos.layers = { 
          x: layersX, 
          y: headerClearance 
      };

      // 4. Right Stack (Bend, Latch, Off, Panic)
      const rightX = w - margin - scroll - largeBtn;
      const panicY = h - margin - scroll - largeBtn;

      let bendY = newPos.layers.y + layersH + margin; 
      const centerY = (h / 2) - (largeBtn / 2);
      if (bendY < centerY) bendY = centerY;

      if (bendY > panicY - (largeBtn * 3)) bendY = panicY - (largeBtn * 3) - gap;

      const totalSpace = panicY - bendY;
      const step = totalSpace / 3;

      newPos.bend = { x: rightX, y: bendY };
      newPos.latch = { x: rightX, y: bendY + step };
      newPos.off = { x: rightX, y: bendY + (step * 2) };
      newPos.panic = { x: rightX, y: panicY };

      // 5. Bottom Left Row
      const bottomY = h - margin - scroll - baseBtn;
      let currentX = margin;

      newPos.center = { x: currentX, y: bottomY };
      currentX += (baseBtn + gap); 

      if (settings.showIncreaseDepthButton) {
          newPos.depth = { x: currentX, y: bottomY };
          currentX += (baseBtn + gap);
          newPos.decreaseDepth = { x: currentX, y: bottomY };
          currentX += (baseBtn + gap);
      }

      currentX += 20 * scale; 
      newPos.chords = { x: currentX, y: bottomY };

      return newPos;
  };

  // Resize Handler & Scale Calculator
  // We use a ref to prevent loops if updateSettings triggers re-renders
  const windowSizeRef = useRef({ w: window.innerWidth, h: window.innerHeight });

  useEffect(() => {
    const handleResize = () => {
        const w = window.innerWidth;
        const h = window.innerHeight;

        // Calculate Auto Scale based on Short Edge
        const shortEdge = Math.min(w, h);
        const newAutoScale = shortEdge / REFERENCE_SHORT_EDGE;
        setAutoScaleFactor(newAutoScale);

        // Recalculate Layout
        const newEffectiveScale = newAutoScale * (settings.uiScale || 1.0);

        updateSettings(prev => ({
            ...prev,
            uiPositions: applyLayout(w, h, newEffectiveScale)
        }));

        windowSizeRef.current = { w, h };
    };

    // Run once on mount to set initial scale/layout
    handleResize();

    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, [settings.uiScale, settings.uiEdgeMargin, settings.showIncreaseDepthButton]); // Re-run if user preferences change

  // Init Engine updates
  useEffect(() => {
    audioEngine.setMasterVolume(masterVolume);
  }, [masterVolume]);

  useEffect(() => {
    audioEngine.setGlobalSpatialScale(spatialScale);
  }, [spatialScale]);

  const handleLimitInteraction = (limit: number) => {
    if (settings.layerOrder[settings.layerOrder.length - 1] !== limit) {
      const newOrder = settings.layerOrder.filter(l => l !== limit);
      newOrder.push(limit);
      updateSettings(prev => ({ ...prev, layerOrder: newOrder }));
    }
  };

  const handlePanic = () => {
    audioEngine.stopAll(); 
    diamondRef.current?.clearLatches(); 
    setActiveChordIds([]); 
    setLatchMode(0);
  };

  const handleOff = () => {
    diamondRef.current?.clearLatches(); 
    setActiveChordIds([]);
    setLatchMode(0);
  };

  const handleLatchToggle = () => {
      setLatchMode(prev => {
          const next = prev + 1;
          if (next > 2) {
              diamondRef.current?.clearLatches();
              return 0;
          }
          return next as 0 | 1 | 2;
      });
  };

  const handleBendToggle = () => {
      updateSettings(prev => ({ ...prev, isPitchBendEnabled: !prev.isPitchBendEnabled }));
  };

  const handleCenter = () => {
      diamondRef.current?.centerView();
  };

  const handleIncreaseDepth = () => {
      diamondRef.current?.increaseDepth();
  };

  const handleDecreaseDepth = () => {
      diamondRef.current?.decreaseDepth();
  };

  const handleAddChord = () => {
      if (diamondRef.current) {
          const latchedNodes = diamondRef.current.getLatchedNodes();
          if (latchedNodes.length === 0) return;

          let slotIndex = settings.savedChords.findIndex(c => c.nodes.length === 0);
          if (slotIndex === -1) {
               slotIndex = settings.savedChords.findIndex(c => !c.visible);
          }

          if (slotIndex !== -1) {
              const newChords = [...settings.savedChords];
              const simplifiedNodes = latchedNodes.map(n => ({
                  id: n.id, n: n.n, d: n.d
              }));

              newChords[slotIndex] = {
                  ...newChords[slotIndex],
                  nodes: simplifiedNodes,
                  visible: true,
                  position: { x: 0, y: 0 } 
              };

              updateSettings(prev => ({ ...prev, savedChords: newChords }));
          }
      }
  };

  const toggleChord = (id: string) => {
      setActiveChordIds(prev => {
          if (prev.includes(id)) {
              return prev.filter(c => c !== id);
          } else {
              return [...prev, id];
          }
      });
  };

  const handleUiPositionUpdate = (key: keyof AppSettings['uiPositions'], pos: XYPos) => {
      updateSettings(prev => ({
          ...prev,
          uiPositions: { ...prev.uiPositions, [key]: pos }
      }));
  };

  return (
    <div className="relative w-screen h-screen overflow-hidden bg-slate-900 font-sans text-white">

      {/* Top Bar */}
      <div 
        className="absolute w-full flex justify-between items-center z-40 pointer-events-none"
        style={{ 
            top: `${(settings.uiEdgeMargin || 6) * PIXELS_PER_MM}px`, 
            paddingLeft: `${(settings.uiEdgeMargin || 6) * PIXELS_PER_MM}px`,
            paddingRight: `${(settings.uiEdgeMargin || 6) * PIXELS_PER_MM + SCROLLBAR_WIDTH}px` 
        }}
      >
        <h1 className="text-xl font-bold tracking-widest text-slate-500 opacity-50">PRISMATONAL</h1>
        <div className="flex gap-2 pointer-events-auto">
          <button 
            onClick={() => setIsSynthOpen(true)}
            className="bg-slate-800/80 hover:bg-indigo-600 px-4 py-2 rounded-lg backdrop-blur transition border border-white/10"
          >
            Synth
          </button>
          <button 
            onClick={() => setIsSettingsOpen(true)}
            className="bg-slate-800/80 hover:bg-slate-600 px-4 py-2 rounded-lg backdrop-blur transition border border-white/10"
          >
            Settings
          </button>
        </div>
      </div>

      {/* Main Canvas - Passing effectiveScale for proportional display */}
      <TonalityDiamond 
        ref={diamondRef}
        settings={settings}
        updateSettings={updateSettings}
        audioEngine={audioEngine} 
        onLimitInteraction={handleLimitInteraction}
        activeChordIds={activeChordIds}
        uiUnlocked={settings.uiUnlocked}
        latchMode={latchMode}
        globalScale={effectiveScale}
      />

      {/* Floating UI - Passing effectiveScale for sizing */}
      <FloatingControls 
        volume={masterVolume}
        setVolume={setMasterVolume}
        spatialScale={spatialScale}
        setSpatialScale={setSpatialScale}
        onPanic={handlePanic}
        onOff={handleOff}
        onLatch={handleLatchToggle}
        latchMode={latchMode}
        onBend={handleBendToggle}
        isBendEnabled={settings.isPitchBendEnabled}
        onCenter={handleCenter}
        onIncreaseDepth={handleIncreaseDepth}
        onDecreaseDepth={handleDecreaseDepth}
        onAddChord={handleAddChord}
        toggleChord={toggleChord}
        activeChordIds={activeChordIds}
        savedChords={settings.savedChords}
        chordShortcutSizeScale={settings.chordShortcutSizeScale}
        showIncreaseDepthButton={settings.showIncreaseDepthButton}
        uiUnlocked={settings.uiUnlocked}
        uiPositions={settings.uiPositions}
        updatePosition={handleUiPositionUpdate}
        draggingId={draggingId}
        setDraggingId={setDraggingId}
        uiScale={effectiveScale}
      />

      <LimitLayerControls 
        settings={settings}
        updateSettings={updateSettings}
        draggingId={draggingId}
        setDraggingId={setDraggingId}
        uiScale={effectiveScale}
      />

      {/* Modals */}
      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)}
        settings={settings}
        updateSettings={updateSettings}
      />

      <SynthControls 
        isOpen={isSynthOpen}
        onClose={() => setIsSynthOpen(false)}
        preset={preset}
        onChange={setPreset}
      />
    </div>
  );
};

export default App;

import React from 'react';
import { AppSettings } from '../types';
import { MARGIN_3MM, SCROLLBAR_WIDTH } from '../constants';

interface Props {
  settings: AppSettings;
  updateSettings: (s: AppSettings) => void;
  draggingId: string | null;
  setDraggingId: (id: string | null) => void;
  uiScale?: number;
}

const LIMITS = [1, 3, 5, 7, 11, 13];

const LimitLayerControls: React.FC<Props> = ({ settings, updateSettings, draggingId, setDraggingId, uiScale = 1.0 }) => {
  const { uiUnlocked, uiPositions } = settings;

  // Base sizing scaled by effective uiScale
  const buttonSize = 48 * uiScale; 
  const iconSize = 24 * uiScale; 

  const isVisible = (limit: number) => {
    // 1-Limit is always visible
    if (limit === 1) return true;
    return !settings.hiddenLimits.includes(limit);
  };

  const toggleVisibility = (limit: number) => {
    // Prevent hiding 1-Limit
    if (limit === 1) return;

    // Toggle 'hiddenLimits' which affects strict filtering
    const isHidden = settings.hiddenLimits.includes(limit);
    let newHidden = [...settings.hiddenLimits];
    if (isHidden) {
      newHidden = newHidden.filter(l => l !== limit);
    } else {
      newHidden.push(limit);
    }
    updateSettings({ ...settings, hiddenLimits: newHidden });
  };

  const bringToFront = (limit: number) => {
    const newOrder = settings.layerOrder.filter(l => l !== limit);
    newOrder.push(limit);
    updateSettings({ ...settings, layerOrder: newOrder });
  };

  // Drag Handler
  const handleDrag = (e: React.PointerEvent) => {
    if (!uiUnlocked) return;

    // Lock check
    if (draggingId !== null && draggingId !== 'layers') return;

    const el = e.currentTarget as HTMLElement;
    const startX = e.clientX;
    const startY = e.clientY;

    // Initial position
    const initialLeft = uiPositions.layers.x;
    const initialTop = uiPositions.layers.y;

    el.setPointerCapture(e.pointerId);
    setDraggingId('layers');

    const onMove = (evt: PointerEvent) => {
        const deltaX = evt.clientX - startX;
        const deltaY = evt.clientY - startY;

        let newX = initialLeft + deltaX;
        let newY = initialTop + deltaY;

        // Clamp to window bounds with Margin + Scrollbar safety
        const maxX = window.innerWidth - el.offsetWidth - MARGIN_3MM - SCROLLBAR_WIDTH;
        const maxY = window.innerHeight - el.offsetHeight - MARGIN_3MM - SCROLLBAR_WIDTH;
        const minX = MARGIN_3MM;
        const minY = MARGIN_3MM;

        newX = Math.max(minX, Math.min(newX, maxX));
        newY = Math.max(minY, Math.min(newY, maxY));

        updateSettings({ 
            ...settings, 
            uiPositions: { 
                ...settings.uiPositions, 
                layers: { x: newX, y: newY } 
            } 
        });
    };

    const onUp = () => {
        setDraggingId(null);
        window.removeEventListener('pointermove', onMove);
        window.removeEventListener('pointerup', onUp);
    };

    window.addEventListener('pointermove', onMove);
    window.addEventListener('pointerup', onUp);
  };

  return (
    <div 
        className={`absolute flex flex-col gap-3 z-[140] bg-slate-900/50 p-2 rounded-xl backdrop-blur-sm border border-slate-700/50 ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : ''}`}
        style={{ left: uiPositions.layers.x, top: uiPositions.layers.y, touchAction: 'none' }}
        onPointerDown={handleDrag}
    >
      {LIMITS.map(limit => {
        const visible = isVisible(limit);
        const color = settings.colors[limit];
        const isTop = settings.layerOrder[settings.layerOrder.length - 1] === limit;
        const isLocked = limit === 1;

        return (
          <div key={limit} className="flex items-center gap-2 group">
            {/* Visibility Toggle */}
            <button 
              onClick={(e) => { e.stopPropagation(); !uiUnlocked && toggleVisibility(limit); }}
              disabled={isLocked}
              className={`flex items-center justify-center rounded transition-colors ${visible ? (isLocked ? 'text-slate-500 cursor-default opacity-50' : 'text-white') : 'text-slate-600'} hover:bg-white/10 ${uiUnlocked ? 'pointer-events-none' : ''}`}
              style={{ width: iconSize, height: iconSize }}
              onPointerDown={(e) => !uiUnlocked && e.stopPropagation()} 
            >
               {visible ? (
                 <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-full h-full p-0.5">
                   <path d="M10 12.5a2.5 2.5 0 100-5 2.5 2.5 0 000 5z" />
                   <path fillRule="evenodd" d="M.664 10.59a1.651 1.651 0 010-1.186A10.004 10.004 0 0110 3c4.257 0 8.201 2.372 9.336 6.41.147.527.147 1.074 0 1.601C18.201 14.628 14.257 17 10 17c-4.257 0-8.201-2.372-9.336-6.41zM14 10a4 4 0 11-8 0 4 4 0 018 0z" clipRule="evenodd" />
                 </svg>
               ) : (
                 <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-full h-full p-0.5">
                   <path fillRule="evenodd" d="M3.28 2.22a.75.75 0 00-1.06 1.06l14.5 14.5a.75.75 0 101.06-1.06l-1.745-1.745A10.029 10.029 0 0018 10c-1.135-4.038-5.079-6.41-9.336-6.41a9.982 9.982 0 00-4.636 1.135L3.28 2.22zm12.98 12.98l-3.212-3.212a3.003 3.003 0 00-4.244-4.244L5.68 4.62A11.967 11.967 0 00.664 9.41a1.651 1.651 0 010 1.18c1.135 4.038 5.079 6.41 9.336 6.41 2.053 0 4.008-.584 5.688-1.613l.572.572z" clipRule="evenodd" />
                   <path d="M10.983 7.796a1.5 1.5 0 012.122 2.122l-2.122-2.122z" />
                 </svg>
               )}
            </button>

            {/* Color/Select Layer Button */}
            <button 
              onClick={(e) => { e.stopPropagation(); !uiUnlocked && bringToFront(limit); }}
              className={`rounded-lg shadow-md border-2 transition-all transform active:scale-95 flex items-center justify-center font-bold text-shadow ${uiUnlocked ? 'pointer-events-none' : ''}`}
              style={{ 
                width: buttonSize, 
                height: buttonSize,
                fontSize: 14 * uiScale,
                backgroundColor: color, 
                borderColor: isTop ? 'white' : 'transparent',
                boxShadow: isTop ? '0 0 10px rgba(255,255,255,0.5)' : 'none',
                opacity: visible ? 1 : 0.2
              }}
              onPointerDown={(e) => !uiUnlocked && e.stopPropagation()}
            >
              {limit}
            </button>
          </div>
        );
      })}
    </div>
  );
};

export default LimitLayerControls;

import React, { useEffect, useRef, useState, useLayoutEffect, useImperativeHandle, forwardRef, useMemo } from 'react';
import { AppSettings, LatticeNode, LatticeLine, ButtonShape } from '../types';
import { getHarmonicDistance, generateLattice } from '../services/LatticeService';
import { getPitchRatioFromScreenDelta, getRainbowPeriod } from '../services/ProjectionService';
import AudioEngine from '../services/AudioEngine';
import { midiService } from '../services/MidiService';

export interface TonalityDiamondHandle {
  clearLatches: () => void;
  centerView: () => void;
  increaseDepth: () => void;
  decreaseDepth: () => void;
  getLatchedNodes: () => LatticeNode[];
}

interface Props {
  settings: AppSettings;
  updateSettings: (s: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) => void;
  audioEngine: AudioEngine;
  onLimitInteraction: (limit: number) => void;
  activeChordIds: string[];
  uiUnlocked: boolean;
  latchMode: 0 | 1 | 2; // 0=Off, 1=LatchAll, 2=Sustain
  globalScale?: number; // Adaptive scaling factor
}

interface ActiveCursor {
  pointerId: number;
  currentX: number;
  currentY: number;
  originNodeId: string | null; // ID if started on a node (Held), Null if started on background (Strum)
  hoverNodeId: string | null;  // Current node under pointer
}

// Spatial Grid Constants (Unscaled base size)
const GRID_CELL_SIZE = 100; 

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, updateSettings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked, latchMode, globalScale = 1.0 } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);

  // Triple Canvas Strategy for correct layering
  // 1. Background Lines (Brightened / Active Voice Leading) - Z: 5
  // 2. Static Lattice (Passive Nodes / Passive Lines) - Z: 10
  // 3. Dynamic Overlay (Active Nodes / Halos / Interactions) - Z: 20
  const bgLineCanvasRef = useRef<HTMLCanvasElement>(null);
  const staticCanvasRef = useRef<HTMLCanvasElement>(null); 
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null); 

  const animationFrameRef = useRef<number>(0);

  // Data State
  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });
  const [isGenerating, setIsGenerating] = useState(false);
  const [isInitialLoad, setIsInitialLoad] = useState(true);

  // Auto-calculated Dimensions
  const [dynamicSize, setDynamicSize] = useState(2000);
  const prevDynamicSizeRef = useRef(2000);

  // Optimization: Memoized Lookups & Spatial Grid
  const nodeMap = useMemo(() => {
      return new Map(data.nodes.map(n => [n.id, n]));
  }, [data.nodes]);

  const spatialGrid = useMemo(() => {
      const grid = new Map<string, LatticeNode[]>();
      const centerOffset = dynamicSize / 2;

      // EFFECTIVE SPACING determines grid placement
      const spacing = settings.buttonSpacingScale * globalScale;

      data.nodes.forEach(node => {
          const x = node.x * spacing + centerOffset;
          const y = node.y * spacing + centerOffset;

          const col = Math.floor(x / GRID_CELL_SIZE);
          const row = Math.floor(y / GRID_CELL_SIZE);
          const key = `${col},${row}`;

          if (!grid.has(key)) grid.set(key, []);
          grid.get(key)!.push(node);
      });
      return grid;
  }, [data.nodes, settings.buttonSpacingScale, dynamicSize, globalScale]);

  // Interaction State
  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  const [persistentLatches, setPersistentLatches] = useState<Map<string, string>>(new Map());

  // Computed Effective Latched Nodes
  // This is the source of truth for audio and visuals
  const effectiveLatchedNodes = useMemo(() => {
      const effective = new Map<string, string>(persistentLatches);

      // Add Chords
      activeChordIds.forEach(chordId => {
        const chordDef = settings.savedChords.find(c => c.id === chordId);
        if (chordDef) {
            chordDef.nodes.forEach(n => {
                if (!effective.has(n.id)) effective.set(n.id, n.id);
            });
        }
      });

      // Add Active Cursors
      activeCursors.forEach(cursor => {
          // Held Note (Pitch Bend Active)
          if (cursor.originNodeId && settings.isPitchBendEnabled) {
              effective.set(cursor.originNodeId, cursor.originNodeId);
          } 
          // Strummed Note (Only if NOT in Latch Mode 1)
          // In Latch Mode 1, mouse-over adds to persistent, so we don't need this temporary state.
          else if (cursor.hoverNodeId && latchMode !== 1) {
              effective.set(cursor.hoverNodeId, cursor.hoverNodeId);
          }
      });

      return effective;
  }, [persistentLatches, activeChordIds, settings.savedChords, activeCursors, latchMode, settings.isPitchBendEnabled]);

  // --- ACTIVE LINES LOGIC (Direct Neighbors or Extended Reach) ---
  const activeLines = useMemo(() => {
    const latched = effectiveLatchedNodes;
    const cursors = activeCursors;
    const lines = data.lines;
    const active: LatticeLine[] = [];
    const reach = settings.voiceLeadingSteps || 1;

    // Stability Filter (prevent flickering)
    const isStable = (id: string) => {
        if (persistentLatches.has(id)) return true;
        const inChord = activeChordIds.some(cid => {
            const c = settings.savedChords.find(ch => ch.id === cid);
            return c?.nodes.some(n => n.id === id);
        });
        if (inChord) return true;
        for (const c of cursors.values()) {
            if (c.originNodeId === id && settings.isPitchBendEnabled) return true;
        }
        if (latchMode === 1) return true;
        return false;
    };

    if (latched.size < 2) return [];

    // Mode 1: Standard Grid Lines (Distance 1)
    if (reach === 1) {
        for (const line of lines) {
            const s = line.sourceId;
            const t = line.targetId;
            if (latched.has(s) && latched.has(t)) {
                if (isStable(s) && isStable(t)) {
                    active.push(line);
                }
            }
        }
    } 
    // Mode 2: Extended Reach (Distance <= 2)
    // This allows "cousin" connections like 1/1 to 6/5
    else if (reach === 2) {
        const activeNodes = Array.from(latched.keys()).filter(isStable).map(id => nodeMap.get(id)).filter(n => n) as LatticeNode[];

        for (let i=0; i<activeNodes.length; i++) {
            for (let j=i+1; j<activeNodes.length; j++) {
                const A = activeNodes[i];
                const B = activeNodes[j];

                // Calculate Manhattan Distance in lattice coordinates
                let dist = 0;
                for (let k=0; k < A.coords.length; k++) {
                    dist += Math.abs(A.coords[k] - B.coords[k]);
                }
                dist += Math.abs(A.octave - B.octave); // simplified octave dist

                if (dist <= 2) {
                    // Create an ephemeral line
                    const maxP = Math.max(A.maxPrime, B.maxPrime);
                    active.push({
                        id: `${A.id}-${B.id}`,
                        x1: A.x, y1: A.y,
                        x2: B.x, y2: B.y,
                        limit: maxP,
                        sourceId: A.id, targetId: B.id
                    });
                }
            }
        }
    }

    return active;
  }, [data.lines, effectiveLatchedNodes, activeCursors, persistentLatches, activeChordIds, latchMode, settings.voiceLeadingSteps, nodeMap, settings.isPitchBendEnabled]);

  // --- LINE BRIGHTENING LOGIC (Neighbors of Active) ---
  const brightenedLines = useMemo(() => {
      if (!settings.lineBrighteningEnabled || effectiveLatchedNodes.size === 0) return [];

      const activeIds = new Set(effectiveLatchedNodes.keys());
      const resultLines = new Set<LatticeLine>();
      const step1Neighbors = new Set<string>();

      // Step 1: Lines connected to any active node
      data.lines.forEach(line => {
          const sActive = activeIds.has(line.sourceId);
          const tActive = activeIds.has(line.targetId);

          if (sActive || tActive) {
              resultLines.add(line);
              if (sActive) step1Neighbors.add(line.targetId);
              if (tActive) step1Neighbors.add(line.sourceId);
          }
      });

      // Step 2: Lines connected to Step 1 neighbors
      if (settings.lineBrighteningSteps === 2) {
          data.lines.forEach(line => {
              if (resultLines.has(line)) return;
              const sNeighbor = step1Neighbors.has(line.sourceId);
              const tNeighbor = step1Neighbors.has(line.targetId);
              if (sNeighbor || tNeighbor) {
                  resultLines.add(line);
              }
          });
      }

      return Array.from(resultLines);
  }, [effectiveLatchedNodes, data.lines, settings.lineBrighteningEnabled, settings.lineBrighteningSteps]);

  // Refs for Render Loop
  const settingsRef = useRef(settings);
  const dataRef = useRef(data);
  const activeCursorsRef = useRef<Map<number, ActiveCursor>>(activeCursors);
  const effectiveLatchedRef = useRef(effectiveLatchedNodes);
  const nodeMapRef = useRef(nodeMap);
  const activeLinesRef = useRef(activeLines);
  const brightenedLinesRef = useRef(brightenedLines);
  const spatialGridRef = useRef(spatialGrid);
  const dynamicSizeRef = useRef(dynamicSize);
  const globalScaleRef = useRef(globalScale);

  const cursorPositionsRef = useRef<Map<number, {x: number, y: number}>>(new Map());

  // Sync Refs
  useEffect(() => { settingsRef.current = settings; }, [settings]);
  useEffect(() => { dataRef.current = data; }, [data]);
  useEffect(() => { activeCursorsRef.current = activeCursors; }, [activeCursors]);
  useEffect(() => { effectiveLatchedRef.current = effectiveLatchedNodes; }, [effectiveLatchedNodes]);
  useEffect(() => { nodeMapRef.current = nodeMap; }, [nodeMap]);
  useEffect(() => { activeLinesRef.current = activeLines; }, [activeLines]);
  useEffect(() => { brightenedLinesRef.current = brightenedLines; }, [brightenedLines]);
  useEffect(() => { spatialGridRef.current = spatialGrid; }, [spatialGrid]);
  useEffect(() => { dynamicSizeRef.current = dynamicSize; }, [dynamicSize]);
  useEffect(() => { globalScaleRef.current = globalScale; }, [globalScale]);

  // Interaction State
  const lastTouchedLimitRef = useRef<number | null>(null);
  const depthHistoryRef = useRef<number[]>([]);
  const prevActiveChordIds = useRef<string[]>([]);

  // --- External API ---
  useImperativeHandle(ref, () => ({
    clearLatches: () => setPersistentLatches(new Map()),
    centerView: () => { centerScroll(); },
    increaseDepth: () => {
        const limit = lastTouchedLimitRef.current;
        if (limit && limit > 1) {
             updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: currentDepth + 1 } };
             });
             depthHistoryRef.current.push(limit);
        }
    },
    decreaseDepth: () => {
        const limit = depthHistoryRef.current.pop();
        if (limit) {
            updateSettings((prev: AppSettings) => {
                 const currentDepth = prev.limitDepths[limit as 3|5|7|11|13];
                 return { ...prev, limitDepths: { ...prev.limitDepths, [limit]: Math.max(0, currentDepth - 1) } };
             });
        }
    },
    getLatchedNodes: () => {
        const result: LatticeNode[] = [];
        effectiveLatchedNodes.forEach((_, id) => {
            const n = nodeMap.get(id);
            if (n) result.push(n);
        });
        return result;
    }
  }));

  const centerScroll = () => {
      if (scrollContainerRef.current) {
        const center = dynamicSize / 2;
        const viewportW = scrollContainerRef.current.clientWidth;
        const viewportH = scrollContainerRef.current.clientHeight;
        scrollContainerRef.current.scrollLeft = center - viewportW / 2;
        scrollContainerRef.current.scrollTop = center - viewportH / 2;
      }
  };

  // Ensure center on load when data is actually ready
  useEffect(() => {
      if (isInitialLoad && !isGenerating && data.nodes.length > 0) {
          centerScroll();
          setIsInitialLoad(false);
      }
  }, [isGenerating, data.nodes.length, isInitialLoad, dynamicSize]);

  // Adjust scroll when dynamic size changes to maintain relative view
  useLayoutEffect(() => {
    const container = scrollContainerRef.current;
    if (!container) return;

    // Skip if this is the initial load, handled by the useEffect above
    if (!isInitialLoad && dynamicSize !== prevDynamicSizeRef.current) {
        const diff = (dynamicSize - prevDynamicSizeRef.current) / 2;
        container.scrollLeft += diff;
        container.scrollTop += diff;
    }
    prevDynamicSizeRef.current = dynamicSize;
  }, [dynamicSize, isInitialLoad]);

  // --- Data Generation ---
  // Generation calculates RELATIVE COORDINATES. Scaling happens at render time.
  const generationDeps = useMemo(() => {
      return JSON.stringify({
          depths: settings.limitDepths,
          complexities: settings.limitComplexities,
          hidden: settings.hiddenLimits,
          ratio: settings.latticeAspectRatio
      });
  }, [settings.limitDepths, settings.limitComplexities, settings.hiddenLimits, settings.latticeAspectRatio]);

  useEffect(() => {
    setIsGenerating(true);
    const timerId = setTimeout(() => {
        const effectiveSettings: AppSettings = JSON.parse(JSON.stringify(settings));
        const hiddenLimits = effectiveSettings.hiddenLimits || [];
        hiddenLimits.forEach((limit: number) => {
            // @ts-ignore
            if (effectiveSettings.limitDepths[limit] !== undefined) effectiveSettings.limitDepths[limit] = 0;
        });

        const result = generateLattice(effectiveSettings);
        const visibleNodeIds = new Set(result.nodes.map(n => n.id));
        const visibleLines = result.lines.filter(l => {
            if (hiddenLimits.includes(l.limit)) return false;
            if (!visibleNodeIds.has(l.sourceId) || !visibleNodeIds.has(l.targetId)) return false;
            return true;
        });

        let maxExtent = 0;
        for (const n of result.nodes) {
            const absX = Math.abs(n.x);
            const absY = Math.abs(n.y);
            if (absX > maxExtent) maxExtent = absX;
            if (absY > maxExtent) maxExtent = absY;
        }

        const padding = 600; 
        // We use the base scale here for buffer calculation, dynamic resizing usually handles the rest
        // But to be safe, we check against globalScale too in the effect below
        const spacing = settingsRef.current.buttonSpacingScale * globalScale; 
        const calculatedSize = (maxExtent * spacing * 2) + padding;
        const finalSize = Math.max(calculatedSize, window.innerWidth, window.innerHeight);

        if (Math.abs(finalSize - dynamicSizeRef.current) > 50) {
            setDynamicSize(finalSize);
        }

        setData({ nodes: result.nodes, lines: visibleLines });
        setIsGenerating(false);
    }, 10);
    return () => clearTimeout(timerId);
  }, [generationDeps]); 

  // Recalculate container size if scaling changes
  useEffect(() => {
      let maxExtent = 0;
      for (const n of data.nodes) {
          const absX = Math.abs(n.x);
          const absY = Math.abs(n.y);
          if (absX > maxExtent) maxExtent = absX;
          if (absY > maxExtent) maxExtent = absY;
      }
      const padding = 600; 
      const spacing = settings.buttonSpacingScale * globalScale;
      const calculatedSize = (maxExtent * spacing * 2) + padding;
      const finalSize = Math.max(calculatedSize, window.innerWidth, window.innerHeight);
      if (Math.abs(finalSize - dynamicSize) > 50) setDynamicSize(finalSize);
  }, [settings.buttonSpacingScale, globalScale]);


  // --- STATIC CANVAS RENDERER ---
  const visualDeps = useMemo(() => JSON.stringify({
      size: settings.buttonSizeScale,
      spacing: settings.buttonSpacingScale,
      colors: settings.colors,
      visuals: settings.limitVisuals,
      shape: settings.buttonShape,
      textScale: settings.nodeTextSizeScale,
      fractionBar: settings.showFractionBar,
      canvasSize: dynamicSize,
      globalScale: globalScale 
  }), [settings.buttonSizeScale, settings.buttonSpacingScale, settings.colors, settings.limitVisuals, settings.buttonShape, settings.nodeTextSizeScale, settings.showFractionBar, dynamicSize, globalScale]);

  useEffect(() => {
      const canvas = staticCanvasRef.current;
      if (!canvas) return;
      const ctx = canvas.getContext('2d', { alpha: true });
      if (!ctx) return;

      const dpr = window.devicePixelRatio || 1;
      const size = dynamicSize;

      if (canvas.width !== size * dpr || canvas.height !== size * dpr) {
          canvas.width = size * dpr;
          canvas.height = size * dpr;
      }

      ctx.setTransform(1, 0, 0, 1, 0, 0);
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.scale(dpr, dpr);

      const centerOffset = size / 2;
      // APPLY GLOBAL SCALE TO VISUALS
      const spacing = settings.buttonSpacingScale * globalScale;
      const baseRadius = (60 * settings.buttonSizeScale * globalScale) / 2;
      const isDiamond = settings.buttonShape === ButtonShape.DIAMOND;

      const linesByLimit: Record<number, number[]> = {};
      for (const line of data.lines) {
          if (!linesByLimit[line.limit]) linesByLimit[line.limit] = [];
          const arr = linesByLimit[line.limit];
          arr.push(line.x1 * spacing + centerOffset, line.y1 * spacing + centerOffset, line.x2 * spacing + centerOffset, line.y2 * spacing + centerOffset);
      }

      ctx.lineCap = 'round';
      // STATIC LINES (Passive)
      for (const limitStr in linesByLimit) {
          const limit = parseInt(limitStr);
          const coords = linesByLimit[limit];
          const color = settings.colors[limit] || '#666';
          const visualSettings = settings.limitVisuals?.[limit] || { size: 1, opacity: 1 };

          ctx.beginPath();
          for(let i=0; i<coords.length; i+=4) {
              ctx.moveTo(coords[i], coords[i+1]);
              ctx.lineTo(coords[i+2], coords[i+3]);
          }
          ctx.lineWidth = (limit === 1 ? 4 : 2) * visualSettings.size * globalScale; // Scale line width
          ctx.strokeStyle = color;
          ctx.globalAlpha = 0.3 * visualSettings.opacity; 

          if (limit === 1) ctx.setLineDash([5 * globalScale, 5 * globalScale]);
          else ctx.setLineDash([]);
          ctx.stroke();
      }
      ctx.setLineDash([]); 

      // STATIC NODES (Passive, Base Layer)
      for (const node of data.nodes) {
          const x = node.x * spacing + centerOffset;
          const y = node.y * spacing + centerOffset;
          const cTop = settings.colors[node.limitTop] || '#666';
          const cBottom = settings.colors[node.limitBottom] || '#666';
          const topVis = settings.limitVisuals?.[node.limitTop] || { size: 1, opacity: 1 };
          const limitScale = topVis.size;
          const limitOpacity = topVis.opacity;
          const radius = baseRadius * limitScale;

          ctx.globalAlpha = 1.0 * limitOpacity;

          ctx.beginPath();
          if (isDiamond) {
              ctx.moveTo(x, y - radius);
              ctx.lineTo(x + radius, y);
              ctx.lineTo(x, y + radius);
              ctx.lineTo(x - radius, y);
          } else {
              ctx.arc(x, y, radius, 0, Math.PI * 2);
          }
          ctx.closePath();

          const grad = ctx.createLinearGradient(x, y - radius, x, y + radius);
          grad.addColorStop(0.45, cTop);
          grad.addColorStop(0.55, cBottom);
          ctx.fillStyle = grad;
          ctx.fill();

          const combinedScale = settings.buttonSizeScale * limitScale;
          if (combinedScale > 0.4) {
              ctx.fillStyle = 'white';
              ctx.textAlign = 'center';
              ctx.textBaseline = 'middle';
              // Scale font size
              let fontSize = Math.max(10, Math.min(18, 14 * combinedScale)) * settings.nodeTextSizeScale * globalScale;
              ctx.font = `bold ${fontSize}px sans-serif`; 

              const spacingY = settings.showFractionBar ? 0.55 : 0.50;
              ctx.fillText(node.n.toString(), x, y - (radius * spacingY));
              if (settings.showFractionBar) {
                  ctx.beginPath();
                  ctx.moveTo(x - (radius * 0.4), y);
                  ctx.lineTo(x + (radius * 0.4), y);
                  ctx.lineWidth = 1 * globalScale;
                  ctx.strokeStyle = `rgba(255,255,255,${0.8 * limitOpacity})`;
                  ctx.stroke();
              }
              ctx.fillText(node.d.toString(), x, y + (radius * spacingY));
          }
      }
  }, [data, visualDeps]); 


  // --- Logic: Latches & Audio Sync ---
  // (Audio sync logic remains same, relies on ID maps, not visuals)
  useEffect(() => {
    if (settings.chordsAlwaysRelatch) {
         const newChords = activeChordIds.filter(id => !prevActiveChordIds.current.includes(id));
         if (newChords.length > 0) {
             const nodes = nodeMap;
             newChords.forEach(chordId => {
                 const chordDef = settings.savedChords.find(c => c.id === chordId);
                 if (chordDef) {
                     chordDef.nodes.forEach(n => {
                        const fullNode = nodes.get(n.id);
                        if (fullNode) {
                            audioEngine.startVoice(`node-${n.id}`, fullNode.ratio, settings.baseFrequency);
                            if (settings.midiEnabled) midiService.noteOn(`node-${n.id}`, fullNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
                        }
                     });
                 }
             });
         }
    }
    prevActiveChordIds.current = activeChordIds;
  }, [activeChordIds, settings.savedChords, settings.chordsAlwaysRelatch, nodeMap]);

  const prevEffectiveRef = useRef<Map<string, string>>(new Map());
  useEffect(() => {
      const current = effectiveLatchedNodes;
      const prev = prevEffectiveRef.current;
      const nodes = nodeMap;

      current.forEach((originId, nodeId) => {
          if (!prev.has(nodeId)) {
               const node = nodes.get(nodeId); 
               if (node) {
                   audioEngine.startVoice(`node-${nodeId}`, node.ratio, settings.baseFrequency);
                   if (settings.midiEnabled) midiService.noteOn(`node-${nodeId}`, node.ratio, settings.baseFrequency, settings.midiPitchBendRange);
               }
          }
      });
      prev.forEach((_, nodeId) => {
          if (!current.has(nodeId)) {
              audioEngine.stopVoice(`node-${nodeId}`);
              if (settings.midiEnabled) midiService.noteOff(`node-${nodeId}`);
          }
      });

      prevEffectiveRef.current = current;
  }, [effectiveLatchedNodes, nodeMap, settings.baseFrequency]);

  useEffect(() => {
    audioEngine.setPolyphony(settings.polyphony);
  }, [settings.polyphony]);

  // Helper for Hit Testing
  const getHitNode = (clientX: number, clientY: number): LatticeNode | null => {
      if (!dynamicCanvasRef.current) return null;
      const rect = dynamicCanvasRef.current.getBoundingClientRect();
      const x = clientX - rect.left;
      const y = clientY - rect.top;

      const centerOffset = dynamicSizeRef.current / 2;
      // Use scaled spacing/radius for hit detection
      const spacing = settings.buttonSpacingScale * globalScale;
      const baseRadius = (60 * settings.buttonSizeScale * globalScale) / 2;

      const col = Math.floor(x / GRID_CELL_SIZE);
      const row = Math.floor(y / GRID_CELL_SIZE);

      const cellsToCheck = [
          `${col},${row}`, `${col+1},${row}`, `${col-1},${row}`,
          `${col},${row+1}`, `${col},${row-1}`,
          `${col+1},${row+1}`, `${col-1},${row-1}`,
          `${col+1},${row-1}`, `${col-1},${row+1}`
      ];

      const grid = spatialGridRef.current;

      for(const key of cellsToCheck) {
          const nodesInCell = grid.get(key);
          if (nodesInCell) {
              for (const node of nodesInCell) {
                  const nx = node.x * spacing + centerOffset;
                  const ny = node.y * spacing + centerOffset;
                  const vis = settings.limitVisuals?.[node.limitTop] || { size: 1 };
                  const r = baseRadius * vis.size;

                  if (x < nx - r || x > nx + r || y < ny - r || y > ny + r) continue;

                  const dx = x - nx;
                  const dy = y - ny;
                  if (dx*dx + dy*dy < r*r) return node;
              }
          }
      }
      return null;
  };

  // --- Interaction Handlers ---
  const handlePointerDown = (e: React.PointerEvent) => {
      if (uiUnlocked || !dynamicCanvasRef.current) return;
      e.preventDefault();
      (e.target as HTMLElement).setPointerCapture(e.pointerId);

      cursorPositionsRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });

      const hitNode = getHitNode(e.clientX, e.clientY);
      const nodeId = hitNode ? hitNode.id : null;

      if (!hitNode && latchMode === 1 && !settings.isPitchBendEnabled) {
          return;
      }

      setActiveCursors(prev => {
          const next = new Map(prev);
          next.set(e.pointerId, {
              pointerId: e.pointerId,
              currentX: e.clientX,
              currentY: e.clientY,
              originNodeId: nodeId, 
              hoverNodeId: nodeId   
          });
          return next;
      });

      if (hitNode) {
        const topLayer = settings.layerOrder[settings.layerOrder.length - 1];
        if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);
        lastTouchedLimitRef.current = hitNode.maxPrime;

        if (latchMode === 1) {
             setPersistentLatches(prev => {
                 const next = new Map(prev);
                 if (next.has(hitNode.id)) next.delete(hitNode.id);
                 else next.set(hitNode.id, hitNode.id);
                 return next;
             });
        }

        if (settings.isPitchBendEnabled) {
            audioEngine.startVoice(`cursor-${e.pointerId}`, hitNode.ratio, settings.baseFrequency);
            if (settings.midiEnabled) midiService.noteOn(`cursor-${e.pointerId}`, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
        }
        else if (latchMode !== 1) {
            audioEngine.startVoice(`cursor-${e.pointerId}`, hitNode.ratio, settings.baseFrequency);
            if (settings.midiEnabled) midiService.noteOn(`cursor-${e.pointerId}`, hitNode.ratio, settings.baseFrequency, settings.midiPitchBendRange);
        }
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (uiUnlocked) return;
    if (!activeCursorsRef.current.has(e.pointerId)) return;

    cursorPositionsRef.current.set(e.pointerId, { x: e.clientX, y: e.clientY });

    const cursor = activeCursorsRef.current.get(e.pointerId)!;
    const hitNode = getHitNode(e.clientX, e.clientY);
    const hitId = hitNode ? hitNode.id : null;

    // --- 1. PITCH BEND LOGIC ---
    if (cursor.originNodeId && settings.isPitchBendEnabled && scrollContainerRef.current) {
         const centerOffset = dynamicSizeRef.current / 2;
         const rect = scrollContainerRef.current.getBoundingClientRect();
         const originNode = nodeMapRef.current.get(cursor.originNodeId);
         if (originNode) {
             // Use scaled spacing for pitch bend calculation
             const spacing = settings.buttonSpacingScale * globalScaleRef.current;
             const originScreenY = (originNode.y * spacing + centerOffset) + rect.top - scrollContainerRef.current.scrollTop;
             const deltaY = e.clientY - originScreenY;
             // Calculate pitch ratio using SCALED spacing
             const bentRatio = getPitchRatioFromScreenDelta(deltaY, settings.buttonSpacingScale * globalScaleRef.current);
             const finalRatio = originNode.ratio * bentRatio;
             audioEngine.glideVoice(`cursor-${e.pointerId}`, finalRatio, settings.baseFrequency, 0.05);
             if (settings.midiEnabled) midiService.pitchBend(`cursor-${e.pointerId}`, finalRatio, settings.baseFrequency, settings.midiPitchBendRange);
         }
    }

    // --- 2. STRUM / PAINT LOGIC ---
    if (cursor.hoverNodeId !== hitId) {
        if (hitNode) {
             const topLayer = settingsRef.current.layerOrder[settingsRef.current.layerOrder.length - 1];
             if (hitNode.maxPrime !== topLayer) onLimitInteraction(hitNode.maxPrime);
        }

        if (latchMode === 1 && hitId) {
            setPersistentLatches(prev => {
                const next = new Map(prev);
                if (next.has(hitId)) next.delete(hitId);
                else next.set(hitId, hitId);
                return next;
            });
        } 

        setActiveCursors((prev: Map<number, ActiveCursor>) => {
            const next = new Map(prev);
            const c = next.get(e.pointerId);
            if(c) { 
                const updatedCursor = { ...c, hoverNodeId: hitId };
                next.set(e.pointerId, updatedCursor); 
            }
            return next;
        });
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (activeCursorsRef.current.has(e.pointerId)) {
        const cursor = activeCursorsRef.current.get(e.pointerId)!;

        if (cursor.originNodeId && settings.isPitchBendEnabled) {
            audioEngine.stopVoice(`cursor-${e.pointerId}`);
            if (settings.midiEnabled) midiService.noteOff(`cursor-${e.pointerId}`);
        }
        else if (cursor.originNodeId && latchMode !== 1) {
            audioEngine.stopVoice(`cursor-${e.pointerId}`);
            if (settings.midiEnabled) midiService.noteOff(`cursor-${e.pointerId}`);
        }

        cursorPositionsRef.current.delete(e.pointerId);
        setActiveCursors(prev => {
            const next = new Map(prev);
            next.delete(e.pointerId);
            return next;
        });
    }
  };

  // --- Animation Loop ---
  useEffect(() => {
    const bgCanvas = bgLineCanvasRef.current;
    const activeCanvas = dynamicCanvasRef.current;

    if (!bgCanvas || !activeCanvas) return;

    const bgCtx = bgCanvas.getContext('2d', { alpha: true });
    const activeCtx = activeCanvas.getContext('2d', { alpha: true });

    if (!bgCtx || !activeCtx) return;

    const dpr = window.devicePixelRatio || 1;

    const render = (time: number) => {
        const currentSettings = settingsRef.current;
        const currentLatched = effectiveLatchedRef.current;
        const currentActiveLines = activeLinesRef.current;
        const currentBrightenedLines = brightenedLinesRef.current;
        const size = dynamicSizeRef.current;
        const cursors = activeCursorsRef.current;
        const currentGlobalScale = globalScaleRef.current;

        if (bgCanvas.width !== size * dpr || bgCanvas.height !== size * dpr) {
            bgCanvas.width = size * dpr;
            bgCanvas.height = size * dpr;
            activeCanvas.width = size * dpr;
            activeCanvas.height = size * dpr;
            bgCtx.scale(dpr, dpr);
            activeCtx.scale(dpr, dpr);
        }

        let viewX = 0, viewY = 0, viewW = size, viewH = size;
        if (scrollContainerRef.current) {
            viewX = scrollContainerRef.current.scrollLeft;
            viewY = scrollContainerRef.current.scrollTop;
            viewW = scrollContainerRef.current.clientWidth;
            viewH = scrollContainerRef.current.clientHeight;
        }

        bgCtx.clearRect(viewX, viewY, viewW, viewH);
        activeCtx.clearRect(viewX, viewY, viewW, viewH);

        const centerOffset = size / 2;
        // Apply Global Scale to Animation Loop
        const spacing = currentSettings.buttonSpacingScale * currentGlobalScale;
        const baseRadius = (60 * currentSettings.buttonSizeScale * currentGlobalScale) / 2;
        const isDiamond = currentSettings.buttonShape === ButtonShape.DIAMOND;
        const colorCache = currentSettings.colors;

        const animationSpeed = (currentSettings.voiceLeadingAnimationSpeed || 2.0) * 0.33;
        const rawPhase = (time * 0.001 * animationSpeed);
        const flowPhase = currentSettings.voiceLeadingReverseDir ? (1.0 - (rawPhase % 1.0)) : (rawPhase % 1.0);

        bgCtx.lineCap = 'round';
        activeCtx.lineCap = 'round';

        const viewPad = 100;
        const leftBound = viewX - viewPad;
        const rightBound = viewX + viewW + viewPad;
        const topBound = viewY - viewPad;
        const bottomBound = viewY + viewH + viewPad;

        if (currentBrightenedLines.length > 0) {
            bgCtx.setLineDash([]);
            for (const line of currentBrightenedLines) {
                const x1 = line.x1 * spacing + centerOffset;
                const y1 = line.y1 * spacing + centerOffset;
                const x2 = line.x2 * spacing + centerOffset;
                const y2 = line.y2 * spacing + centerOffset;

                if (Math.max(x1, x2) < leftBound || Math.min(x1, x2) > rightBound || Math.max(y1, y2) < topBound || Math.min(y1, y2) > bottomBound) continue;

                const limitColor = colorCache[line.limit] || '#666';

                bgCtx.beginPath();
                bgCtx.moveTo(x1, y1);
                bgCtx.lineTo(x2, y2);
                bgCtx.lineWidth = 2 * currentGlobalScale;
                bgCtx.strokeStyle = limitColor;
                bgCtx.globalAlpha = 0.8; 
                bgCtx.stroke();
            }
        }

        bgCtx.setLineDash([]); 
        for (const line of currentActiveLines) {
            const x1 = line.x1 * spacing + centerOffset;
            const y1 = line.y1 * spacing + centerOffset;
            const x2 = line.x2 * spacing + centerOffset;
            const y2 = line.y2 * spacing + centerOffset;

            if (Math.max(x1, x2) < leftBound || Math.min(x1, x2) > rightBound || Math.max(y1, y2) < topBound || Math.min(y1, y2) > bottomBound) continue;

            const limitColor = colorCache[line.limit] || '#666';

            bgCtx.beginPath();
            bgCtx.moveTo(x1, y1);
            bgCtx.lineTo(x2, y2);
            bgCtx.lineWidth = 4 * currentGlobalScale;
            bgCtx.strokeStyle = limitColor;
            bgCtx.globalAlpha = 1.0;
            bgCtx.stroke();

            if (currentSettings.isVoiceLeadingAnimationEnabled) {
                const grad = bgCtx.createLinearGradient(x1, y1, x2, y2);
                const p = flowPhase;

                grad.addColorStop(0, 'rgba(255,255,255,0)');
                const pulseWidth = 0.2;
                const start = Math.max(0, p - pulseWidth);
                const end = Math.min(1, p + pulseWidth);
                if (start > 0) grad.addColorStop(start, 'rgba(255,255,255,0)');
                grad.addColorStop(p, 'rgba(255,255,255,0.7)'); 
                if (end < 1) grad.addColorStop(end, 'rgba(255,255,255,0)');
                grad.addColorStop(1, 'rgba(255,255,255,0)');

                bgCtx.strokeStyle = grad;
                bgCtx.lineWidth = 10 * (0.5 + currentSettings.voiceLeadingGlowAmount) * currentGlobalScale;
                bgCtx.globalAlpha = 0.3; 
                bgCtx.stroke();

                bgCtx.lineWidth = 4 * currentGlobalScale;
                bgCtx.globalAlpha = 1.0;
                bgCtx.stroke();
            }
        }

        for (const id of currentLatched.keys()) {
             const node = nodeMapRef.current.get(id);
             if (!node) continue;

             const x = node.x * spacing + centerOffset;
             const y = node.y * spacing + centerOffset;

             if (x < leftBound || x > rightBound || y < topBound || y > bottomBound) continue;

             const cTop = colorCache[node.limitTop] || '#666';
             const cBottom = colorCache[node.limitBottom] || '#666';

             const vis = currentSettings.limitVisuals?.[node.limitTop] || { size: 1 };
             const limitScale = vis.size;
             const zoomScale = currentSettings.latchedZoomScale;
             const radius = baseRadius * limitScale * zoomScale;

             activeCtx.globalAlpha = 1.0; 
             activeCtx.beginPath();
             if (isDiamond) {
                activeCtx.moveTo(x, y - radius);
                activeCtx.lineTo(x + radius, y);
                activeCtx.lineTo(x, y + radius);
                activeCtx.lineTo(x - radius, y);
             } else {
                activeCtx.arc(x, y, radius, 0, Math.PI * 2);
             }
             activeCtx.closePath();

             const grad = activeCtx.createLinearGradient(x, y - radius, x, y + radius);
             grad.addColorStop(0.45, cTop);
             grad.addColorStop(0.55, cBottom);
             activeCtx.fillStyle = grad;
             activeCtx.fill();

             if (currentSettings.isColoredIlluminationEnabled) {
                 const rainbowPeriod = getRainbowPeriod(spacing / currentGlobalScale); // Pass base spacing for consistent coloration logic? No, projection relies on visual Y.
                 // Actually ProjectionService uses spacingScale to determine pitch height logic.
                 // Let's just use the current visual Y for rainbow phase.
                 const rp = getRainbowPeriod(currentSettings.buttonSpacingScale * currentGlobalScale);
                 const phase = (y % rp) / rp;
                 const hue = (currentSettings.rainbowOffset + phase * 360) % 360;
                 const sat = currentSettings.isRainbowModeEnabled ? currentSettings.rainbowSaturation : 100;
                 activeCtx.strokeStyle = `hsl(${hue}, ${sat}%, 60%)`;
                 activeCtx.lineWidth = 4 * currentGlobalScale;
             } else {
                 activeCtx.strokeStyle = 'white';
                 activeCtx.lineWidth = 3 * currentGlobalScale;
             }
             activeCtx.stroke();

             const combinedScale = currentSettings.buttonSizeScale * limitScale * zoomScale;
             if (combinedScale > 0.4) {
                activeCtx.fillStyle = 'white';
                activeCtx.textAlign = 'center';
                activeCtx.textBaseline = 'middle';
                let fontSize = Math.max(12, Math.min(22, 16 * combinedScale)) * currentSettings.nodeTextSizeScale * currentGlobalScale;
                activeCtx.font = `bold ${fontSize}px sans-serif`; 
                const spacingY = currentSettings.showFractionBar ? 0.55 : 0.50;
                activeCtx.fillText(node.n.toString(), x, y - (radius * spacingY));
                if (currentSettings.showFractionBar) {
                    activeCtx.beginPath();
                    activeCtx.moveTo(x - (radius * 0.4), y);
                    activeCtx.lineTo(x + (radius * 0.4), y);
                    activeCtx.lineWidth = 1 * currentGlobalScale;
                    activeCtx.strokeStyle = 'white';
                    activeCtx.stroke();
                }
                activeCtx.fillText(node.d.toString(), x, y + (radius * spacingY));
             }
        }

        if (currentSettings.isPitchBendEnabled) {
            cursors.forEach(c => {
                if (c.originNodeId) { 
                    const node = nodeMapRef.current.get(c.originNodeId);
                    if(node) {
                         const nx = node.x * spacing + centerOffset;
                         const ny = node.y * spacing + centerOffset;
                         const pos = cursorPositionsRef.current.get(c.pointerId);
                         if (!pos) return;

                         let cx = 0, cy = 0;
                         if (scrollContainerRef.current) {
                             const r = scrollContainerRef.current.getBoundingClientRect();
                             cx = (pos.x - r.left) + scrollContainerRef.current.scrollLeft;
                             cy = (pos.y - r.top) + scrollContainerRef.current.scrollTop;
                         }

                         activeCtx.beginPath();
                         activeCtx.moveTo(nx, ny);
                         activeCtx.lineTo(cx, cy);
                         activeCtx.strokeStyle = 'white';
                         activeCtx.lineWidth = 2 * currentGlobalScale;
                         activeCtx.globalAlpha = 0.5;
                         activeCtx.stroke();
                    }
                }
            });
        }

        animationFrameRef.current = requestAnimationFrame(render);
    };

    animationFrameRef.current = requestAnimationFrame(render);
    return () => cancelAnimationFrame(animationFrameRef.current);
  }, []); 

  // Use scaled spacing for Rainbow Period
  const rainbowPeriod = getRainbowPeriod(settings.buttonSpacingScale * globalScale);

  const rainbowBackgroundFixed = useMemo(() => {
    if (settings.isRainbowModeEnabled) {
        const stops: string[] = [];
        const steps = 6;
        for (let i = 0; i <= steps; i++) {
            const pct = (i / steps) * 100;
            const hue = (settings.rainbowOffset + i * 60); 
            stops.push(`hsl(${hue}, ${settings.rainbowSaturation}%, ${settings.rainbowBrightness}%) ${pct}%`);
        }
        return `linear-gradient(to bottom, ${stops.join(', ')})`;
    }
    return undefined;
  }, [settings.isRainbowModeEnabled, settings.rainbowOffset, settings.rainbowSaturation, settings.rainbowBrightness]);

  const bgOffsetY = (dynamicSize / 2) - (rainbowPeriod / 3);

  return (
    <div 
        ref={scrollContainerRef}
        className="w-full h-full overflow-auto bg-slate-950 relative"
        style={{ touchAction: 'none' }}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerLeave={handlePointerUp}
        onPointerCancel={handlePointerUp}
    >
        <div 
            className="relative"
            style={{ 
                // Ensure min-width is 100% of viewport to prevent black background on wide screens
                minWidth: '100%',
                minHeight: '100%',
                width: dynamicSize, 
                height: dynamicSize,
                backgroundImage: rainbowBackgroundFixed,
                backgroundSize: `100% ${rainbowPeriod}px`,
                backgroundRepeat: 'repeat',
                backgroundPosition: `0px ${bgOffsetY}px`,
                pointerEvents: uiUnlocked ? 'none' : 'auto',
            }}
        >
           {/* Layer 1: Brightened Lines & Voice Leading Lines */}
           <canvas 
             ref={bgLineCanvasRef}
             className="absolute top-0 left-0 z-[5] pointer-events-none"
             style={{ width: '100%', height: '100%' }}
           />
           {/* Layer 2: Static Lattice (Passive Nodes/Lines) */}
           <canvas 
             ref={staticCanvasRef}
             className="absolute top-0 left-0 z-[10] pointer-events-none"
             style={{ width: '100%', height: '100%' }}
           />
           {/* Layer 3: Dynamic Overlay (Active Nodes & Interaction Lines) */}
           <canvas 
             ref={dynamicCanvasRef}
             className="absolute top-0 left-0 z-[20] pointer-events-none"
             style={{ width: '100%', height: '100%' }}
           />

           {isGenerating && (
             <div className="absolute top-4 right-4 z-50 flex items-center gap-2 bg-slate-900/80 p-2 rounded-full backdrop-blur-sm border border-white/10 shadow-xl">
                 <svg className="animate-spin h-5 w-5 text-blue-500" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                   <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                   <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                 </svg>
                 <span className="text-xs font-bold text-slate-300 pr-2">Calculating...</span>
             </div>
           )}
        </div>
    </div>
  );
});

export default React.memo(TonalityDiamond);

export enum LimitType {
  LIMIT_3 = 3,
  LIMIT_5 = 5,
  LIMIT_7 = 7,
  LIMIT_11 = 11,
  LIMIT_13 = 13,
}

export enum WaveformType {
  SINE = 'sine',
  SQUARE = 'square',
  SAWTOOTH = 'sawtooth',
  TRIANGLE = 'triangle',
}

export enum ButtonShape {
  CIRCLE = '50%',
  DIAMOND = '0%',
}

export interface LimitColorMap {
  [key: number]: string;
}

export interface LimitVisualSetting {
    size: number;   // 0.1 to 2.0 (Multiplier of base size)
    opacity: number; // 0.0 to 1.0
}

export interface LimitVisualsMap {
    [key: number]: LimitVisualSetting;
}

export interface ChordNode {
  id: string; // Coordinate key
  n: number;
  d: number;
}

export interface ChordDefinition {
  id: string; // "A", "B", etc.
  label: string;
  color: string;
  nodes: ChordNode[];
  visible: boolean; // Is shortcut on screen?
  position: { x: number; y: number }; // Relative position or legacy absolute
}

export interface XYPos {
  x: number;
  y: number;
}

export interface AppSettings {
  // Individual depths (Steps from center)
  limitDepths: {
    3: number;
    5: number;
    7: number;
    11: number;
    13: number;
  };

  // Individual complexity limits (Max Numerator/Denominator per axis)
  limitComplexities: {
    3: number;
    5: number;
    7: number;
    11: number;
    13: number;
  };

  // Increase Depth Settings
  showIncreaseDepthButton: boolean;
  centerResetsDepth: boolean;

  // Chords
  savedChords: ChordDefinition[];
  chordShortcutSizeScale: number; // 0.33 to 1.0 relative to main buttons
  chordsAlwaysRelatch: boolean; // If true, activating a chord re-triggers notes even if playing

  // Visible toggle for lower limits (View only)
  hiddenLimits: number[]; 

  layerOrder: number[]; // Array of limit numbers, index 0 = back, last index = front

  // Audio Settings
  baseFrequency: number; // Hz for 1/1

  // Voice Leading / Focus Mode
  isVoiceLeadingEnabled: boolean;
  voiceLeadingStrength: number; // 0 to 1, higher means stricter falloff

  // Voice Leading Visuals
  isVoiceLeadingAnimationEnabled: boolean;
  voiceLeadingAnimationSpeed: number; // seconds
  voiceLeadingReverseDir: boolean; // Reverse the direction of the flow animation
  voiceLeadingGlowAmount: number; // 0.0 to 1.0 (Controls width/intensity of the lobe)
  voiceLeadingSteps: number; // 1 or 2 (Reach for active voice leading lines)

  // Line Brightening
  lineBrighteningEnabled: boolean;
  lineBrighteningSteps: number; // 1 or 2

  // Momentum is deprecated/greyed out in favor of Latch Mode
  isMomentumEnabled: boolean; 

  // Latch Settings
  latchedZoomScale: number; // Scale factor for active nodes (1.0 to 2.0)

  // Appearance
  buttonSizeScale: number; // Global Scalar 0.5 to 2.0
  buttonSpacingScale: number; // 0.5 to 5.0
  latticeAspectRatio: number; // 0.5 (Stretched X) to 2.0 (Squished X)
  canvasSize: number; // Width/Height of the scrollable area in pixels (e.g. 3000, 5000)
  buttonShape: ButtonShape;
  colors: LimitColorMap;

  // Per-Limit Visuals (Size/Opacity)
  limitVisuals: LimitVisualsMap;

  // Text Appearance
  nodeTextSizeScale: number; // 0.5 to 2.0
  showFractionBar: boolean;

  isPitchBendEnabled: boolean;
  isPitchSnapEnabled: boolean;
  polyphony: number;
  pitchOffLocked: boolean;
  volumeLocked: boolean;

  // Visuals - Rainbow
  isRainbowModeEnabled: boolean;
  rainbowSaturation: number; // 0-100
  rainbowBrightness: number; // 0-100
  rainbowOffset: number; // 0-360 (Hue shift)
  isColoredIlluminationEnabled: boolean;

  // MIDI Settings
  midiEnabled: boolean;
  midiOutputId: string | null;
  midiPitchBendRange: number; // Semitones (typically 2, 12, 24, or 48)

  // UI Relocation & Scaling
  uiUnlocked: boolean;
  uiScale: number; // 0.5 (Tiny) to 1.5 (Huge)
  uiEdgeMargin: number; // in Millimeters (1-10)
  uiPositions: {
    volume: XYPos;
    space: XYPos;
    panic: XYPos;
    off: XYPos;
    latch: XYPos;
    bend: XYPos;
    center: XYPos;
    depth: XYPos;
    decreaseDepth: XYPos;
    chords: XYPos;
    layers: XYPos;
  };
}

export interface OscillatorConfig {
  enabled: boolean;
  waveform: WaveformType;
  coarseDetune: number; // Cents -1200 to 1200
  fineDetune: number; // Cents -50 to 50
  gain: number; // 0 to 1 (Mix)

  // Envelope
  attack: number;
  decay: number;
  sustain: number;
  release: number;

  // Filter
  filterCutoff: number; // Hz
  filterResonance: number; // Q factor

  // LFO
  lfoRate: number; // Hz
  lfoDepth: number; // Amount 0-100
  lfoTarget: 'none' | 'pitch' | 'filter' | 'tremolo';
}

export type ModSource = 'lfo1' | 'lfo2' | 'lfo3' | 'env1' | 'env2' | 'env3';
export type ModTarget = 
    'osc1_pitch' | 'osc1_gain' | 'osc1_cutoff' | 'osc1_res' |
    'osc2_pitch' | 'osc2_gain' | 'osc2_cutoff' | 'osc2_res' |
    'osc3_pitch' | 'osc3_gain' | 'osc3_cutoff' | 'osc3_res';

export interface ModulationRow {
    id: string;
    enabled: boolean;
    source: ModSource;
    target: ModTarget;
    amount: number; // -100 to 100
}

export type ReverbType = 'room' | 'hall' | 'cathedral' | 'plate' | 'shimmer';

export interface SynthPreset {
  id: number | string;
  name: string;

  osc1: OscillatorConfig;
  osc2: OscillatorConfig;
  osc3: OscillatorConfig;

  // Modulation Matrix
  modMatrix: ModulationRow[];

  // Master Gain for the preset
  gain: number; 

  // Stereo & Pan
  spread?: number; // 0 to 1 (Voice Stereo Width)
  stereoPanSpeed?: number; // Hz
  stereoPanDepth?: number; // 0 to 1 (Auto-Pan amount)

  // Reverb Unit
  reverbType?: ReverbType; // Convolution Preset (Logic base)
  reverbMix: number; // 0 to 1
  reverbSize: number; // Duration in seconds (0.1 to 10.0)
  reverbDamping: number; // 0 (Bright) to 1 (Dark)
  reverbDiffusion?: number; // 0 (Grainy) to 1 (Smooth)

  // Delay Unit
  delayMix: number; // 0 to 1
  delayTime: number; // Seconds
  delayFeedback: number; // 0 to 0.95

  // Dynamics (Compressor/Limiter) (Global)
  compressorThreshold: number; // dB (-60 to 0)
  compressorRatio: number; // 1 to 20
  compressorRelease: number; // seconds
}

// Slot Types
export type PlayMode = 'normal' | 'latch' | 'strum';

export interface PresetState {
    normal: SynthPreset;
    latch: SynthPreset;
    strum: SynthPreset;
}

export interface LatticeNode {
  id: string; // Coordinate key "0,0,0,0,0:oct"
  ratio: number; // Absolute Frequency multiplier (including octave)
  n: number; // Numerator (adjusted for octave)
  d: number; // Denominator (adjusted for octave)
  label: string; 
  x: number; // Screen X
  y: number; // Screen Y
  limitTop: number; 
  limitBottom: number;
  maxPrime: number; // For Z-sorting
  coords: number[]; // [p3, p5, p7, p11, p13]
  octave: number; // -2, -1, 0, 1, 2
}

export interface LatticeLine {
  id: string;
  x1: number;
  y1: number;
  x2: number;
  y2: number;
  limit: number;
  sourceId: string;
  targetId: string;
}

export interface ActiveVoice {
  id: string; // Pointer ID or Node ID
  nodeId?: string;
  stop: () => void;
  setDetune: (cents: number) => void;
}

export interface GenerationOrigin {
  coords: number[];
  octave: number;
}

import { useSyncExternalStore } from 'react';
import { AppSettings, SynthPreset, PresetState, PlayMode } from '../types';
import { DEFAULT_SETTINGS, DEFAULT_PRESET } from '../constants';

interface StoreState {
    settings: AppSettings;
    presets: PresetState;
}

const SETTINGS_KEY = 'prismatonal_settings_v5'; 
const PRESET_KEY = 'prismatonal_presets_v5';

class PrismaStore {
  private state: StoreState;
  private listeners: Set<() => void> = new Set();

  constructor() {
    // Load Settings
    const savedSettings = localStorage.getItem(SETTINGS_KEY);
    const loadedSettings = savedSettings ? { ...DEFAULT_SETTINGS, ...JSON.parse(savedSettings) } : DEFAULT_SETTINGS;

    loadedSettings.uiPositions = { ...DEFAULT_SETTINGS.uiPositions, ...(loadedSettings.uiPositions || {}) };

    // Load Presets
    const savedPresets = localStorage.getItem(PRESET_KEY);
    let loadedPresets: PresetState;

    if (savedPresets) {
        loadedPresets = JSON.parse(savedPresets);
    } else {
        // Default all to DEFAULT_PRESET (Noise Wash)
        loadedPresets = {
            normal: JSON.parse(JSON.stringify(DEFAULT_PRESET)),
            latch: JSON.parse(JSON.stringify(DEFAULT_PRESET)),
            strum: JSON.parse(JSON.stringify(DEFAULT_PRESET))
        };
    }

    this.state = {
        settings: loadedSettings,
        presets: loadedPresets
    };
  }

  // --- ACTIONS ---

  updateSettings = (partial: Partial<AppSettings> | ((prev: AppSettings) => AppSettings)) => {
    const current = this.state.settings;
    let next: AppSettings;

    if (typeof partial === 'function') {
      next = partial(current);
    } else {
      next = { ...current, ...partial };
    }

    if (next === current) return;

    this.state = { ...this.state, settings: next };
    localStorage.setItem(SETTINGS_KEY, JSON.stringify(next));
    this.notify();
  };

  setPreset = (mode: PlayMode, newPreset: SynthPreset) => {
    const current = this.state.presets[mode];
    if (newPreset === current) return;

    const nextPresets = { ...this.state.presets, [mode]: newPreset };
    this.state = { ...this.state, presets: nextPresets };

    localStorage.setItem(PRESET_KEY, JSON.stringify(nextPresets));
    this.notify();
  };

  // --- SUBSCRIPTION ---
  subscribe = (listener: () => void) => {
    this.listeners.add(listener);
    return () => this.listeners.delete(listener);
  };

  getSnapshot = () => {
    return this.state;
  };

  private notify() {
    this.listeners.forEach(l => l());
  }
}

export const store = new PrismaStore();

// --- REACT HOOK ---
export function useStore() {
  const state = useSyncExternalStore(store.subscribe, store.getSnapshot);

  return {
    settings: state.settings,
    presets: state.presets, // Now returns the full object of 3
    updateSettings: store.updateSettings,
    setPreset: store.setPreset
  };
}

export const AUDIO_PROCESSOR_CODE = `
// --- DSP UTILS ---
const TWO_PI = 2 * Math.PI;

const DUMMY_OSC_CONFIG = {
    enabled: false,
    waveform: 'sine',
    coarseDetune: 0,
    fineDetune: 0,
    gain: 0,
    attack: 0.1,
    decay: 0.1,
    sustain: 0,
    release: 0.1,
    filterCutoff: 20000,
    filterResonance: 0,
    lfoRate: 1,
    lfoDepth: 0,
    lfoTarget: 'none'
};

const DUMMY_PRESET_DATA = {
    osc1: DUMMY_OSC_CONFIG,
    osc2: DUMMY_OSC_CONFIG,
    osc3: DUMMY_OSC_CONFIG,
    modMatrix: [],
    gain: 1.0,
    spread: 0,
    stereoPanSpeed: 0,
    stereoPanDepth: 0
};

class PolyBLEP {
  constructor(sampleRate) {
    this.sampleRate = sampleRate;
  }

  get(t, dt) {
    if (dt < 1e-9) return 0.0;
    if (t < dt) {
      t /= dt;
      return t + t - t * t - 1.0;
    } else if (t > 1.0 - dt) {
      t = (t - 1.0) / dt;
      return t * t + t + t + 1.0;
    }
    return 0.0;
  }
}

class SVF {
  constructor() {
    this.low = 0.0;
    this.band = 0.0;
    this.high = 0.0;
    this.notch = 0.0;
  }

  reset() {
    this.low = 0.0;
    this.band = 0.0;
    this.high = 0.0;
    this.notch = 0.0;
  }

  process(input, cutoff, res, sampleRate) {
    const safeCutoff = Math.max(20, Math.min(cutoff, sampleRate * 0.42));
    let f = 2.0 * Math.sin(Math.PI * safeCutoff / sampleRate);
    const q = 1.0 / (res + 0.5);

    this.low += f * this.band;
    this.high = input - this.low - q * this.band;
    this.band += f * this.high;
    this.notch = this.high + this.low;

    return this.low; 
  }
}

class Envelope {
  constructor() {
    this.stage = 'idle'; 
    this.value = 0.0;
    this.velocity = 0.0;
  }

  trigger(velocity = 1.0) {
    this.stage = 'attack';
    this.velocity = velocity;
  }

  release() {
    if (this.stage !== 'idle') {
        this.stage = 'release';
    }
  }

  reset() {
      this.stage = 'idle';
      this.value = 0.0;
  }

  process(config, dt) {
    const att = (config.attack !== undefined) ? config.attack : 0.01;
    const dec = (config.decay !== undefined) ? config.decay : 0.1;
    const sus = (config.sustain !== undefined) ? config.sustain : 1.0;
    const rel = (config.release !== undefined) ? config.release : 0.1;

    switch (this.stage) {
      case 'idle':
        this.value = 0.0;
        return 0.0;

      case 'attack':
        const attRate = 1.0 / (Math.max(0.001, att));
        this.value += attRate * dt;
        if (this.value >= 1.0) {
          this.value = 1.0;
          this.stage = 'decay';
        }
        return this.value * this.velocity;

      case 'decay':
        const decRate = 1.0 / (Math.max(0.001, dec));
        this.value += (sus - this.value) * (decRate * dt * 5.0); 
        return this.value * this.velocity;

      case 'sustain':
        this.value = sus;
        return this.value * this.velocity;

      case 'release':
        const relRate = 1.0 / (Math.max(0.001, rel));
        this.value -= this.value * (relRate * dt * 5.0);
        if (this.value < 0.001) {
          this.value = 0.0;
          this.stage = 'idle';
        }
        return this.value * this.velocity;

      default:
        return 0.0;
    }
  }
}

class Oscillator {
  constructor(sampleRate) {
    this.phase = 0.0; 
    this.blep = new PolyBLEP(sampleRate);
    this.sampleRate = sampleRate;
  }

  reset() {
      this.phase = 0.0;
  }

  process(freq, type, dt) {
    if (!Number.isFinite(freq) || freq <= 0 || freq > 24000) return 0.0;

    this.phase += dt * freq;
    while (this.phase >= 1.0) this.phase -= 1.0;

    let sample = 0.0;

    switch (type) {
      case 'sine':
        sample = Math.sin(TWO_PI * this.phase);
        break;
      case 'triangle':
        let t = -1.0 + (2.0 * this.phase);
        sample = 2.0 * (Math.abs(t) - 0.5);
        break;
      case 'sawtooth':
        sample = (2.0 * this.phase) - 1.0;
        sample -= this.blep.get(this.phase, dt * freq);
        break;
      case 'square':
        sample = this.phase < 0.5 ? 1.0 : -1.0;
        sample += this.blep.get(this.phase, dt * freq);
        let phase2 = (this.phase + 0.5) % 1.0;
        sample -= this.blep.get(phase2, dt * freq);
        break;
    }

    return sample;
  }
}

class Voice {
  constructor(sampleRate) {
    this.sampleRate = sampleRate;
    this.active = false;
    this.id = '';
    this.type = 'normal'; // 'normal', 'latch', 'strum'
    this.panPos = 0; 

    this.baseFreq = 440;
    this.targetFreq = 440;
    this.startTime = 0; 
    this.releaseTime = 0; 

    this.oscs = [
        new Oscillator(sampleRate),
        new Oscillator(sampleRate),
        new Oscillator(sampleRate)
    ];

    this.filters = [ new SVF(), new SVF(), new SVF() ];
    this.envs = [ new Envelope(), new Envelope(), new Envelope() ];
    this.lfoPhases = [0.0, 0.0, 0.0];
    this.envVals = new Float32Array(3);
    this.lfoVals = new Float32Array(3);
  }

  trigger(id, freq, type) {
    this.id = id;
    this.type = type || 'normal';
    this.baseFreq = freq;
    this.targetFreq = freq;
    this.active = true;
    this.startTime = currentTime; 
    this.releaseTime = 0; 

    this.oscs.forEach(osc => osc.reset());

    this.envs.forEach(env => {
        env.reset();
        env.trigger();
    });

    this.filters.forEach(f => f.reset());
    this.lfoPhases.fill(0.0);
  }

  release() {
    this.releaseTime = currentTime;
    this.envs.forEach(env => env.release());
  }

  hardStop() {
      this.active = false;
      this.envs.forEach(env => env.reset());
      this.filters.forEach(f => f.reset());
  }

  getLevel() {
    return Math.max(this.envs[0].value, this.envs[1].value, this.envs[2].value);
  }

  process(presetData, dt) {
    if (!this.active || !presetData) return 0.0;

    // Smooth Pitch Glide
    const diff = this.targetFreq - this.baseFreq;
    if (Math.abs(diff) > 0.001) {
      this.baseFreq += diff * 0.005; 
    } else {
      this.baseFreq = this.targetFreq;
    }

    const oscConfigs = [
        presetData.osc1 || DUMMY_OSC_CONFIG,
        presetData.osc2 || DUMMY_OSC_CONFIG,
        presetData.osc3 || DUMMY_OSC_CONFIG
    ];
    const matrix = presetData.modMatrix || [];

    let anyEnvActive = false;

    // 1. Compute Sources
    for (let i = 0; i < 3; i++) {
        const config = oscConfigs[i];
        const envVal = this.envs[i].process(config, dt);
        this.envVals[i] = envVal;
        if (this.envs[i].stage !== 'idle') anyEnvActive = true;

        const rate = (config.lfoRate !== undefined) ? config.lfoRate : 0.0;
        this.lfoPhases[i] += rate * dt;
        if (this.lfoPhases[i] >= 1.0) this.lfoPhases[i] -= 1.0;
        this.lfoVals[i] = Math.sin(TWO_PI * this.lfoPhases[i]);
    }

    if (!anyEnvActive) {
      this.active = false;
      return 0.0;
    }

    let modP1=0, modP2=0, modP3=0;
    let modC1=0, modC2=0, modC3=0;
    let modG1=0, modG2=0, modG3=0;
    let modR1=0, modR2=0, modR3=0;

    const mLen = matrix.length;
    for(let i=0; i<mLen; i++) {
        const row = matrix[i];
        if (!row.enabled) continue;

        let srcVal = 0;
        switch(row.source) {
            case 'lfo1': srcVal = this.lfoVals[0]; break;
            case 'lfo2': srcVal = this.lfoVals[1]; break;
            case 'lfo3': srcVal = this.lfoVals[2]; break;
            case 'env1': srcVal = this.envVals[0]; break;
            case 'env2': srcVal = this.envVals[1]; break;
            case 'env3': srcVal = this.envVals[2]; break;
        }

        const amt = srcVal * (Number.isFinite(row.amount) ? row.amount : 0);

        switch(row.target) {
            case 'osc1_pitch': modP1 += amt; break;
            case 'osc1_cutoff': modC1 += amt; break;
            case 'osc1_gain': modG1 += amt; break;
            case 'osc1_res': modR1 += amt; break;
            case 'osc2_pitch': modP2 += amt; break;
            case 'osc2_cutoff': modC2 += amt; break;
            case 'osc2_gain': modG2 += amt; break;
            case 'osc2_res': modR2 += amt; break;
            case 'osc3_pitch': modP3 += amt; break;
            case 'osc3_cutoff': modC3 += amt; break;
            case 'osc3_gain': modG3 += amt; break;
            case 'osc3_res': modR3 += amt; break;
        }
    }

    let voiceMix = 0.0;

    for (let i = 0; i < 3; i++) {
        const config = oscConfigs[i];
        if (!config.enabled) continue;

        const envVal = this.envVals[i];
        if (envVal < 0.0001) continue;

        let lfoVal = this.lfoVals[i];
        const lfoDepth = config.lfoDepth || 0;
        let hardPitch = 0, hardFilter = 0, hardAmp = 1.0;

        if (config.lfoTarget === 'pitch') hardPitch = lfoVal * lfoDepth;
        else if (config.lfoTarget === 'filter') hardFilter = lfoVal * lfoDepth * 20;
        else if (config.lfoTarget === 'tremolo') hardAmp = 1.0 - (lfoVal * (lfoDepth * 0.005));

        let modPitch=0, modCutoff=0, modGain=0, modRes=0;
        if (i===0) { modPitch=modP1; modCutoff=modC1; modGain=modG1; modRes=modR1; }
        else if (i===1) { modPitch=modP2; modCutoff=modC2; modGain=modG2; modRes=modR2; }
        else { modPitch=modP3; modCutoff=modC3; modGain=modG3; modRes=modR3; }

        const cents = config.coarseDetune + config.fineDetune + hardPitch + (modPitch * 1200);
        const detuneMult = Math.pow(2, cents / 1200.0);
        const oscFreq = this.baseFreq * detuneMult;

        let signal = this.oscs[i].process(oscFreq, config.waveform, dt);

        let cutoff = config.filterCutoff + hardFilter + (modCutoff * 5000);
        let res = config.filterResonance + (modRes * 10);
        if (res < 0) res = 0;

        signal = this.filters[i].process(signal, cutoff, res, this.sampleRate);

        const gainMod = Math.max(0, 1.0 + modGain); 
        const finalGain = config.gain * envVal * hardAmp * gainMod;

        voiceMix += signal * finalGain;
    }

    return voiceMix;
  }
}

class PrismaProcessor extends AudioWorkletProcessor {
  constructor() {
    super();
    this.voices = [];
    for(let i=0; i<32; i++) {
        const v = new Voice(sampleRate);
        // Deterministic spread -1 to 1 based on voice index
        v.panPos = Math.sin(i * 123.456); 
        this.voices.push(v);
    }

    // Store 3 separate presets
    this.presets = {
        normal: DUMMY_PRESET_DATA,
        latch: DUMMY_PRESET_DATA,
        strum: DUMMY_PRESET_DATA
    };

    this.maxPolyphony = 10; 

    // DC Blocker State (Stereo)
    this.xm1L = 0; this.ym1L = 0;
    this.xm1R = 0; this.ym1R = 0;

    // Auto-Pan State
    this.panPhase = 0;

    this.port.onmessage = (e) => {
      const msg = e.data;
      if (msg.type === 'update_preset') {
        const { mode, data } = msg;
        if (mode && this.presets[mode]) {
            this.presets[mode] = this.normalizePreset(data);
        }
      } else if (msg.type === 'config') {
         if (msg.polyphony) this.maxPolyphony = msg.polyphony;
      } else if (msg.type === 'note_on') {
        this.triggerVoice(msg.id, msg.freq, msg.voiceType);
      } else if (msg.type === 'note_off') {
        this.releaseVoice(msg.id);
      } else if (msg.type === 'glide') {
        this.glideVoice(msg.id, msg.freq);
      } else if (msg.type === 'stop_all') {
         this.voices.forEach(v => v.hardStop());
      }
    };
  }

  normalizePreset(data) {
      return {
          osc1: { ...DUMMY_OSC_CONFIG, ...(data.osc1 || {}) },
          osc2: { ...DUMMY_OSC_CONFIG, ...(data.osc2 || {}) },
          osc3: { ...DUMMY_OSC_CONFIG, ...(data.osc3 || {}) },
          modMatrix: (data.modMatrix || []).map(row => ({
              ...row,
              amount: (Number.isFinite(row.amount) ? row.amount : 0) / 100.0
          })),
          gain: data.gain || 0.5,
          spread: data.spread || 0,
          stereoPanSpeed: data.stereoPanSpeed || 0,
          stereoPanDepth: data.stereoPanDepth || 0
      };
  }

  triggerVoice(id, freq, type) {
    for (let i = 0; i < this.voices.length; i++) {
        if (this.voices[i].active && this.voices[i].id === id) {
            this.voices[i].trigger(id, freq, type);
            return;
        }
    }
    let heldCount = 0;
    let physicallyFree = null;
    let quietestHeld = null;
    let minHeldLevel = 1000.0;
    let quietestVoice = null;
    let minLevel = 1000.0;

    for (let i = 0; i < this.voices.length; i++) {
        const v = this.voices[i];
        if (!v.active) {
            if (!physicallyFree) physicallyFree = v;
            continue;
        }
        const level = v.getLevel();
        if (level < minLevel) {
            minLevel = level;
            quietestVoice = v;
        }
        if (v.releaseTime === 0) {
            heldCount++;
            if (level < minHeldLevel) {
                minHeldLevel = level;
                quietestHeld = v;
            }
        }
    }

    if (heldCount >= this.maxPolyphony && quietestHeld) {
        quietestHeld.release();
    }

    if (physicallyFree) {
        physicallyFree.trigger(id, freq, type);
    } else if (quietestVoice) {
        quietestVoice.trigger(id, freq, type);
    }
  }

  releaseVoice(id) {
    for (let i = 0; i < this.voices.length; i++) {
        if (this.voices[i].active && this.voices[i].id === id) {
            this.voices[i].release();
        }
    }
  }

  glideVoice(id, freq) {
    for (let i = 0; i < this.voices.length; i++) {
        if (this.voices[i].active && this.voices[i].id === id) {
             // Only apply glide if this voice allows bending
             if (this.voices[i].type !== 'strum') {
                 this.voices[i].targetFreq = freq;
             }
        }
    }
  }

  process(inputs, outputs, parameters) {
    const output = outputs[0];
    const channelL = output[0];
    const channelR = output[1];
    if (!channelL) return true;
    const len = channelL.length;
    const dt = 1.0 / sampleRate;

    // We use the settings from 'normal' preset as the Global Master FX controller for simplicity,
    // or we could average them. Let's use 'normal' for global pan/spread timing.
    const masterPreset = this.presets.normal;
    const panSpeed = (masterPreset.stereoPanSpeed !== undefined) ? masterPreset.stereoPanSpeed : 0.0;
    const panDepth = (masterPreset.stereoPanDepth !== undefined) ? masterPreset.stereoPanDepth : 0.0;

    for (let s = 0; s < len; s++) {
        let mixL = 0.0;
        let mixR = 0.0;

        // Auto-Pan LFO
        this.panPhase += dt * panSpeed;
        if(this.panPhase > 1.0) this.panPhase -= 1.0;
        const autoPanVal = Math.sin(this.panPhase * TWO_PI) * panDepth;

        for (let i = 0; i < this.voices.length; i++) {
            const v = this.voices[i];
            if (v.active) {
                // Pick the correct preset based on voice type
                const presetToUse = this.presets[v.type] || this.presets.normal;

                const val = v.process(presetToUse, dt);

                if (Number.isFinite(val)) {
                    // Spread + AutoPan Logic
                    const spreadAmount = presetToUse.spread || 0;
                    let p = v.panPos * spreadAmount;
                    p += autoPanVal;
                    p = Math.max(-1.0, Math.min(1.0, p));

                    const gainL = 0.5 * (1.0 - p);
                    const gainR = 0.5 * (1.0 + p);

                    // Apply per-preset master gain here
                    const voiceGain = presetToUse.gain || 0.5;

                    mixL += val * gainL * voiceGain;
                    mixR += val * gainR * voiceGain;
                } else {
                    v.hardStop();
                }
            }
        }

        // --- GAIN STAGE (PRE-FX) ---
        mixL *= 0.1;
        mixR *= 0.1;

        // --- SOFT CLIPPER (Stereo) ---
        mixL = Math.tanh(mixL * 0.7);
        mixR = Math.tanh(mixR * 0.7);

        // --- DC BLOCKER (Stereo) ---
        // Left
        const yL = mixL - this.xm1L + 0.995 * this.ym1L;
        this.xm1L = mixL;
        this.ym1L = yL;

        // Right
        const yR = mixR - this.xm1R + 0.995 * this.ym1R;
        this.xm1R = mixR;
        this.ym1R = yR;

        channelL[s] = yL;
        if (channelR) channelR[s] = yR;
    }

    return true;
  }
}

