import { createHostAdapter, IHostAdapter, MidiDevice, TransportCallback } from './HostAdapter';

// Re-export for consumers (SettingsModal, etc.)
export type { MidiDevice };

class MidiService {
    private adapter: IHostAdapter | null = null;
    private initialized = false;

    // Channel Management for Polyphonic Pitch Bend (MPE-style)
    private activeNotes: Map<string, { channel: number, note: number }> = new Map(); 
    private nextChannel = 0; // 0-15 (corresponding to Ch 1-16)

    constructor() {}

    public async init(): Promise<boolean> {
        if (this.initialized) return true;

        this.adapter = await createHostAdapter();

        if (this.adapter) {
            console.log(`Initializing MIDI: ${this.adapter.type.toUpperCase()} Backend Detected`);
            this.initialized = true;
            return true;
        } else {
            console.warn("MIDI not supported in this environment");
            return false;
        }
    }

    public async getOutputs(): Promise<MidiDevice[]> {
        if (!this.adapter) return [];
        return this.adapter.getOutputs();
    }

    public setOutput(id: string | null) {
        if (this.adapter) {
            this.adapter.setOutput(id);
        }
    }

    public setTransportCallback(cb: TransportCallback) {
        if (this.adapter) {
            this.adapter.setTransportCallback(cb);
        }
    }

    // --- MIDI MESSAGES ---

    private sendBytes(bytes: number[]) {
        if (this.adapter) {
            this.adapter.sendMidi(bytes);
        }
    }

    public noteOn(id: string, ratio: number, baseFreq: number, bendRange: number) {
        const freq = baseFreq * ratio;
        const midiFloat = 69 + 12 * Math.log2(freq / 440);
        const noteNumber = Math.round(midiFloat);
        const bendSemitones = midiFloat - noteNumber;

        const normalizedBend = bendSemitones / bendRange; 
        const bendValue = Math.min(16383, Math.max(0, Math.round(8192 + (normalizedBend * 8192))));

        // Channel Rotation for MPE
        let channel = this.nextChannel;
        this.nextChannel = (this.nextChannel + 1) % 16; 

        this.activeNotes.set(id, { channel, note: noteNumber });

        // Pitch Bend LSB/MSB
        const lsb = bendValue & 0x7F;
        const msb = (bendValue >> 7) & 0x7F;

        // Send Pitch Bend (0xE0)
        this.sendBytes([0xE0 | channel, lsb, msb]);

        // Send Note On (0x90)
        this.sendBytes([0x90 | channel, noteNumber, 100]);
    }

    public noteOff(id: string) {
        const data = this.activeNotes.get(id);
        if (!data) return;

        // Note Off (0x80)
        this.sendBytes([0x80 | data.channel, data.note, 0]);
        this.activeNotes.delete(id);
    }

    public pitchBend(id: string, ratio: number, baseFreq: number, bendRange: number) {
        const data = this.activeNotes.get(id);
        if (!data) return;

        // Re-calc logic
        const freq = baseFreq * ratio;
        const exactMidi = 69 + 12 * Math.log2(freq / 440);

        const diffSemitones = exactMidi - data.note;

        const normalizedBend = diffSemitones / bendRange;
        const bendValue = Math.min(16383, Math.max(0, Math.round(8192 + (normalizedBend * 8192))));

        const lsb = bendValue & 0x7F;
        const msb = (bendValue >> 7) & 0x7F;

        this.sendBytes([0xE0 | data.channel, lsb, msb]);
    }

    // Standard MIDI Panic: Sends All Notes Off (CC 123) and All Sound Off (CC 120) to all channels
    public panic() {
        this.activeNotes.clear();
        if (!this.adapter) return;

        for (let ch = 0; ch < 16; ch++) {
            // CC 123: All Notes Off
            this.sendBytes([0xB0 | ch, 123, 0]);
            // CC 120: All Sound Off (Immediate mute)
            this.sendBytes([0xB0 | ch, 120, 0]);
            // Reset Pitch Bend
            this.sendBytes([0xE0 | ch, 0, 64]);
        }
    }
}

export const midiService = new MidiService();

import { SynthPreset, AppSettings, ReverbType, PresetState, PlayMode } from '../types';
import { store } from './Store';
import { DEFAULT_PRESET, REVERB_DEFAULTS } from '../constants';
import { AUDIO_PROCESSOR_CODE } from './AudioProcessorCode';

class AudioEngine {
  private ctx: AudioContext | null = null;
  private workletNode: AudioWorkletNode | null = null;
  private initPromise: Promise<void> | null = null;

  // FX Chain
  private limiter: DynamicsCompressorNode | null = null;
  private dryGain: GainNode | null = null;
  private reverbNode: ConvolverNode | null = null;
  private reverbGain: GainNode | null = null;
  private delayNode: DelayNode | null = null;
  private delayFeedbackGain: GainNode | null = null;
  private delayOutputGain: GainNode | null = null;

  private currentMasterVol: number = 0.8;
  private globalSpatialScale: number = 1.0;

  // Cache active presets for FX updates
  private activePresets: PresetState;

  constructor() {
    // Initialize Presets safely
    const rawPresets = store.getSnapshot().presets;
    this.activePresets = {
        normal: this.ensurePresetSafety(rawPresets.normal),
        latch: this.ensurePresetSafety(rawPresets.latch),
        strum: this.ensurePresetSafety(rawPresets.strum)
    };

    store.subscribe(() => {
        const newPresets = store.getSnapshot().presets;
        this.updatePresets(newPresets);
    });
  }

  private isMobile() {
      return /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);
  }

  private ensurePresetSafety(p: any): SynthPreset {
     if (!p) return DEFAULT_PRESET;
     const safe = { ...DEFAULT_PRESET, ...p };
     safe.osc1 = { ...DEFAULT_PRESET.osc1, ...(p.osc1 || {}) };
     safe.osc2 = { ...DEFAULT_PRESET.osc2, ...(p.osc2 || {}) };
     safe.osc3 = { ...DEFAULT_PRESET.osc3, ...(p.osc3 || {}) };
     safe.modMatrix = p.modMatrix || [];
     safe.reverbType = p.reverbType || 'hall'; 
     if (safe.reverbSize === undefined) safe.reverbSize = REVERB_DEFAULTS[safe.reverbType || 'hall'].size;
     if (safe.reverbDamping === undefined) safe.reverbDamping = REVERB_DEFAULTS[safe.reverbType || 'hall'].damping;
     if (safe.reverbDiffusion === undefined) safe.reverbDiffusion = REVERB_DEFAULTS[safe.reverbType || 'hall'].diffusion;
     return safe;
  }

  private updatePresets(newPresets: PresetState) {
      const modes: PlayMode[] = ['normal', 'latch', 'strum'];
      let recomputeReverb = false;

      // We use 'normal' preset as the master for Global FX settings like Reverb Type/Size
      // to avoid conflict.
      const oldMaster = this.activePresets.normal;
      const newMaster = newPresets.normal;

      if (
          oldMaster.reverbType !== newMaster.reverbType ||
          oldMaster.reverbSize !== newMaster.reverbSize ||
          oldMaster.reverbDamping !== newMaster.reverbDamping ||
          oldMaster.reverbDiffusion !== newMaster.reverbDiffusion
      ) {
          recomputeReverb = true;
      }

      this.activePresets = {
          normal: this.ensurePresetSafety(newPresets.normal),
          latch: this.ensurePresetSafety(newPresets.latch),
          strum: this.ensurePresetSafety(newPresets.strum)
      };

      if (recomputeReverb && this.ctx) {
          this.updateReverbBuffer();
      }
      this.updateFX();

      if (this.workletNode) {
          modes.forEach(mode => {
              this.workletNode!.port.postMessage({ 
                  type: 'update_preset', 
                  mode: mode, 
                  data: this.activePresets[mode] 
              });
          });
      }
  }

  // Synchronous check and resume - Vital for iOS Chrome
  public async resume() {
      // CRITICAL: On iOS Chrome, if context doesn't exist yet, we must create it synchronously here
      if (!this.ctx) {
          // Trigger init immediately
          await this.init(); 
      }

      if (this.ctx && this.ctx.state === 'suspended') {
          await this.ctx.resume();
      }
  }

  public async init() {
    if (this.initPromise) return this.initPromise;

    this.initPromise = (async () => {
        if (!this.ctx) {
            const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;

            // Get user preference from store
            const settings = store.getSnapshot().settings;
            // Force 'playback' if user hasn't touched it (which default is 'playback')
            // This is critical for iPad 7/Mobile static fix.
            const latencyHint = settings.audioLatencyHint || 'playback';

            this.ctx = new AudioContextClass({
                latencyHint: latencyHint,
            });

            // Robustness: Auto-resume on state change (Desktop disconnect/reconnect logic)
            this.ctx.onstatechange = () => {
                if (this.ctx && this.ctx.state === 'suspended') {
                    // Attempt to resume immediately if user is active
                    this.ctx.resume().catch(e => console.warn("Audio auto-resume failed:", e));
                }
            };

            try {
                const blob = new Blob([AUDIO_PROCESSOR_CODE], { type: 'application/javascript' });
                const workletUrl = URL.createObjectURL(blob);

                // Polyfill check or standard addModule
                if (this.ctx.audioWorklet && this.ctx.audioWorklet.addModule) {
                    await this.ctx.audioWorklet.addModule(workletUrl);
                } else {
                    console.error("AudioWorklet not supported");
                    return;
                }

                URL.revokeObjectURL(workletUrl);

                this.workletNode = new AudioWorkletNode(this.ctx, 'synth-processor', {
                    numberOfInputs: 0,
                    numberOfOutputs: 1,
                    outputChannelCount: [2]
                });

                // Initial send
                (['normal', 'latch', 'strum'] as PlayMode[]).forEach(mode => {
                    this.workletNode!.port.postMessage({ 
                        type: 'update_preset', 
                        mode: mode, 
                        data: this.activePresets[mode] 
                    });
                });
                this.workletNode.port.postMessage({ type: 'config', polyphony: store.getSnapshot().settings.polyphony });

                this.setupFX();

                if (this.workletNode && this.dryGain && this.reverbGain && this.delayOutputGain) {
                     this.workletNode.connect(this.dryGain);
                     this.workletNode.connect(this.reverbGain);
                     this.workletNode.connect(this.delayOutputGain);
                }

            } catch (e) {
                console.error("Failed to load AudioWorklet", e);
                this.initPromise = null; 
                return;
            }
        }

        if (this.ctx && this.ctx.state === 'suspended') {
            await this.ctx.resume();
        }
    })();

    return this.initPromise;
  }

  private setupFX() {
    if (!this.ctx) return;

    try {
        this.dryGain?.disconnect();
        this.reverbNode?.disconnect();
        this.reverbGain?.disconnect();
        this.delayNode?.disconnect();
        this.delayFeedbackGain?.disconnect();
        this.delayOutputGain?.disconnect();
        this.limiter?.disconnect();
    } catch(e) { /* ignore */ }

    this.limiter = this.ctx.createDynamicsCompressor();
    // Soften the limiter for mobile to avoid hard pumping which can sound like crackle
    this.limiter.threshold.value = -8.0; 
    this.limiter.ratio.value = 10.0;
    this.limiter.attack.value = 0.005;
    this.limiter.connect(this.ctx.destination);

    this.dryGain = this.ctx.createGain();
    this.dryGain.connect(this.limiter);

    this.reverbNode = this.ctx.createConvolver();
    this.updateReverbBuffer();

    this.reverbGain = this.ctx.createGain();
    this.reverbGain.connect(this.reverbNode);
    this.reverbNode.connect(this.limiter);

    this.delayNode = this.ctx.createDelay(5.0);
    this.delayFeedbackGain = this.ctx.createGain();
    this.delayOutputGain = this.ctx.createGain();

    this.delayOutputGain.connect(this.delayNode);
    this.delayNode.connect(this.limiter); 
    this.delayNode.connect(this.delayFeedbackGain);
    this.delayFeedbackGain.connect(this.delayNode);

    if (this.workletNode) {
        this.workletNode.disconnect();
        this.workletNode.connect(this.dryGain);
        this.workletNode.connect(this.reverbGain);
        this.workletNode.connect(this.delayOutputGain);
    }

    this.updateFX();
    this.setMasterVolume(this.currentMasterVol);
  }

  private updateReverbBuffer() {
      if (!this.reverbNode || !this.ctx) return;

      // Use NORMAL preset as the master for reverb tail generation
      const master = this.activePresets.normal;
      const type = master.reverbType || 'hall';

      const duration = master.reverbSize ?? REVERB_DEFAULTS[type].size;
      const damping = master.reverbDamping ?? REVERB_DEFAULTS[type].damping;
      const diffusion = master.reverbDiffusion ?? REVERB_DEFAULTS[type].diffusion;

      let brightness = 1.0 - damping; 

      let preDelay = 0.0;
      let decay = 2.0;
      let density = 0.5;

      switch(type) {
          case 'room': 
              decay = 3.0; density = 0.8; 
              break;
          case 'hall': 
              decay = 2.0; density = 0.6; preDelay = 0.02;
              break;
          case 'cathedral': 
              decay = 1.5; density = 0.4; preDelay = 0.04;
              break;
          case 'plate': 
              decay = 4.0; density = 1.0; 
              break;
          case 'shimmer': 
              decay = 0.8; density = 0.2; 
              break;
          default: 
              decay = 2.0; density = 0.5;
      }

      this.reverbNode.buffer = this.createImpulseResponse(duration, decay, brightness, density, preDelay, diffusion);
  }

  private updateFX() {
      if (!this.ctx) return;
      const now = this.ctx.currentTime;
      const ramp = 0.1;

      // Use NORMAL preset for global FX levels
      const master = this.activePresets.normal;

      const scaledReverbMix = Math.min(1.0, master.reverbMix * this.globalSpatialScale);
      const scaledDelayMix = Math.min(1.0, master.delayMix * this.globalSpatialScale);

      if (this.reverbGain) this.reverbGain.gain.setTargetAtTime(scaledReverbMix, now, ramp);
      if (this.delayOutputGain) this.delayOutputGain.gain.setTargetAtTime(scaledDelayMix, now, ramp);

      const scaledFeedback = Math.min(0.95, master.delayFeedback * Math.sqrt(this.globalSpatialScale));
      if (this.delayFeedbackGain) this.delayFeedbackGain.gain.setTargetAtTime(scaledFeedback, now, ramp);

      if (this.delayNode) this.delayNode.delayTime.setTargetAtTime(master.delayTime, now, ramp);

      if (this.limiter) {
          const thresh = master.compressorThreshold ?? -20.0;
          const ratio = master.compressorRatio ?? 12;
          const release = master.compressorRelease ?? 0.25;

          this.limiter.threshold.setTargetAtTime(thresh, now, ramp);
          this.limiter.ratio.setTargetAtTime(ratio, now, ramp);
          this.limiter.release.setTargetAtTime(release, now, ramp);
      }

      if (this.dryGain) {
          const dryLevel = Math.max(0.5, 1.0 - (scaledReverbMix * 0.4));
          this.dryGain.gain.setTargetAtTime(dryLevel * this.currentMasterVol, now, ramp);
      }
  }

  private createImpulseResponse(duration: number, baseDecayCurve: number, brightness: number, density: number, preDelay: number, diffusion: number): AudioBuffer {
    if (!this.ctx) throw new Error("No Context");
    const sampleRate = this.ctx.sampleRate;
    const length = Math.floor(sampleRate * duration);
    const impulse = this.ctx.createBuffer(2, length, sampleRate);
    const left = impulse.getChannelData(0);
    const right = impulse.getChannelData(1);

    const startSample = Math.floor(preDelay * sampleRate);
    let lpL = 0, lpR = 0;
    const baseSmoothing = 0.01 + (1.0 - brightness) * 0.985; 
    const decayCurve = baseDecayCurve + (1.0 - brightness) * 4.0;

    for (let i = startSample; i < length; i++) {
        let nL = (Math.random() * 2 - 1);
        let nR = (Math.random() * 2 - 1);
        const progress = (i - startSample) / (length - startSample);
        const currentSmoothing = baseSmoothing * (0.8 + 0.2 * progress);

        lpL += (nL - lpL) * (1.0 - currentSmoothing);
        lpR += (nR - lpR) * (1.0 - currentSmoothing);

        const env = Math.pow(1 - progress, decayCurve);
        const diffMask = (Math.random() < (0.05 + 0.95 * diffusion)) ? 1 : 0;
        const diffGain = diffMask > 0 ? 1.0 / Math.sqrt(0.05 + 0.95 * diffusion) : 0;

        left[i] = lpL * env * diffMask * diffGain;
        right[i] = lpR * env * diffMask * diffGain;
    }

    const erDuration = Math.floor(0.08 * sampleRate);
    const erCount = Math.floor(8 + density * 12); 

    for (let k = 0; k < erCount; k++) {
        const delay = startSample + Math.floor(Math.random() * erDuration);
        if (delay < length) {
            const erAmp = (1.0 - (k / erCount)) * 0.8; 
            const pan = Math.random() * 2 - 1; 
            const gainL = erAmp * (0.5 - 0.5 * pan);
            const gainR = erAmp * (0.5 + 0.5 * pan);
            left[delay] += (Math.random() * 2 - 1) * gainL;
            right[delay] += (Math.random() * 2 - 1) * gainR;
        }
    }

    let maxVal = 0;
    for (let i = 0; i < length; i++) {
        if (Math.abs(left[i]) > maxVal) maxVal = Math.abs(left[i]);
        if (Math.abs(right[i]) > maxVal) maxVal = Math.abs(right[i]);
    }
    const scale = 0.5 / Math.max(0.001, maxVal); 
    for (let i = 0; i < length; i++) {
        left[i] *= scale;
        right[i] *= scale;
    }

    return impulse;
  }

  public setPolyphony(count: number) {
      if (this.workletNode) {
          this.workletNode.port.postMessage({ type: 'config', polyphony: count });
      }
  }

  public setMasterVolume(val: number) {
    this.currentMasterVol = val;
    this.updateFX();
  }

  public setGlobalSpatialScale(val: number) {
      this.globalSpatialScale = val;
      this.updateFX();
  }

  public async startVoice(id: string, ratio: number, baseFrequency: number, type: PlayMode = 'normal') {
    // Ensure active
    if (this.ctx && this.ctx.state === 'suspended') {
        this.ctx.resume();
    }

    await this.init();
    if (!this.workletNode) return;

    const freq = baseFrequency * ratio;
    this.workletNode.port.postMessage({ 
        type: 'note_on', 
        id: id, 
        freq: freq,
        voiceType: type
    });
  }

  public stopVoice(id: string) {
    if (!this.workletNode) return;
    this.workletNode.port.postMessage({ 
        type: 'note_off', 
        id: id 
    });
  }

  public glideVoice(id: string, newRatio: number, baseFrequency: number) {
    if (!this.workletNode) return;
    const freq = baseFrequency * newRatio;
    this.workletNode.port.postMessage({ 
        type: 'glide', 
        id: id, 
        freq: freq 
    });
  }

  public stopAll() {
    if (!this.workletNode) return;
    this.workletNode.port.postMessage({ type: 'stop_all' });
    this.setupFX();
  }
}

export const audioEngine = new AudioEngine();
export default AudioEngine;

import React, { useState, useEffect, useRef } from 'react';
import TonalityDiamond, { TonalityDiamondHandle } from './components/TonalityDiamond';
import SettingsModal from './components/SettingsModal';
import SynthControls from './components/SynthControls';
import FloatingControls from './components/FloatingControls';
import LimitLayerControls from './components/LimitLayerControls';
import { audioEngine } from './services/AudioEngine'; // Import singleton
import { midiService } from './services/MidiService';
import { useStore } from './services/Store';
import { AppSettings, ChordDefinition, XYPos } from './types';
import { PIXELS_PER_MM } from './constants';

const REFERENCE_SHORT_EDGE = 1080; // Baseline resolution for 1.0 scale

const App: React.FC = () => {
  const { settings, presets, updateSettings, setPreset } = useStore();

  const [masterVolume, setMasterVolume] = useState(0.8);
  const [spatialScale, setSpatialScale] = useState(1.0); 
  const [activeChordIds, setActiveChordIds] = useState<string[]>([]);
  const [draggingId, setDraggingId] = useState<string | null>(null);

  // Adaptive Scaling State
  const [autoScaleFactor, setAutoScaleFactor] = useState(1.0);

  // 0 = Off, 1 = Latch All, 2 = Sustain (Partial Latch)
  const [latchMode, setLatchMode] = useState<0 | 1 | 2>(0);

  // Modals
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isSynthOpen, setIsSynthOpen] = useState(false);

  const diamondRef = useRef<TonalityDiamondHandle>(null);

  // Computed Effective Scale (Auto * User Preference)
  const effectiveScale = autoScaleFactor * (settings.uiScale || 1.0);

  // Audio Warmup - Reinforced for iOS
  useEffect(() => {
    const warmup = (e: Event) => {
        // Prevent default for touchend to ensure audio context can resume cleanly
        // if this is the very first interaction
        // However, we must be careful not to block clicking buttons

        // Resume/Init context immediately on user interaction
        audioEngine.resume().then(() => {
            // Optional: Log success
        });

        // Remove listeners
        window.removeEventListener('pointerdown', warmup);
        window.removeEventListener('keydown', warmup);
        window.removeEventListener('touchstart', warmup);
        window.removeEventListener('touchend', warmup);
        window.removeEventListener('click', warmup);
    };

    window.addEventListener('pointerdown', warmup);
    window.addEventListener('keydown', warmup);
    window.addEventListener('touchstart', warmup);
    window.addEventListener('touchend', warmup);
    window.addEventListener('click', warmup);

    return () => {
        window.removeEventListener('pointerdown', warmup);
        window.removeEventListener('keydown', warmup);
        window.removeEventListener('touchstart', warmup);
        window.removeEventListener('touchend', warmup);
        window.removeEventListener('click', warmup);
    };
  }, []);

  // Update CSS Variable for global usage if needed
  useEffect(() => {
      document.documentElement.style.setProperty('--ui-scale', effectiveScale.toString());
  }, [effectiveScale]);

  // Measure Safe Areas (Notches/Home Bars)
  const getSafeAreas = () => {
      if (typeof document === 'undefined') return { top: 0, right: 0, bottom: 0, left: 0 };
      const div = document.createElement('div');
      div.style.paddingTop = 'env(safe-area-inset-top)';
      div.style.paddingRight = 'env(safe-area-inset-right)';
      div.style.paddingBottom = 'env(safe-area-inset-bottom)';
      div.style.paddingLeft = 'env(safe-area-inset-left)';
      div.style.position = 'absolute';
      div.style.visibility = 'hidden';
      document.body.appendChild(div);
      const computed = getComputedStyle(div);
      const safe = {
          top: parseInt(computed.paddingTop) || 0,
          right: parseInt(computed.paddingRight) || 0,
          bottom: parseInt(computed.paddingBottom) || 0,
          left: parseInt(computed.paddingLeft) || 0
      };
      document.body.removeChild(div);
      return safe;
  };

  // Central Layout Calculation Logic
  const applyLayout = (w: number, h: number, scale: number) => {
      const safeArea = getSafeAreas();

      // Use configured margin, defaulting to 4mm if not set
      const marginPx = (settings.uiEdgeMargin || 4) * PIXELS_PER_MM;

      const marginTop = marginPx + safeArea.top;
      // Force extra margin on right if safe area is 0 to ensure visual gap from scrollbar
      const marginRight = marginPx + safeArea.right + (safeArea.right === 0 ? 4 : 0);
      const marginBottom = marginPx + safeArea.bottom;
      const marginLeft = marginPx + safeArea.left;

      const baseGap = marginPx; // Spacing between buttons matches the margin

      // --- TOP CENTER (Space & Volume) ---
      const sliderWidth = 290 * scale; 
      const centerGap = 120 * scale; 
      const totalTopWidth = (sliderWidth * 2) + centerGap;
      const topStartX = (w / 2) - (totalTopWidth / 2);

      const newPos = { ...settings.uiPositions };

      newPos.space = { x: topStartX, y: marginTop };
      newPos.volume = { x: topStartX + sliderWidth + centerGap, y: marginTop };

      // --- RIGHT STACK (Layers + Buttons) ---
      const largeBtn = 80 * scale; 

      // Precise width calculation
      // Limit Bar: p-2(8) + icon(24*s) + gap-2(8) + btn(48*s) + p-2(8) = 24 + 72*s
      // Note: scale here is effective scale
      const limitBarWidth = 24 + (72 * scale); 
      const largeBtnWidth = largeBtn;

      // Calculate Layers Height
      const layerRowHeight = 48 * scale;
      const layerGap = 12;
      const layerPadding = 16;
      const layersHeight = (layerRowHeight * 6) + (layerGap * 5) + layerPadding;

      const separatorGap = largeBtn;
      const btnGap = 10 * scale;

      const totalStackHeight = layersHeight + separatorGap + (4 * largeBtn) + (3 * btnGap);

      // Start Y (Centered vertically)
      let startY = (h / 2) - (totalStackHeight / 2);
      if (startY < marginTop + 50) startY = marginTop + 50;

      // X Positions (Right Aligned to Margin)
      // Use window.innerWidth (w) but subtract scrollbar width manually if on desktop
      // Since 'w' passed here is clientWidth from the resize handler, it already excludes scrollbar.
      const limitBarX = w - marginRight - limitBarWidth;
      const buttonsX = w - marginRight - largeBtnWidth;

      newPos.layers = { x: limitBarX, y: startY };

      let currentY = startY + layersHeight + separatorGap;

      newPos.bend = { x: buttonsX, y: currentY };
      currentY += largeBtn + btnGap;

      newPos.latch = { x: buttonsX, y: currentY };
      currentY += largeBtn + btnGap;

      newPos.off = { x: buttonsX, y: currentY };
      currentY += largeBtn + btnGap;

      newPos.panic = { x: buttonsX, y: currentY };

      // --- BOTTOM LEFT ROW ---
      const baseBtn = 48 * scale;
      const bottomY = h - marginBottom - baseBtn; 
      let currentX = marginLeft;

      newPos.center = { x: currentX, y: bottomY };
      currentX += (baseBtn + baseGap); 

      if (settings.showIncreaseDepthButton) {
          newPos.depth = { x: currentX, y: bottomY };
          currentX += (baseBtn + baseGap);
          newPos.decreaseDepth = { x: currentX, y: bottomY };
          currentX += (baseBtn + baseGap);
      }

      currentX += 20 * scale; 
      newPos.chords = { x: currentX, y: bottomY };

      return newPos;
  };

  // Resize Handler & Scale Calculator
  const windowSizeRef = useRef({ w: typeof window !== 'undefined' ? window.innerWidth : 1000, h: typeof window !== 'undefined' ? window.innerHeight : 800 });

  useEffect(() => {
    const handleResize = () => {
        // Use clientWidth to exclude scrollbars for precise inner alignment
        const w = document.documentElement.clientWidth;
        const h = document.documentElement.clientHeight;

        const shortEdge = Math.min(w, h);
        const newAutoScale = shortEdge / REFERENCE_SHORT_EDGE;
        setAutoScaleFactor(newAutoScale);

        const newEffectiveScale = newAutoScale * (settings.uiScale || 1.0);

        updateSettings(prev => ({
            ...prev,
            uiPositions: applyLayout(w, h, newEffectiveScale)
        }));

        windowSizeRef.current = { w, h };
    };

    handleResize();

    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, [settings.uiScale, settings.uiEdgeMargin, settings.showIncreaseDepthButton]); 

  // Init Engine updates
  useEffect(() => {
    audioEngine.setMasterVolume(masterVolume);
  }, [masterVolume]);

  useEffect(() => {
    audioEngine.setGlobalSpatialScale(spatialScale);
  }, [spatialScale]);

  const handleLimitInteraction = (limit: number) => {
    if (settings.layerOrder[settings.layerOrder.length - 1] !== limit) {
      const newOrder = settings.layerOrder.filter(l => l !== limit);
      newOrder.push(limit);
      updateSettings(prev => ({ ...prev, layerOrder: newOrder }));
    }
  };

  const handlePanic = () => {
    audioEngine.stopAll(); 
    midiService.panic(); // Robust MIDI Panic (All Notes Off)
    diamondRef.current?.clearLatches(); 
    setActiveChordIds([]); 
    setLatchMode(0);
    setIsSettingsOpen(false);
    setIsSynthOpen(false);
  };

  const handleOff = () => {
    diamondRef.current?.clearLatches(); 
    setActiveChordIds([]);
    setLatchMode(0);
  };

  const handleLatchToggle = () => {
      setLatchMode(prev => {
          const next = prev + 1;
          if (next > 2) {
              diamondRef.current?.clearLatches();
              return 0;
          }
          return next as 0 | 1 | 2;
      });
  };

  const handleBendToggle = () => {
      updateSettings(prev => ({ ...prev, isPitchBendEnabled: !prev.isPitchBendEnabled }));
  };

  const handleCenter = () => {
      diamondRef.current?.centerView();
  };

  const handleIncreaseDepth = () => {
      diamondRef.current?.increaseDepth();
  };

  const handleDecreaseDepth = () => {
      diamondRef.current?.decreaseDepth();
  };

  const handleAddChord = () => {
      if (diamondRef.current) {
          const latchedNodes = diamondRef.current.getLatchedNodes();
          if (latchedNodes.length === 0) return;

          let slotIndex = settings.savedChords.findIndex(c => c.nodes.length === 0);
          if (slotIndex === -1) {
               slotIndex = settings.savedChords.findIndex(c => !c.visible);
          }

          if (slotIndex !== -1) {
              const newChords = [...settings.savedChords];
              const simplifiedNodes = latchedNodes.map(n => ({
                  id: n.id, n: n.n, d: n.d
              }));

              newChords[slotIndex] = {
                  ...newChords[slotIndex],
                  nodes: simplifiedNodes,
                  visible: true,
                  position: { x: 0, y: 0 } 
              };

              updateSettings(prev => ({ ...prev, savedChords: newChords }));
          }
      }
  };

  const toggleChord = (id: string) => {
      setActiveChordIds(prev => {
          if (prev.includes(id)) {
              return prev.filter(c => c !== id);
          } else {
              return [...prev, id];
          }
      });
  };

  const handleUiPositionUpdate = (key: keyof AppSettings['uiPositions'], pos: XYPos) => {
      updateSettings(prev => ({
          ...prev,
          uiPositions: { ...prev.uiPositions, [key]: pos }
      }));
  };

  // --- Keyboard Shortcuts ---
  useEffect(() => {
      const handleKeyDown = (e: KeyboardEvent) => {
          // Ignore if typing in an input field
          const target = e.target as HTMLElement;
          if (target.tagName === 'INPUT' || target.tagName === 'SELECT' || target.tagName === 'TEXTAREA') return;

          switch(e.key.toLowerCase()) {
              case ' ': // Spacebar -> Latch
                  e.preventDefault();
                  handleLatchToggle();
                  break;
              case 'escape': // Esc -> Panic/Close
                  e.preventDefault();
                  handlePanic();
                  break;
              case 'c': // C -> Center
                  handleCenter();
                  break;
              case 's': // S -> Settings
                  setIsSettingsOpen(prev => !prev);
                  if(isSynthOpen) setIsSynthOpen(false);
                  break;
              case 'm': // M -> Synth (Menu)
                  setIsSynthOpen(prev => !prev);
                  if(isSettingsOpen) setIsSettingsOpen(false);
                  break;
          }
      };

      window.addEventListener('keydown', handleKeyDown);
      return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isSettingsOpen, isSynthOpen]); // Re-bind on modal state change to ensure fresh closures if needed

  // Header Safe Area Calculation
  const marginPx = (settings.uiEdgeMargin || 4) * PIXELS_PER_MM;
  const headerTop = `calc(${marginPx}px + env(safe-area-inset-top))`;
  const headerLeft = `calc(${marginPx}px + env(safe-area-inset-left))`;
  const headerRight = `calc(${marginPx}px + env(safe-area-inset-right))`;

  return (
    <div className="relative w-screen h-screen overflow-hidden bg-slate-900 font-sans text-white">

      {/* Top Left: Title */}
      <div 
        className="absolute z-50 pointer-events-none"
        style={{ top: headerTop, left: headerLeft }}
      >
        <h1 className="text-sm font-bold tracking-widest text-slate-500 opacity-50 leading-none">PRISMATONAL</h1>
      </div>

      {/* Top Right: Synth & Settings Buttons */}
      <div 
        className="absolute z-50 flex gap-2 pointer-events-auto"
        style={{ top: headerTop, right: headerRight }}
      >
          <button 
            onClick={() => setIsSettingsOpen(true)}
            className="bg-slate-800/80 hover:bg-slate-600 px-3 py-1 text-xs rounded backdrop-blur transition border border-white/10 h-8 flex items-center"
          >
            Settings (S)
          </button>
          <button 
            onClick={() => setIsSynthOpen(true)}
            className="bg-slate-800/80 hover:bg-indigo-600 px-3 py-1 text-xs rounded backdrop-blur transition border border-white/10 h-8 flex items-center"
          >
            Synth (M)
          </button>
      </div>

      {/* Main Canvas */}
      <TonalityDiamond 
        ref={diamondRef}
        settings={settings}
        updateSettings={updateSettings}
        audioEngine={audioEngine} 
        onLimitInteraction={handleLimitInteraction}
        activeChordIds={activeChordIds}
        uiUnlocked={settings.uiUnlocked}
        latchMode={latchMode}
        globalScale={effectiveScale}
      />

      {/* Floating UI */}
      <FloatingControls 
        volume={masterVolume}
        setVolume={setMasterVolume}
        spatialScale={spatialScale}
        setSpatialScale={setSpatialScale}
        onPanic={handlePanic}
        onOff={handleOff}
        onLatch={handleLatchToggle}
        latchMode={latchMode}
        onBend={handleBendToggle}
        isBendEnabled={settings.isPitchBendEnabled}
        onCenter={handleCenter}
        onIncreaseDepth={handleIncreaseDepth}
        onDecreaseDepth={handleDecreaseDepth}
        onAddChord={handleAddChord}
        toggleChord={toggleChord}
        activeChordIds={activeChordIds}
        savedChords={settings.savedChords}
        chordShortcutSizeScale={settings.chordShortcutSizeScale}
        showIncreaseDepthButton={settings.showIncreaseDepthButton}
        uiUnlocked={settings.uiUnlocked}
        uiPositions={settings.uiPositions}
        updatePosition={handleUiPositionUpdate}
        draggingId={draggingId}
        setDraggingId={setDraggingId}
        uiScale={effectiveScale}
      />

      <LimitLayerControls 
        settings={settings}
        updateSettings={updateSettings}
        draggingId={draggingId}
        setDraggingId={setDraggingId}
        uiScale={effectiveScale}
      />

      {/* Modals */}
      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)}
        settings={settings}
        updateSettings={updateSettings}
      />

      <SynthControls 
        isOpen={isSynthOpen}
        onClose={() => setIsSynthOpen(false)}
        presets={presets}
        onChange={setPreset}
      />
    </div>
  );
};

