      let paintMode: 'add' | 'remove' | 'pending' | undefined = undefined;
      if (latchMode === 1) {
          if (hitNode) {
              // Direct hit: Determine intent immediately
              paintMode = persistentLatches.has(hitNode.id) ? 'remove' : 'add';
          } else {
