import React, { useState, useEffect, useRef } from 'react';
import TonalityDiamond, { TonalityDiamondHandle } from './components/TonalityDiamond';
import SettingsModal from './components/SettingsModal';
import SynthControls from './components/SynthControls';
import FloatingControls from './components/FloatingControls';
import LimitLayerControls from './components/LimitLayerControls';
import { audioEngine } from './services/AudioEngine'; // Import singleton
import { midiService } from './services/MidiService';
import { useStore } from './services/Store';
import { AppSettings, ChordDefinition, XYPos } from './types';
import { PIXELS_PER_MM } from './constants';

const REFERENCE_SHORT_EDGE = 1080; // Baseline resolution for 1.0 scale

const App: React.FC = () => {
  const { settings, presets, updateSettings, setPreset } = useStore();

  const [masterVolume, setMasterVolume] = useState(0.8);
  const [spatialScale, setSpatialScale] = useState(1.0); 
  const [activeChordIds, setActiveChordIds] = useState<string[]>([]);
  const [draggingId, setDraggingId] = useState<string | null>(null);

  // Adaptive Scaling State
  const [autoScaleFactor, setAutoScaleFactor] = useState(1.0);

  // 0 = Off, 1 = Latch All, 2 = Sustain (Partial Latch)
  const [latchMode, setLatchMode] = useState<0 | 1 | 2>(0);

  // Modals
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isSynthOpen, setIsSynthOpen] = useState(false);

  const diamondRef = useRef<TonalityDiamondHandle>(null);

  // Computed Effective Scale (Auto * User Preference)
  const effectiveScale = autoScaleFactor * (settings.uiScale || 1.0);

  // Audio Warmup - Reinforced for iOS
  useEffect(() => {
    const warmup = (e: Event) => {
        // Prevent default for touchend to ensure audio context can resume cleanly
        // if this is the very first interaction
        // However, we must be careful not to block clicking buttons

        // Resume/Init context immediately on user interaction
        audioEngine.resume().then(() => {
            // Optional: Log success
        });

        // Remove listeners
        window.removeEventListener('pointerdown', warmup);
        window.removeEventListener('keydown', warmup);
        window.removeEventListener('touchstart', warmup);
        window.removeEventListener('touchend', warmup);
        window.removeEventListener('click', warmup);
    };

    window.addEventListener('pointerdown', warmup);
    window.addEventListener('keydown', warmup);
    window.addEventListener('touchstart', warmup);
    window.addEventListener('touchend', warmup);
    window.addEventListener('click', warmup);

    return () => {
        window.removeEventListener('pointerdown', warmup);
        window.removeEventListener('keydown', warmup);
        window.removeEventListener('touchstart', warmup);
        window.removeEventListener('touchend', warmup);
        window.removeEventListener('click', warmup);
    };
  }, []);

  // Update CSS Variable for global usage if needed
  useEffect(() => {
      document.documentElement.style.setProperty('--ui-scale', effectiveScale.toString());
  }, [effectiveScale]);

  // Measure Safe Areas (Notches/Home Bars)
  const getSafeAreas = () => {
      if (typeof document === 'undefined') return { top: 0, right: 0, bottom: 0, left: 0 };
      const div = document.createElement('div');
      div.style.paddingTop = 'env(safe-area-inset-top)';
      div.style.paddingRight = 'env(safe-area-inset-right)';
      div.style.paddingBottom = 'env(safe-area-inset-bottom)';
      div.style.paddingLeft = 'env(safe-area-inset-left)';
      div.style.position = 'absolute';
      div.style.visibility = 'hidden';
      document.body.appendChild(div);
      const computed = getComputedStyle(div);
      const safe = {
          top: parseInt(computed.paddingTop) || 0,
          right: parseInt(computed.paddingRight) || 0,
          bottom: parseInt(computed.paddingBottom) || 0,
          left: parseInt(computed.paddingLeft) || 0
      };
      document.body.removeChild(div);
      return safe;
  };

  // Central Layout Calculation Logic
  const applyLayout = (w: number, h: number, scale: number) => {
      const safeArea = getSafeAreas();

      // Use configured margin, defaulting to 4mm if not set
      const marginPx = (settings.uiEdgeMargin || 4) * PIXELS_PER_MM;

      const marginTop = marginPx + safeArea.top;
      // Force extra margin on right if safe area is 0 to ensure visual gap from scrollbar
      const marginRight = marginPx + safeArea.right + (safeArea.right === 0 ? 4 : 0);
      const marginBottom = marginPx + safeArea.bottom;
      const marginLeft = marginPx + safeArea.left;

      const baseGap = marginPx; // Spacing between buttons matches the margin

      // --- TOP CENTER (Space & Volume) ---
      const sliderWidth = 200 * scale; // Updated to match smaller sliders
      const centerGap = 120 * scale; 
      const totalTopWidth = (sliderWidth * 2) + centerGap;
      const topStartX = (w / 2) - (totalTopWidth / 2);

      const newPos = { ...settings.uiPositions };

      newPos.space = { x: topStartX, y: marginTop };
      newPos.volume = { x: topStartX + sliderWidth + centerGap, y: marginTop };

      // --- RIGHT STACK (Layers + Buttons) ---
      const largeBtn = 80 * scale; 

      // Precise width calculation
      // Limit Bar: p-2(8) + icon(24*s) + gap-2(8) + btn(48*s) + p-2(8) = 24 + 72*s
      // Note: scale here is effective scale
      const limitBarWidth = 24 + (72 * scale); 
      const largeBtnWidth = largeBtn;

      // Calculate Layers Height
      const layerRowHeight = 48 * scale;
      const layerGap = 12;
      const layerPadding = 16;
      const layersHeight = (layerRowHeight * 6) + (layerGap * 5) + layerPadding;

      const separatorGap = largeBtn;
      const btnGap = 10 * scale;

      const totalStackHeight = layersHeight + separatorGap + (4 * largeBtn) + (3 * btnGap);

      // Start Y (Centered vertically)
      let startY = (h / 2) - (totalStackHeight / 2);
      if (startY < marginTop + 50) startY = marginTop + 50;

      // X Positions (Right Aligned to Margin)
      // Use window.innerWidth (w) but subtract scrollbar width manually if on desktop
      // Since 'w' passed here is clientWidth from the resize handler, it already excludes scrollbar.
      const limitBarX = w - marginRight - limitBarWidth;
      const buttonsX = w - marginRight - largeBtnWidth;

      newPos.layers = { x: limitBarX, y: startY };

      let currentY = startY + layersHeight + separatorGap;

      newPos.bend = { x: buttonsX, y: currentY };
      currentY += largeBtn + btnGap;

      newPos.latch = { x: buttonsX, y: currentY };
      currentY += largeBtn + btnGap;

      newPos.off = { x: buttonsX, y: currentY };
      currentY += largeBtn + btnGap;

      newPos.panic = { x: buttonsX, y: currentY };

      // --- BOTTOM LEFT ROW ---
      const baseBtn = 48 * scale;
      // Lifted by ~4mm (approx 15px at scale 1.0) to match Panic visual balance
      const bottomLiftOffset = 15 * scale;
      const bottomY = h - marginBottom - baseBtn - bottomLiftOffset; 

      let currentX = marginLeft;

      newPos.center = { x: currentX, y: bottomY };
      currentX += (baseBtn + baseGap); 

      if (settings.showIncreaseDepthButton) {
          newPos.depth = { x: currentX, y: bottomY };
          currentX += (baseBtn + baseGap);
          newPos.decreaseDepth = { x: currentX, y: bottomY };
          currentX += (baseBtn + baseGap);
      }

      currentX += 20 * scale; 
      newPos.chords = { x: currentX, y: bottomY };

      return newPos;
  };

  // Resize Handler & Scale Calculator
  const windowSizeRef = useRef({ w: typeof window !== 'undefined' ? window.innerWidth : 1000, h: typeof window !== 'undefined' ? window.innerHeight : 800 });

  useEffect(() => {
    const handleResize = () => {
        // Use clientWidth to exclude scrollbars for precise inner alignment
        const w = document.documentElement.clientWidth;
        const h = document.documentElement.clientHeight;

        const shortEdge = Math.min(w, h);
        const newAutoScale = shortEdge / REFERENCE_SHORT_EDGE;
        setAutoScaleFactor(newAutoScale);

        const newEffectiveScale = newAutoScale * (settings.uiScale || 1.0);

        updateSettings(prev => ({
            ...prev,
            uiPositions: applyLayout(w, h, newEffectiveScale)
        }));

        windowSizeRef.current = { w, h };
    };

    handleResize();

    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, [settings.uiScale, settings.uiEdgeMargin, settings.showIncreaseDepthButton]); 

  // Init Engine updates
  useEffect(() => {
    audioEngine.setMasterVolume(masterVolume);
  }, [masterVolume]);

  useEffect(() => {
    audioEngine.setGlobalSpatialScale(spatialScale);
  }, [spatialScale]);

  const handleLimitInteraction = (limit: number) => {
    if (settings.layerOrder[settings.layerOrder.length - 1] !== limit) {
      const newOrder = settings.layerOrder.filter(l => l !== limit);
      newOrder.push(limit);
      updateSettings(prev => ({ ...prev, layerOrder: newOrder }));
    }
  };

  const handlePanic = () => {
    audioEngine.stopAll(); 
    midiService.panic(); // Robust MIDI Panic (All Notes Off)
    diamondRef.current?.clearLatches(); 
    setActiveChordIds([]); 
    setLatchMode(0);
    setIsSettingsOpen(false);
    setIsSynthOpen(false);
  };

  const handleOff = () => {
    diamondRef.current?.clearLatches(); 
    setActiveChordIds([]);
    setLatchMode(0);
  };

  const handleLatchToggle = () => {
      setLatchMode(prev => {
          const next = prev + 1;
          if (next > 2) {
              diamondRef.current?.clearLatches();
              return 0;
          }
          return next as 0 | 1 | 2;
      });
  };

  const handleBendToggle = () => {
      updateSettings(prev => ({ ...prev, isPitchBendEnabled: !prev.isPitchBendEnabled }));
  };

  const handleCenter = () => {
      diamondRef.current?.centerView();
  };

  const handleIncreaseDepth = () => {
      diamondRef.current?.increaseDepth();
  };

  const handleDecreaseDepth = () => {
      diamondRef.current?.decreaseDepth();
  };

  const handleAddChord = () => {
      if (diamondRef.current) {
          const latchedNodes = diamondRef.current.getLatchedNodes();
          if (latchedNodes.length === 0) return;

          let slotIndex = settings.savedChords.findIndex(c => c.nodes.length === 0);
          if (slotIndex === -1) {
               slotIndex = settings.savedChords.findIndex(c => !c.visible);
          }

          if (slotIndex !== -1) {
              const newChords = [...settings.savedChords];
              const simplifiedNodes = latchedNodes.map(n => ({
                  id: n.id, n: n.n, d: n.d
              }));

              newChords[slotIndex] = {
                  ...newChords[slotIndex],
                  nodes: simplifiedNodes,
                  visible: true,
                  position: { x: 0, y: 0 } 
              };

              updateSettings(prev => ({ ...prev, savedChords: newChords }));
          }
      }
  };

  const toggleChord = (id: string) => {
      setActiveChordIds(prev => {
          if (prev.includes(id)) {
              return prev.filter(c => c !== id);
          } else {
              return [...prev, id];
          }
      });
  };

  const handleUiPositionUpdate = (key: keyof AppSettings['uiPositions'], pos: XYPos) => {
      updateSettings(prev => ({
          ...prev,
          uiPositions: { ...prev.uiPositions, [key]: pos }
      }));
  };

  // --- Keyboard Shortcuts ---
  useEffect(() => {
      const handleKeyDown = (e: KeyboardEvent) => {
          // Always allow Escape to close settings/synth if open
          if (e.key === 'Escape' && (isSettingsOpen || isSynthOpen)) {
              setIsSettingsOpen(false);
              setIsSynthOpen(false);
              return;
          }

          // Ignore if typing in an input field
          const target = e.target as HTMLElement;
          if (target.tagName === 'INPUT' || target.tagName === 'SELECT' || target.tagName === 'TEXTAREA') return;

          // Gate everything else behind the setting
          if (!settings.enableKeyboardShortcuts) return;

          const key = e.key.toLowerCase();

          // Prevent defaults for app-control keys
          if ([' ', 'arrowup', 'arrowdown', 'arrowleft', 'arrowright'].includes(key)) {
              e.preventDefault();
          }

          switch(key) {
              case ' ': // Spacebar -> Latch
                  handleLatchToggle();
                  break;
              case 'escape': // Esc -> Panic
                  handlePanic();
                  break;
              case 'c': // C -> Center
                  handleCenter();
                  break;
              case 's': // S -> Settings
                  setIsSettingsOpen(prev => !prev);
                  if(isSynthOpen) setIsSynthOpen(false);
                  break;
              case 'm': // M -> Synth (Menu)
                  setIsSynthOpen(prev => !prev);
                  if(isSettingsOpen) setIsSettingsOpen(false);
                  break;
              case 'o': // O -> Off
                  handleOff();
                  break;
              case 'b': // B -> Bend
                  handleBendToggle();
                  break;
              case 'enter': // Enter -> Add Chord
              case 'a': // A -> Add Chord (Alternative)
                  handleAddChord();
                  break;
              case '.': // . -> Increase Depth
                  handleIncreaseDepth();
                  break;
              case ',': // , -> Decrease Depth
                  handleDecreaseDepth();
                  break;

              // Volume Control
              case 'arrowup': 
                  setMasterVolume(v => Math.min(1.0, v + 0.05));
                  break;
              case 'arrowdown':
                  setMasterVolume(v => Math.max(0.0, v - 0.05));
                  break;

              // Reverb Control (Right/Left)
              case 'arrowright':
                  setSpatialScale(s => Math.min(2.0, s + 0.05));
                  break;
              case 'arrowleft':
                  setSpatialScale(s => Math.max(0.0, s - 0.05));
                  break;
          }
      };

      window.addEventListener('keydown', handleKeyDown);
      return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isSettingsOpen, isSynthOpen, settings.enableKeyboardShortcuts]);

  // Header Safe Area Calculation
  const marginPx = (settings.uiEdgeMargin || 4) * PIXELS_PER_MM;
  const headerTop = `calc(${marginPx}px + env(safe-area-inset-top))`;
  const headerLeft = `calc(${marginPx}px + env(safe-area-inset-left))`;
  const headerRight = `calc(${marginPx}px + env(safe-area-inset-right))`;

  return (
    <div className="relative w-screen h-screen overflow-hidden bg-slate-900 font-sans text-white">

      {/* Top Left: Title */}
      <div 
        className="absolute z-50 pointer-events-none"
        style={{ top: headerTop, left: headerLeft }}
      >
        <h1 className="text-sm font-bold tracking-widest text-slate-500 opacity-50 leading-none">PRISMATONAL</h1>
      </div>

      {/* Top Right: Synth & Settings Buttons */}
      <div 
        className="absolute z-50 flex gap-2 pointer-events-auto"
        style={{ top: headerTop, right: headerRight }}
      >
          <button 
            onClick={() => setIsSettingsOpen(true)}
            className="bg-slate-800/80 hover:bg-slate-600 px-3 py-1 text-xs rounded backdrop-blur transition border border-white/10 h-8 flex items-center font-bold"
          >
            Settings
          </button>
          <button 
            onClick={() => setIsSynthOpen(true)}
            className="bg-slate-800/80 hover:bg-indigo-600 px-3 py-1 text-xs rounded backdrop-blur transition border border-white/10 h-8 flex items-center font-bold"
          >
            Synth
          </button>
      </div>

      {/* Main Canvas */}
      <TonalityDiamond 
        ref={diamondRef}
        settings={settings}
        updateSettings={updateSettings}
        audioEngine={audioEngine} 
        onLimitInteraction={handleLimitInteraction}
        activeChordIds={activeChordIds}
        uiUnlocked={settings.uiUnlocked}
        latchMode={latchMode}
        globalScale={effectiveScale}
      />

      {/* Floating UI */}
      <FloatingControls 
        volume={masterVolume}
        setVolume={setMasterVolume}
        spatialScale={spatialScale}
        setSpatialScale={setSpatialScale}
        onPanic={handlePanic}
        onOff={handleOff}
        onLatch={handleLatchToggle}
        latchMode={latchMode}
        onBend={handleBendToggle}
        isBendEnabled={settings.isPitchBendEnabled}
        onCenter={handleCenter}
        onIncreaseDepth={handleIncreaseDepth}
        onDecreaseDepth={handleDecreaseDepth}
        onAddChord={handleAddChord}
        toggleChord={toggleChord}
        activeChordIds={activeChordIds}
        savedChords={settings.savedChords}
        chordShortcutSizeScale={settings.chordShortcutSizeScale}
        showIncreaseDepthButton={settings.showIncreaseDepthButton}
        uiUnlocked={settings.uiUnlocked}
        uiPositions={settings.uiPositions}
        updatePosition={handleUiPositionUpdate}
        draggingId={draggingId}
        setDraggingId={setDraggingId}
        uiScale={effectiveScale}
      />

      <LimitLayerControls 
        settings={settings}
        updateSettings={updateSettings}
        draggingId={draggingId}
        setDraggingId={setDraggingId}
        uiScale={effectiveScale}
      />

      {/* Modals */}
      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)}
        settings={settings}
        updateSettings={updateSettings}
      />

      <SynthControls 
        isOpen={isSynthOpen}
        onClose={() => setIsSynthOpen(false)}
        presets={presets}
        onChange={setPreset}
      />
    </div>
  );
};

export default App;

export const AUDIO_PROCESSOR_CODE = `
// --- DSP UTILS ---
const TWO_PI = 2 * Math.PI;

const DUMMY_OSC_CONFIG = {
    enabled: false,
    waveform: 'sine',
    coarseDetune: 0,
    fineDetune: 0,
    gain: 0,
    attack: 0.1,
    decay: 0.1,
    sustain: 0,
    release: 0.1,
    filterCutoff: 20000,
    filterResonance: 0,
    lfoRate: 1,
    lfoDepth: 0,
    lfoTarget: 'none'
};

const DUMMY_PRESET_DATA = {
    osc1: DUMMY_OSC_CONFIG,
    osc2: DUMMY_OSC_CONFIG,
    osc3: DUMMY_OSC_CONFIG,
    modMatrix: [],
    gain: 1.0,
    spread: 0,
    stereoPanSpeed: 0,
    stereoPanDepth: 0
};

class PolyBLEP {
  constructor(sampleRate) {
    this.sampleRate = sampleRate;
  }

  get(t, dt) {
    if (dt < 1e-9) return 0.0;
    if (t < dt) {
      t /= dt;
      return t + t - t * t - 1.0;
    } else if (t > 1.0 - dt) {
      t = (t - 1.0) / dt;
      return t * t + t + t + 1.0;
    }
    return 0.0;
  }
}

class SVF {
  constructor() {
    this.low = 0.0;
    this.band = 0.0;
    this.high = 0.0;
    this.notch = 0.0;
  }

  reset() {
    this.low = 0.0;
    this.band = 0.0;
    this.high = 0.0;
    this.notch = 0.0;
  }

  process(input, cutoff, res, sampleRate) {
    const safeCutoff = Math.max(20, Math.min(cutoff, sampleRate * 0.42));
    let f = 2.0 * Math.sin(Math.PI * safeCutoff / sampleRate);
    const q = 1.0 / (res + 0.5);

    this.low += f * this.band;
    this.high = input - this.low - q * this.band;
    this.band += f * this.high;
    this.notch = this.high + this.low;

    return this.low; 
  }
}

class Envelope {
  constructor() {
    this.stage = 'idle'; 
    this.value = 0.0;
    this.velocity = 0.0;
  }

  trigger(velocity = 1.0) {
    this.stage = 'attack';
    this.velocity = velocity;
  }

  release() {
    if (this.stage !== 'idle') {
        this.stage = 'release';
    }
  }

  reset() {
      this.stage = 'idle';
      this.value = 0.0;
  }

  process(config, dt) {
    const att = (config.attack !== undefined) ? config.attack : 0.01;
    const dec = (config.decay !== undefined) ? config.decay : 0.1;
    const sus = (config.sustain !== undefined) ? config.sustain : 1.0;
    const rel = (config.release !== undefined) ? config.release : 0.1;

    switch (this.stage) {
      case 'idle':
        this.value = 0.0;
        return 0.0;

      case 'attack':
        const attRate = 1.0 / (Math.max(0.001, att));
        this.value += attRate * dt;
        if (this.value >= 1.0) {
          this.value = 1.0;
          this.stage = 'decay';
        }
        return this.value * this.velocity;

      case 'decay':
        const decRate = 1.0 / (Math.max(0.001, dec));
        this.value += (sus - this.value) * (decRate * dt * 5.0); 
        return this.value * this.velocity;

      case 'sustain':
        this.value = sus;
        return this.value * this.velocity;

      case 'release':
        const relRate = 1.0 / (Math.max(0.001, rel));
        this.value -= this.value * (relRate * dt * 5.0);
        if (this.value < 0.001) {
          this.value = 0.0;
          this.stage = 'idle';
        }
        return this.value * this.velocity;

      default:
        return 0.0;
    }
  }
}

class Oscillator {
  constructor(sampleRate) {
    this.phase = 0.0; 
    this.blep = new PolyBLEP(sampleRate);
    this.sampleRate = sampleRate;
  }

  reset() {
      // Free-running oscillators - do not reset phase on key press
      // this.phase = 0.0; 
  }

  process(freq, type, dt) {
    if (!Number.isFinite(freq) || freq <= 0 || freq > 24000) return 0.0;

    this.phase += dt * freq;
    while (this.phase >= 1.0) this.phase -= 1.0;

    let sample = 0.0;

    switch (type) {
      case 'sine':
        sample = Math.sin(TWO_PI * this.phase);
        break;
      case 'triangle':
        let t = -1.0 + (2.0 * this.phase);
        sample = 2.0 * (Math.abs(t) - 0.5);
        break;
      case 'sawtooth':
        sample = (2.0 * this.phase) - 1.0;
        sample -= this.blep.get(this.phase, dt * freq);
        break;
      case 'square':
        sample = this.phase < 0.5 ? 1.0 : -1.0;
        sample += this.blep.get(this.phase, dt * freq);
        let phase2 = (this.phase + 0.5) % 1.0;
        sample -= this.blep.get(phase2, dt * freq);
        break;
    }

    return sample;
  }
}

class Voice {
  constructor(sampleRate) {
    this.sampleRate = sampleRate;
    this.active = false;
    this.id = '';
    this.type = 'normal'; // 'normal', 'latch', 'strum'
    this.panPos = 0; 

    this.baseFreq = 440;
    this.targetFreq = 440;
    this.startTime = 0; 
    this.releaseTime = 0; 

    this.oscs = [
        new Oscillator(sampleRate),
        new Oscillator(sampleRate),
        new Oscillator(sampleRate)
    ];

    this.filters = [ new SVF(), new SVF(), new SVF() ];
    this.envs = [ new Envelope(), new Envelope(), new Envelope() ];
    this.lfoPhases = [0.0, 0.0, 0.0];
    this.envVals = new Float32Array(3);
    this.lfoVals = new Float32Array(3);
  }

  trigger(id, freq, type) {
    this.id = id;
    this.type = type || 'normal';
    this.baseFreq = freq;
    this.targetFreq = freq;
    this.active = true;
    this.startTime = currentTime; 
    this.releaseTime = 0; 

    // Do not reset oscillator phase to avoid clicks
    // this.oscs.forEach(osc => osc.reset());

    this.envs.forEach(env => {
        // Soft reset: don't force value to 0 if retriggering to avoid pops
        // env.reset(); 
        env.trigger();
    });

    this.filters.forEach(f => f.reset());
    this.lfoPhases.fill(0.0);
  }

  release() {
    this.releaseTime = currentTime;
    this.envs.forEach(env => env.release());
  }

  hardStop() {
      this.active = false;
      this.envs.forEach(env => env.reset());
      this.filters.forEach(f => f.reset());
  }

  getLevel() {
    return Math.max(this.envs[0].value, this.envs[1].value, this.envs[2].value);
  }

  process(presetData, dt) {
    if (!this.active || !presetData) return 0.0;

    // Smooth Pitch Glide
    const diff = this.targetFreq - this.baseFreq;
    if (Math.abs(diff) > 0.001) {
      this.baseFreq += diff * 0.005; 
    } else {
      this.baseFreq = this.targetFreq;
    }

    const oscConfigs = [
        presetData.osc1 || DUMMY_OSC_CONFIG,
        presetData.osc2 || DUMMY_OSC_CONFIG,
        presetData.osc3 || DUMMY_OSC_CONFIG
    ];
    const matrix = presetData.modMatrix || [];

    let anyEnvActive = false;

    // 1. Compute Sources
    for (let i = 0; i < 3; i++) {
        const config = oscConfigs[i];
        const envVal = this.envs[i].process(config, dt);
        this.envVals[i] = envVal;
        if (this.envs[i].stage !== 'idle') anyEnvActive = true;

        const rate = (config.lfoRate !== undefined) ? config.lfoRate : 0.0;
        this.lfoPhases[i] += rate * dt;
        if (this.lfoPhases[i] >= 1.0) this.lfoPhases[i] -= 1.0;
        this.lfoVals[i] = Math.sin(TWO_PI * this.lfoPhases[i]);
    }

    if (!anyEnvActive) {
      this.active = false;
      return 0.0;
    }

    let modP1=0, modP2=0, modP3=0;
    let modC1=0, modC2=0, modC3=0;
    let modG1=0, modG2=0, modG3=0;
    let modR1=0, modR2=0, modR3=0;

    const mLen = matrix.length;
    for(let i=0; i<mLen; i++) {
        const row = matrix[i];
        if (!row.enabled) continue;

        let srcVal = 0;
        switch(row.source) {
            case 'lfo1': srcVal = this.lfoVals[0]; break;
            case 'lfo2': srcVal = this.lfoVals[1]; break;
            case 'lfo3': srcVal = this.lfoVals[2]; break;
            case 'env1': srcVal = this.envVals[0]; break;
            case 'env2': srcVal = this.envVals[1]; break;
            case 'env3': srcVal = this.envVals[2]; break;
        }

        const amt = srcVal * (Number.isFinite(row.amount) ? row.amount : 0);

        switch(row.target) {
            case 'osc1_pitch': modP1 += amt; break;
            case 'osc1_cutoff': modC1 += amt; break;
            case 'osc1_gain': modG1 += amt; break;
            case 'osc1_res': modR1 += amt; break;
            case 'osc2_pitch': modP2 += amt; break;
            case 'osc2_cutoff': modC2 += amt; break;
            case 'osc2_gain': modG2 += amt; break;
            case 'osc2_res': modR2 += amt; break;
            case 'osc3_pitch': modP3 += amt; break;
            case 'osc3_cutoff': modC3 += amt; break;
            case 'osc3_gain': modG3 += amt; break;
            case 'osc3_res': modR3 += amt; break;
        }
    }

    let voiceMix = 0.0;

    for (let i = 0; i < 3; i++) {
        const config = oscConfigs[i];
        if (!config.enabled) continue;

        const envVal = this.envVals[i];
        if (envVal < 0.0001) continue;

        let lfoVal = this.lfoVals[i];
        const lfoDepth = config.lfoDepth || 0;
        let hardPitch = 0, hardFilter = 0, hardAmp = 1.0;

        if (config.lfoTarget === 'pitch') hardPitch = lfoVal * lfoDepth;
        else if (config.lfoTarget === 'filter') hardFilter = lfoVal * lfoDepth * 20;
        else if (config.lfoTarget === 'tremolo') hardAmp = 1.0 - (lfoVal * (lfoDepth * 0.005));

        let modPitch=0, modCutoff=0, modGain=0, modRes=0;
        if (i===0) { modPitch=modP1; modCutoff=modC1; modGain=modG1; modRes=modR1; }
        else if (i===1) { modPitch=modP2; modCutoff=modC2; modGain=modG2; modRes=modR2; }
        else { modPitch=modP3; modCutoff=modC3; modGain=modG3; modRes=modR3; }

        const cents = config.coarseDetune + config.fineDetune + hardPitch + (modPitch * 1200);
        const detuneMult = Math.pow(2, cents / 1200.0);
        const oscFreq = this.baseFreq * detuneMult;

        let signal = this.oscs[i].process(oscFreq, config.waveform, dt);

        let cutoff = config.filterCutoff + hardFilter + (modCutoff * 5000);
        let res = config.filterResonance + (modRes * 10);
        if (res < 0) res = 0;

        signal = this.filters[i].process(signal, cutoff, res, this.sampleRate);

        const gainMod = Math.max(0, 1.0 + modGain); 
        const finalGain = config.gain * envVal * hardAmp * gainMod;

        voiceMix += signal * finalGain;
    }

    return voiceMix;
  }
}

class PrismaProcessor extends AudioWorkletProcessor {
  constructor() {
    super();
    // 2x Oversampling setup
    const OVERSAMPLE = 2;
    this.oversample = OVERSAMPLE;
    const workingRate = sampleRate * OVERSAMPLE;

    this.voices = [];
    // Increase physical voice limit to 64 to allow for large strums/washes
    for(let i=0; i<64; i++) {
        const v = new Voice(workingRate);
        v.panPos = Math.sin(i * 123.456); 
        this.voices.push(v);
    }

    this.presets = {
        normal: DUMMY_PRESET_DATA,
        latch: DUMMY_PRESET_DATA,
        strum: DUMMY_PRESET_DATA
    };

    this.maxPolyphony = 32; // Default starting high
    this.strumDuration = 0.5;

    this.xm1L = 0; this.ym1L = 0;
    this.xm1R = 0; this.ym1R = 0;
    this.panPhase = 0;

    this.port.onmessage = (e) => {
      const msg = e.data;
      if (msg.type === 'update_preset') {
        const { mode, data } = msg;
        if (mode && this.presets[mode]) {
            this.presets[mode] = this.normalizePreset(data);
        }
      } else if (msg.type === 'config') {
         if (msg.polyphony) this.maxPolyphony = msg.polyphony;
         if (msg.strumDuration) this.strumDuration = msg.strumDuration;
      } else if (msg.type === 'note_on') {
        this.triggerVoice(msg.id, msg.freq, msg.voiceType);
      } else if (msg.type === 'note_off') {
        this.releaseVoice(msg.id);
      } else if (msg.type === 'glide') {
        this.glideVoice(msg.id, msg.freq);
      } else if (msg.type === 'stop_all') {
         this.voices.forEach(v => v.hardStop());
      }
    };
  }

  normalizePreset(data) {
      return {
          osc1: { ...DUMMY_OSC_CONFIG, ...(data.osc1 || {}) },
          osc2: { ...DUMMY_OSC_CONFIG, ...(data.osc2 || {}) },
          osc3: { ...DUMMY_OSC_CONFIG, ...(data.osc3 || {}) },
          modMatrix: (data.modMatrix || []).map(row => ({
              ...row,
              amount: (Number.isFinite(row.amount) ? row.amount : 0) / 100.0
          })),
          gain: data.gain || 0.5,
          spread: data.spread || 0,
          stereoPanSpeed: data.stereoPanSpeed || 0,
          stereoPanDepth: data.stereoPanDepth || 0
      };
  }

  triggerVoice(id, freq, type) {
    // 1. If voice ID already active (re-trigger), use it
    for (let i = 0; i < this.voices.length; i++) {
        if (this.voices[i].active && this.voices[i].id === id) {
            this.voices[i].trigger(id, freq, type);
            return;
        }
    }

    let heldCount = 0;
    let physicallyFree = null;
    let quietestVoice = null;
    let minLevel = 1000.0;

    // Improved Stealing Candidate Logic
    let oldestReleased = null;
    let minReleaseTime = Number.MAX_VALUE;

    for (let i = 0; i < this.voices.length; i++) {
        const v = this.voices[i];

        if (!v.active) {
            if (!physicallyFree) physicallyFree = v;
            continue;
        }

        const level = v.getLevel();
        if (level < minLevel) {
            minLevel = level;
            quietestVoice = v;
        }

        if (v.releaseTime === 0) {
            // Actively held
            heldCount++;
        } else {
            // Releasing - track oldest
            if (v.releaseTime < minReleaseTime) {
                minReleaseTime = v.releaseTime;
                oldestReleased = v;
            }
        }
    }

    // STEALING LOGIC
    if (heldCount >= this.maxPolyphony) {
        if (oldestReleased) {
            oldestReleased.trigger(id, freq, type);
            return;
        }
        if (quietestVoice) {
            quietestVoice.trigger(id, freq, type);
            return;
        }
    }

    if (physicallyFree) {
        physicallyFree.trigger(id, freq, type);
    } else if (oldestReleased) {
        oldestReleased.trigger(id, freq, type);
    } else if (quietestVoice) {
        quietestVoice.trigger(id, freq, type);
    }
  }

  releaseVoice(id) {
    for (let i = 0; i < this.voices.length; i++) {
        if (this.voices[i].active && this.voices[i].id === id) {
            this.voices[i].release();
        }
    }
  }

  glideVoice(id, freq) {
    for (let i = 0; i < this.voices.length; i++) {
        if (this.voices[i].active && this.voices[i].id === id) {
             if (this.voices[i].type !== 'strum') {
                 this.voices[i].targetFreq = freq;
             }
        }
    }
  }

  process(inputs, outputs, parameters) {
    const output = outputs[0];
    const channelL = output[0];
    const channelR = output[1];
    if (!channelL) return true;
    const len = channelL.length;

    // Oversampling Constants
    const OVERSAMPLE = this.oversample;
    const workingRate = sampleRate * OVERSAMPLE;
    const dt = 1.0 / workingRate;

    const masterPreset = this.presets.normal;
    const panSpeed = (masterPreset.stereoPanSpeed !== undefined) ? masterPreset.stereoPanSpeed : 0.0;
    const panDepth = (masterPreset.stereoPanDepth !== undefined) ? masterPreset.stereoPanDepth : 0.0;

    for (let s = 0; s < len; s++) {
        let accL = 0.0;
        let accR = 0.0;

        // --- OVERSAMPLED LOOP ---
        for (let os = 0; os < OVERSAMPLE; os++) {
            let mixL = 0.0;
            let mixR = 0.0;

            this.panPhase += dt * panSpeed;
            if(this.panPhase > 1.0) this.panPhase -= 1.0;
            const autoPanVal = Math.sin(this.panPhase * TWO_PI) * panDepth;

            for (let i = 0; i < this.voices.length; i++) {
                const v = this.voices[i];
                if (v.active) {
                    if (v.type === 'strum' && v.releaseTime === 0) {
                        if (currentTime - v.startTime >= this.strumDuration) {
                            v.release();
                        }
                    }

                    const presetToUse = this.presets[v.type] || this.presets.normal;
                    const val = v.process(presetToUse, dt);

                    if (Number.isFinite(val)) {
                        const spreadAmount = presetToUse.spread || 0;
                        let p = v.panPos * spreadAmount;
                        p += autoPanVal;
                        p = Math.max(-1.0, Math.min(1.0, p));

                        const gainL = 0.5 * (1.0 - p);
                        const gainR = 0.5 * (1.0 + p);
                        const voiceGain = presetToUse.gain || 0.5;

                        mixL += val * gainL * voiceGain;
                        mixR += val * gainR * voiceGain;
                    } else {
                        v.hardStop();
                    }
                }
            }

            // --- NON-LINEARITIES (Apply at 2x rate to reduce aliasing) ---
            mixL *= 0.05; // Headroom
            mixR *= 0.05;

            // Soft Clipper
            mixL = Math.tanh(mixL * 0.8);
            mixR = Math.tanh(mixR * 0.8);

            accL += mixL;
            accR += mixR;
        }

        // --- DOWNSAMPLE (Decimation) ---
        // Simple averaging filter
        const outL = accL / OVERSAMPLE;
        const outR = accR / OVERSAMPLE;

        // --- DC BLOCKER (Linear, safe at 1x) ---
        const yL = outL - this.xm1L + 0.995 * this.ym1L;
        this.xm1L = outL;
        this.ym1L = yL;

        const yR = outR - this.xm1R + 0.995 * this.ym1R;
        this.xm1R = outR;
        this.ym1R = yR;

        channelL[s] = yL;
        if (channelR) channelR[s] = yR;
    }

    return true;
  }
}

registerProcessor('synth-processor', PrismaProcessor);
`;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { SynthPreset, WaveformType, OscillatorConfig, ModulationRow, ModSource, ModTarget, ReverbType, PresetState, PlayMode } from '../types';
import { PRESETS, REVERB_DEFAULTS } from '../constants';
import { useStore } from '../services/Store';

interface Props {
  presets: PresetState;
  onChange: (mode: PlayMode, p: SynthPreset) => void;
  isOpen: boolean;
  onClose: () => void;
}

// Envelope Graph Component
const EnvelopeGraph = ({ attack, decay, sustain, release }: { attack: number, decay: number, sustain: number, release: number }) => {
    const width = 200;
    const height = 60;
    const pad = 2;

    // Scale X logic: Attack/Decay/Release up to ~5s usually.
    // We want a non-linear visual scale so 0.1s is visible but 5s fits.
    // Simple approach: Fixed pixel widths relative to values with a cap.

    const scaleTime = (t: number) => Math.min(width / 3, Math.pow(t, 0.5) * 30);

    const xA = pad + scaleTime(attack);
    const xD = xA + scaleTime(decay);
    // Sustain is a level, but we give it some width to visualize "holding"
    const xS = xD + 30; 
    const xR = xS + scaleTime(release);

    // Y coords (inverted)
    const yBase = height - pad;
    const yPeak = pad;
    const ySus = yBase - (sustain * (height - 2 * pad));

    const path = `M ${pad} ${yBase} L ${xA} ${yPeak} L ${xD} ${ySus} L ${xS} ${ySus} L ${xR} ${yBase}`;

    return (
        <div className="w-full bg-slate-900 rounded border border-slate-700 h-[60px] overflow-hidden relative">
            <svg width="100%" height="100%" viewBox={`0 0 ${Math.max(width, xR + 10)} ${height}`} className="absolute top-0 left-0">
                <path d={path} fill="none" stroke="#6366f1" strokeWidth="2" />
                <path d={`${path} L ${xR} ${height} L ${pad} ${height} Z`} fill="rgba(99, 102, 241, 0.2)" stroke="none" />
            </svg>
            <div className="absolute bottom-1 right-2 text-[8px] text-slate-500 pointer-events-none">ADSR VISUALIZER</div>
        </div>
    );
};

// Matrix Grid Constants
const MATRIX_SOURCES: { id: ModSource, label: string }[] = [
    { id: 'lfo1', label: 'LFO 1' },
    { id: 'lfo2', label: 'LFO 2' },
    { id: 'lfo3', label: 'LFO 3' },
    { id: 'env1', label: 'ENV 1' },
    { id: 'env2', label: 'ENV 2' },
    { id: 'env3', label: 'ENV 3' },
];

const MATRIX_TARGETS: { id: ModTarget, label: string }[] = [
    { id: 'osc1_pitch', label: 'Pitch 1' },
    { id: 'osc1_cutoff', label: 'Cut 1' },
    { id: 'osc1_gain', label: 'Gain 1' },
    { id: 'osc1_res', label: 'Res 1' },
    { id: 'osc2_pitch', label: 'Pitch 2' },
    { id: 'osc2_cutoff', label: 'Cut 2' },
    { id: 'osc2_gain', label: 'Gain 2' },
    { id: 'osc2_res', label: 'Res 2' },
    { id: 'osc3_pitch', label: 'Pitch 3' },
    { id: 'osc3_cutoff', label: 'Cut 3' },
    { id: 'osc3_gain', label: 'Gain 3' },
    { id: 'osc3_res', label: 'Res 3' },
];

const SynthControls: React.FC<Props> = ({ presets, onChange, isOpen, onClose }) => {
  const [activeVoiceMode, setActiveVoiceMode] = useState<PlayMode>('normal');
  const [activeTab, setActiveTab] = useState<'osc1' | 'osc2' | 'osc3' | 'matrix' | 'fx'>('osc1');
  const { userBank, saveUserPatch } = useStore();

  // Show save dialog UI state
  const [isSaveMode, setIsSaveMode] = useState(false);
  const [saveSlotIndex, setSaveSlotIndex] = useState(0);
  const [saveName, setSaveName] = useState("");

  // Matrix Interaction State
  const [draggingCell, setDraggingCell] = useState<{ source: ModSource, target: ModTarget, startY: number, startVal: number } | null>(null);

  // Group presets by category
  const categorizedPresets = useMemo(() => {
      const groups: Record<string, SynthPreset[]> = {};
      PRESETS.forEach(p => {
          const cat = p.category || 'Uncategorized';
          if (!groups[cat]) groups[cat] = [];
          groups[cat].push(p);
      });
      return groups;
  }, []);

  if (!isOpen) return null;

  const currentPreset = presets[activeVoiceMode];

  const updateGlobal = (key: keyof SynthPreset, val: any) => {
    onChange(activeVoiceMode, { ...currentPreset, [key]: val });
  };

  const updateOsc = (oscKey: 'osc1' | 'osc2' | 'osc3', key: keyof OscillatorConfig, val: any) => {
      const newOsc = { ...currentPreset[oscKey], [key]: val };
      onChange(activeVoiceMode, { ...currentPreset, [oscKey]: newOsc });
  };

  const loadPreset = (p: SynthPreset) => {
      const cloned = JSON.parse(JSON.stringify(p));
      onChange(activeVoiceMode, cloned);
  };

  const handleResetToDefault = () => {
      const factory = PRESETS.find(p => p.name === currentPreset.name);
      if (factory) {
          loadPreset(factory);
      } else {
          const userP = userBank.find(p => p.name === currentPreset.name);
          if (userP) loadPreset(userP);
      }
  };

  const handleSaveToSlot = () => {
      if (saveName.trim() === "") return;
      const presetToSave = {
          ...currentPreset,
          name: saveName,
          id: `user-${Date.now()}` 
      };
      saveUserPatch(saveSlotIndex, presetToSave);
      setIsSaveMode(false);
  };

  const handleReverbTypeChange = (type: ReverbType) => {
      const defaults = REVERB_DEFAULTS[type];
      onChange(activeVoiceMode, {
          ...currentPreset,
          reverbType: type,
          reverbSize: defaults.size,
          reverbDamping: defaults.damping,
          reverbDiffusion: defaults.diffusion
      });
  };

  // Matrix Logic
  const getMatrixValue = (source: ModSource, target: ModTarget) => {
      const row = currentPreset.modMatrix?.find(r => r.source === source && r.target === target);
      return row ? row.amount : 0;
  };

  const setMatrixValue = (source: ModSource, target: ModTarget, amount: number) => {
      let newMatrix = [...(currentPreset.modMatrix || [])];
      const existingIdx = newMatrix.findIndex(r => r.source === source && r.target === target);

      if (amount === 0) {
          // Remove if zero to keep clean
          if (existingIdx !== -1) {
              newMatrix.splice(existingIdx, 1);
          }
      } else {
          if (existingIdx !== -1) {
              newMatrix[existingIdx] = { ...newMatrix[existingIdx], amount, enabled: true };
          } else {
              newMatrix.push({
                  id: `${source}-${target}-${Date.now()}`,
                  enabled: true,
                  source,
                  target,
                  amount
              });
          }
      }
      onChange(activeVoiceMode, { ...currentPreset, modMatrix: newMatrix });
  };

  const handleMatrixDragStart = (e: React.PointerEvent, source: ModSource, target: ModTarget) => {
      e.currentTarget.setPointerCapture(e.pointerId);
      setDraggingCell({
          source, target,
          startY: e.clientY,
          startVal: getMatrixValue(source, target)
      });
  };

  const handleMatrixDragMove = (e: React.PointerEvent) => {
      if (!draggingCell) return;
      const deltaY = draggingCell.startY - e.clientY; // Drag UP to increase
      const step = 1; // 1% per pixel
      let newVal = draggingCell.startVal + (deltaY * step);
      newVal = Math.max(-100, Math.min(100, Math.round(newVal)));

      if (newVal !== getMatrixValue(draggingCell.source, draggingCell.target)) {
          setMatrixValue(draggingCell.source, draggingCell.target, newVal);
      }
  };

  const handleMatrixDragEnd = () => {
      setDraggingCell(null);
  };

  const renderOscillatorTab = (oscKey: 'osc1' | 'osc2' | 'osc3', label: string) => {
      const config = currentPreset[oscKey];
      const canToggle = oscKey !== 'osc1'; 

      return (
          <div className="space-y-6 animate-in fade-in duration-300">
              <div className="flex justify-between items-center mb-4">
                  <h3 className="text-sm font-bold text-slate-300 uppercase">{label} Settings</h3>
                  {canToggle && (
                      <label className="flex items-center gap-2 cursor-pointer bg-slate-900/50 px-3 py-1 rounded border border-slate-600">
                          <input 
                              type="checkbox" 
                              checked={config.enabled} 
                              onChange={(e) => updateOsc(oscKey, 'enabled', e.target.checked)}
                              className="rounded border-slate-600 text-indigo-500 focus:ring-indigo-500"
                          />
                          <span className={`text-xs font-bold ${config.enabled ? 'text-white' : 'text-slate-500'}`}>
                              {config.enabled ? 'ENABLED' : 'DISABLED'}
                          </span>
                      </label>
                  )}
              </div>

              <div className={`space-y-6 ${!config.enabled ? 'opacity-40 pointer-events-none grayscale' : ''}`}>
                {/* Waveform & Mix */}
                <div className="p-3 bg-slate-900/50 rounded border border-slate-700">
                    <div className="grid grid-cols-4 gap-1 mb-4">
                        {Object.values(WaveformType).map(w => (
                            <button 
                                key={w}
                                onClick={() => updateOsc(oscKey, 'waveform', w)}
                                className={`px-1 py-1 text-[10px] rounded border ${config.waveform === w ? 'bg-indigo-600 border-indigo-500' : 'bg-slate-700 border-slate-600'}`}
                            >
                                {w}
                            </button>
                        ))}
                    </div>
                    <div className="space-y-3">
                        <div>
                            <label className="flex justify-between text-xs mb-1"><span>Mix (Gain)</span> <span>{(config.gain * 100).toFixed(0)}%</span></label>
                            <input type="range" min="0" max="1" step="0.01" value={config.gain} onChange={(e) => updateOsc(oscKey, 'gain', parseFloat(e.target.value))} className="w-full h-1 bg-indigo-500 rounded appearance-none" />
                        </div>
                        <div>
                            <label className="flex justify-between text-xs mb-1"><span>Coarse Detune</span> <span>{config.coarseDetune} cents</span></label>
                            <input type="range" min="-1200" max="1200" step="10" value={config.coarseDetune} onChange={(e) => updateOsc(oscKey, 'coarseDetune', parseInt(e.target.value))} className="w-full h-1 bg-indigo-500 rounded appearance-none" />
                        </div>
                        <div>
                            <label className="flex justify-between text-xs mb-1"><span>Fine Detune</span> <span>{config.fineDetune} cents</span></label>
                            <input type="range" min="-50" max="50" step="1" value={config.fineDetune} onChange={(e) => updateOsc(oscKey, 'fineDetune', parseInt(e.target.value))} className="w-full h-1 bg-indigo-400 rounded appearance-none" />
                        </div>
                    </div>
                </div>

                {/* Filter */}
                <div className="space-y-2">
                    <h4 className="text-xs font-bold text-slate-400">Filter</h4>
                    <div>
                        <label className="flex justify-between text-xs mb-1"><span>Cutoff</span> <span>{config.filterCutoff}Hz</span></label>
                        <input type="range" min="20" max="10000" step="10" value={config.filterCutoff} onChange={(e) => updateOsc(oscKey, 'filterCutoff', parseFloat(e.target.value))} className="w-full h-1 bg-yellow-600 rounded appearance-none" />
                    </div>
                    <div>
                        <label className="flex justify-between text-xs mb-1"><span>Resonance (Q)</span> <span>{config.filterResonance.toFixed(1)}</span></label>
                        <input type="range" min="0" max="20" step="0.1" value={config.filterResonance} onChange={(e) => updateOsc(oscKey, 'filterResonance', parseFloat(e.target.value))} className="w-full h-1 bg-yellow-600 rounded appearance-none" />
                    </div>
                </div>

                {/* Envelope */}
                 <div className="space-y-2">
                    <div className="flex justify-between items-center">
                        <h4 className="text-xs font-bold text-slate-400">Envelope</h4>
                        <span className="text-[10px] text-slate-500 italic">Adjust sliders to shape</span>
                    </div>

                    {/* Visualizer */}
                    <EnvelopeGraph 
                        attack={config.attack} 
                        decay={config.decay} 
                        sustain={config.sustain} 
                        release={config.release} 
                    />

                    <div className="grid grid-cols-2 gap-3 pt-2">
                        <div>
                            <label className="flex justify-between text-xs mb-1"><span>Att: {config.attack.toFixed(2)}s</span></label>
                            <input type="range" min="0.01" max="5.0" step="0.01" value={config.attack} onChange={(e) => updateOsc(oscKey, 'attack', parseFloat(e.target.value))} className="w-full h-1 bg-indigo-900 rounded appearance-none" />
                        </div>
                        <div>
                            <label className="flex justify-between text-xs mb-1"><span>Dec: {config.decay.toFixed(2)}s</span></label>
                            <input type="range" min="0.01" max="5.0" step="0.01" value={config.decay} onChange={(e) => updateOsc(oscKey, 'decay', parseFloat(e.target.value))} className="w-full h-1 bg-indigo-900 rounded appearance-none" />
                        </div>
                        <div>
                            <label className="flex justify-between text-xs mb-1"><span>Sus: {config.sustain.toFixed(2)}</span></label>
                            <input type="range" min="0.0" max="1.0" step="0.01" value={config.sustain} onChange={(e) => updateOsc(oscKey, 'sustain', parseFloat(e.target.value))} className="w-full h-1 bg-indigo-900 rounded appearance-none" />
                        </div>
                        <div>
                            <label className="flex justify-between text-xs mb-1"><span>Rel: {config.release.toFixed(2)}s</span></label>
                            <input type="range" min="0.01" max="8.0" step="0.01" value={config.release} onChange={(e) => updateOsc(oscKey, 'release', parseFloat(e.target.value))} className="w-full h-1 bg-indigo-900 rounded appearance-none" />
                        </div>
                    </div>
                </div>

                {/* LFO */}
                <div className="p-3 bg-slate-900/50 rounded border border-slate-700">
                    <h3 className="text-xs font-bold text-slate-300 uppercase mb-3">LFO</h3>
                    <div className="flex gap-2 mb-4 text-[10px]">
                        {(['none', 'pitch', 'filter', 'tremolo'] as const).map(target => (
                             <button 
                                key={target}
                                onClick={() => updateOsc(oscKey, 'lfoTarget', target)} 
                                className={`flex-1 py-1 rounded border capitalize ${config.lfoTarget === target ? 'bg-pink-600 border-pink-500' : 'bg-slate-700 border-slate-600'}`}
                             >
                                 {target}
                             </button>
                        ))}
                    </div>
                    <div className="space-y-2">
                        <div>
                            <label className="flex justify-between text-xs mb-1"><span>Rate</span> <span>{config.lfoRate} Hz</span></label>
                            <input type="range" min="0.1" max="20" step="0.1" value={config.lfoRate} onChange={(e) => updateOsc(oscKey, 'lfoRate', parseFloat(e.target.value))} className="w-full h-1 bg-pink-500 rounded appearance-none" />
                        </div>
                        <div>
                            <label className="flex justify-between text-xs mb-1"><span>Depth</span> <span>{config.lfoDepth}</span></label>
                            <input type="range" min="0" max="100" step="1" value={config.lfoDepth} onChange={(e) => updateOsc(oscKey, 'lfoDepth', parseFloat(e.target.value))} className="w-full h-1 bg-pink-500 rounded appearance-none" />
                        </div>
                    </div>
                </div>
            </div>
          </div>
      );
  };

  return (
    <div className="fixed top-0 right-0 h-full w-[450px] bg-slate-800/95 backdrop-blur shadow-2xl z-[200] transform transition-transform p-0 overflow-hidden border-l border-slate-700 flex flex-col">
        {/* Header */}
        <div className="flex justify-between items-center p-6 pb-2">
            <h2 className="text-xl font-bold">Synth Engine</h2>
            <button onClick={onClose} className="text-slate-400 hover:text-white">Close</button>
        </div>

        {/* VOICE MODE TABS (Normal / Latch / Strum) */}
        <div className="flex border-b border-slate-700 bg-slate-900/80 mx-4 mt-2 rounded-t-lg overflow-hidden">
            {(['normal', 'latch', 'strum'] as PlayMode[]).map(mode => (
                <button
                    key={mode}
                    onClick={() => setActiveVoiceMode(mode)}
                    className={`flex-1 py-3 text-xs font-bold uppercase transition border-b-2 ${
                        activeVoiceMode === mode 
                        ? 'border-indigo-500 text-indigo-400 bg-slate-800' 
                        : 'border-transparent text-slate-500 hover:bg-slate-800/50'
                    }`}
                >
                    {mode}
