                          ))}
                      </div>

                       <div className={`bg-slate-900/40 p-3 rounded border border-slate-700/50 space-y-3 transition-opacity ${settings.scaleMode !== 'ji-lattice' ? 'opacity-50 pointer-events-none' : ''}`}>
