                                      {settings.backgroundImageData && (<div className="w-10 h-10 rounded border border-slate-500 overflow-hidden bg-black"><img src={settings.backgroundImageData} alt="Preview" className="w-full h-full object-cover" /></div>)}
                                  </div>
