// Helper component for Validated Numeric Input using Derived State pattern
const NumberInput = ({
    value,
    min,
    max,
    onChange,
    suffix = "",
    className = ""
}: {
    value: number;
    min: number;
    max: number;
    onChange: (val: number) => void;
    suffix?: string;
    className?: string;
}) => {
    // 1. Initialize State
    const [text, setText] = useState(value !== undefined && !isNaN(value) ? value.toString() : min.toString());
    const [prevValue, setPrevValue] = useState(value);
    const [error, setError] = useState<string | null>(null);

    // 2. Derived State Pattern (Update state during render if prop changes)
    if (value !== prevValue && value !== undefined && !isNaN(value)) {
        // Only update text if the numeric value actually changed to something new
        // and doesn't match the current text interpretation (prevents cursor jumping if user is typing "1." or "1.0")
        const currentNum = parseFloat(text);
        if (Math.abs(currentNum - value) > 0.0001) {
             setText(value.toString());
             setError(null);
        }
        setPrevValue(value);
    }

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const val = e.target.value;
        if (val !== '' && !/^[\d.]+$/.test(val)) return;

        setText(val);

        if (val === '') return; 

        const num = parseFloat(val);
        if (isNaN(num)) return;

        if (num < min || num > max) {
            setError(`Range: ${min}-${max}`);
        } else {
            setError(null);
            // Defer the parent update to blur or valid input to avoid rapid re-renders if desired,
            // but for responsiveness we call it here.
            onChange(num);
        }
    };

    const handleBlur = () => {
        const num = parseFloat(text);
        // Reset to prop value if invalid on blur
        if (text === '' || isNaN(num) || error) {
            setText(value.toString());
            setError(null);
        }
    };

    return (
        <div className="flex flex-col flex-grow">
            <div className="relative">
                <input 
                    type="text" 
                    inputMode="decimal"
                    value={text}
                    onChange={handleChange}
                    onBlur={handleBlur}
                    className={`w-full bg-slate-700 rounded p-2 text-sm text-white border border-slate-600 focus:outline-none focus:border-blue-500 transition-colors ${className} ${error ? 'border-red-500 focus:border-red-500' : ''}`}
                />
                {suffix && <span className="absolute right-3 top-2 text-sm text-slate-400 pointer-events-none">{suffix}</span>}
            </div>
            {error && <span className="text-[10px] text-red-400 mt-1 font-bold animate-pulse">{error}</span>}
        </div>
    );
};

