// Hardcoded palettes for procedural backgrounds
const PRESET_PALETTES: Record<string, LimitColorMap> = {
    'charcoal': {
        1: '#FFFFFF', 3: '#D4D4D8', 5: '#A1A1AA', 7: '#71717A', 11: '#52525B', 13: '#3F3F46'
    },
