const SynthControls: React.FC<Props> = ({ presets, onChange, isOpen, onClose }) => {
  const [activeVoiceMode, setActiveVoiceMode] = useState<PlayMode>('normal');
  const [activeTab, setActiveTab] = useState<'osc1' | 'osc2' | 'osc3' | 'matrix' | 'fx' | 'arp'>('osc1');
  const { userBank, saveUserPatch } = useStore();

  const [isSaveMode, setIsSaveMode] = useState(false);
  const [saveSlotIndex, setSaveSlotIndex] = useState(0);
  const [saveName, setSaveName] = useState("");
  const [draggingCell, setDraggingCell] = useState<{ source: ModSource, target: ModTarget, startY: number, startVal: number } | null>(null);

  const categorizedPresets = useMemo(() => {
      const groups: Record<string, SynthPreset[]> = {};
      PRESETS.forEach(p => {
          const cat = p.category || 'Uncategorized';
          if (!groups[cat]) groups[cat] = [];
          groups[cat].push(p);
      });
      return groups;
  }, []);

  if (!isOpen) return null;

  const currentPreset = presets[activeVoiceMode];

  const updateGlobal = (key: keyof SynthPreset, val: any) => {
    onChange(activeVoiceMode, { ...currentPreset, [key]: val });
  };

  const updateArp = (key: keyof import('../types').ArpConfig, val: any) => {
      const currentArp = currentPreset.arpConfig || { direction: 'order', division: '1/8', octaves: 1, gate: 0.8, swing: 0 };
      const newArp = { ...currentArp, [key]: val };
      onChange(activeVoiceMode, { ...currentPreset, arpConfig: newArp });
  };

  const updateOsc = (oscKey: 'osc1' | 'osc2' | 'osc3', key: keyof OscillatorConfig, val: any) => {
      const newOsc = { ...currentPreset[oscKey], [key]: val };
      onChange(activeVoiceMode, { ...currentPreset, [oscKey]: newOsc });
  };

  const loadPreset = (p: SynthPreset) => {
      const cloned = JSON.parse(JSON.stringify(p));
      onChange(activeVoiceMode, cloned);
  };

  const handleResetToDefault = () => {
      const factory = PRESETS.find(p => p.name === currentPreset.name);
      if (factory) {
          loadPreset(factory);
      } else {
          const userP = userBank.find(p => p.name === currentPreset.name);
          if (userP) loadPreset(userP);
      }
  };

  const handleSaveToSlot = () => {
      if (saveName.trim() === "") return;
      const presetToSave = { ...currentPreset, name: saveName, id: `user-${Date.now()}` };
      saveUserPatch(saveSlotIndex, presetToSave);
      setIsSaveMode(false);
  };

  const handleReverbTypeChange = (type: ReverbType) => {
      const defaults = REVERB_DEFAULTS[type];
      onChange(activeVoiceMode, {
          ...currentPreset,
          reverbType: type,
          reverbSize: defaults.size,
          reverbDamping: defaults.damping,
          reverbDiffusion: defaults.diffusion
      });
  };

  const getMatrixValue = (source: ModSource, target: ModTarget) => {
      const row = currentPreset.modMatrix?.find(r => r.source === source && r.target === target);
      return row ? row.amount : 0;
  };

  const setMatrixValue = (source: ModSource, target: ModTarget, amount: number) => {
      let newMatrix = [...(currentPreset.modMatrix || [])];
      const existingIdx = newMatrix.findIndex(r => r.source === source && r.target === target);
      if (amount === 0) {
          if (existingIdx !== -1) newMatrix.splice(existingIdx, 1);
      } else {
          if (existingIdx !== -1) {
              newMatrix[existingIdx] = { ...newMatrix[existingIdx], amount, enabled: true };
          } else {
              newMatrix.push({ id: `${source}-${target}-${Date.now()}`, enabled: true, source, target, amount });
          }
      }
      onChange(activeVoiceMode, { ...currentPreset, modMatrix: newMatrix });
  };

  const handleMatrixDragStart = (e: React.PointerEvent, source: ModSource, target: ModTarget) => {
      e.currentTarget.setPointerCapture(e.pointerId);
      setDraggingCell({ source, target, startY: e.clientY, startVal: getMatrixValue(source, target) });
  };

  const handleMatrixDragMove = (e: React.PointerEvent) => {
      if (!draggingCell) return;
      const deltaY = draggingCell.startY - e.clientY; 
      let newVal = draggingCell.startVal + (deltaY * 1);
      newVal = Math.max(-100, Math.min(100, Math.round(newVal)));
      if (newVal !== getMatrixValue(draggingCell.source, draggingCell.target)) {
          setMatrixValue(draggingCell.source, draggingCell.target, newVal);
      }
  };

  const renderOscillatorTab = (oscKey: 'osc1' | 'osc2' | 'osc3', label: string) => {
      const config = currentPreset[oscKey];
      const canToggle = oscKey !== 'osc1'; 
      return (
          <div className="space-y-6 animate-in fade-in duration-300">
              <div className="flex justify-between items-center mb-4">
                  <h3 className="text-sm font-bold text-slate-300 uppercase">{label} Settings</h3>
                  {canToggle && (
                      <label className="flex items-center gap-2 cursor-pointer bg-slate-900/50 px-3 py-1 rounded border border-slate-600">
                          <input type="checkbox" checked={config.enabled} onChange={(e) => updateOsc(oscKey, 'enabled', e.target.checked)} className="rounded border-slate-600 text-indigo-500 focus:ring-indigo-500" />
                          <span className={`text-xs font-bold ${config.enabled ? 'text-white' : 'text-slate-500'}`}>{config.enabled ? 'ENABLED' : 'DISABLED'}</span>
                      </label>
                  )}
              </div>
              <div className={`space-y-6 ${!config.enabled ? 'opacity-40 pointer-events-none grayscale' : ''}`}>
                <div className="p-3 bg-slate-900/50 rounded border border-slate-700">
                    <div className="grid grid-cols-4 gap-1 mb-4">
                        {Object.values(WaveformType).map(w => (
                            <button key={w} onClick={() => updateOsc(oscKey, 'waveform', w)} className={`px-1 py-1 text-[10px] rounded border ${config.waveform === w ? 'bg-indigo-600 border-indigo-500' : 'bg-slate-700 border-slate-600'}`}>{w}</button>
                        ))}
                    </div>
                    <div className="space-y-3">
                        <div>
                            <label className="flex justify-between text-xs mb-1"><span>Mix</span> <span>{(config.gain * 100).toFixed(0)}%</span></label>
                            <input type="range" min="0" max="1" step="0.01" value={config.gain} onChange={(e) => updateOsc(oscKey, 'gain', parseFloat(e.target.value))} className="w-full h-1 bg-indigo-500 rounded appearance-none" />
                        </div>
                        <div>
                            <label className="flex justify-between text-xs mb-1"><span>Coarse</span> <span>{config.coarseDetune} cents</span></label>
                            <input type="range" min="-1200" max="1200" step="10" value={config.coarseDetune} onChange={(e) => updateOsc(oscKey, 'coarseDetune', parseInt(e.target.value))} className="w-full h-1 bg-indigo-500 rounded appearance-none" />
                        </div>
                        <div>
                            <label className="flex justify-between text-xs mb-1"><span>Fine</span> <span>{config.fineDetune} cents</span></label>
                            <input type="range" min="-50" max="50" step="1" value={config.fineDetune} onChange={(e) => updateOsc(oscKey, 'fineDetune', parseInt(e.target.value))} className="w-full h-1 bg-indigo-400 rounded appearance-none" />
                        </div>
                    </div>
                </div>
                <div className="space-y-2">
                    <h4 className="text-xs font-bold text-slate-400">Filter</h4>
                    <div>
                        <label className="flex justify-between text-xs mb-1"><span>Cutoff</span> <span>{config.filterCutoff}Hz</span></label>
                        <input type="range" min="20" max="10000" step="10" value={config.filterCutoff} onChange={(e) => updateOsc(oscKey, 'filterCutoff', parseFloat(e.target.value))} className="w-full h-1 bg-yellow-600 rounded appearance-none" />
                    </div>
                    <div>
                        <label className="flex justify-between text-xs mb-1"><span>Resonance</span> <span>{config.filterResonance.toFixed(1)}</span></label>
                        <input type="range" min="0" max="20" step="0.1" value={config.filterResonance} onChange={(e) => updateOsc(oscKey, 'filterResonance', parseFloat(e.target.value))} className="w-full h-1 bg-yellow-600 rounded appearance-none" />
                    </div>
                </div>
                <div className="space-y-2">
                    <h4 className="text-xs font-bold text-slate-400">Envelope</h4>
                    <EnvelopeGraph attack={config.attack} decay={config.decay} sustain={config.sustain} release={config.release} />
                    <div className="grid grid-cols-2 gap-3 pt-2">
                        <div><label className="flex justify-between text-xs mb-1"><span>A: {config.attack.toFixed(2)}s</span></label><input type="range" min="0.01" max="5.0" step="0.01" value={config.attack} onChange={(e) => updateOsc(oscKey, 'attack', parseFloat(e.target.value))} className="w-full h-1 bg-indigo-900 rounded appearance-none" /></div>
                        <div><label className="flex justify-between text-xs mb-1"><span>D: {config.decay.toFixed(2)}s</span></label><input type="range" min="0.01" max="5.0" step="0.01" value={config.decay} onChange={(e) => updateOsc(oscKey, 'decay', parseFloat(e.target.value))} className="w-full h-1 bg-indigo-900 rounded appearance-none" /></div>
                        <div><label className="flex justify-between text-xs mb-1"><span>S: {config.sustain.toFixed(2)}</span></label><input type="range" min="0.0" max="1.0" step="0.01" value={config.sustain} onChange={(e) => updateOsc(oscKey, 'sustain', parseFloat(e.target.value))} className="w-full h-1 bg-indigo-900 rounded appearance-none" /></div>
                        <div><label className="flex justify-between text-xs mb-1"><span>R: {config.release.toFixed(2)}s</span></label><input type="range" min="0.01" max="8.0" step="0.01" value={config.release} onChange={(e) => updateOsc(oscKey, 'release', parseFloat(e.target.value))} className="w-full h-1 bg-indigo-900 rounded appearance-none" /></div>
                    </div>
                </div>
                <div className="p-3 bg-slate-900/50 rounded border border-slate-700">
                    <h3 className="text-xs font-bold text-slate-300 uppercase mb-3">LFO</h3>
                    <div className="flex gap-2 mb-4 text-[10px]">
                        {(['none', 'pitch', 'filter', 'tremolo'] as const).map(target => (
                             <button key={target} onClick={() => updateOsc(oscKey, 'lfoTarget', target)} className={`flex-1 py-1 rounded border capitalize ${config.lfoTarget === target ? 'bg-pink-600 border-pink-500' : 'bg-slate-700 border-slate-600'}`}>{target}</button>
                        ))}
                    </div>
                    <div className="space-y-2">
                        <div><label className="flex justify-between text-xs mb-1"><span>Rate</span> <span>{config.lfoRate} Hz</span></label><input type="range" min="0.1" max="20" step="0.1" value={config.lfoRate} onChange={(e) => updateOsc(oscKey, 'lfoRate', parseFloat(e.target.value))} className="w-full h-1 bg-pink-500 rounded appearance-none" /></div>
                        <div><label className="flex justify-between text-xs mb-1"><span>Depth</span> <span>{config.lfoDepth}</span></label><input type="range" min="0" max="100" step="1" value={config.lfoDepth} onChange={(e) => updateOsc(oscKey, 'lfoDepth', parseFloat(e.target.value))} className="w-full h-1 bg-pink-500 rounded appearance-none" /></div>
                    </div>
                </div>
            </div>
          </div>
      );
  };

  const arpConfig = currentPreset.arpConfig || { direction: 'order', division: '1/8', octaves: 1, gate: 0.8, swing: 0 };

  return (
    <div className="fixed top-0 right-0 h-full w-[450px] bg-slate-800/95 backdrop-blur shadow-2xl z-[200] transform transition-transform p-0 overflow-hidden border-l border-slate-700 flex flex-col">
        <div className="flex justify-between items-center p-6 pb-2">
            <h2 className="text-xl font-bold">Synth Engine</h2>
            <button onClick={onClose} className="text-slate-400 hover:text-white">Close</button>
        </div>

        <div className="flex border-b border-slate-700 bg-slate-900/80 mx-4 mt-2 rounded-t-lg overflow-hidden">
            {(['normal', 'latch', 'strum', 'arpeggio'] as PlayMode[]).map(mode => (
                <button
                    key={mode}
                    onClick={() => setActiveVoiceMode(mode)}
                    className={`flex-1 py-3 text-xs font-bold uppercase transition border-b-2 ${activeVoiceMode === mode ? 'border-indigo-500 text-indigo-400 bg-slate-800' : 'border-transparent text-slate-500 hover:bg-slate-800/50'}`}
                >
                    {mode}
                </button>
            ))}
        </div>

        {!isSaveMode ? (
            <div className="px-6 py-4 bg-slate-800 border-b border-slate-700 space-y-3">
                <div>
                    <label className="block text-[10px] text-slate-400 mb-1 uppercase font-bold tracking-wider">Active Patch</label>
                    <div className="relative">
                        <select 
                            value={currentPreset.name}
                            onChange={(e) => {
                                let p = PRESETS.find(pr => pr.name === e.target.value);
                                if (!p) p = userBank.find(pr => pr.name === e.target.value);
                                if (p) loadPreset(p);
                            }}
                            className="w-full bg-slate-900 border border-slate-600 rounded p-2 text-sm text-white appearance-none focus:border-indigo-500 focus:outline-none"
                        >
                            {Object.keys(categorizedPresets).map(cat => (
                                <optgroup key={cat} label={cat}>{categorizedPresets[cat].map(p => (<option key={p.id} value={p.name}>{p.name}</option>))}</optgroup>
                            ))}
                            <optgroup label="User Bank">{userBank.map((p, idx) => (<option key={`user-${idx}`} value={p.name}>{p.name}</option>))}</optgroup>
                        </select>
                    </div>
                </div>
                <div className="flex gap-2">
                    <button onClick={() => { setSaveName(currentPreset.name); setIsSaveMode(true); }} className="flex-1 py-1.5 bg-indigo-700 hover:bg-indigo-600 text-indigo-100 text-xs font-bold rounded transition border border-indigo-500">Save to Slot</button>
                    <button onClick={handleResetToDefault} className="flex-1 py-1.5 bg-yellow-700 hover:bg-yellow-600 text-yellow-100 text-xs font-bold rounded transition border border-yellow-500">Reset to Default</button>
                </div>
            </div>
        ) : (
            <div className="px-6 py-4 bg-indigo-900/20 border-b border-indigo-500/30">
                <div className="flex justify-between items-center mb-2">
                    <label className="text-[10px] text-indigo-300 font-bold uppercase">Save Current Patch</label>
                    <button onClick={() => setIsSaveMode(false)} className="text-xs text-slate-400 hover:text-white">Cancel</button>
                </div>
                <input type="text" value={saveName} onChange={(e) => setSaveName(e.target.value)} placeholder="Patch Name" className="w-full bg-slate-900 border border-indigo-500 rounded p-2 text-sm mb-2 text-white" />
                <select value={saveSlotIndex} onChange={(e) => setSaveSlotIndex(parseInt(e.target.value))} className="w-full bg-slate-900 border border-slate-600 rounded p-2 text-sm text-white mb-3">
                    {userBank.map((p, idx) => (<option key={idx} value={idx}>Slot {idx+1}: {p.name}</option>))}
                </select>
                <button onClick={handleSaveToSlot} className="w-full py-2 bg-indigo-600 hover:bg-indigo-500 text-white font-bold rounded text-xs transition">Confirm Save</button>
            </div>
        )}

        <div className="flex border-b border-slate-700 bg-slate-900/50">
            {(['osc1', 'osc2', 'osc3'] as const).map(osc => (
                 <button key={osc} onClick={() => setActiveTab(osc)} className={`flex-1 py-3 text-[10px] font-bold uppercase transition flex flex-col items-center justify-center gap-1 ${activeTab === osc ? 'text-indigo-400 border-b-2 border-indigo-400 bg-slate-800' : 'text-slate-500 hover:text-slate-300'}`}>
                    <span>{osc.replace('osc', 'Osc ')}</span>
                    <span className={`w-1.5 h-1.5 rounded-full ${currentPreset[osc].enabled ? 'bg-green-500 shadow-[0_0_5px_rgba(34,197,94,0.8)]' : 'bg-slate-700'}`}></span>
                </button>
            ))}
             <button onClick={() => setActiveTab('matrix')} className={`flex-1 py-3 text-[10px] font-bold uppercase transition flex flex-col items-center justify-center gap-1 ${activeTab === 'matrix' ? 'text-purple-400 border-b-2 border-purple-400 bg-slate-800' : 'text-slate-500 hover:text-slate-300'}`}>
                <span>Mods</span>
                <span className={`w-1.5 h-1.5 rounded-full ${(currentPreset.modMatrix?.length || 0) > 0 ? 'bg-purple-500 shadow-[0_0_5px_rgba(168,85,247,0.8)]' : 'bg-slate-700'}`}></span>
            </button>
             <button onClick={() => setActiveTab('fx')} className={`flex-1 py-3 text-[10px] font-bold uppercase transition flex flex-col items-center justify-center gap-1 ${activeTab === 'fx' ? 'text-green-400 border-b-2 border-green-400 bg-slate-800' : 'text-slate-500 hover:text-slate-300'}`}>
                <span>FX</span>
                <span className="w-1.5 h-1.5 rounded-full bg-green-500 shadow-[0_0_5px_rgba(34,197,94,0.8)]"></span>
            </button>
             <button onClick={() => setActiveTab('arp')} className={`flex-1 py-3 text-[10px] font-bold uppercase transition flex flex-col items-center justify-center gap-1 ${activeTab === 'arp' ? 'text-red-400 border-b-2 border-red-400 bg-slate-800' : 'text-slate-500 hover:text-slate-300'}`}>
                <span>Arp</span>
                <span className={`w-1.5 h-1.5 rounded-full bg-red-500 shadow-[0_0_5px_rgba(239,68,68,0.8)]`}></span>
            </button>
        </div>

        <div className="flex-1 overflow-y-auto p-6 scrollbar-thin scrollbar-thumb-slate-700" onPointerUp={() => setDraggingCell(null)} onPointerLeave={() => setDraggingCell(null)} onPointerMove={handleMatrixDragMove}>
            {activeTab === 'osc1' && renderOscillatorTab('osc1', 'Oscillator 1')}
            {activeTab === 'osc2' && renderOscillatorTab('osc2', 'Oscillator 2')}
            {activeTab === 'osc3' && renderOscillatorTab('osc3', 'Oscillator 3')}

            {activeTab === 'matrix' && (
                <div className="space-y-4 animate-in fade-in duration-300">
                    <div className="flex justify-between items-center mb-2"><h3 className="text-sm font-bold text-purple-300 uppercase">Modulation Grid</h3><div className="text-[10px] text-slate-500 italic">Drag vertical on cells to adjust amount</div></div>
                    <div className="overflow-x-auto pb-4"><div className="min-w-[600px]"><div className="grid grid-cols-[60px_repeat(12,1fr)] gap-1">
                        <div className="text-[10px] font-bold text-slate-500">SRC / DST</div>{MATRIX_TARGETS.map(t => (<div key={t.id} className="text-[9px] font-bold text-slate-400 text-center uppercase rotate-0 whitespace-nowrap overflow-hidden text-ellipsis" title={t.label}>{t.label.replace('Osc', 'O').replace('Pitch', 'P').replace('Cut', 'C').replace('Gain', 'G').replace('Res', 'Q')}</div>))}
                        {MATRIX_SOURCES.map(source => (<React.Fragment key={source.id}><div className="text-[10px] font-bold text-purple-400 flex items-center h-8 bg-slate-900/50 px-1 rounded-l">{source.label}</div>{MATRIX_TARGETS.map(target => { const amount = getMatrixValue(source.id, target.id); const isActive = amount !== 0; return (<div key={`${source.id}-${target.id}`} className={`h-8 border border-slate-700 rounded flex flex-col justify-end items-center relative overflow-hidden cursor-ns-resize group ${isActive ? 'bg-purple-900/30 border-purple-500/50' : 'bg-slate-800 hover:bg-slate-700'}`} onPointerDown={(e) => handleMatrixDragStart(e, source.id, target.id)}>{isActive && (<div className={`absolute bottom-0 left-0 w-full transition-all ${amount > 0 ? 'bg-purple-500' : 'bg-orange-500'}`} style={{ height: `${Math.abs(amount)}%`, opacity: 0.4 }} />)}<span className={`text-[9px] z-10 font-mono ${isActive ? 'text-white font-bold' : 'text-transparent group-hover:text-slate-500'}`}>{amount !== 0 ? amount : '-'}</span></div>); })}</React.Fragment>))}
                    </div></div></div>
                </div>
            )}

            {activeTab === 'fx' && (
                 <div className="space-y-6 animate-in fade-in duration-300">
                    <h3 className="text-sm font-bold text-slate-300 uppercase mb-2">Global Effects ({activeVoiceMode})</h3>
                    <div><label className="flex justify-between text-xs mb-1 font-bold"><span>Master Gain</span> <span>{(currentPreset.gain * 100).toFixed(0)}%</span></label><input type="range" min="0.0" max="1.0" step="0.01" value={currentPreset.gain} onChange={(e) => updateGlobal('gain', parseFloat(e.target.value))} className="w-full h-1 bg-green-500 rounded appearance-none" /></div>
                    <div className="p-3 bg-slate-900/50 rounded border border-slate-700 space-y-4">
                         <h3 className="text-xs font-bold text-cyan-300 uppercase">Stereo & Pan</h3>
                         <div><label className="flex justify-between text-xs mb-1"><span>Stereo Width</span> <span>{((currentPreset.spread || 0) * 100).toFixed(0)}%</span></label><input type="range" min="0" max="1" step="0.01" value={currentPreset.spread || 0} onChange={(e) => updateGlobal('spread', parseFloat(e.target.value))} className="w-full h-1 bg-cyan-600 rounded appearance-none" /></div>
                         <div><label className="flex justify-between text-xs mb-1"><span>Auto-Pan Rate</span> <span>{(currentPreset.stereoPanSpeed || 0).toFixed(2)} Hz</span></label><input type="range" min="0" max="10" step="0.1" value={currentPreset.stereoPanSpeed || 0} onChange={(e) => updateGlobal('stereoPanSpeed', parseFloat(e.target.value))} className="w-full h-1 bg-cyan-600 rounded appearance-none" /></div>
                         <div><label className="flex justify-between text-xs mb-1"><span>Auto-Pan Depth</span> <span>{((currentPreset.stereoPanDepth || 0) * 100).toFixed(0)}%</span></label><input type="range" min="0" max="1" step="0.01" value={currentPreset.stereoPanDepth || 0} onChange={(e) => updateGlobal('stereoPanDepth', parseFloat(e.target.value))} className="w-full h-1 bg-cyan-600 rounded appearance-none" /></div>
                    </div>
                    <div className="p-3 bg-slate-900/50 rounded border border-slate-700 space-y-4">
                         <h3 className="text-xs font-bold text-teal-300 uppercase">Delay</h3>
                         <div><label className="flex justify-between text-xs mb-1"><span>Delay Mix</span> <span>{(currentPreset.delayMix * 100).toFixed(0)}%</span></label><input type="range" min="0" max="1" step="0.01" value={currentPreset.delayMix} onChange={(e) => updateGlobal('delayMix', parseFloat(e.target.value))} className="w-full h-1 bg-teal-600 rounded appearance-none" /></div>
                         <div><label className="flex justify-between text-xs mb-1"><span>Time</span> <span>{currentPreset.delayTime.toFixed(2)}s</span></label><input type="range" min="0" max="2" step="0.05" value={currentPreset.delayTime} onChange={(e) => updateGlobal('delayTime', parseFloat(e.target.value))} className="w-full h-1 bg-teal-600 rounded appearance-none" /></div>
                         <div><label className="flex justify-between text-xs mb-1"><span>Feedback</span> <span>{(currentPreset.delayFeedback * 100).toFixed(0)}%</span></label><input type="range" min="0" max="0.9" step="0.01" value={currentPreset.delayFeedback} onChange={(e) => updateGlobal('delayFeedback', parseFloat(e.target.value))} className="w-full h-1 bg-teal-600 rounded appearance-none" /></div>
                    </div>
                    <div className="p-3 bg-slate-900/50 rounded border border-slate-700 space-y-4">
                         <h3 className="text-xs font-bold text-blue-300 uppercase">Reverb</h3>
                         <select value={currentPreset.reverbType || 'room'} onChange={(e) => handleReverbTypeChange(e.target.value as ReverbType)} className="w-full bg-slate-700 text-xs rounded p-1 border border-slate-600 capitalize" disabled={activeVoiceMode !== 'normal'}>{(['room', 'hall', 'cathedral', 'plate', 'shimmer'] as ReverbType[]).map(type => (<option key={type} value={type}>{type}</option>))}</select>
                         <div><label className="flex justify-between text-xs mb-1"><span>Mix</span> <span>{(currentPreset.reverbMix * 100).toFixed(0)}%</span></label><input type="range" min="0" max="1" step="0.01" value={currentPreset.reverbMix} onChange={(e) => updateGlobal('reverbMix', parseFloat(e.target.value))} className="w-full h-1 bg-blue-600 rounded appearance-none" /></div>
                         <div><label className="flex justify-between text-xs mb-1"><span>Size</span> <span>{(currentPreset.reverbSize || 2.5).toFixed(1)}s</span></label><input type="range" min="0.1" max="10.0" step="0.1" value={currentPreset.reverbSize || 2.5} onChange={(e) => updateGlobal('reverbSize', parseFloat(e.target.value))} disabled={activeVoiceMode !== 'normal'} className={`w-full h-1 rounded appearance-none ${activeVoiceMode !== 'normal' ? 'bg-slate-600' : 'bg-blue-600'}`} /></div>
                         <div><label className="flex justify-between text-xs mb-1"><span>Damping</span> <span>{((currentPreset.reverbDamping || 0.5) * 100).toFixed(0)}%</span></label><input type="range" min="0" max="1" step="0.01" value={currentPreset.reverbDamping || 0.5} onChange={(e) => updateGlobal('reverbDamping', parseFloat(e.target.value))} disabled={activeVoiceMode !== 'normal'} className={`w-full h-1 rounded appearance-none ${activeVoiceMode !== 'normal' ? 'bg-slate-600' : 'bg-blue-600'}`} /></div>
                         <div><label className="flex justify-between text-xs mb-1"><span>Diffusion</span> <span>{((currentPreset.reverbDiffusion || 0.8) * 100).toFixed(0)}%</span></label><input type="range" min="0" max="1" step="0.01" value={currentPreset.reverbDiffusion || 0.8} onChange={(e) => updateGlobal('reverbDiffusion', parseFloat(e.target.value))} disabled={activeVoiceMode !== 'normal'} className={`w-full h-1 rounded appearance-none ${activeVoiceMode !== 'normal' ? 'bg-slate-600' : 'bg-blue-600'}`} /></div>
                    </div>
                </div>
            )}

            {activeTab === 'arp' && (
                <div className="space-y-6 animate-in fade-in duration-300">
                    <h3 className="text-sm font-bold text-slate-300 uppercase mb-2">Granular Arp Settings ({activeVoiceMode})</h3>
                    <div className="p-4 bg-slate-900/50 rounded border border-slate-700 space-y-4">

                        <div>
                            <label className="block text-xs font-bold text-slate-400 mb-1">Direction</label>
                            <div className="flex bg-slate-800 rounded border border-slate-600 overflow-hidden">
                                {(['order', 'up', 'down', 'updown', 'random'] as ArpDirection[]).map(dir => (
                                    <button 
                                        key={dir} 
                                        onClick={() => updateArp('direction', dir)}
                                        className={`flex-1 py-1 text-[10px] uppercase font-bold ${arpConfig.direction === dir ? 'bg-red-600 text-white' : 'text-slate-400 hover:bg-slate-700'}`}
                                    >
                                        {dir}
                                    </button>
                                ))}
                            </div>
                        </div>

                        <div>
                            <label className="block text-xs font-bold text-slate-400 mb-1">Time Division</label>
                            <div className="flex bg-slate-800 rounded border border-slate-600 overflow-hidden">
                                {(['1/1', '1/2', '1/4', '1/8', '1/16', '1/32'] as ArpDivision[]).map(div => (
                                    <button 
                                        key={div} 
                                        onClick={() => updateArp('division', div)}
                                        className={`flex-1 py-1 text-[10px] font-mono font-bold ${arpConfig.division === div ? 'bg-red-600 text-white' : 'text-slate-400 hover:bg-slate-700'}`}
                                    >
                                        {div}
                                    </button>
                                ))}
                            </div>
                        </div>

                        <div>
                            <label className="flex justify-between text-xs mb-1"><span>Octave Range</span> <span className="font-bold text-white">{arpConfig.octaves}</span></label>
                            <input type="range" min="1" max="4" step="1" value={arpConfig.octaves} onChange={(e) => updateArp('octaves', parseInt(e.target.value))} className="w-full h-1 bg-red-600 rounded appearance-none" />
                        </div>

                        <div>
                            <label className="flex justify-between text-xs mb-1"><span>Gate Length</span> <span className="font-bold text-white">{(arpConfig.gate * 100).toFixed(0)}%</span></label>
                            <input type="range" min="0.1" max="1.0" step="0.05" value={arpConfig.gate} onChange={(e) => updateArp('gate', parseFloat(e.target.value))} className="w-full h-1 bg-red-600 rounded appearance-none" />
                        </div>

                        <div>
                            <label className="flex justify-between text-xs mb-1"><span>Swing</span> <span className="font-bold text-white">{arpConfig.swing}%</span></label>
                            <input type="range" min="0" max="100" step="1" value={arpConfig.swing} onChange={(e) => updateArp('swing', parseInt(e.target.value))} className="w-full h-1 bg-red-600 rounded appearance-none" />
                        </div>

                    </div>
                    <p className="text-[10px] text-slate-500 text-center italic">These settings apply when 'Arpeggio' mode is active.</p>
                </div>
            )}

            <div className="pt-4 border-t border-slate-700 mt-4">
                <p className="text-[10px] text-slate-500 text-center">Changes applied immediately</p>
            </div>
        </div>
    </div>
  );
};

export default SynthControls;

import React, { useState } from 'react';
import { ChordDefinition, XYPos, AppSettings, ArpeggioDefinition } from '../types';
import { MARGIN_3MM, SCROLLBAR_WIDTH } from '../constants';

interface Props {
  volume: number;
  setVolume: (v: number) => void;
  spatialScale: number;
  setSpatialScale: (v: number) => void;
  onPanic: () => void;
  onOff: () => void;
  onLatch: () => void;
  latchMode: 0 | 1 | 2;
  onBend: () => void;
  isBendEnabled: boolean;
  onCenter: () => void;
  onIncreaseDepth: () => void;
  onDecreaseDepth: () => void;
  onAddChord: () => void;
  toggleChord: (id: string) => void;
  activeChordIds: string[];
  savedChords: ChordDefinition[];
  chordShortcutSizeScale: number;
  showIncreaseDepthButton: boolean;
  uiUnlocked: boolean;
  uiPositions: AppSettings['uiPositions'];
  updatePosition: (key: keyof AppSettings['uiPositions'], pos: XYPos) => void;
  draggingId: string | null;
  setDraggingId: (id: string | null) => void;
  uiScale?: number;

  // Arp Props
  arpeggios?: ArpeggioDefinition[];
  arpBpm?: number;
  onArpToggle?: (id: string) => void;
  onArpBpmChange?: (bpm: number) => void;
  recordingArpId?: string | null; // ID of arp currently recording (blinking)
  currentArpStep?: number;
}

const FloatingControls: React.FC<Props> = ({ 
  volume, setVolume, spatialScale, setSpatialScale, 
  onPanic, onOff, onLatch, latchMode, onBend, isBendEnabled, onCenter, onIncreaseDepth, onDecreaseDepth, onAddChord, toggleChord,
  activeChordIds, savedChords, chordShortcutSizeScale,
  showIncreaseDepthButton, uiUnlocked, uiPositions, updatePosition,
  draggingId, setDraggingId,
  uiScale = 1.0,
  arpeggios = [], arpBpm = 120, onArpToggle, onArpBpmChange, recordingArpId, currentArpStep
}) => {

  const [showSequencer, setShowSequencer] = useState(false);

  const handleDrag = (e: React.PointerEvent, key: keyof AppSettings['uiPositions']) => {
    if (!uiUnlocked) return;
    if (draggingId !== null && draggingId !== key) return;

    const el = e.currentTarget as HTMLElement;
    const startX = e.clientX;
    const startY = e.clientY;
    const initialLeft = uiPositions[key as keyof typeof uiPositions].x;
    const initialTop = uiPositions[key as keyof typeof uiPositions].y;

    el.setPointerCapture(e.pointerId);
    setDraggingId(key);

    const onMove = (evt: PointerEvent) => {
        const deltaX = evt.clientX - startX;
        const deltaY = evt.clientY - startY;
        let newX = initialLeft + deltaX;
        let newY = initialTop + deltaY;
        const maxX = window.innerWidth - el.offsetWidth - MARGIN_3MM - SCROLLBAR_WIDTH;
        const maxY = window.innerHeight - el.offsetHeight - MARGIN_3MM - SCROLLBAR_WIDTH;
        const minX = MARGIN_3MM;
        const minY = MARGIN_3MM;
        newX = Math.max(minX, Math.min(newX, maxX));
        newY = Math.max(minY, Math.min(newY, maxY));
        updatePosition(key, { x: newX, y: newY });
    };

    const onUp = () => {
        setDraggingId(null);
        window.removeEventListener('pointermove', onMove);
        window.removeEventListener('pointerup', onUp);
        window.removeEventListener('pointercancel', onUp);
    };

    window.addEventListener('pointermove', onMove);
    window.addEventListener('pointerup', onUp);
    window.addEventListener('pointercancel', onUp);
  };

  const baseSize = 48 * uiScale; 
  const chordSize = baseSize * chordShortcutSizeScale;
  const largeBtnSize = 80 * uiScale;

  const sliderWidth = 290 * uiScale; 
  const sliderHeight = 40 * uiScale;

  const draggableStyle = (key: string) => ({
      left: uiPositions[key as keyof typeof uiPositions].x,
      top: uiPositions[key as keyof typeof uiPositions].y,
      touchAction: 'none' as React.CSSProperties['touchAction'],
  });

  const handleButtonPress = (e: React.PointerEvent, key: keyof AppSettings['uiPositions'], action: () => void) => {
      e.stopPropagation();
      if (uiUnlocked) {
          handleDrag(e, key);
      } else {
          action();
      }
  };

  const getLatchStyle = () => {
      const base = "absolute rounded-full flex items-center justify-center font-bold uppercase tracking-wider backdrop-blur transition-all z-[150] select-none shadow-lg";
      const unlocked = uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : '';
      if (latchMode === 1) return `${base} ${unlocked} bg-green-500 text-white border-2 border-green-300 shadow-[0_0_20px_rgba(34,197,94,0.8)]`;
      else if (latchMode === 2) return `${base} ${unlocked} bg-green-900/60 text-green-400 border-2 border-green-400 ring-4 ring-green-500/30 animate-pulse shadow-[0_0_15px_rgba(34,197,94,0.4)]`;
      else return `${base} ${unlocked} bg-green-900/40 border-2 border-green-500/50 text-green-500 hover:bg-green-800/60 active:bg-green-600 active:text-white shadow-[0_0_15px_rgba(34,197,94,0.2)]`;
  };

  // Find currently active or recording arp to display in Sequencer
  const activeArp = arpeggios.find(a => a.isPlaying || a.id === recordingArpId);
  const activeSteps = activeArp ? activeArp.steps : [];

  return (
    <>
      <style>{`
        .prismatonal-slider::-webkit-slider-thumb { -webkit-appearance: none; appearance: none; width: 12px; height: 12px; border-radius: 50%; background: currentColor; cursor: pointer; border: 2px solid white; box-shadow: 0 0 5px rgba(0,0,0,0.5); }
        .prismatonal-slider::-moz-range-thumb { width: 12px; height: 12px; border-radius: 50%; background: currentColor; cursor: pointer; border: 2px solid white; box-shadow: 0 0 5px rgba(0,0,0,0.5); }
      `}</style>

      {/* Arpeggio Bar - Redesigned to be Compact Panel with Grid */}
      <div 
        className={`absolute bg-slate-900/90 rounded-2xl flex flex-col items-center backdrop-blur-xl border border-white/10 transition-colors z-[150] shadow-2xl overflow-visible ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : ''}`}
        style={{ ...draggableStyle('arpeggioBar'), minWidth: 200 * uiScale, padding: 8 * uiScale }}
        onPointerDown={(e) => handleDrag(e, 'arpeggioBar')}
      >
        <div className="w-full flex flex-col gap-2">
             <div className="flex justify-between items-center px-1">
                 <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">ARP</span>
                 <div className="flex items-center gap-1">
                     <div className={`w-2 h-2 rounded-full ${arpeggios.some(a => a.isPlaying) && (Math.floor(Date.now() / (30000/arpBpm!)) % 2 === 0) ? 'bg-green-500 shadow-[0_0_5px_lime]' : 'bg-slate-800'}`}></div>
                     <input 
                        type="number" 
                        value={arpBpm} 
                        onChange={(e) => onArpBpmChange && onArpBpmChange(parseInt(e.target.value))}
                        className="w-10 bg-transparent text-right text-xs font-mono font-bold text-blue-300 focus:outline-none border-b border-transparent focus:border-blue-500"
                        onPointerDown={(e) => e.stopPropagation()}
                     />
                     <span className="text-[8px] text-slate-600 font-bold">BPM</span>
                 </div>
             </div>

             <div className="flex gap-1.5 justify-center flex-wrap">
                 {arpeggios.map(arp => {
                     const isRecording = recordingArpId === arp.id;
                     const isPlaying = arp.isPlaying;
                     const hasData = arp.steps.length > 0;

                     let btnClass = "bg-slate-800/80 border-slate-600 text-slate-400";
                     if (isRecording) btnClass = "bg-red-900/80 border-red-500 text-white animate-pulse shadow-[0_0_10px_red]";
                     else if (isPlaying) btnClass = "bg-blue-600 border-blue-400 text-white shadow-[0_0_10px_blue]";
                     else if (hasData) btnClass = "bg-slate-700 border-blue-500/30 text-blue-200";

                     return (
                         <button 
                            key={arp.id}
                            className={`rounded-lg flex items-center justify-center font-bold border-2 transition-all hover:scale-105 active:scale-95 ${btnClass}`}
                            style={{ width: 36 * uiScale, height: 36 * uiScale, fontSize: 14 * uiScale }}
                            onPointerDown={(e) => { e.stopPropagation(); if(onArpToggle) onArpToggle(arp.id); }}
                         >
                             {arp.id}
                         </button>
                     );
                 })}
             </div>
        </div>

        {/* Dropdown Toggle */}
        <button 
            className="w-full h-4 mt-2 bg-slate-800/50 hover:bg-slate-700/50 rounded flex items-center justify-center cursor-pointer transition-colors"
            onPointerDown={(e) => { e.stopPropagation(); setShowSequencer(!showSequencer); }}
        >
             <svg xmlns="http://www.w3.org/2000/svg" className={`h-3 w-3 text-slate-400 transition-transform ${showSequencer ? 'rotate-180' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
               <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
             </svg>
        </button>

        {/* Sequencer Dropdown */}
        {showSequencer && (
            <div 
                className="absolute top-full left-0 bg-slate-900/90 backdrop-blur-xl border border-white/10 rounded-xl mt-2 shadow-2xl p-4 z-[140] flex flex-col gap-2"
                style={{ width: '400px', height: '300px', transformOrigin: 'top left' }}
                onPointerDown={(e) => e.stopPropagation()} 
            >
                <div className="flex justify-between items-center pb-2 border-b border-white/5">
                    <span className="text-xs font-bold text-slate-400">SEQUENCER VIEW ({activeArp?.id || 'None'})</span>
                    <span className="text-[10px] text-slate-600">{activeSteps.length} Steps</span>
                </div>

                <div className="flex-1 overflow-x-auto overflow-y-hidden flex gap-1 items-end p-2 bg-slate-950/50 rounded-lg relative">
                    {activeSteps.length === 0 && (
                        <div className="absolute inset-0 flex items-center justify-center text-slate-600 text-xs italic">
                            {recordingArpId ? "Play notes to record..." : "Select an Arp to view"}
                        </div>
                    )}
                    {activeSteps.map((step, idx) => {
                        const isCurrent = idx === currentArpStep;
                        // Visualize pitch height somewhat
                        const heightPct = Math.min(100, Math.max(10, Math.log2(step.ratio) * 20 + 50));

                        return (
                            <div key={idx} className="flex flex-col gap-1 items-center min-w-[20px] h-full justify-end group">
                                <div 
                                    className={`w-4 rounded-t transition-all ${isCurrent ? 'bg-white shadow-[0_0_10px_white]' : 'bg-blue-600 opacity-60 group-hover:opacity-100'}`} 
                                    style={{ height: `${heightPct}%` }}
                                ></div>
                                <span className={`text-[8px] font-mono ${isCurrent ? 'text-white font-bold' : 'text-slate-600'}`}>{idx+1}</span>
                            </div>
                        );
                    })}
                </div>
                <div className="flex justify-end">
                     {/* Placeholder for editing controls (Delete Last, Clear) */}
                     {activeArp && activeSteps.length > 0 && recordingArpId && (
                         <span className="text-[10px] text-red-400 animate-pulse">Recording...</span>
                     )}
                </div>
            </div>
        )}
      </div>

      {/* Volume Slider */}
      <div 
        className={`absolute bg-slate-900/60 p-2 rounded-full flex items-center gap-2 backdrop-blur-md border border-white/10 transition-colors z-[150] ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : ''}`}
        style={{ ...draggableStyle('volume'), width: sliderWidth, height: sliderHeight }}
        onPointerDown={(e) => handleDrag(e, 'volume')}
      >
        <span className="font-bold text-slate-300 select-none text-center" style={{ fontSize: 10 * uiScale, width: 60 * uiScale }}>VOLUME</span>
        <input 
          type="range" min="0" max="1" step="0.01" value={volume} onChange={(e) => setVolume(parseFloat(e.target.value))} disabled={uiUnlocked}
          className={`prismatonal-slider w-full rounded-lg appearance-none text-green-500 ${uiUnlocked ? 'cursor-move opacity-50' : 'cursor-pointer'}`}
          style={{ height: 4 * uiScale, background: `linear-gradient(to right, #22c55e 0%, #22c55e ${volume * 100}%, #334155 ${volume * 100}%, #334155 100%)` }}
          onPointerDown={(e) => !uiUnlocked && e.stopPropagation()} 
        />
      </div>

      {/* Reverb Slider */}
      <div 
        className={`absolute bg-slate-900/60 p-2 rounded-full flex items-center gap-2 backdrop-blur-md border border-white/10 transition-colors z-[150] ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : ''}`}
        style={{ ...draggableStyle('space'), width: sliderWidth, height: sliderHeight }}
        onPointerDown={(e) => handleDrag(e, 'space')}
      >
        <span className="font-bold text-slate-300 select-none text-center" style={{ fontSize: 10 * uiScale, width: 60 * uiScale }}>REVERB</span>
        <input 
            type="range" min="0" max="2" step="0.01" value={spatialScale} onChange={(e) => setSpatialScale(parseFloat(e.target.value))} disabled={uiUnlocked}
            className={`prismatonal-slider w-full rounded-lg appearance-none text-blue-500 ${uiUnlocked ? 'cursor-move opacity-50' : 'cursor-pointer'}`}
            style={{ height: 4 * uiScale, background: `linear-gradient(to right, #3b82f6 0%, #3b82f6 ${(spatialScale/2) * 100}%, #334155 ${(spatialScale/2) * 100}%, #334155 100%)` }}
            onPointerDown={(e) => !uiUnlocked && e.stopPropagation()} 
        />
      </div>

      <button className={`absolute rounded-full flex items-center justify-center font-bold uppercase tracking-wider backdrop-blur transition-all z-[150] select-none border-2 shadow-lg ${isBendEnabled ? 'bg-purple-600 text-white border-purple-300 shadow-[0_0_15px_rgba(168,85,247,0.6)]' : 'bg-purple-900/40 text-purple-400 border-purple-500/50 hover:bg-purple-800/60'} ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : ''}`} style={{ ...draggableStyle('bend'), width: largeBtnSize, height: largeBtnSize, fontSize: 14 * uiScale }} onPointerDown={(e) => handleButtonPress(e, 'bend', onBend)}>BEND</button>
      <button className={getLatchStyle()} style={{ ...draggableStyle('latch'), width: largeBtnSize, height: largeBtnSize, fontSize: 14 * uiScale }} onPointerDown={(e) => handleButtonPress(e, 'latch', onLatch)}>LATCH</button>
      <button className={`absolute rounded-full bg-yellow-900/40 border-2 border-yellow-500/50 flex items-center justify-center text-yellow-500 font-bold uppercase tracking-wider backdrop-blur hover:bg-yellow-800/60 active:bg-yellow-600 active:text-white transition-all shadow-[0_0_15px_rgba(234,179,8,0.2)] z-[150] select-none ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : ''}`} style={{ ...draggableStyle('off'), width: largeBtnSize, height: largeBtnSize, fontSize: 14 * uiScale }} onPointerDown={(e) => handleButtonPress(e, 'off', onOff)}>OFF</button>
      <button className={`absolute rounded-full bg-red-900/40 border-2 border-red-500/50 flex items-center justify-center text-red-500 font-bold uppercase tracking-wider backdrop-blur hover:bg-red-800/60 active:bg-red-600 active:text-white transition-all shadow-[0_0_15px_rgba(239,68,68,0.2)] z-[150] select-none ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : ''}`} style={{ ...draggableStyle('panic'), width: largeBtnSize, height: largeBtnSize, fontSize: 14 * uiScale }} onPointerDown={(e) => handleButtonPress(e, 'panic', onPanic)}>PANIC</button>

      <button className={`absolute rounded bg-yellow-600/20 border-2 border-yellow-500 flex items-center justify-center text-yellow-500 font-bold backdrop-blur hover:bg-yellow-600/40 active:bg-yellow-600 active:text-white transition-all shadow-[0_0_15px_rgba(234,179,8,0.4)] z-[150] select-none ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : ''}`} style={{ ...draggableStyle('center'), width: baseSize, height: baseSize }} onPointerDown={(e) => handleButtonPress(e, 'center', onCenter)} title="Center Display"><svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" style={{ width: baseSize * 0.5, height: baseSize * 0.5 }}><path strokeLinecap="round" strokeLinejoin="round" d="M3.75 3.75v4.5m0-4.5h4.5m-4.5 0L9 9M3.75 20.25v-4.5m0 4.5h4.5m-4.5 0L9 15M20.25 3.75h-4.5m4.5 0v4.5m0-4.5L15 9m5.25 11.25h-4.5m4.5 0v-4.5m0 4.5L15 15" /></svg></button>

      {showIncreaseDepthButton && (<button className={`absolute rounded bg-blue-600/20 border-2 border-blue-500 flex items-center justify-center text-blue-500 font-bold backdrop-blur hover:bg-blue-600/40 active:bg-blue-600 active:text-white transition-all shadow-[0_0_15px_rgba(59,130,246,0.4)] z-[150] select-none ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : ''}`} style={{ ...draggableStyle('depth'), width: baseSize, height: baseSize }} onPointerDown={(e) => handleButtonPress(e, 'depth', onIncreaseDepth)} title="Increase Depth from Selection"><svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" style={{ width: baseSize * 0.5, height: baseSize * 0.5 }}><path strokeLinecap="round" strokeLinejoin="round" d="M3.75 3.75v4.5m0-4.5h4.5m-4.5 0L9 9M3.75 20.25v-4.5m0 4.5h4.5m-4.5 0L9 15M20.25 3.75h-4.5m4.5 0v4.5m0-4.5L15 9m5.25 11.25h-4.5m4.5 0v-4.5m0 4.5L15 15" /><circle cx="12" cy="12" r="3" stroke="currentColor" strokeWidth="2" fill="none" /></svg></button>)}

      {showIncreaseDepthButton && (<button className={`absolute rounded bg-green-600/20 border-2 border-green-500 flex items-center justify-center text-green-500 font-bold backdrop-blur hover:bg-green-600/40 active:bg-green-600 active:text-white transition-all shadow-[0_0_15px_rgba(34,197,94,0.4)] z-[150] select-none ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : ''}`} style={{ ...draggableStyle('decreaseDepth'), width: baseSize, height: baseSize }} onPointerDown={(e) => handleButtonPress(e, 'decreaseDepth', onDecreaseDepth)} title="Undo Last Depth Increase"><svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" style={{ width: baseSize * 0.5, height: baseSize * 0.5 }}><path strokeLinecap="round" strokeLinejoin="round" d="M4 4 L10 10 M10 10 L10 6 M10 10 L6 10" /><path strokeLinecap="round" strokeLinejoin="round" d="M20 4 L14 10 M14 10 L14 6 M14 10 L18 10" /><path strokeLinecap="round" strokeLinejoin="round" d="M4 20 L10 14 M10 14 L10 18 M10 14 L6 14" /><path strokeLinecap="round" strokeLinejoin="round" d="M20 20 L14 14 M14 14 L14 18 M14 14 L18 14" /></svg></button>)}

      <div className={`absolute flex gap-2 flex-wrap items-start z-[150] ${uiUnlocked ? 'cursor-move bg-white/5 rounded p-2 border border-yellow-500/30' : ''}`} style={{ ...draggableStyle('chords'), maxWidth: '80vw' }} onPointerDown={(e) => handleDrag(e, 'chords')}>
          <button className={`rounded border-2 border-slate-500 border-dashed flex items-center justify-center text-slate-500 font-bold backdrop-blur hover:bg-slate-700/40 hover:text-white hover:border-white transition-all select-none ${uiUnlocked ? 'pointer-events-none' : ''}`} style={{ width: chordSize, height: chordSize }} onPointerDown={(e) => !uiUnlocked && e.stopPropagation()} onClick={!uiUnlocked ? onAddChord : undefined} title="Store currently latched notes as a Chord"><svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-1/2 h-1/2"><path strokeLinecap="round" strokeLinejoin="round" d="M12 4.5v15m7.5-7.5h-15" /></svg></button>
          {savedChords.filter(c => c.visible).map((chord) => {
              const isActive = activeChordIds.includes(chord.id);
              return (<button key={chord.id} className={`rounded flex items-center justify-center font-bold backdrop-blur transition-all shadow-lg select-none ${uiUnlocked ? 'pointer-events-none' : ''}`} style={{ width: chordSize, height: chordSize, fontSize: 12 * uiScale, backgroundColor: isActive ? chord.color : `${chord.color}33`, borderColor: chord.color, borderWidth: 2, color: isActive ? '#fff' : chord.color, boxShadow: isActive ? `0 0 10px ${chord.color}` : 'none' }} onPointerDown={(e) => !uiUnlocked && e.stopPropagation()} onClick={() => !uiUnlocked && toggleChord(chord.id)} title={`Chord ${chord.id}: ${chord.label}`}>{chord.id}</button>);
          })}
      </div>
    </>
  );
};

export default FloatingControls;

import React, { useState } from 'react';
import { ChordDefinition, XYPos, AppSettings, ArpeggioDefinition } from '../types';
import { MARGIN_3MM, SCROLLBAR_WIDTH } from '../constants';

interface Props {
  volume: number;
  setVolume: (v: number) => void;
  spatialScale: number;
  setSpatialScale: (v: number) => void;
  onPanic: () => void;
  onOff: () => void;
  onLatch: () => void;
  latchMode: 0 | 1 | 2;
  onBend: () => void;
  isBendEnabled: boolean;
  onCenter: () => void;
  onIncreaseDepth: () => void;
  onDecreaseDepth: () => void;
  onAddChord: () => void;
  toggleChord: (id: string) => void;
  activeChordIds: string[];
  savedChords: ChordDefinition[];
  chordShortcutSizeScale: number;
  showIncreaseDepthButton: boolean;
  uiUnlocked: boolean;
  uiPositions: AppSettings['uiPositions'];
  updatePosition: (key: keyof AppSettings['uiPositions'], pos: XYPos) => void;
  draggingId: string | null;
  setDraggingId: (id: string | null) => void;
  uiScale?: number;

  // Arp Props
  arpeggios?: ArpeggioDefinition[];
  arpBpm?: number;
  onArpToggle?: (id: string) => void;
  onArpBpmChange?: (bpm: number) => void;
  recordingArpId?: string | null; // ID of arp currently recording (blinking)
  currentArpStep?: number;
}

const FloatingControls: React.FC<Props> = ({ 
  volume, setVolume, spatialScale, setSpatialScale, 
  onPanic, onOff, onLatch, latchMode, onBend, isBendEnabled, onCenter, onIncreaseDepth, onDecreaseDepth, onAddChord, toggleChord,
  activeChordIds, savedChords, chordShortcutSizeScale,
  showIncreaseDepthButton, uiUnlocked, uiPositions, updatePosition,
  draggingId, setDraggingId,
  uiScale = 1.0,
  arpeggios = [], arpBpm = 120, onArpToggle, onArpBpmChange, recordingArpId, currentArpStep
}) => {

  const [showSequencer, setShowSequencer] = useState(false);

  const handleDrag = (e: React.PointerEvent, key: keyof AppSettings['uiPositions']) => {
    if (!uiUnlocked) return;
    if (draggingId !== null && draggingId !== key) return;

    const el = e.currentTarget as HTMLElement;
    const startX = e.clientX;
    const startY = e.clientY;
    const initialLeft = uiPositions[key as keyof typeof uiPositions].x;
    const initialTop = uiPositions[key as keyof typeof uiPositions].y;

    el.setPointerCapture(e.pointerId);
    setDraggingId(key);

    const onMove = (evt: PointerEvent) => {
        const deltaX = evt.clientX - startX;
        const deltaY = evt.clientY - startY;
        let newX = initialLeft + deltaX;
        let newY = initialTop + deltaY;
        const maxX = window.innerWidth - el.offsetWidth - MARGIN_3MM - SCROLLBAR_WIDTH;
        const maxY = window.innerHeight - el.offsetHeight - MARGIN_3MM - SCROLLBAR_WIDTH;
        const minX = MARGIN_3MM;
        const minY = MARGIN_3MM;
        newX = Math.max(minX, Math.min(newX, maxX));
        newY = Math.max(minY, Math.min(newY, maxY));
        updatePosition(key, { x: newX, y: newY });
    };

    const onUp = () => {
        setDraggingId(null);
        window.removeEventListener('pointermove', onMove);
        window.removeEventListener('pointerup', onUp);
        window.removeEventListener('pointercancel', onUp);
    };

    window.addEventListener('pointermove', onMove);
    window.addEventListener('pointerup', onUp);
    window.addEventListener('pointercancel', onUp);
  };

  const baseSize = 48 * uiScale; 
  const chordSize = baseSize * chordShortcutSizeScale;
  const largeBtnSize = 80 * uiScale;

  const sliderWidth = 290 * uiScale; 
  const sliderHeight = 40 * uiScale;

  const draggableStyle = (key: string) => ({
      left: uiPositions[key as keyof typeof uiPositions].x,
      top: uiPositions[key as keyof typeof uiPositions].y,
      touchAction: 'none' as React.CSSProperties['touchAction'],
  });

  const handleButtonPress = (e: React.PointerEvent, key: keyof AppSettings['uiPositions'], action: () => void) => {
      e.stopPropagation();
      if (uiUnlocked) {
          handleDrag(e, key);
      } else {
          action();
      }
  };

  const getLatchStyle = () => {
      const base = "absolute rounded-2xl flex items-center justify-center font-bold uppercase tracking-widest backdrop-blur-xl transition-all z-[150] select-none shadow-xl border border-white/10";
      const unlocked = uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : '';

      if (latchMode === 1) return `${base} ${unlocked} bg-green-600/90 text-white shadow-[0_0_20px_rgba(34,197,94,0.4)]`;
      else if (latchMode === 2) return `${base} ${unlocked} bg-slate-900/90 text-green-400 border-green-500/50 ring-1 ring-green-500/30 animate-pulse`;
      else return `${base} ${unlocked} bg-slate-900/80 text-green-600/50 hover:bg-slate-800 hover:text-green-500 active:bg-slate-700 active:text-green-400`;
  };

  const getButtonStyle = (active: boolean, colorClass: string) => {
      const base = "absolute rounded-2xl flex items-center justify-center font-bold uppercase tracking-widest backdrop-blur-xl transition-all z-[150] select-none shadow-xl border border-white/10";
      const unlocked = uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : '';
      if (active) return `${base} ${unlocked} bg-${colorClass}-600/90 text-white shadow-[0_0_15px_rgba(var(--color-${colorClass}-500),0.4)]`;
      return `${base} ${unlocked} bg-slate-900/80 text-slate-500 hover:bg-slate-800 hover:text-${colorClass}-400 active:bg-slate-700 active:text-white`;
  };

  // Find currently active or recording arp to display in Sequencer
  const activeArp = arpeggios.find(a => a.isPlaying || a.id === recordingArpId);
  const activeSteps = activeArp ? activeArp.steps : [];

  return (
    <>
      <style>{`
        .prismatonal-slider::-webkit-slider-thumb { -webkit-appearance: none; appearance: none; width: 12px; height: 12px; border-radius: 50%; background: currentColor; cursor: pointer; border: 2px solid white; box-shadow: 0 0 5px rgba(0,0,0,0.5); }
        .prismatonal-slider::-moz-range-thumb { width: 12px; height: 12px; border-radius: 50%; background: currentColor; cursor: pointer; border: 2px solid white; box-shadow: 0 0 5px rgba(0,0,0,0.5); }
      `}</style>

      {/* Arpeggio Bar */}
      <div 
        className={`absolute bg-slate-900/90 rounded-2xl flex flex-col items-center backdrop-blur-xl border border-white/10 transition-colors z-[150] shadow-2xl overflow-visible ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : ''}`}
        style={{ ...draggableStyle('arpeggioBar'), minWidth: 200 * uiScale, padding: 8 * uiScale }}
        onPointerDown={(e) => handleDrag(e, 'arpeggioBar')}
      >
        <div className="w-full flex flex-col gap-2">
             <div className="flex justify-between items-center px-2 pt-1">
                 <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">ARP</span>
                 <div className="flex items-center gap-2 bg-slate-950/50 rounded-lg px-2 py-1 border border-white/5">
                     <div className={`w-1.5 h-1.5 rounded-full transition-colors ${arpeggios.some(a => a.isPlaying) && (Math.floor(Date.now() / (30000/arpBpm!)) % 2 === 0) ? 'bg-green-400 shadow-[0_0_5px_lime]' : 'bg-slate-700'}`}></div>
                     <input 
                        type="number" 
                        value={arpBpm} 
                        onChange={(e) => onArpBpmChange && onArpBpmChange(parseInt(e.target.value))}
                        className="w-8 bg-transparent text-right text-[10px] font-mono font-bold text-slate-300 focus:outline-none focus:text-blue-400"
                        onPointerDown={(e) => e.stopPropagation()}
                     />
                     <span className="text-[8px] text-slate-600 font-bold tracking-wider">BPM</span>
                 </div>
             </div>

             <div className="flex gap-1.5 justify-center flex-wrap px-1">
                 {arpeggios.map(arp => {
                     const isRecording = recordingArpId === arp.id;
                     const isPlaying = arp.isPlaying;
                     const hasData = arp.steps.length > 0;

                     let btnClass = "bg-slate-800/50 border-slate-700 text-slate-500 hover:bg-slate-700 hover:text-slate-300";
                     if (isRecording) btnClass = "bg-red-500/20 border-red-500/50 text-red-400 animate-pulse shadow-[0_0_10px_rgba(239,68,68,0.2)]";
                     else if (isPlaying) btnClass = "bg-blue-600 text-white border-blue-500 shadow-[0_0_10px_rgba(59,130,246,0.3)]";
                     else if (hasData) btnClass = "bg-slate-800 border-blue-500/30 text-blue-400";

                     return (
                         <button 
                            key={arp.id}
                            className={`rounded-lg flex items-center justify-center font-bold border transition-all active:scale-95 ${btnClass}`}
                            style={{ width: 32 * uiScale, height: 32 * uiScale, fontSize: 12 * uiScale }}
                            onPointerDown={(e) => { e.stopPropagation(); if(onArpToggle) onArpToggle(arp.id); }}
                         >
                             {arp.id}
                         </button>
                     );
                 })}
             </div>
        </div>

        {/* Dropdown Toggle */}
        <button 
            className="w-full h-3 mt-2 bg-slate-800/30 hover:bg-slate-700/50 rounded-full flex items-center justify-center cursor-pointer transition-colors group"
            onPointerDown={(e) => { e.stopPropagation(); setShowSequencer(!showSequencer); }}
        >
             <svg xmlns="http://www.w3.org/2000/svg" className={`h-2 w-2 text-slate-600 group-hover:text-slate-400 transition-transform ${showSequencer ? 'rotate-180' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
               <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M19 9l-7 7-7-7" />
             </svg>
        </button>

        {/* Sequencer Dropdown */}
        {showSequencer && (
            <div 
                className="absolute top-full left-0 bg-slate-900/95 backdrop-blur-xl border border-white/10 rounded-xl mt-2 shadow-2xl p-4 z-[140] flex flex-col gap-3"
                style={{ width: '400px', height: '280px', transformOrigin: 'top left' }}
                onPointerDown={(e) => e.stopPropagation()} 
            >
                <div className="flex justify-between items-center pb-2 border-b border-white/5">
                    <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">SEQUENCER VIEW ({activeArp?.id || 'None'})</span>
                    <span className="text-[9px] font-mono text-slate-600">{activeSteps.length} Steps</span>
                </div>

                <div className="flex-1 overflow-x-auto overflow-y-hidden flex gap-px items-end p-3 bg-black/40 rounded-lg relative inner-shadow border border-white/5">
                    {activeSteps.length === 0 && (
                        <div className="absolute inset-0 flex items-center justify-center text-slate-600 text-[10px] uppercase tracking-wider">
                            {recordingArpId ? "Play notes to record..." : "Select an Arp to view"}
                        </div>
                    )}
                    {activeSteps.map((step, idx) => {
                        const isCurrent = idx === currentArpStep;
                        const heightPct = Math.min(100, Math.max(10, Math.log2(step.ratio) * 20 + 50));

                        return (
                            <div key={idx} className="flex flex-col gap-1 items-center min-w-[16px] h-full justify-end group relative">
                                <div 
                                    className={`w-3 rounded-sm transition-all ${isCurrent ? 'bg-white shadow-[0_0_8px_white]' : 'bg-blue-500/40 hover:bg-blue-400/80'}`} 
                                    style={{ height: `${heightPct}%` }}
                                ></div>
                                <div className="h-px w-full bg-white/5"></div>
                            </div>
                        );
                    })}
                </div>
                <div className="flex justify-between items-end">
                     <div className="text-[9px] text-slate-600 font-mono">
                        {recordingArpId ? <span className="text-red-400 animate-pulse">● RECORDING</span> : "READY"}
                     </div>
                </div>
            </div>
        )}
      </div>

      {/* Volume Slider */}
      <div 
        className={`absolute bg-slate-900/90 rounded-2xl flex items-center gap-3 backdrop-blur-xl border border-white/10 transition-colors z-[150] px-4 shadow-xl ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : ''}`}
        style={{ ...draggableStyle('volume'), width: sliderWidth, height: sliderHeight }}
        onPointerDown={(e) => handleDrag(e, 'volume')}
      >
        <span className="font-bold text-slate-500 select-none text-center tracking-widest" style={{ fontSize: 9 * uiScale, width: 50 * uiScale }}>VOL</span>
        <input 
          type="range" min="0" max="1" step="0.01" value={volume} onChange={(e) => setVolume(parseFloat(e.target.value))} disabled={uiUnlocked}
          className={`prismatonal-slider w-full rounded-full appearance-none bg-slate-800 h-1.5 ${uiUnlocked ? 'cursor-move opacity-50' : 'cursor-pointer'}`}
          style={{ background: `linear-gradient(to right, #22c55e 0%, #22c55e ${volume * 100}%, #1e293b ${volume * 100}%, #1e293b 100%)` }}
          onPointerDown={(e) => !uiUnlocked && e.stopPropagation()} 
        />
      </div>

      {/* Reverb Slider */}
      <div 
        className={`absolute bg-slate-900/90 rounded-2xl flex items-center gap-3 backdrop-blur-xl border border-white/10 transition-colors z-[150] px-4 shadow-xl ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : ''}`}
        style={{ ...draggableStyle('space'), width: sliderWidth, height: sliderHeight }}
        onPointerDown={(e) => handleDrag(e, 'space')}
      >
        <span className="font-bold text-slate-500 select-none text-center tracking-widest" style={{ fontSize: 9 * uiScale, width: 50 * uiScale }}>VERB</span>
        <input 
            type="range" min="0" max="2" step="0.01" value={spatialScale} onChange={(e) => setSpatialScale(parseFloat(e.target.value))} disabled={uiUnlocked}
            className={`prismatonal-slider w-full rounded-full appearance-none bg-slate-800 h-1.5 ${uiUnlocked ? 'cursor-move opacity-50' : 'cursor-pointer'}`}
            style={{ background: `linear-gradient(to right, #3b82f6 0%, #3b82f6 ${(spatialScale/2) * 100}%, #1e293b ${(spatialScale/2) * 100}%, #1e293b 100%)` }}
            onPointerDown={(e) => !uiUnlocked && e.stopPropagation()} 
        />
      </div>

      <button className={getButtonStyle(isBendEnabled, 'purple')} style={{ ...draggableStyle('bend'), width: largeBtnSize, height: largeBtnSize, fontSize: 11 * uiScale }} onPointerDown={(e) => handleButtonPress(e, 'bend', onBend)}>BEND</button>
      <button className={getLatchStyle()} style={{ ...draggableStyle('latch'), width: largeBtnSize, height: largeBtnSize, fontSize: 11 * uiScale }} onPointerDown={(e) => handleButtonPress(e, 'latch', onLatch)}>LATCH</button>
      <button className={`absolute rounded-2xl flex items-center justify-center font-bold uppercase tracking-widest backdrop-blur-xl transition-all z-[150] select-none shadow-xl border border-white/10 bg-slate-900/80 text-yellow-600/50 hover:bg-slate-800 hover:text-yellow-500 active:bg-slate-700 active:text-yellow-400 ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : ''}`} style={{ ...draggableStyle('off'), width: largeBtnSize, height: largeBtnSize, fontSize: 11 * uiScale }} onPointerDown={(e) => handleButtonPress(e, 'off', onOff)}>OFF</button>
      <button className={`absolute rounded-2xl flex items-center justify-center font-bold uppercase tracking-widest backdrop-blur-xl transition-all z-[150] select-none shadow-xl border border-white/10 bg-slate-900/80 text-red-600/50 hover:bg-slate-800 hover:text-red-500 active:bg-slate-700 active:text-red-400 ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : ''}`} style={{ ...draggableStyle('panic'), width: largeBtnSize, height: largeBtnSize, fontSize: 11 * uiScale }} onPointerDown={(e) => handleButtonPress(e, 'panic', onPanic)}>PANIC</button>

      <button className={`absolute rounded-xl bg-slate-900/80 border border-white/10 flex items-center justify-center text-yellow-500 font-bold backdrop-blur-xl hover:bg-slate-800 hover:text-yellow-400 transition-all shadow-lg z-[150] select-none ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : ''}`} style={{ ...draggableStyle('center'), width: baseSize, height: baseSize }} onPointerDown={(e) => handleButtonPress(e, 'center', onCenter)} title="Center Display"><svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" style={{ width: baseSize * 0.5, height: baseSize * 0.5 }}><path strokeLinecap="round" strokeLinejoin="round" d="M3.75 3.75v4.5m0-4.5h4.5m-4.5 0L9 9M3.75 20.25v-4.5m0 4.5h4.5m-4.5 0L9 15M20.25 3.75h-4.5m4.5 0v4.5m0-4.5L15 9m5.25 11.25h-4.5m4.5 0v-4.5m0 4.5L15 15" /></svg></button>

      {showIncreaseDepthButton && (<button className={`absolute rounded-xl bg-slate-900/80 border border-white/10 flex items-center justify-center text-blue-500 font-bold backdrop-blur-xl hover:bg-slate-800 hover:text-blue-400 transition-all shadow-lg z-[150] select-none ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : ''}`} style={{ ...draggableStyle('depth'), width: baseSize, height: baseSize }} onPointerDown={(e) => handleButtonPress(e, 'depth', onIncreaseDepth)} title="Increase Depth from Selection"><svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" style={{ width: baseSize * 0.5, height: baseSize * 0.5 }}><path strokeLinecap="round" strokeLinejoin="round" d="M3.75 3.75v4.5m0-4.5h4.5m-4.5 0L9 9M3.75 20.25v-4.5m0 4.5h4.5m-4.5 0L9 15M20.25 3.75h-4.5m4.5 0v4.5m0-4.5L15 9m5.25 11.25h-4.5m4.5 0v-4.5m0 4.5L15 15" /><circle cx="12" cy="12" r="3" stroke="currentColor" strokeWidth="2" fill="none" /></svg></button>)}

      {showIncreaseDepthButton && (<button className={`absolute rounded-xl bg-green-600/20 border-2 border-green-500 flex items-center justify-center text-green-500 font-bold backdrop-blur hover:bg-green-600/40 active:bg-green-600 active:text-white transition-all shadow-[0_0_15px_rgba(34,197,94,0.4)] z-[150] select-none ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : ''}`} style={{ ...draggableStyle('decreaseDepth'), width: baseSize, height: baseSize }} onPointerDown={(e) => handleButtonPress(e, 'decreaseDepth', onDecreaseDepth)} title="Undo Last Depth Increase"><svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" style={{ width: baseSize * 0.5, height: baseSize * 0.5 }}><path strokeLinecap="round" strokeLinejoin="round" d="M4 4 L10 10 M10 10 L10 6 M10 10 L6 10" /><path strokeLinecap="round" strokeLinejoin="round" d="M20 4 L14 10 M14 10 L14 6 M14 10 L18 10" /><path strokeLinecap="round" strokeLinejoin="round" d="M4 20 L10 14 M10 14 L10 18 M10 14 L6 14" /><path strokeLinecap="round" strokeLinejoin="round" d="M20 20 L14 14 M14 14 L14 18 M14 14 L18 14" /></svg></button>)}

      <div className={`absolute flex gap-2 flex-wrap items-start z-[150] ${uiUnlocked ? 'cursor-move bg-slate-800/50 rounded-xl p-3 border border-yellow-500/30' : ''}`} style={{ ...draggableStyle('chords'), maxWidth: '80vw' }} onPointerDown={(e) => handleDrag(e, 'chords')}>
          <button className={`rounded-lg border border-slate-700 border-dashed flex items-center justify-center text-slate-500 font-bold backdrop-blur-xl bg-slate-900/80 hover:bg-slate-800 hover:text-white hover:border-white/50 transition-all select-none ${uiUnlocked ? 'pointer-events-none' : ''}`} style={{ width: chordSize, height: chordSize }} onPointerDown={(e) => !uiUnlocked && e.stopPropagation()} onClick={!uiUnlocked ? onAddChord : undefined} title="Store currently latched notes as a Chord"><svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" className="w-1/2 h-1/2"><path strokeLinecap="round" strokeLinejoin="round" d="M12 4.5v15m7.5-7.5h-15" /></svg></button>
          {savedChords.filter(c => c.visible).map((chord) => {
              const isActive = activeChordIds.includes(chord.id);
              return (<button key={chord.id} className={`rounded-lg flex items-center justify-center font-bold backdrop-blur-xl transition-all shadow-lg select-none border ${uiUnlocked ? 'pointer-events-none' : ''}`} style={{ width: chordSize, height: chordSize, fontSize: 11 * uiScale, backgroundColor: isActive ? chord.color : `${chord.color}11`, borderColor: chord.color, color: isActive ? '#fff' : chord.color, boxShadow: isActive ? `0 0 10px ${chord.color}40` : 'none' }} onPointerDown={(e) => !uiUnlocked && e.stopPropagation()} onClick={() => !uiUnlocked && toggleChord(chord.id)} title={`Chord ${chord.id}: ${chord.label}`}>{chord.id}</button>);
          })}
      </div>
    </>
  );
};

export default FloatingControls;

import React from 'react';
import { AppSettings } from '../types';
import { MARGIN_3MM, SCROLLBAR_WIDTH } from '../constants';

interface Props {
  settings: AppSettings;
  updateSettings: (s: AppSettings) => void;
  draggingId: string | null;
  setDraggingId: (id: string | null) => void;
  uiScale?: number;
}

const LIMITS = [1, 3, 5, 7, 11, 13];

const LimitLayerControls: React.FC<Props> = ({ settings, updateSettings, draggingId, setDraggingId, uiScale = 1.0 }) => {
  const { uiUnlocked, uiPositions } = settings;

  // Base sizing scaled by effective uiScale
  const buttonSize = 48 * uiScale; 
  const iconSize = 24 * uiScale; 

  const isVisible = (limit: number) => {
    // 1-Limit is always visible
    if (limit === 1) return true;
    return !settings.hiddenLimits.includes(limit);
  };

  const toggleVisibility = (limit: number) => {
    if (limit === 1) return;
    const isHidden = settings.hiddenLimits.includes(limit);
    let newHidden = [...settings.hiddenLimits];
    if (isHidden) {
      newHidden = newHidden.filter(l => l !== limit);
    } else {
      newHidden.push(limit);
    }
    updateSettings({ ...settings, hiddenLimits: newHidden });
  };

  const bringToFront = (limit: number) => {
    const newOrder = settings.layerOrder.filter(l => l !== limit);
    newOrder.push(limit);
    updateSettings({ ...settings, layerOrder: newOrder });
  };

  // Drag Handler
  const handleDrag = (e: React.PointerEvent) => {
    if (!uiUnlocked) return;
    if (draggingId !== null && draggingId !== 'layers') return;

    const el = e.currentTarget as HTMLElement;
    const startX = e.clientX;
    const startY = e.clientY;

    const initialLeft = uiPositions.layers.x;
    const initialTop = uiPositions.layers.y;

    el.setPointerCapture(e.pointerId);
    setDraggingId('layers');

    const onMove = (evt: PointerEvent) => {
        const deltaX = evt.clientX - startX;
        const deltaY = evt.clientY - startY;

        let newX = initialLeft + deltaX;
        let newY = initialTop + deltaY;

        const maxX = window.innerWidth - el.offsetWidth - MARGIN_3MM - SCROLLBAR_WIDTH;
        const maxY = window.innerHeight - el.offsetHeight - MARGIN_3MM - SCROLLBAR_WIDTH;
        const minX = MARGIN_3MM;
        const minY = MARGIN_3MM;

        newX = Math.max(minX, Math.min(newX, maxX));
        newY = Math.max(minY, Math.min(newY, maxY));

        updateSettings({ 
            ...settings, 
            uiPositions: { 
                ...settings.uiPositions, 
                layers: { x: newX, y: newY } 
            } 
        });
    };

    const onUp = () => {
        setDraggingId(null);
        window.removeEventListener('pointermove', onMove);
        window.removeEventListener('pointerup', onUp);
        window.removeEventListener('pointercancel', onUp);
    };

    window.addEventListener('pointermove', onMove);
    window.addEventListener('pointerup', onUp);
    window.addEventListener('pointercancel', onUp);
  };

  return (
    <div 
        className={`absolute flex flex-col gap-3 z-[140] bg-slate-900/90 p-2 rounded-2xl backdrop-blur-xl border border-white/10 shadow-xl ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : ''}`}
        style={{ left: uiPositions.layers.x, top: uiPositions.layers.y, touchAction: 'none' }}
        onPointerDown={handleDrag}
    >
      {LIMITS.map(limit => {
        const visible = isVisible(limit);
        const color = settings.colors[limit];
        const isTop = settings.layerOrder[settings.layerOrder.length - 1] === limit;
        const isLocked = limit === 1;

        return (
          <div key={limit} className="flex items-center gap-2 group">
            {/* Visibility Toggle */}
            <button 
              onClick={(e) => { e.stopPropagation(); !uiUnlocked && toggleVisibility(limit); }}
              disabled={isLocked}
              className={`flex items-center justify-center rounded transition-colors ${visible ? (isLocked ? 'text-slate-500 cursor-default opacity-50' : 'text-slate-300') : 'text-slate-600'} hover:text-white ${uiUnlocked ? 'pointer-events-none' : ''}`}
              style={{ width: iconSize, height: iconSize }}
              onPointerDown={(e) => !uiUnlocked && e.stopPropagation()} 
            >
               {visible ? (
                 <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-full h-full p-0.5">
                   <path d="M10 12.5a2.5 2.5 0 100-5 2.5 2.5 0 000 5z" />
                   <path fillRule="evenodd" d="M.664 10.59a1.651 1.651 0 010-1.186A10.004 10.004 0 0110 3c4.257 0 8.201 2.372 9.336 6.41.147.527.147 1.074 0 1.601C18.201 14.628 14.257 17 10 17c-4.257 0-8.201-2.372-9.336-6.41zM14 10a4 4 0 11-8 0 4 4 0 018 0z" clipRule="evenodd" />
                 </svg>
               ) : (
                 <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" className="w-full h-full p-0.5">
