// Helper component for Validated Numeric Input
const NumberInput = ({
    value,
    min,
    max,
    onChange,
    suffix = "",
    className = ""
}: {
    value: number;
    min: number;
    max: number;
    onChange: (val: number) => void;
    suffix?: string;
    className?: string;
}) => {
    const safeValue = (typeof value === 'number' && !isNaN(value)) ? value : min;
    const [text, setText] = useState(safeValue.toString());
    const [prevValue, setPrevValue] = useState(safeValue);
    const [error, setError] = useState<string | null>(null);

    if (value !== prevValue && value !== undefined && !isNaN(value)) {
        const currentNum = parseFloat(text);
        if (Math.abs(currentNum - value) > 0.0001) {
             setText(value.toString());
             setError(null);
        }
        setPrevValue(value);
    }

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const val = e.target.value;
        if (val !== '' && !/^[\d.]+$/.test(val)) return;
        setText(val);
        if (val === '') return; 
        const num = parseFloat(val);
        if (isNaN(num)) return;
        if (num < min || num > max) {
            setError(`Range: ${min}-${max}`);
        } else {
            setError(null);
            onChange(num);
        }
    };

    const handleBlur = () => {
        const num = parseFloat(text);
        if (text === '' || isNaN(num) || error) {
            setText(prevValue.toString());
            setError(null);
        }
    };

    return (
        <div className="flex flex-col flex-grow">
            <div className="relative">
                <input 
                    type="text" 
                    inputMode="decimal"
                    value={text}
                    onChange={handleChange}
                    onBlur={handleBlur}
                    className={`w-full bg-slate-800/80 rounded-lg p-2 text-sm text-white border border-white/10 focus:outline-none focus:border-blue-500 transition-colors ${className} ${error ? 'border-red-500 focus:border-red-500' : ''}`}
                />
                {suffix && <span className="absolute right-3 top-2 text-xs text-slate-500 pointer-events-none">{suffix}</span>}
            </div>
            {error && <span className="text-[10px] text-red-400 mt-1 font-bold animate-pulse">{error}</span>}
        </div>
    );
};

