      updateSettings({ ...settings, savedChords: newChords });
  };

  const setDefaultColors = () => {
    updateSettings({ ...settings, colors: { ...DEFAULT_COLORS } });
  };

  const hslToHex = (h: number, s: number, l: number) => {
    l /= 100;
    const a = s * Math.min(l, 1 - l) / 100;
    const f = (n: number) => {
      const k = (n + h / 30) % 12;
      const color = l - a * Math.max(Math.min(k - 3, 9 - k, 1), -1);
      return Math.round(255 * color).toString(16).padStart(2, '0');
    };
    return `#${f(0)}${f(8)}${f(4)}`;
  };

  const extractColorsFromImage = (imageSrc: string): Promise<LimitColorMap> => {
    return new Promise((resolve) => {
        const img = new Image();
        img.src = imageSrc;
        img.onload = () => {
            const cvs = document.createElement('canvas');
            const ctx = cvs.getContext('2d');
            cvs.width = 50;
            cvs.height = 50;
            ctx?.drawImage(img, 0, 0, 50, 50);
            const data = ctx?.getImageData(0, 0, 50, 50).data;
            if(!data) { resolve(DEFAULT_COLORS); return; }
            const getHex = (x: number, y: number) => {
                const i = (y * 50 + x) * 4;
                const r = data[i];
                const g = data[i+1];
                const b = data[i+2];
                return "#" + ((1 << 24) + (r << 16) + (g << 8) + b).toString(16).slice(1);
            }
            const extracted: LimitColorMap = { 1: getHex(25, 25), 3: getHex(10, 10), 5: getHex(40, 40), 7: getHex(40, 10), 11: getHex(10, 40), 13: getHex(25, 10) };
            resolve(extracted);
        };
        img.onerror = () => resolve(DEFAULT_COLORS);
    });
  };

  const pairLimitsToBackground = async () => {
