              const result = evt.target?.result as string;
              updateSettings({ ...settings, backgroundImageData: result, backgroundMode: 'image' });
          };
          reader.readAsDataURL(file);
      }
      if (bgImageInputRef.current) bgImageInputRef.current.value = '';
  };

  return (
    <div className="fixed inset-0 bg-black/60 z-[200] flex items-center justify-center backdrop-blur-sm">
      <div className="bg-slate-900/95 backdrop-blur-xl rounded-2xl w-[95%] max-w-4xl max-h-[90vh] overflow-hidden text-slate-200 shadow-2xl border border-white/10 flex flex-col">
