const SynthControls: React.FC<Props> = ({ presets, onChange, isOpen, onClose }) => {
  const [activeVoiceMode, setActiveVoiceMode] = useState<PlayMode>('normal');
  const [activeTab, setActiveTab] = useState<'osc1' | 'osc2' | 'osc3' | 'matrix' | 'fx' | 'arp'>('osc1');
  const { userBank, saveUserPatch } = useStore();
  const [isSaveMode, setIsSaveMode] = useState(false);
  const [saveSlotIndex, setSaveSlotIndex] = useState(0);
  const [saveName, setSaveName] = useState("");
  const [draggingCell, setDraggingCell] = useState<{ source: ModSource, target: ModTarget, startY: number, startVal: number } | null>(null);

  const categorizedPresets = useMemo(() => {
      const groups: Record<string, SynthPreset[]> = {};
      PRESETS.forEach(p => { const cat = p.category || 'Uncategorized'; if (!groups[cat]) groups[cat] = []; groups[cat].push(p); });
      return groups;
  }, []);

  if (!isOpen) return null;

  const currentPreset = presets[activeVoiceMode];
  // ... helper functions omitted for brevity (same as previous) ...
  const updateGlobal = (key: keyof SynthPreset, val: any) => { onChange(activeVoiceMode, { ...currentPreset, [key]: val }); };
  const updateArp = (key: keyof import('../types').ArpConfig, val: any) => { const currentArp = currentPreset.arpConfig || { direction: 'order', division: '1/8', octaves: 1, gate: 0.8, swing: 0 }; onChange(activeVoiceMode, { ...currentPreset, arpConfig: { ...currentArp, [key]: val } }); };
  const updateOsc = (oscKey: 'osc1' | 'osc2' | 'osc3', key: keyof OscillatorConfig, val: any) => { onChange(activeVoiceMode, { ...currentPreset, [oscKey]: { ...currentPreset[oscKey], [key]: val } }); };
  const loadPreset = (p: SynthPreset) => { onChange(activeVoiceMode, JSON.parse(JSON.stringify(p))); };
  const handleResetToDefault = () => { const factory = PRESETS.find(p => p.name === currentPreset.name); if (factory) loadPreset(factory); else { const userP = userBank.find(p => p.name === currentPreset.name); if (userP) loadPreset(userP); } };
  const handleSaveToSlot = () => { if (saveName.trim() === "") return; saveUserPatch(saveSlotIndex, { ...currentPreset, name: saveName, id: `user-${Date.now()}` }); setIsSaveMode(false); };
  const handleReverbTypeChange = (type: ReverbType) => { const d = REVERB_DEFAULTS[type]; onChange(activeVoiceMode, { ...currentPreset, reverbType: type, reverbSize: d.size, reverbDamping: d.damping, reverbDiffusion: d.diffusion }); };
  const getMatrixValue = (s: ModSource, t: ModTarget) => currentPreset.modMatrix?.find(r => r.source === s && r.target === t)?.amount || 0;
  const setMatrixValue = (s: ModSource, t: ModTarget, amt: number) => { 
      let m = [...(currentPreset.modMatrix || [])]; const idx = m.findIndex(r => r.source === s && r.target === t);
      if (amt === 0) { if (idx !== -1) m.splice(idx, 1); } 
      else { if (idx !== -1) m[idx] = { ...m[idx], amount: amt, enabled: true }; else m.push({ id: `${s}-${t}-${Date.now()}`, enabled: true, source: s, target: t, amount: amt }); }
      onChange(activeVoiceMode, { ...currentPreset, modMatrix: m });
  };
  const handleMatrixDragStart = (e: React.PointerEvent, s: ModSource, t: ModTarget) => { e.currentTarget.setPointerCapture(e.pointerId); setDraggingCell({ source: s, target: t, startY: e.clientY, startVal: getMatrixValue(s, t) }); };
  const handleMatrixDragMove = (e: React.PointerEvent) => { if (!draggingCell) return; const deltaY = draggingCell.startY - e.clientY; let v = Math.max(-100, Math.min(100, Math.round(draggingCell.startVal + deltaY))); if (v !== getMatrixValue(draggingCell.source, draggingCell.target)) setMatrixValue(draggingCell.source, draggingCell.target, v); };

  const renderOscillatorTab = (oscKey: 'osc1' | 'osc2' | 'osc3', label: string) => {
      const config = currentPreset[oscKey];
      return (
          <div className="space-y-6 animate-in fade-in duration-300">
              <div className="flex justify-between items-center mb-2 px-1">
                  <h3 className="text-xs font-bold text-slate-400 uppercase tracking-widest">{label}</h3>
                  {oscKey !== 'osc1' && (
                      <label className="flex items-center gap-2 cursor-pointer bg-white/5 px-2 py-1 rounded-lg border border-white/5 hover:bg-white/10 transition">
                          <input type="checkbox" checked={config.enabled} onChange={(e) => updateOsc(oscKey, 'enabled', e.target.checked)} className="rounded border-slate-600 text-indigo-500 focus:ring-indigo-500" />
                          <span className={`text-[10px] font-bold ${config.enabled ? 'text-white' : 'text-slate-500'}`}>{config.enabled ? 'ON' : 'OFF'}</span>
                      </label>
                  )}
              </div>
              <div className={`space-y-4 ${!config.enabled ? 'opacity-40 pointer-events-none grayscale' : ''}`}>
                <div className="p-4 bg-white/5 rounded-xl border border-white/5">
                    <div className="flex bg-black/20 rounded-lg p-1 mb-4">
                        {Object.values(WaveformType).map(w => (
                            <button key={w} onClick={() => updateOsc(oscKey, 'waveform', w)} className={`flex-1 py-1 text-[10px] rounded-md uppercase font-bold transition-all ${config.waveform === w ? 'bg-indigo-600 text-white shadow' : 'text-slate-500 hover:text-slate-300'}`}>{w}</button>
                        ))}
                    </div>
                    <div className="space-y-3">
                        {/* Sliders styled to match high-end look */}
                        {['gain', 'coarseDetune', 'fineDetune'].map(param => (
                            <div key={param}>
                                <label className="flex justify-between text-[10px] font-bold text-slate-500 mb-1 uppercase tracking-wide"><span>{param.replace('Detune', '')}</span></label>
                                <input type="range" 
                                    min={param === 'gain' ? 0 : param === 'coarseDetune' ? -1200 : -50} 
                                    max={param === 'gain' ? 1 : param === 'coarseDetune' ? 1200 : 50} 
                                    step={param === 'gain' ? 0.01 : param === 'coarseDetune' ? 10 : 1} 
                                    value={config[param as keyof OscillatorConfig] as number} 
                                    onChange={(e) => updateOsc(oscKey, param as keyof OscillatorConfig, parseFloat(e.target.value))} 
                                    className="w-full h-1 bg-slate-700 rounded-full appearance-none cursor-pointer" 
                                />
                            </div>
                        ))}
                    </div>
                </div>
                {/* Envelope Section */}
                <div className="p-4 bg-white/5 rounded-xl border border-white/5">
                    <h4 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-3">Envelope</h4>
                    <EnvelopeGraph attack={config.attack} decay={config.decay} sustain={config.sustain} release={config.release} />
                    <div className="grid grid-cols-4 gap-2 pt-3">
                        {['attack', 'decay', 'sustain', 'release'].map(p => (
                            <div key={p}>
                                <label className="block text-[9px] font-bold text-slate-500 uppercase text-center mb-1">{p.charAt(0)}</label>
                                <input type="range" min={p === 'sustain' ? 0 : 0.01} max={p === 'release' ? 8 : 5} step={0.01} value={config[p as keyof OscillatorConfig] as number} onChange={(e) => updateOsc(oscKey, p as keyof OscillatorConfig, parseFloat(e.target.value))} className="w-full h-20 bg-slate-700 rounded-full appearance-none cursor-pointer" style={{writingMode: 'vertical-lr', direction: 'rtl'}} />
                            </div>
                        ))}
                    </div>
                </div>
              </div>
          </div>
      );
  };

  const arpConfig = currentPreset.arpConfig || { direction: 'order', division: '1/8', octaves: 1, gate: 0.8, swing: 0 };

  return (
    <div className="fixed top-0 right-0 h-full w-[400px] bg-slate-900/90 backdrop-blur-xl shadow-2xl z-[200] border-l border-white/10 flex flex-col rounded-l-3xl">
        <div className="flex justify-between items-center p-6 border-b border-white/10 bg-white/5">
            <h2 className="text-lg font-bold tracking-widest uppercase text-white">Synth Engine</h2>
            <button onClick={onClose} className="text-slate-500 hover:text-white transition">Close</button>
        </div>

        <div className="flex border-b border-white/10 bg-black/20 p-1">
            {(['normal', 'latch', 'strum', 'arpeggio'] as PlayMode[]).map(mode => (
                <button key={mode} onClick={() => setActiveVoiceMode(mode)} className={`flex-1 py-2 text-[10px] font-bold uppercase tracking-wide rounded-lg transition-all ${activeVoiceMode === mode ? 'bg-indigo-600 text-white shadow' : 'text-slate-500 hover:text-slate-300'}`}>{mode}</button>
            ))}
        </div>

        <div className="flex border-b border-white/10 bg-slate-900/50">
            {['osc1', 'osc2', 'osc3', 'matrix', 'fx', 'arp'].map(tab => (
                 <button key={tab} onClick={() => setActiveTab(tab as any)} className={`flex-1 py-3 text-[9px] font-bold uppercase transition flex flex-col items-center gap-1 ${activeTab === tab ? 'text-white border-b-2 border-white bg-white/5' : 'text-slate-500 hover:text-slate-300'}`}>
                    {tab.replace('osc', 'OSC ').toUpperCase()}
                </button>
            ))}
        </div>

        <div className="flex-1 overflow-y-auto p-6 scrollbar-thin scrollbar-thumb-slate-700 bg-transparent" onPointerUp={() => setDraggingCell(null)} onPointerLeave={() => setDraggingCell(null)} onPointerMove={handleMatrixDragMove}>
            {activeTab.startsWith('osc') && renderOscillatorTab(activeTab as any, `Oscillator ${activeTab.slice(3)}`)}

            {activeTab === 'matrix' && (
                <div className="space-y-4">
                    <h3 className="text-xs font-bold text-purple-400 uppercase tracking-widest mb-2">Mod Matrix</h3>
                    <div className="overflow-x-auto pb-4"><div className="min-w-[600px]"><div className="grid grid-cols-[60px_repeat(12,1fr)] gap-1">
                        <div className="text-[9px] font-bold text-slate-600">SRC / DST</div>{MATRIX_TARGETS.map(t => (<div key={t.id} className="text-[8px] font-bold text-slate-500 text-center uppercase rotate-0 whitespace-nowrap overflow-hidden text-ellipsis" title={t.label}>{t.label.replace('Osc', 'O').replace('Pitch', 'P').replace('Cut', 'C').replace('Gain', 'G').replace('Res', 'Q')}</div>))}
                        {MATRIX_SOURCES.map(source => (<React.Fragment key={source.id}><div className="text-[9px] font-bold text-purple-400/80 flex items-center h-6 bg-white/5 px-1 rounded-l">{source.label}</div>{MATRIX_TARGETS.map(target => { const amount = getMatrixValue(source.id, target.id); const isActive = amount !== 0; return (<div key={`${source.id}-${target.id}`} className={`h-6 border border-white/5 rounded flex flex-col justify-end items-center relative overflow-hidden cursor-ns-resize group ${isActive ? 'bg-purple-900/40 border-purple-500/50' : 'bg-black/20 hover:bg-white/5'}`} onPointerDown={(e) => handleMatrixDragStart(e, source.id, target.id)}>{isActive && (<div className={`absolute bottom-0 left-0 w-full transition-all ${amount > 0 ? 'bg-purple-500' : 'bg-orange-500'}`} style={{ height: `${Math.abs(amount)}%`, opacity: 0.5 }} />)}<span className={`text-[8px] z-10 font-mono ${isActive ? 'text-white font-bold' : 'text-transparent group-hover:text-slate-500'}`}>{amount !== 0 ? amount : '-'}</span></div>); })}</React.Fragment>))}
                    </div></div></div>
                </div>
            )}

            {activeTab === 'arp' && (
                <div className="space-y-6">
                    <h3 className="text-xs font-bold text-red-400 uppercase tracking-widest mb-2">Arpeggiator</h3>
                    <div className="p-4 bg-white/5 rounded-xl border border-white/5 space-y-5">
                        <div>
                            <label className="block text-[10px] font-bold text-slate-500 mb-2 uppercase">Direction</label>
                            <div className="flex bg-black/20 rounded-lg p-1">
                                {(['order', 'up', 'down', 'updown', 'random'] as ArpDirection[]).map(dir => (
                                    <button key={dir} onClick={() => updateArp('direction', dir)} className={`flex-1 py-1 text-[9px] uppercase font-bold rounded ${arpConfig.direction === dir ? 'bg-red-600 text-white shadow' : 'text-slate-500 hover:text-slate-300'}`}>{dir}</button>
                                ))}
                            </div>
                        </div>
                        <div>
                            <label className="block text-[10px] font-bold text-slate-500 mb-2 uppercase">Division</label>
                            <div className="flex bg-black/20 rounded-lg p-1">
                                {(['1/1', '1/2', '1/4', '1/8', '1/16', '1/32'] as ArpDivision[]).map(div => (
                                    <button key={div} onClick={() => updateArp('division', div)} className={`flex-1 py-1 text-[9px] font-mono font-bold rounded ${arpConfig.division === div ? 'bg-red-600 text-white shadow' : 'text-slate-500 hover:text-slate-300'}`}>{div}</button>
                                ))}
                            </div>
                        </div>
                        {['octaves', 'gate', 'swing'].map(p => (
                            <div key={p}>
                                <label className="flex justify-between text-[10px] font-bold text-slate-500 mb-1 uppercase"><span>{p}</span><span className="text-white">{p === 'gate' ? (arpConfig.gate * 100).toFixed(0) + '%' : arpConfig[p as keyof typeof arpConfig]}</span></label>
                                <input type="range" min={p === 'octaves' ? 1 : p === 'gate' ? 0.1 : 0} max={p === 'octaves' ? 4 : p === 'gate' ? 1.0 : 100} step={p === 'gate' ? 0.05 : 1} value={arpConfig[p as keyof typeof arpConfig] as number} onChange={(e) => updateArp(p as any, parseFloat(e.target.value))} className="w-full h-1 bg-slate-700 rounded-full appearance-none cursor-pointer" />
                            </div>
                        ))}
                    </div>
                </div>
            )}

            {/* FX Tab placeholder structure for style match */}
            {activeTab === 'fx' && (
                 <div className="space-y-6">
                    <h3 className="text-xs font-bold text-green-400 uppercase tracking-widest mb-2">Global Effects</h3>
                    {/* ... Inputs same as before but styled with rounded-full inputs and bg-white/5 containers ... */}
                    <div className="p-4 bg-white/5 rounded-xl border border-white/5 space-y-4">
                         <h3 className="text-[10px] font-bold text-cyan-300 uppercase">Stereo & Pan</h3>
                         {/* ... mapped controls ... */}
                    </div>
                 </div>
            )}
        </div>
    </div>
  );
};

export default SynthControls;

import React, { useState, useEffect, useRef } from 'react';
import TonalityDiamond, { TonalityDiamondHandle } from './components/TonalityDiamond';
import SettingsModal from './components/SettingsModal';
import SynthControls from './components/SynthControls';
import FloatingControls from './components/FloatingControls';
import LimitLayerControls from './components/LimitLayerControls';
import { audioEngine } from './services/AudioEngine';
import { midiService } from './services/MidiService';
import { useStore } from './services/Store';
import { AppSettings, ChordDefinition, XYPos, ArpeggioStep } from './types';
import { PIXELS_PER_MM } from './constants';
import { arpeggiatorService } from './services/ArpeggiatorService';

const REFERENCE_SHORT_EDGE = 1080; 

const App: React.FC = () => {
  const { settings, presets, updateSettings, setPreset } = useStore();

  const [masterVolume, setMasterVolume] = useState(0.8);
  const [spatialScale, setSpatialScale] = useState(1.0); 
  const [activeChordIds, setActiveChordIds] = useState<string[]>([]);
  const [draggingId, setDraggingId] = useState<string | null>(null);
  const [autoScaleFactor, setAutoScaleFactor] = useState(1.0);
  const [latchMode, setLatchMode] = useState<0 | 1 | 2>(0);

  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isSynthOpen, setIsSynthOpen] = useState(false);

  // Arpeggio State
  const [recordingArpId, setRecordingArpId] = useState<string | null>(null);
  const [currentArpStep, setCurrentArpStep] = useState(0);

  const diamondRef = useRef<TonalityDiamondHandle>(null);

  const effectiveScale = autoScaleFactor * (settings.uiScale || 1.0);

  useEffect(() => {
    const warmup = (e: Event) => {
        audioEngine.resume().then(() => {});
        window.removeEventListener('pointerdown', warmup);
        window.removeEventListener('keydown', warmup);
        window.removeEventListener('touchstart', warmup);
        window.removeEventListener('touchend', warmup);
        window.removeEventListener('click', warmup);
    };

    window.addEventListener('pointerdown', warmup);
    window.addEventListener('keydown', warmup);
    window.addEventListener('touchstart', warmup);
    window.addEventListener('touchend', warmup);
    window.addEventListener('click', warmup);

    return () => {
        window.removeEventListener('pointerdown', warmup);
        window.removeEventListener('keydown', warmup);
        window.removeEventListener('touchstart', warmup);
        window.removeEventListener('touchend', warmup);
        window.removeEventListener('click', warmup);
    };
  }, []);

  useEffect(() => {
      document.documentElement.style.setProperty('--ui-scale', effectiveScale.toString());
  }, [effectiveScale]);

  const getSafeAreas = () => {
      if (typeof document === 'undefined') return { top: 0, right: 0, bottom: 0, left: 0 };
      const div = document.createElement('div');
      div.style.paddingTop = 'env(safe-area-inset-top)';
      div.style.paddingRight = 'env(safe-area-inset-right)';
      div.style.paddingBottom = 'env(safe-area-inset-bottom)';
      div.style.paddingLeft = 'env(safe-area-inset-left)';
      div.style.position = 'absolute';
      div.style.visibility = 'hidden';
      document.body.appendChild(div);
      const computed = getComputedStyle(div);
      const safe = {
          top: parseInt(computed.paddingTop) || 0,
          right: parseInt(computed.paddingRight) || 0,
          bottom: parseInt(computed.paddingBottom) || 0,
          left: parseInt(computed.paddingLeft) || 0
      };
      document.body.removeChild(div);
      return safe;
  };

  const applyLayout = (w: number, h: number, scale: number) => {
      const safeArea = getSafeAreas();
      const marginPx = (settings.uiEdgeMargin || 4) * PIXELS_PER_MM;

      const marginTop = marginPx + safeArea.top;
      const marginRight = marginPx + safeArea.right + (safeArea.right === 0 ? 4 : 0);
      const marginBottom = marginPx + safeArea.bottom;
      const marginLeft = marginPx + safeArea.left;
      const baseGap = marginPx; 

      const sliderWidth = 290 * scale; 
      // Arp Bar width = 2.0 * sliderWidth (Widened slightly)
      const arpBarWidth = sliderWidth * 2.0;

      const newPos = { ...settings.uiPositions };

      // Top Layout: [Space] [Volume] ... [ArpBar] ... [Settings/Synth]
      // Left Top
      newPos.space = { x: marginLeft, y: marginTop };
      newPos.volume = { x: marginLeft + sliderWidth + 20 * scale, y: marginTop };

      // Center Top (Arp Bar)
      // Centered between the Volume slider end and the Screen Center?
      // "between Settings and Volume". Settings is Right. Volume is Left.
      // So place Arp Bar in the middle of the screen x-axis roughly.
      const arpX = (w / 2) - (arpBarWidth / 2);
      newPos.arpeggioBar = { x: arpX, y: marginTop };

      const largeBtn = 80 * scale; 
      const limitBarWidth = 24 + (72 * scale); 
      const largeBtnWidth = largeBtn;
      const layerRowHeight = 48 * scale;
      const layerGap = 12;
      const layerPadding = 16;
      const layersHeight = (layerRowHeight * 6) + (layerGap * 5) + layerPadding;
      const separatorGap = largeBtn;
      const btnGap = 10 * scale;
      const totalStackHeight = layersHeight + separatorGap + (4 * largeBtn) + (3 * btnGap);
      let startY = (h / 2) - (totalStackHeight / 2);
      if (startY < marginTop + 50) startY = marginTop + 50;
      const limitBarX = w - marginRight - limitBarWidth;
      const buttonsX = w - marginRight - largeBtnWidth;

      newPos.layers = { x: limitBarX, y: startY };
      let currentY = startY + layersHeight + separatorGap;
      newPos.bend = { x: buttonsX, y: currentY };
      currentY += largeBtn + btnGap;
      newPos.latch = { x: buttonsX, y: currentY };
      currentY += largeBtn + btnGap;
      newPos.off = { x: buttonsX, y: currentY };
      currentY += largeBtn + btnGap;
      newPos.panic = { x: buttonsX, y: currentY };

      const baseBtn = 48 * scale;
      const bottomLiftOffset = 15 * scale;
      const bottomY = h - marginBottom - baseBtn - bottomLiftOffset; 
      let currentX = marginLeft;

      newPos.center = { x: currentX, y: bottomY };
      currentX += (baseBtn + baseGap); 
      if (settings.showIncreaseDepthButton) {
          newPos.depth = { x: currentX, y: bottomY };
          currentX += (baseBtn + baseGap);
          newPos.decreaseDepth = { x: currentX, y: bottomY };
          currentX += (baseBtn + baseGap);
      }
      currentX += 20 * scale; 
      newPos.chords = { x: currentX, y: bottomY };

      return newPos;
  };

  const windowSizeRef = useRef({ w: typeof window !== 'undefined' ? window.innerWidth : 1000, h: typeof window !== 'undefined' ? window.innerHeight : 800 });

  useEffect(() => {
    const handleResize = () => {
        const w = document.documentElement.clientWidth;
        const h = document.documentElement.clientHeight;
        const shortEdge = Math.min(w, h);
        const newAutoScale = shortEdge / REFERENCE_SHORT_EDGE;
        setAutoScaleFactor(newAutoScale);
        const newEffectiveScale = newAutoScale * (settings.uiScale || 1.0);
        updateSettings(prev => ({
            ...prev,
            uiPositions: applyLayout(w, h, newEffectiveScale)
        }));
        windowSizeRef.current = { w, h };
    };
    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, [settings.uiScale, settings.uiEdgeMargin, settings.showIncreaseDepthButton]); 

  useEffect(() => {
    audioEngine.setMasterVolume(masterVolume);
  }, [masterVolume]);

  useEffect(() => {
    audioEngine.setGlobalSpatialScale(spatialScale);
  }, [spatialScale]);

  const handleLimitInteraction = (limit: number) => {
    if (settings.layerOrder[settings.layerOrder.length - 1] !== limit) {
      const newOrder = settings.layerOrder.filter(l => l !== limit);
      newOrder.push(limit);
      updateSettings(prev => ({ ...prev, layerOrder: newOrder }));
    }
  };

  const handlePanic = () => {
    audioEngine.stopAll(); 
    arpeggiatorService.stop();
    midiService.panic();
    diamondRef.current?.clearLatches(); 
    setActiveChordIds([]); 
    setLatchMode(0);
    setRecordingArpId(null);
    updateSettings(prev => ({ 
        ...prev, 
        arpeggios: prev.arpeggios.map(a => ({ ...a, isPlaying: false })) 
    }));
    setIsSettingsOpen(false);
    setIsSynthOpen(false);
  };

  const handleOff = () => {
    diamondRef.current?.clearLatches(); 
    setActiveChordIds([]);
    setLatchMode(0);
    setRecordingArpId(null);
  };

  const handleLatchToggle = () => {
      setLatchMode(prev => {
          const next = prev + 1;
          if (next > 2) {
              diamondRef.current?.clearLatches();
              return 0;
          }
          return next as 0 | 1 | 2;
      });
  };

  const handleBendToggle = () => updateSettings(prev => ({ ...prev, isPitchBendEnabled: !prev.isPitchBendEnabled }));
  const handleCenter = () => diamondRef.current?.centerView();
  const handleIncreaseDepth = () => diamondRef.current?.increaseDepth();
  const handleDecreaseDepth = () => diamondRef.current?.decreaseDepth();

  const handleAddChord = () => {
      if (diamondRef.current) {
          const latchedNodes = diamondRef.current.getLatchedNodes();
          if (latchedNodes.length === 0) return;
          let slotIndex = settings.savedChords.findIndex(c => c.nodes.length === 0);
          if (slotIndex === -1) slotIndex = settings.savedChords.findIndex(c => !c.visible);

          if (slotIndex !== -1) {
              const newChords = [...settings.savedChords];
              const simplifiedNodes = latchedNodes.map(n => ({ id: n.id, n: n.n, d: n.d }));
              newChords[slotIndex] = {
                  ...newChords[slotIndex],
                  nodes: simplifiedNodes,
                  visible: true,
                  position: { x: 0, y: 0 } 
              };
              updateSettings(prev => ({ ...prev, savedChords: newChords }));
          }
      }
  };

  const toggleChord = (id: string) => {
      setActiveChordIds(prev => prev.includes(id) ? prev.filter(c => c !== id) : [...prev, id]);
  };

  const handleUiPositionUpdate = (key: keyof AppSettings['uiPositions'], pos: XYPos) => {
      updateSettings(prev => ({ ...prev, uiPositions: { ...prev.uiPositions, [key]: pos } }));
  };

  // --- Arp Handlers ---
  const handleArpToggle = (id: string) => {
      const arp = settings.arpeggios.find(a => a.id === id);
      if (!arp) return;

      if (recordingArpId === id) {
          setRecordingArpId(null);
          return;
      }

      if (recordingArpId) {
          setRecordingArpId(id);
          return;
      }

      if (arp.steps.length === 0) {
          setRecordingArpId(id);
          updateSettings(prev => ({
              ...prev,
              arpeggios: prev.arpeggios.map(a => a.id === id ? { ...a, isPlaying: false } : a)
          }));
          return;
      }

      const newIsPlaying = !arp.isPlaying;
      const newArps = settings.arpeggios.map(a => {
          if (a.id === id) return { ...a, isPlaying: newIsPlaying };
          return { ...a, isPlaying: false };
      });

      updateSettings(prev => ({ ...prev, arpeggios: newArps }));

      if (newIsPlaying) {
          arpeggiatorService.start(arp.steps, settings.arpBpm, (step) => setCurrentArpStep(step));
      } else {
          arpeggiatorService.stop();
      }
  };

  const handleArpRecordNote = (nodeId: string, ratio: number) => {
      if (!recordingArpId) return;

      const arpIndex = settings.arpeggios.findIndex(a => a.id === recordingArpId);
      if (arpIndex === -1) return;

      const currentSteps = settings.arpeggios[arpIndex].steps;
      if (currentSteps.length >= 32) {
          setRecordingArpId(null);
          return;
      }

      const newStep: ArpeggioStep = { nodeId, ratio };
      const newArps = [...settings.arpeggios];
      newArps[arpIndex] = {
          ...newArps[arpIndex],
          steps: [...currentSteps, newStep]
      };

      updateSettings(prev => ({ ...prev, arpeggios: newArps }));
  };

  const handleArpBpmChange = (bpm: number) => {
      updateSettings(prev => ({ ...prev, arpBpm: bpm }));
      arpeggiatorService.updateBpm(bpm);
  };

  useEffect(() => {
      const handleKeyDown = (e: KeyboardEvent) => {
          if (e.key === 'Escape' && (isSettingsOpen || isSynthOpen)) {
              setIsSettingsOpen(false); setIsSynthOpen(false); return;
          }
          const target = e.target as HTMLElement;
          if (target.tagName === 'INPUT' || target.tagName === 'SELECT' || target.tagName === 'TEXTAREA') return;
          if (!settings.enableKeyboardShortcuts) return;

          const key = e.key.toLowerCase();
          if ([' ', 'arrowup', 'arrowdown', 'arrowleft', 'arrowright'].includes(key)) e.preventDefault();

          switch(key) {
              case ' ': handleLatchToggle(); break;
              case 'escape': handlePanic(); break;
              case 'c': handleCenter(); break;
              case 's': setIsSettingsOpen(prev => !prev); if(isSynthOpen) setIsSynthOpen(false); break;
              case 'm': setIsSynthOpen(prev => !prev); if(isSettingsOpen) setIsSettingsOpen(false); break;
              case 'o': handleOff(); break;
              case 'b': handleBendToggle(); break;
              case 'enter': case 'a': handleAddChord(); break;
              case '.': handleIncreaseDepth(); break;
              case ',': handleDecreaseDepth(); break;
              case 'arrowup': setMasterVolume(v => Math.min(1.0, v + 0.05)); break;
              case 'arrowdown': setMasterVolume(v => Math.max(0.0, v - 0.05)); break;
              case 'arrowright': setSpatialScale(s => Math.min(2.0, s + 0.05)); break;
              case 'arrowleft': setSpatialScale(s => Math.max(0.0, s - 0.05)); break;
          }
      };
      window.addEventListener('keydown', handleKeyDown);
      return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isSettingsOpen, isSynthOpen, settings.enableKeyboardShortcuts]);

  const marginPx = (settings.uiEdgeMargin || 4) * PIXELS_PER_MM;
  const headerTop = `calc(${marginPx}px + env(safe-area-inset-top))`;
  const headerLeft = `calc(${marginPx}px + env(safe-area-inset-left))`;
  const headerRight = `calc(${marginPx}px + env(safe-area-inset-right))`;

  return (
    <div className="relative w-screen h-screen overflow-hidden bg-slate-900 font-sans text-white">
      <div className="absolute z-50 pointer-events-none" style={{ top: headerTop, left: headerLeft }}>
        <h1 className="text-sm font-bold tracking-widest text-slate-500 opacity-20 leading-none">PRISMATONAL</h1>
      </div>

      <div className="absolute z-50 flex gap-2 pointer-events-auto" style={{ top: headerTop, right: headerRight }}>
          <button onClick={() => setIsSettingsOpen(true)} className="bg-slate-800/80 hover:bg-slate-700 px-3 py-1 text-xs rounded backdrop-blur transition border border-white/10 h-8 flex items-center font-bold text-slate-400 uppercase tracking-widest hover:text-white">Settings</button>
          <button onClick={() => setIsSynthOpen(true)} className="bg-slate-800/80 hover:bg-indigo-900/50 px-3 py-1 text-xs rounded backdrop-blur transition border border-white/10 h-8 flex items-center font-bold text-slate-400 uppercase tracking-widest hover:text-white">Synth</button>
      </div>

      <TonalityDiamond 
        ref={diamondRef}
        settings={settings}
        updateSettings={updateSettings}
        audioEngine={audioEngine} 
        onLimitInteraction={handleLimitInteraction}
        activeChordIds={activeChordIds}
        uiUnlocked={settings.uiUnlocked}
        latchMode={latchMode}
        globalScale={effectiveScale}
        onNodeTrigger={handleArpRecordNote} 
      />

      <FloatingControls 
        volume={masterVolume} setVolume={setMasterVolume}
        spatialScale={spatialScale} setSpatialScale={setSpatialScale}
        onPanic={handlePanic} onOff={handleOff}
        onLatch={handleLatchToggle} latchMode={latchMode}
        onBend={handleBendToggle} isBendEnabled={settings.isPitchBendEnabled}
        onCenter={handleCenter}
        onIncreaseDepth={handleIncreaseDepth} onDecreaseDepth={handleDecreaseDepth}
        onAddChord={handleAddChord} toggleChord={toggleChord}
        activeChordIds={activeChordIds} savedChords={settings.savedChords}
        chordShortcutSizeScale={settings.chordShortcutSizeScale}
        showIncreaseDepthButton={settings.showIncreaseDepthButton}
        uiUnlocked={settings.uiUnlocked}
        uiPositions={settings.uiPositions} updatePosition={handleUiPositionUpdate}
        draggingId={draggingId} setDraggingId={setDraggingId}
        uiScale={effectiveScale}

        arpeggios={settings.arpeggios}
        arpBpm={settings.arpBpm}
        onArpToggle={handleArpToggle}
        onArpBpmChange={handleArpBpmChange}
        recordingArpId={recordingArpId}
        currentArpStep={currentArpStep}
      />

      <LimitLayerControls settings={settings} updateSettings={updateSettings} draggingId={draggingId} setDraggingId={setDraggingId} uiScale={effectiveScale} />
      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} settings={settings} updateSettings={updateSettings} />
      <SynthControls isOpen={isSynthOpen} onClose={() => setIsSynthOpen(false)} presets={presets} onChange={setPreset} />
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { ChordDefinition, XYPos, AppSettings, ArpeggioDefinition } from '../types';
import { MARGIN_3MM, SCROLLBAR_WIDTH } from '../constants';

interface Props {
  volume: number;
  setVolume: (v: number) => void;
  spatialScale: number;
  setSpatialScale: (v: number) => void;
  onPanic: () => void;
  onOff: () => void;
  onLatch: () => void;
  latchMode: 0 | 1 | 2;
  onBend: () => void;
  isBendEnabled: boolean;
  onCenter: () => void;
  onIncreaseDepth: () => void;
  onDecreaseDepth: () => void;
  onAddChord: () => void;
  toggleChord: (id: string) => void;
  activeChordIds: string[];
  savedChords: ChordDefinition[];
  chordShortcutSizeScale: number;
  showIncreaseDepthButton: boolean;
  uiUnlocked: boolean;
  uiPositions: AppSettings['uiPositions'];
  updatePosition: (key: keyof AppSettings['uiPositions'], pos: XYPos) => void;
  draggingId: string | null;
  setDraggingId: (id: string | null) => void;
  uiScale?: number;

  // Arp Props
  arpeggios?: ArpeggioDefinition[];
  arpBpm?: number;
  onArpToggle?: (id: string) => void;
  onArpBpmChange?: (bpm: number) => void;
  recordingArpId?: string | null; // ID of arp currently recording (blinking)
  currentArpStep?: number;
}

const FloatingControls: React.FC<Props> = ({ 
  volume, setVolume, spatialScale, setSpatialScale, 
  onPanic, onOff, onLatch, latchMode, onBend, isBendEnabled, onCenter, onIncreaseDepth, onDecreaseDepth, onAddChord, toggleChord,
  activeChordIds, savedChords, chordShortcutSizeScale,
  showIncreaseDepthButton, uiUnlocked, uiPositions, updatePosition,
  draggingId, setDraggingId,
  uiScale = 1.0,
  arpeggios = [], arpBpm = 120, onArpToggle, onArpBpmChange, recordingArpId, currentArpStep
}) => {

  const [showSequencer, setShowSequencer] = useState(false);

  const handleDrag = (e: React.PointerEvent, key: keyof AppSettings['uiPositions']) => {
    if (!uiUnlocked) return;
    if (draggingId !== null && draggingId !== key) return;

    const el = e.currentTarget as HTMLElement;
    const startX = e.clientX;
    const startY = e.clientY;
    const initialLeft = uiPositions[key as keyof typeof uiPositions].x;
    const initialTop = uiPositions[key as keyof typeof uiPositions].y;

    el.setPointerCapture(e.pointerId);
    setDraggingId(key);

    const onMove = (evt: PointerEvent) => {
        const deltaX = evt.clientX - startX;
        const deltaY = evt.clientY - startY;
        let newX = initialLeft + deltaX;
        let newY = initialTop + deltaY;
        const maxX = window.innerWidth - el.offsetWidth - MARGIN_3MM - SCROLLBAR_WIDTH;
        const maxY = window.innerHeight - el.offsetHeight - MARGIN_3MM - SCROLLBAR_WIDTH;
        const minX = MARGIN_3MM;
        const minY = MARGIN_3MM;
        newX = Math.max(minX, Math.min(newX, maxX));
        newY = Math.max(minY, Math.min(newY, maxY));
        updatePosition(key, { x: newX, y: newY });
    };

    const onUp = () => {
        setDraggingId(null);
        window.removeEventListener('pointermove', onMove);
        window.removeEventListener('pointerup', onUp);
        window.removeEventListener('pointercancel', onUp);
    };

    window.addEventListener('pointermove', onMove);
    window.addEventListener('pointerup', onUp);
    window.addEventListener('pointercancel', onUp);
  };

  const baseSize = 48 * uiScale; 
  const chordSize = baseSize * chordShortcutSizeScale;
  const largeBtnSize = 80 * uiScale;

  const sliderWidth = 290 * uiScale; 
  const sliderHeight = 40 * uiScale;

  // Widened Arp Bar
  const arpBarWidth = sliderWidth * 2.0;

  const draggableStyle = (key: string) => ({
      left: uiPositions[key as keyof typeof uiPositions].x,
      top: uiPositions[key as keyof typeof uiPositions].y,
      touchAction: 'none' as React.CSSProperties['touchAction'],
  });

  const handleButtonPress = (e: React.PointerEvent, key: keyof AppSettings['uiPositions'], action: () => void) => {
      e.stopPropagation();
      if (uiUnlocked) {
          handleDrag(e, key);
      } else {
          action();
      }
  };

  // REVERTED to rounded-full
  const getLatchStyle = () => {
      const base = "absolute rounded-full flex items-center justify-center font-bold uppercase tracking-widest backdrop-blur-xl transition-all z-[150] select-none shadow-xl border border-white/10";
      const unlocked = uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : '';

      if (latchMode === 1) return `${base} ${unlocked} bg-green-600/90 text-white shadow-[0_0_20px_rgba(34,197,94,0.4)]`;
      else if (latchMode === 2) return `${base} ${unlocked} bg-slate-900/90 text-green-400 border-green-500/50 ring-1 ring-green-500/30 animate-pulse`;
      else return `${base} ${unlocked} bg-slate-900/80 text-green-600/50 hover:bg-slate-800 hover:text-green-500 active:bg-slate-700 active:text-green-400`;
  };

  const getButtonStyle = (active: boolean, colorClass: string) => {
      const base = "absolute rounded-full flex items-center justify-center font-bold uppercase tracking-widest backdrop-blur-xl transition-all z-[150] select-none shadow-xl border border-white/10";
      const unlocked = uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : '';
      if (active) return `${base} ${unlocked} bg-${colorClass}-600/90 text-white shadow-[0_0_15px_rgba(var(--color-${colorClass}-500),0.4)]`;
      return `${base} ${unlocked} bg-slate-900/80 text-slate-500 hover:bg-slate-800 hover:text-${colorClass}-400 active:bg-slate-700 active:text-white`;
  };

  // Find currently active or recording arp to display in Sequencer
  const activeArp = arpeggios.find(a => a.isPlaying || a.id === recordingArpId);
  const activeSteps = activeArp ? activeArp.steps : [];

  return (
    <>
      <style>{`
        .prismatonal-slider::-webkit-slider-thumb { -webkit-appearance: none; appearance: none; width: 12px; height: 12px; border-radius: 50%; background: currentColor; cursor: pointer; border: 2px solid white; box-shadow: 0 0 5px rgba(0,0,0,0.5); }
        .prismatonal-slider::-moz-range-thumb { width: 12px; height: 12px; border-radius: 50%; background: currentColor; cursor: pointer; border: 2px solid white; box-shadow: 0 0 5px rgba(0,0,0,0.5); }
      `}</style>

      {/* Arpeggio Bar */}
      <div 
        className={`absolute bg-slate-900/90 rounded-2xl flex flex-col items-center backdrop-blur-xl border border-white/10 transition-colors z-[150] shadow-2xl overflow-visible ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : ''}`}
        style={{ ...draggableStyle('arpeggioBar'), minWidth: arpBarWidth, padding: 10 * uiScale }}
        onPointerDown={(e) => handleDrag(e, 'arpeggioBar')}
      >
        <div className="w-full flex flex-col gap-3">
             <div className="flex justify-between items-center px-2 pt-1">
                 <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">ARPEGGIATOR</span>
                 <div className="flex items-center gap-3">
                     <div className={`w-1.5 h-1.5 rounded-full transition-colors ${arpeggios.some(a => a.isPlaying) && (Math.floor(Date.now() / (30000/arpBpm!)) % 2 === 0) ? 'bg-green-400 shadow-[0_0_5px_lime]' : 'bg-slate-700'}`}></div>
                     {/* BPM Buttons */}
                     <div className="flex items-center gap-1 bg-slate-950/50 rounded-lg p-1 border border-white/5">
                        <button 
                            className="w-5 h-5 flex items-center justify-center bg-slate-800 hover:bg-slate-700 rounded text-[10px] text-slate-400"
                            onPointerDown={(e) => { e.stopPropagation(); onArpBpmChange && onArpBpmChange(Math.max(1, (arpBpm || 120) - 1)); }}
                        >-</button>
                        <input 
                            type="number" 
                            value={arpBpm} 
                            onChange={(e) => onArpBpmChange && onArpBpmChange(parseInt(e.target.value))}
                            className="w-8 bg-transparent text-center text-[10px] font-mono font-bold text-slate-300 focus:outline-none"
                            onPointerDown={(e) => e.stopPropagation()}
                        />
                        <button 
                            className="w-5 h-5 flex items-center justify-center bg-slate-800 hover:bg-slate-700 rounded text-[10px] text-slate-400"
                            onPointerDown={(e) => { e.stopPropagation(); onArpBpmChange && onArpBpmChange(Math.min(300, (arpBpm || 120) + 1)); }}
                        >+</button>
                     </div>
                     <span className="text-[8px] text-slate-500 font-bold tracking-wider">BPM</span>
                 </div>
             </div>

             <div className="flex gap-2 justify-center flex-wrap px-1">
                 {arpeggios.map(arp => {
                     const isRecording = recordingArpId === arp.id;
                     const isPlaying = arp.isPlaying;
                     const hasData = arp.steps.length > 0;

                     let btnClass = "bg-slate-800/50 border-slate-700 text-slate-500 hover:bg-slate-700 hover:text-slate-300";
                     if (isRecording) btnClass = "bg-red-500/20 border-red-500/50 text-red-400 animate-pulse shadow-[0_0_10px_rgba(239,68,68,0.2)]";
                     else if (isPlaying) btnClass = "bg-blue-600 text-white border-blue-500 shadow-[0_0_10px_rgba(59,130,246,0.3)]";
                     else if (hasData) btnClass = "bg-slate-800 border-blue-500/30 text-blue-400";

                     return (
                         <button 
                            key={arp.id}
                            // Reverted to rounded (squares) and made larger
                            className={`rounded flex items-center justify-center font-bold border transition-all active:scale-95 ${btnClass}`}
                            style={{ width: 40 * uiScale, height: 40 * uiScale, fontSize: 14 * uiScale }}
                            onPointerDown={(e) => { e.stopPropagation(); if(onArpToggle) onArpToggle(arp.id); }}
                         >
                             {arp.id}
                         </button>
                     );
                 })}
             </div>
        </div>

        {/* Dropdown Toggle */}
        <button 
            className="w-full h-3 mt-2 bg-slate-800/30 hover:bg-slate-700/50 rounded-full flex items-center justify-center cursor-pointer transition-colors group"
            onPointerDown={(e) => { e.stopPropagation(); setShowSequencer(!showSequencer); }}
        >
             <svg xmlns="http://www.w3.org/2000/svg" className={`h-2 w-2 text-slate-600 group-hover:text-slate-400 transition-transform ${showSequencer ? 'rotate-180' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
               <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M19 9l-7 7-7-7" />
             </svg>
        </button>

        {/* Sequencer Dropdown */}
        {showSequencer && (
            <div 
                className="absolute top-full left-0 bg-slate-900/95 backdrop-blur-xl border border-white/10 rounded-xl mt-2 shadow-2xl p-4 z-[140] flex flex-col gap-3"
                style={{ width: '400px', height: '280px', transformOrigin: 'top left' }}
                onPointerDown={(e) => e.stopPropagation()} 
            >
                <div className="flex justify-between items-center pb-2 border-b border-white/5">
                    <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">SEQUENCER VIEW ({activeArp?.id || 'None'})</span>
                    <span className="text-[9px] font-mono text-slate-600">{activeSteps.length} Steps</span>
                </div>

                <div className="flex-1 overflow-x-auto overflow-y-hidden flex gap-px items-end p-3 bg-black/40 rounded-lg relative inner-shadow border border-white/5">
                    {activeSteps.length === 0 && (
                        <div className="absolute inset-0 flex items-center justify-center text-slate-600 text-[10px] uppercase tracking-wider">
                            {recordingArpId ? "Play notes to record..." : "Select an Arp to view"}
                        </div>
                    )}
                    {activeSteps.map((step, idx) => {
                        const isCurrent = idx === currentArpStep;
                        const heightPct = Math.min(100, Math.max(10, Math.log2(step.ratio) * 20 + 50));

                        return (
                            <div key={idx} className="flex flex-col gap-1 items-center min-w-[16px] h-full justify-end group relative">
                                <div 
                                    className={`w-3 rounded-sm transition-all ${isCurrent ? 'bg-white shadow-[0_0_8px_white]' : 'bg-blue-500/40 hover:bg-blue-400/80'}`} 
                                    style={{ height: `${heightPct}%` }}
                                ></div>
                                <div className="h-px w-full bg-white/5"></div>
                            </div>
                        );
                    })}
                </div>
                <div className="flex justify-between items-end">
                     <div className="text-[9px] text-slate-600 font-mono">
                        {recordingArpId ? <span className="text-red-400 animate-pulse">● RECORDING</span> : "READY"}
                     </div>
                </div>
            </div>
        )}
      </div>

      {/* Volume Slider */}
      <div 
        className={`absolute bg-slate-900/90 rounded-2xl flex items-center gap-3 backdrop-blur-xl border border-white/10 transition-colors z-[150] px-4 shadow-xl ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : ''}`}
        style={{ ...draggableStyle('volume'), width: sliderWidth, height: sliderHeight }}
        onPointerDown={(e) => handleDrag(e, 'volume')}
      >
        <span className="font-bold text-slate-400 select-none text-center tracking-widest" style={{ fontSize: 9 * uiScale, width: 50 * uiScale }}>VOL</span>
        <input 
          type="range" min="0" max="1" step="0.01" value={volume} onChange={(e) => setVolume(parseFloat(e.target.value))} disabled={uiUnlocked}
          className={`prismatonal-slider w-full rounded-full appearance-none bg-slate-800 h-1.5 ${uiUnlocked ? 'cursor-move opacity-50' : 'cursor-pointer'}`}
          style={{ background: `linear-gradient(to right, #22c55e 0%, #22c55e ${volume * 100}%, #1e293b ${volume * 100}%, #1e293b 100%)` }}
          onPointerDown={(e) => !uiUnlocked && e.stopPropagation()} 
        />
      </div>

      {/* Reverb Slider */}
      <div 
        className={`absolute bg-slate-900/90 rounded-2xl flex items-center gap-3 backdrop-blur-xl border border-white/10 transition-colors z-[150] px-4 shadow-xl ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : ''}`}
        style={{ ...draggableStyle('space'), width: sliderWidth, height: sliderHeight }}
        onPointerDown={(e) => handleDrag(e, 'space')}
      >
        <span className="font-bold text-slate-400 select-none text-center tracking-widest" style={{ fontSize: 9 * uiScale, width: 50 * uiScale }}>VERB</span>
        <input 
            type="range" min="0" max="2" step="0.01" value={spatialScale} onChange={(e) => setSpatialScale(parseFloat(e.target.value))} disabled={uiUnlocked}
            className={`prismatonal-slider w-full rounded-full appearance-none bg-slate-800 h-1.5 ${uiUnlocked ? 'cursor-move opacity-50' : 'cursor-pointer'}`}
            style={{ background: `linear-gradient(to right, #3b82f6 0%, #3b82f6 ${(spatialScale/2) * 100}%, #1e293b ${(spatialScale/2) * 100}%, #1e293b 100%)` }}
            onPointerDown={(e) => !uiUnlocked && e.stopPropagation()} 
        />
      </div>

      <button className={getButtonStyle(isBendEnabled, 'purple')} style={{ ...draggableStyle('bend'), width: largeBtnSize, height: largeBtnSize, fontSize: 11 * uiScale }} onPointerDown={(e) => handleButtonPress(e, 'bend', onBend)}>BEND</button>
      <button className={getLatchStyle()} style={{ ...draggableStyle('latch'), width: largeBtnSize, height: largeBtnSize, fontSize: 11 * uiScale }} onPointerDown={(e) => handleButtonPress(e, 'latch', onLatch)}>LATCH</button>
      <button className={`absolute rounded-full flex items-center justify-center font-bold uppercase tracking-widest backdrop-blur-xl transition-all z-[150] select-none shadow-xl border border-white/10 bg-slate-900/80 text-yellow-600/50 hover:bg-slate-800 hover:text-yellow-500 active:bg-slate-700 active:text-yellow-400 ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : ''}`} style={{ ...draggableStyle('off'), width: largeBtnSize, height: largeBtnSize, fontSize: 11 * uiScale }} onPointerDown={(e) => handleButtonPress(e, 'off', onOff)}>OFF</button>
      <button className={`absolute rounded-full flex items-center justify-center font-bold uppercase tracking-widest backdrop-blur-xl transition-all z-[150] select-none shadow-xl border border-white/10 bg-slate-900/80 text-red-600/50 hover:bg-slate-800 hover:text-red-500 active:bg-slate-700 active:text-red-400 ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : ''}`} style={{ ...draggableStyle('panic'), width: largeBtnSize, height: largeBtnSize, fontSize: 11 * uiScale }} onPointerDown={(e) => handleButtonPress(e, 'panic', onPanic)}>PANIC</button>

      {/* REVERTED bottom buttons to 'rounded' squares */}
      <button className={`absolute rounded bg-slate-900/80 border border-white/10 flex items-center justify-center text-yellow-500 font-bold backdrop-blur-xl hover:bg-slate-800 hover:text-yellow-400 transition-all shadow-lg z-[150] select-none ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : ''}`} style={{ ...draggableStyle('center'), width: baseSize, height: baseSize }} onPointerDown={(e) => handleButtonPress(e, 'center', onCenter)} title="Center Display"><svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" style={{ width: baseSize * 0.5, height: baseSize * 0.5 }}><path strokeLinecap="round" strokeLinejoin="round" d="M3.75 3.75v4.5m0-4.5h4.5m-4.5 0L9 9M3.75 20.25v-4.5m0 4.5h4.5m-4.5 0L9 15M20.25 3.75h-4.5m4.5 0v4.5m0-4.5L15 9m5.25 11.25h-4.5m4.5 0v-4.5m0 4.5L15 15" /></svg></button>

      {showIncreaseDepthButton && (<button className={`absolute rounded bg-slate-900/80 border border-white/10 flex items-center justify-center text-blue-500 font-bold backdrop-blur-xl hover:bg-slate-800 hover:text-blue-400 transition-all shadow-lg z-[150] select-none ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : ''}`} style={{ ...draggableStyle('depth'), width: baseSize, height: baseSize }} onPointerDown={(e) => handleButtonPress(e, 'depth', onIncreaseDepth)} title="Increase Depth from Selection"><svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" style={{ width: baseSize * 0.5, height: baseSize * 0.5 }}><path strokeLinecap="round" strokeLinejoin="round" d="M3.75 3.75v4.5m0-4.5h4.5m-4.5 0L9 9M3.75 20.25v-4.5m0 4.5h4.5m-4.5 0L9 15M20.25 3.75h-4.5m4.5 0v4.5m0-4.5L15 9m5.25 11.25h-4.5m4.5 0v-4.5m0 4.5L15 15" /><circle cx="12" cy="12" r="3" stroke="currentColor" strokeWidth="2" fill="none" /></svg></button>)}

      {showIncreaseDepthButton && (<button className={`absolute rounded bg-green-600/20 border-2 border-green-500 flex items-center justify-center text-green-500 font-bold backdrop-blur hover:bg-green-600/40 active:bg-green-600 active:text-white transition-all shadow-[0_0_15px_rgba(34,197,94,0.4)] z-[150] select-none ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : ''}`} style={{ ...draggableStyle('decreaseDepth'), width: baseSize, height: baseSize }} onPointerDown={(e) => handleButtonPress(e, 'decreaseDepth', onDecreaseDepth)} title="Undo Last Depth Increase"><svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={2} stroke="currentColor" style={{ width: baseSize * 0.5, height: baseSize * 0.5 }}><path strokeLinecap="round" strokeLinejoin="round" d="M4 4 L10 10 M10 10 L10 6 M10 10 L6 10" /><path strokeLinecap="round" strokeLinejoin="round" d="M20 4 L14 10 M14 10 L14 6 M14 10 L18 10" /><path strokeLinecap="round" strokeLinejoin="round" d="M4 20 L10 14 M10 14 L10 18 M10 14 L6 14" /><path strokeLinecap="round" strokeLinejoin="round" d="M20 20 L14 14 M14 14 L14 18 M14 14 L18 14" /></svg></button>)}

      <div className={`absolute flex gap-2 flex-wrap items-start z-[150] ${uiUnlocked ? 'cursor-move bg-slate-800/50 rounded-xl p-3 border border-yellow-500/30' : ''}`} style={{ ...draggableStyle('chords'), maxWidth: '80vw' }} onPointerDown={(e) => handleDrag(e, 'chords')}>
