          <h2 className="text-lg font-bold text-white tracking-widest uppercase">Configuration</h2>
          <button onClick={onClose} className="text-slate-500 hover:text-white transition group" title="Close">
             <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 group-hover:scale-110 transition-transform" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
             </svg>
          </button>
        </div>

        {/* Tabs */}
        <div className="flex border-b border-white/10 bg-black/20 overflow-x-auto flex-shrink-0 relative z-10">
           {['general', 'behavior', 'color', 'midi', 'data'].map(tab => (
               <button 
                key={tab}
                onClick={() => setActiveTab(tab as any)} 
                className={`flex-1 py-3 px-4 text-xs font-bold uppercase tracking-wider transition whitespace-nowrap ${activeTab === tab ? 'text-white border-b-2 border-white bg-white/5' : 'text-slate-500 hover:text-slate-300'}`}
               >
                   {tab}
               </button>
           ))}
        </div>

        <div className="p-6 overflow-y-auto flex-1 min-h-0 bg-transparent">
            {activeTab === 'general' && (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8 animate-in fade-in duration-300">
                  <div className="space-y-6">
                      <h3 className="text-xs font-bold text-blue-400 border-b border-white/10 pb-1 uppercase tracking-wider">Audio Settings</h3>
                      <div className="bg-white/5 p-4 rounded-xl border border-white/5 space-y-3">
                          <label className="block text-xs font-bold text-slate-400 uppercase">Latency Mode</label>
                          <div className="flex gap-2">
                              {['interactive', 'balanced', 'playback'].map(mode => (
                                  <button key={mode} onClick={() => handleChange('audioLatencyHint', mode)} className={`flex-1 py-2 text-[10px] font-bold rounded-lg border capitalize tracking-wide transition-all ${settings.audioLatencyHint === mode ? 'bg-blue-600 border-blue-500 text-white shadow-lg' : 'bg-slate-800 border-slate-700 text-slate-500 hover:bg-slate-700'}`}>{mode === 'interactive' ? 'Low' : mode === 'playback' ? 'High' : mode}</button>
                              ))}
                          </div>
                      </div>
                      <h3 className="text-xs font-bold text-blue-400 border-b border-white/10 pb-1 uppercase tracking-wider">Grid Structure</h3>
                      <div>
                          <label className="block text-xs font-bold text-slate-400 mb-2 uppercase">Base Frequency</label>
                          <NumberInput value={settings.baseFrequency} min={20} max={15000} suffix="Hz" onChange={(val) => handleChange('baseFrequency', val)} />
                      </div>
                      <div className="bg-white/5 p-4 rounded-xl border border-white/5 space-y-4">
                          <label className="block text-xs font-bold text-slate-400 uppercase">Lattice Depth</label>
                          {[3, 5, 7, 11, 13].map(limit => (
                              <div key={limit} className="flex items-center gap-3">
                                  <span className="w-12 text-[10px] font-bold text-slate-500">{limit}-Lim</span>
                                  <input type="range" min="0" max="6" step="1" value={settings.limitDepths?.[limit as 3|5|7|11|13] ?? 0} onChange={(e) => handleLimitDepthChange(limit as any, parseInt(e.target.value))} className="flex-grow h-1 bg-slate-700 rounded-lg appearance-none cursor-pointer" />
                                  <span className="text-[10px] font-mono w-4 text-right text-slate-300">{settings.limitDepths?.[limit as 3|5|7|11|13] ?? 0}</span>
                              </div>
                          ))}
                      </div>
                  </div>
                  <div className="space-y-6">
