                       <div className="bg-white/5 p-4 rounded-xl border border-white/5 space-y-4">
                           <div>
                               <label className="block text-xs font-bold text-slate-400 mb-2 uppercase">Scale</label>
                               <div className="flex gap-2">
                                   {[0.5, 0.75, 1.0, 1.25, 1.5].map(scale => (
                                       <button key={scale} onClick={() => handleChange('uiScale', scale)} className={`flex-1 py-2 text-[10px] font-bold rounded-lg border transition-all ${settings.uiScale === scale ? 'bg-blue-600 border-blue-500 text-white' : 'bg-slate-800 border-slate-700 text-slate-500 hover:bg-slate-700'}`}>{scale}</button>
                                   ))}
                               </div>
                           </div>
                       </div>
                  </div>
