  const updateOsc = (oscKey: 'osc1' | 'osc2' | 'osc3', key: keyof OscillatorConfig, val: any) => { onChange(activeVoiceMode, { ...currentPreset, [oscKey]: { ...currentPreset[oscKey], [key]: val } }); };
  const loadPreset = (p: SynthPreset) => { onChange(activeVoiceMode, JSON.parse(JSON.stringify(p))); };
  const handleResetToDefault = () => { const factory = PRESETS.find(p => p.name === currentPreset.name); if (factory) loadPreset(factory); else { const userP = userBank.find(p => p.name === currentPreset.name); if (userP) loadPreset(userP); } };
  const handleSaveToSlot = () => { if (saveName.trim() === "") return; saveUserPatch(saveSlotIndex, { ...currentPreset, name: saveName, id: `user-${Date.now()}` }); setIsSaveMode(false); };
  const handleReverbTypeChange = (type: ReverbType) => { const d = REVERB_DEFAULTS[type]; onChange(activeVoiceMode, { ...currentPreset, reverbType: type, reverbSize: d.size, reverbDamping: d.damping, reverbDiffusion: d.diffusion }); };
  const getMatrixValue = (s: ModSource, t: ModTarget) => currentPreset.modMatrix?.find(r => r.source === s && r.target === t)?.amount || 0;
  const setMatrixValue = (s: ModSource, t: ModTarget, amt: number) => { 
      let m = [...(currentPreset.modMatrix || [])]; const idx = m.findIndex(r => r.source === s && r.target === t);
      if (amt === 0) { if (idx !== -1) m.splice(idx, 1); } 
      else { if (idx !== -1) m[idx] = { ...m[idx], amount: amt, enabled: true }; else m.push({ id: `${s}-${t}-${Date.now()}`, enabled: true, source: s, target: t, amount: amt }); }
      onChange(activeVoiceMode, { ...currentPreset, modMatrix: m });
  };
  const handleMatrixDragStart = (e: React.PointerEvent, s: ModSource, t: ModTarget) => { e.currentTarget.setPointerCapture(e.pointerId); setDraggingCell({ source: s, target: t, startY: e.clientY, startVal: getMatrixValue(s, t) }); };
  const handleMatrixDragMove = (e: React.PointerEvent) => { if (!draggingCell) return; const deltaY = draggingCell.startY - e.clientY; let v = Math.max(-100, Math.min(100, Math.round(draggingCell.startVal + deltaY))); if (v !== getMatrixValue(draggingCell.source, draggingCell.target)) setMatrixValue(draggingCell.source, draggingCell.target, v); };

  const renderOscillatorTab = (oscKey: 'osc1' | 'osc2' | 'osc3', label: string) => {
      const config = currentPreset[oscKey];
      return (
          <div className="space-y-6 animate-in fade-in duration-300">
