import { ArpeggioStep, SynthPreset } from '../types';
import { audioEngine } from './AudioEngine';
import { midiService } from './MidiService';
import { store } from './Store';

type OnStepCallback = (stepIndex: number) => void;

class ArpeggiatorService {
    private isRunning: boolean = false;
    private timerId: number | null = null;
    private currentStepIndex: number = 0;

    // The "source" steps from the recording
    private baseSteps: ArpeggioStep[] = [];

    // The "effective" steps after processing Direction and Octave Range
    private playbackQueue: { nodeId: string, ratio: number, originalIndex: number }[] = [];

    private onStepCallback: OnStepCallback | null = null;
    private lastPlayedVoiceId: string | null = null;
    private lastNoteOffTimer: number | null = null;

    public start(steps: ArpeggioStep[], bpm: number, onStep?: OnStepCallback) {
        this.stop();
        if (steps.length === 0) return;

        this.baseSteps = steps;
        this.onStepCallback = onStep || null;
        this.isRunning = true;
        this.currentStepIndex = 0;

        this.recalculateQueue();
        this.scheduleNextStep();
    }

    public stop() {
        this.isRunning = false;
        if (this.timerId) {
            clearTimeout(this.timerId);
            this.timerId = null;
        }
        if (this.lastNoteOffTimer) {
            clearTimeout(this.lastNoteOffTimer);
            this.lastNoteOffTimer = null;
        }
        this.stopLastNote();
        this.currentStepIndex = 0;
    }

    public updateBpm(newBpm: number) {
        // Just continue running, the next schedule will pick up the new BPM from store/args
    }

    private stopLastNote() {
        if (this.lastPlayedVoiceId) {
            audioEngine.stopVoice(this.lastPlayedVoiceId);
            midiService.noteOff(this.lastPlayedVoiceId);
            this.lastPlayedVoiceId = null;
        }
    }

    private recalculateQueue() {
        const state = store.getSnapshot();
        const preset = state.presets.arpeggio;
        const config = preset.arpConfig || { direction: 'order', division: '1/8', octaves: 1, gate: 0.8, swing: 0, length: 16 };

        let pool = this.baseSteps.map((s, i) => ({ ...s, originalIndex: i }));
        let final: { nodeId: string, ratio: number, originalIndex: number }[] = [];

        // 1. Octave Expansion
        const octaves = Math.max(1, Math.min(4, config.octaves));
        let expandedPool = [];
        for (let oct = 0; oct < octaves; oct++) {
            const mult = Math.pow(2, oct);
            for (const step of pool) {
                expandedPool.push({
                    nodeId: step.nodeId, // Note: nodeId string might refer to base octave, but ratio is what matters for audio
                    ratio: step.ratio * mult,
                    originalIndex: step.originalIndex,
                    sortRatio: step.ratio * mult 
                });
            }
        }

        // 2. Direction
        switch (config.direction) {
            case 'up':
                expandedPool.sort((a, b) => a.sortRatio - b.sortRatio);
                final = expandedPool;
                break;
            case 'down':
                expandedPool.sort((a, b) => b.sortRatio - a.sortRatio);
                final = expandedPool;
                break;
            case 'updown':
                {
                    const up = [...expandedPool].sort((a, b) => a.sortRatio - b.sortRatio);
                    const down = [...expandedPool].sort((a, b) => b.sortRatio - a.sortRatio);
                    // Avoid repeating top/bottom notes? Standard arp usually repeats.
                    final = [...up, ...down];
                }
                break;
            case 'random':
                // Shuffle
                for (let i = expandedPool.length - 1; i > 0; i--) {
                    const j = Math.floor(Math.random() * (i + 1));
                    [expandedPool[i], expandedPool[j]] = [expandedPool[j], expandedPool[i]];
                }
                final = expandedPool;
                break;
            case 'order':
            default:
                // Order preserves recording order, but what about octaves?
                // Usually Order + Octaves means: Sequence Oct 0, Sequence Oct 1, etc.
                final = expandedPool; // Already in Octave 0 then Oct 1 order from loop above
                break;
        }

        this.playbackQueue = final;
    }

    private scheduleNextStep() {
        if (!this.isRunning) return;

        const state = store.getSnapshot();
        const bpm = state.settings.arpBpm || 120;
        const preset = state.presets.arpeggio;
        const config = preset.arpConfig || { direction: 'order', division: '1/8', octaves: 1, gate: 0.8, swing: 0, length: 16 };

        // 1. Calculate Note Duration
        const beatMs = 60000 / bpm; // Duration of 1/4 note
        let div = 0.5; // default 1/8 relative to 1/4 beat

        switch(config.division) {
            case '1/1': div = 4.0; break;
            case '1/2': div = 2.0; break;
            case '1/4': div = 1.0; break;
            case '1/8': div = 0.5; break;
            case '1/16': div = 0.25; break;
            case '1/32': div = 0.125; break;
            // Triplets: 2/3 of the straight value
            case '1/4T': div = 1.0 * (2/3); break;
            case '1/8T': div = 0.5 * (2/3); break;
            case '1/16T': div = 0.25 * (2/3); break;
        }
        const stepDurationMs = beatMs * div;

        // 2. Calculate Swing
        // Swing affects even steps (index 1, 3, 5...)
        let currentDelay = stepDurationMs;
        if (config.swing > 0) {
            const isEvenStep = (this.currentStepIndex % 2) !== 0; // 0-based index. 0 is "Odd" (1st), 1 is "Even" (2nd)
            const swingAmount = (config.swing / 100) * 0.33; // Max 33% swing (triplet feel)

            if (isEvenStep) {
                currentDelay = stepDurationMs * (1.0 - swingAmount); 
            } else {
                currentDelay = stepDurationMs * (1.0 + swingAmount);
            }
        }

        // 3. Play Current Step
        this.recalculateQueue(); // Refresh queue in case settings changed
        if (this.playbackQueue.length === 0) return;

        // Apply Pattern Length Constraint
        const patternLength = Math.max(1, config.length || 16);

        // Modulo by pattern length to loop within the defined grid size
        // If queue is shorter than length, we just loop the queue (standard arp behavior)
        // BUT if user wants "Matrix Sequencer" feel, empty steps should be silence?
        // Standard Arps usually just cycle the notes you hold. The "Pattern Length" is usually implicit.
        // However, if we want to simulate a sequencer with N steps, and we have M notes...
        // Let's stick to standard Arp behavior: cycle through available notes. 
        // The "Length" parameter will strictly clip the cycle if the generated sequence is longer,
        // or just serve as the visualization grid.
        // Let's make "Length" define the loop point of the SEQUENCE.

        // Effective loop length is the minimum of (actual generated notes) and (configured length)
        // Wait, if I set length 16 and play 3 notes, I expect 3 notes to loop.
        // If I set length 2 and play 3 notes, I expect 2 notes to loop.
        const effectiveLoopLength = Math.min(this.playbackQueue.length, patternLength);

        // Safely wrap index
        const wrappedIndex = this.currentStepIndex % effectiveLoopLength;
        const step = this.playbackQueue[wrappedIndex];

        // Trigger Sound
        if (this.lastPlayedVoiceId) {
            this.stopLastNote();
        }

        const voiceId = `arp-${step.nodeId}-${Date.now()}`;
        audioEngine.startVoice(voiceId, step.ratio, state.settings.baseFrequency, 'arpeggio');
        if (state.settings.midiEnabled) {
            midiService.noteOn(voiceId, step.ratio, state.settings.baseFrequency, state.settings.midiPitchBendRange);
        }
        this.lastPlayedVoiceId = voiceId;

        // Visual Callback (maps back to original recorder index)
        if (this.onStepCallback) {
            this.onStepCallback(step.originalIndex);
        }

        // Schedule Note Off (Gate)
        const gateLen = stepDurationMs * Math.min(1.0, Math.max(0.1, config.gate));
        this.lastNoteOffTimer = window.setTimeout(() => {
            this.stopLastNote();
        }, gateLen);

        // Schedule Next Step
        this.timerId = window.setTimeout(() => {
            this.currentStepIndex++;
            this.scheduleNextStep();
        }, currentDelay);
    }
}

export const arpeggiatorService = new ArpeggiatorService();

import React, { useState, useEffect, useRef } from 'react';
import TonalityDiamond, { TonalityDiamondHandle } from './components/TonalityDiamond';
import SettingsModal from './components/SettingsModal';
import SynthControls from './components/SynthControls';
import FloatingControls from './components/FloatingControls';
import LimitLayerControls from './components/LimitLayerControls';
import { audioEngine } from './services/AudioEngine';
import { midiService } from './services/MidiService';
import { useStore } from './services/Store';
import { AppSettings, ChordDefinition, XYPos, ArpeggioStep, ArpConfig } from './types';
import { PIXELS_PER_MM } from './constants';
import { arpeggiatorService } from './services/ArpeggiatorService';

const REFERENCE_SHORT_EDGE = 1080; 

const App: React.FC = () => {
  const { settings, presets, updateSettings, setPreset } = useStore();

  const [masterVolume, setMasterVolume] = useState(0.8);
  const [spatialScale, setSpatialScale] = useState(1.0); 
  const [brightness, setBrightness] = useState(1.0); // Tone control

  const [activeChordIds, setActiveChordIds] = useState<string[]>([]);
  const [draggingId, setDraggingId] = useState<string | null>(null);
  const [autoScaleFactor, setAutoScaleFactor] = useState(1.0);
  const [latchMode, setLatchMode] = useState<0 | 1 | 2>(0);

  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isSynthOpen, setIsSynthOpen] = useState(false);

  // Arpeggio State
  const [recordingArpId, setRecordingArpId] = useState<string | null>(null);
  const [currentArpStep, setCurrentArpStep] = useState(0);

  const diamondRef = useRef<TonalityDiamondHandle>(null);

  const effectiveScale = autoScaleFactor * (settings.uiScale || 1.0);

  useEffect(() => {
    const warmup = (e: Event) => {
        audioEngine.resume().then(() => {});
        window.removeEventListener('pointerdown', warmup);
        window.removeEventListener('keydown', warmup);
        window.removeEventListener('touchstart', warmup);
        window.removeEventListener('touchend', warmup);
        window.removeEventListener('click', warmup);
    };

    window.addEventListener('pointerdown', warmup);
    window.addEventListener('keydown', warmup);
    window.addEventListener('touchstart', warmup);
    window.addEventListener('touchend', warmup);
    window.addEventListener('click', warmup);

    return () => {
        window.removeEventListener('pointerdown', warmup);
        window.removeEventListener('keydown', warmup);
        window.removeEventListener('touchstart', warmup);
        window.removeEventListener('touchend', warmup);
        window.removeEventListener('click', warmup);
    };
  }, []);

  useEffect(() => {
      document.documentElement.style.setProperty('--ui-scale', effectiveScale.toString());
  }, [effectiveScale]);

  const getSafeAreas = () => {
      if (typeof document === 'undefined') return { top: 0, right: 0, bottom: 0, left: 0 };
      const div = document.createElement('div');
      div.style.paddingTop = 'env(safe-area-inset-top)';
      div.style.paddingRight = 'env(safe-area-inset-right)';
      div.style.paddingBottom = 'env(safe-area-inset-bottom)';
      div.style.paddingLeft = 'env(safe-area-inset-left)';
      div.style.position = 'absolute';
      div.style.visibility = 'hidden';
      document.body.appendChild(div);
      const computed = getComputedStyle(div);
      const safe = {
          top: parseInt(computed.paddingTop) || 0,
          right: parseInt(computed.paddingRight) || 0,
          bottom: parseInt(computed.paddingBottom) || 0,
          left: parseInt(computed.paddingLeft) || 0
      };
      document.body.removeChild(div);
      return safe;
  };

  const applyLayout = (w: number, h: number, scale: number) => {
      const safeArea = getSafeAreas();
      const marginPx = (settings.uiEdgeMargin || 4) * PIXELS_PER_MM;

      const marginTop = marginPx + safeArea.top;
      const marginRight = marginPx + safeArea.right + (safeArea.right === 0 ? 4 : 0);
      const marginBottom = marginPx + safeArea.bottom;
      const marginLeft = marginPx + safeArea.left;
      const baseGap = marginPx; 

      // Widened Audio Stack (approx 2cm wider than previous)
      const audioStackWidth = 400 * scale; 
      const arpBarWidth = 250 * scale;
      const settingsAreaWidth = 180 * scale; 

      const newPos = { ...settings.uiPositions };

      const requiredWidth = arpBarWidth + audioStackWidth + settingsAreaWidth + (baseGap * 4);
      const shouldHideExtras = w < requiredWidth;

      if (shouldHideExtras) {
          newPos.arpeggioBar = { x: -9999, y: -9999 };
          newPos.layers = { x: -9999, y: -9999 };
          newPos.volume = { x: (w / 2) - (audioStackWidth / 2), y: marginTop };
      } else {
          newPos.arpeggioBar = { x: marginLeft, y: marginTop };
          const startSpace = marginLeft + arpBarWidth + baseGap;
          const endSpace = w - marginRight - settingsAreaWidth - baseGap;
          const centerAvailable = (startSpace + endSpace) / 2;
          newPos.volume = { x: centerAvailable - (audioStackWidth / 2), y: marginTop };
      }

      newPos.space = { x: -9999, y: -9999 };

      const largeBtn = 80 * scale; 
      const limitBarWidth = 24 + (72 * scale); 
      const largeBtnWidth = largeBtn;
      const layerRowHeight = 48 * scale;
      const layerGap = 12;
      const layerPadding = 16;
      const layersHeight = (layerRowHeight * 6) + (layerGap * 5) + layerPadding;
      const separatorGap = largeBtn;
      const btnGap = 10 * scale;
      const totalStackHeight = layersHeight + separatorGap + (4 * largeBtn) + (3 * btnGap);

      let startY = (h / 2) - (totalStackHeight / 2);
      if (startY < marginTop + 50) startY = marginTop + 50;

      const buttonsX = w - marginRight - largeBtnWidth;

      if (shouldHideExtras) {
          newPos.layers = { x: -9999, y: -9999 };
      } else {
          const limitBarX = w - marginRight - limitBarWidth;
          newPos.layers = { x: limitBarX, y: startY };
      }

      let currentY = startY + layersHeight + separatorGap;
      newPos.bend = { x: buttonsX, y: currentY };
      currentY += largeBtn + btnGap;
      newPos.latch = { x: buttonsX, y: currentY };
      currentY += largeBtn + btnGap;
      newPos.off = { x: buttonsX, y: currentY };
      currentY += largeBtn + btnGap;
      newPos.panic = { x: buttonsX, y: currentY };

      const baseBtn = 48 * scale;
      const bottomLiftOffset = 15 * scale;
      const bottomY = h - marginBottom - baseBtn - bottomLiftOffset; 
      let currentX = marginLeft;

      newPos.center = { x: currentX, y: bottomY };
      currentX += (baseBtn + baseGap); 
      if (settings.showIncreaseDepthButton) {
          newPos.depth = { x: currentX, y: bottomY };
          currentX += (baseBtn + baseGap);
          newPos.decreaseDepth = { x: currentX, y: bottomY };
          currentX += (baseBtn + baseGap);
      }
      currentX += 20 * scale; 
      newPos.chords = { x: currentX, y: bottomY };

      return newPos;
  };

  const windowSizeRef = useRef({ w: typeof window !== 'undefined' ? window.innerWidth : 1000, h: typeof window !== 'undefined' ? window.innerHeight : 800 });

  useEffect(() => {
    const handleResize = () => {
        const w = document.documentElement.clientWidth;
        const h = document.documentElement.clientHeight;
        const shortEdge = Math.min(w, h);
        const newAutoScale = shortEdge / REFERENCE_SHORT_EDGE;
        setAutoScaleFactor(newAutoScale);
        const newEffectiveScale = newAutoScale * (settings.uiScale || 1.0);
        updateSettings(prev => ({
            ...prev,
            uiPositions: applyLayout(w, h, newEffectiveScale)
        }));
        windowSizeRef.current = { w, h };
    };
    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, [settings.uiScale, settings.uiEdgeMargin, settings.showIncreaseDepthButton]); 

  useEffect(() => {
    audioEngine.setMasterVolume(masterVolume);
  }, [masterVolume]);

  useEffect(() => {
    audioEngine.setGlobalSpatialScale(spatialScale);
  }, [spatialScale]);

  useEffect(() => {
    audioEngine.setGlobalBrightness(brightness);
  }, [brightness]);

  const handleLimitInteraction = (limit: number) => {
    if (settings.layerOrder[settings.layerOrder.length - 1] !== limit) {
      const newOrder = settings.layerOrder.filter(l => l !== limit);
      newOrder.push(limit);
      updateSettings(prev => ({ ...prev, layerOrder: newOrder }));
    }
  };

  const handlePanic = () => {
    audioEngine.stopAll(); 
    arpeggiatorService.stop();
    midiService.panic();
    diamondRef.current?.clearLatches(); 
    setActiveChordIds([]); 
    setLatchMode(0);
    setRecordingArpId(null);
    updateSettings(prev => ({ 
        ...prev, 
        arpeggios: prev.arpeggios.map(a => ({ ...a, isPlaying: false })) 
    }));
    setIsSettingsOpen(false);
    setIsSynthOpen(false);
  };

  const handleOff = () => {
    diamondRef.current?.clearLatches(); 
    setActiveChordIds([]);
    setLatchMode(0);
    setRecordingArpId(null);
  };

  const handleLatchToggle = () => {
      setLatchMode(prev => {
          const next = prev + 1;
          if (next > 2) {
              diamondRef.current?.clearLatches();
              return 0;
          }
          return next as 0 | 1 | 2;
      });
  };

  const handleBendToggle = () => updateSettings(prev => ({ ...prev, isPitchBendEnabled: !prev.isPitchBendEnabled }));
  const handleCenter = () => diamondRef.current?.centerView();
  const handleIncreaseDepth = () => diamondRef.current?.increaseDepth();
  const handleDecreaseDepth = () => diamondRef.current?.decreaseDepth();

  const handleAddChord = () => {
      if (diamondRef.current) {
          const latchedNodes = diamondRef.current.getLatchedNodes();
          if (latchedNodes.length === 0) return;
          let slotIndex = settings.savedChords.findIndex(c => c.nodes.length === 0);
          if (slotIndex === -1) slotIndex = settings.savedChords.findIndex(c => !c.visible);

          if (slotIndex !== -1) {
              const newChords = [...settings.savedChords];
              const simplifiedNodes = latchedNodes.map(n => ({ id: n.id, n: n.n, d: n.d }));
              newChords[slotIndex] = {
                  ...newChords[slotIndex],
                  nodes: simplifiedNodes,
                  visible: true,
                  position: { x: 0, y: 0 } 
              };
              updateSettings(prev => ({ ...prev, savedChords: newChords }));
          }
      }
  };

  const toggleChord = (id: string) => {
      setActiveChordIds(prev => prev.includes(id) ? prev.filter(c => c !== id) : [...prev, id]);
  };

  const handleUiPositionUpdate = (key: keyof AppSettings['uiPositions'], pos: XYPos) => {
      updateSettings(prev => ({ ...prev, uiPositions: { ...prev.uiPositions, [key]: pos } }));
  };

  // --- Arp Handlers ---
  const handleArpToggle = (id: string) => {
      const arp = settings.arpeggios.find(a => a.id === id);
      if (!arp) return;

      if (recordingArpId === id) {
          setRecordingArpId(null);
          return;
      }

      if (recordingArpId) {
          setRecordingArpId(id);
          return;
      }

      if (arp.steps.length === 0) {
          setRecordingArpId(id);
          updateSettings(prev => ({
              ...prev,
              arpeggios: prev.arpeggios.map(a => a.id === id ? { ...a, isPlaying: false } : a)
          }));
          return;
      }

      const newIsPlaying = !arp.isPlaying;
      const newArps = settings.arpeggios.map(a => {
          if (a.id === id) return { ...a, isPlaying: newIsPlaying };
          return { ...a, isPlaying: false }; 
      });

      updateSettings(prev => ({ ...prev, arpeggios: newArps }));

      if (newIsPlaying) {
          arpeggiatorService.start(arp.steps, settings.arpBpm, (step) => setCurrentArpStep(step));
      } else {
          arpeggiatorService.stop();
      }
  };

  const handleArpRecordNote = (nodeId: string, ratio: number) => {
      if (!recordingArpId) return;

      const arpIndex = settings.arpeggios.findIndex(a => a.id === recordingArpId);
      if (arpIndex === -1) return;

      const currentSteps = settings.arpeggios[arpIndex].steps;
      if (currentSteps.length >= 32) {
          setRecordingArpId(null);
          return;
      }

      const newStep: ArpeggioStep = { nodeId, ratio };
      const newArps = [...settings.arpeggios];
      newArps[arpIndex] = {
          ...newArps[arpIndex],
          steps: [...currentSteps, newStep]
      };

      updateSettings(prev => ({ ...prev, arpeggios: newArps }));
  };

  const handleArpBpmChange = (bpm: number) => {
      updateSettings(prev => ({ ...prev, arpBpm: bpm }));
      arpeggiatorService.updateBpm(bpm);
  };

  const handleArpConfigChange = (partial: Partial<ArpConfig>) => {
      const currentPreset = presets.arpeggio;
      if (!currentPreset) return;
      const currentConfig = currentPreset.arpConfig || { direction: 'order', division: '1/8', octaves: 1, gate: 0.8, swing: 0, length: 16 };
      setPreset('arpeggio', { 
          ...currentPreset, 
          arpConfig: { ...currentConfig, ...partial } 
      });
  };

  useEffect(() => {
      const handleKeyDown = (e: KeyboardEvent) => {
          if (e.key === 'Escape' && (isSettingsOpen || isSynthOpen)) {
              setIsSettingsOpen(false); setIsSynthOpen(false); return;
          }
          const target = e.target as HTMLElement;
          if (target.tagName === 'INPUT' || target.tagName === 'SELECT' || target.tagName === 'TEXTAREA') return;
          if (!settings.enableKeyboardShortcuts) return;

          const key = e.key.toLowerCase();
          if ([' ', 'arrowup', 'arrowdown', 'arrowleft', 'arrowright'].includes(key)) e.preventDefault();

          switch(key) {
              case ' ': handleLatchToggle(); break;
              case 'escape': handlePanic(); break;
              case 'c': handleCenter(); break;
              case 's': setIsSettingsOpen(prev => !prev); if(isSynthOpen) setIsSynthOpen(false); break;
              case 'm': setIsSynthOpen(prev => !prev); if(isSettingsOpen) setIsSettingsOpen(false); break;
              case 'o': handleOff(); break;
              case 'b': handleBendToggle(); break;
              case 'enter': case 'a': handleAddChord(); break;
              case '.': handleIncreaseDepth(); break;
              case ',': handleDecreaseDepth(); break;
              case 'arrowup': setMasterVolume(v => Math.min(1.0, v + 0.05)); break;
              case 'arrowdown': setMasterVolume(v => Math.max(0.0, v - 0.05)); break;
              case 'arrowright': setSpatialScale(s => Math.min(2.0, s + 0.05)); break;
              case 'arrowleft': setSpatialScale(s => Math.max(0.0, s - 0.05)); break;
          }
      };
      window.addEventListener('keydown', handleKeyDown);
      return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isSettingsOpen, isSynthOpen, settings.enableKeyboardShortcuts]);

  const marginPx = (settings.uiEdgeMargin || 4) * PIXELS_PER_MM;
  const headerTop = `calc(${marginPx}px + env(safe-area-inset-top))`;
  const headerLeft = `calc(${marginPx}px + env(safe-area-inset-left))`;
  const headerRight = `calc(${marginPx}px + env(safe-area-inset-right))`;

  const headerBtnClass = "bg-slate-900/50 hover:bg-slate-800 px-3 py-1 rounded-xl backdrop-blur-sm transition border border-slate-700/50 h-8 flex items-center text-[10px] font-bold text-slate-400 uppercase tracking-widest hover:text-white shadow-lg";

  // Arp config for current preset
  const currentArpConfig = presets.arpeggio.arpConfig || { direction: 'order', division: '1/8', octaves: 1, gate: 0.8, swing: 0, length: 16 };

  return (
    <div className="relative w-screen h-screen overflow-hidden bg-slate-900 font-sans text-white">
      <div className="absolute z-50 pointer-events-none" style={{ top: headerTop, left: headerLeft }}>
        <h1 className="text-sm font-bold tracking-widest text-slate-500 opacity-20 leading-none">PRISMATONAL</h1>
      </div>

      <div className="absolute z-50 flex gap-2 pointer-events-auto" style={{ top: headerTop, right: headerRight }}>
          <button onClick={() => setIsSettingsOpen(true)} className={headerBtnClass}>Settings</button>
          <button onClick={() => setIsSynthOpen(true)} className={headerBtnClass}>Synth</button>
      </div>

      <TonalityDiamond 
        ref={diamondRef}
        settings={settings}
        updateSettings={updateSettings}
        audioEngine={audioEngine} 
        onLimitInteraction={handleLimitInteraction}
        activeChordIds={activeChordIds}
        uiUnlocked={settings.uiUnlocked}
        latchMode={latchMode}
        globalScale={effectiveScale}
        onNodeTrigger={handleArpRecordNote} 
      />

      <FloatingControls 
        volume={masterVolume} setVolume={setMasterVolume}
        spatialScale={spatialScale} setSpatialScale={setSpatialScale}
        brightness={brightness} setBrightness={setBrightness}

        onPanic={handlePanic} onOff={handleOff}
        onLatch={handleLatchToggle} latchMode={latchMode}
        onBend={handleBendToggle} isBendEnabled={settings.isPitchBendEnabled}
        onCenter={handleCenter}
        onIncreaseDepth={handleIncreaseDepth} onDecreaseDepth={handleDecreaseDepth}
        onAddChord={handleAddChord} toggleChord={toggleChord}
        activeChordIds={activeChordIds} savedChords={settings.savedChords}
        chordShortcutSizeScale={settings.chordShortcutSizeScale}
        showIncreaseDepthButton={settings.showIncreaseDepthButton}
        uiUnlocked={settings.uiUnlocked}
        uiPositions={settings.uiPositions} updatePosition={handleUiPositionUpdate}
        draggingId={draggingId} setDraggingId={setDraggingId}
        uiScale={effectiveScale}

        arpeggios={settings.arpeggios}
        arpBpm={settings.arpBpm}
        arpConfig={currentArpConfig}
        onArpToggle={handleArpToggle}
        onArpBpmChange={handleArpBpmChange}
        onArpConfigChange={handleArpConfigChange}
        recordingArpId={recordingArpId}
        currentArpStep={currentArpStep}
      />

      <LimitLayerControls settings={settings} updateSettings={updateSettings} draggingId={draggingId} setDraggingId={setDraggingId} uiScale={effectiveScale} />
      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} settings={settings} updateSettings={updateSettings} />
      <SynthControls isOpen={isSynthOpen} onClose={() => setIsSynthOpen(false)} presets={presets} onChange={setPreset} />
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { ChordDefinition, XYPos, AppSettings, ArpeggioDefinition, ArpConfig, ArpDirection, ArpDivision } from '../types';
import { MARGIN_3MM, SCROLLBAR_WIDTH } from '../constants';

interface Props {
  volume: number;
  setVolume: (v: number) => void;
  spatialScale: number;
  setSpatialScale: (v: number) => void;
  brightness: number;
  setBrightness: (v: number) => void;

  onPanic: () => void;
  onOff: () => void;
  onLatch: () => void;
  latchMode: 0 | 1 | 2;
  onBend: () => void;
  isBendEnabled: boolean;
  onCenter: () => void;
  onIncreaseDepth: () => void;
  onDecreaseDepth: () => void;
  onAddChord: () => void;
  toggleChord: (id: string) => void;
  activeChordIds: string[];
  savedChords: ChordDefinition[];
  chordShortcutSizeScale: number;
  showIncreaseDepthButton: boolean;
  uiUnlocked: boolean;
  uiPositions: AppSettings['uiPositions'];
  updatePosition: (key: keyof AppSettings['uiPositions'], pos: XYPos) => void;
  draggingId: string | null;
  setDraggingId: (id: string | null) => void;
  uiScale?: number;

  // Arp Props
  arpeggios?: ArpeggioDefinition[];
  arpBpm?: number;
  arpConfig?: ArpConfig;
  onArpToggle?: (id: string) => void;
  onArpBpmChange?: (bpm: number) => void;
  onArpConfigChange?: (config: Partial<ArpConfig>) => void;
  recordingArpId?: string | null; 
  currentArpStep?: number;
}

const FloatingControls: React.FC<Props> = ({ 
  volume, setVolume, spatialScale, setSpatialScale, brightness, setBrightness,
  onPanic, onOff, onLatch, latchMode, onBend, isBendEnabled, onCenter, onIncreaseDepth, onDecreaseDepth, onAddChord, toggleChord,
  activeChordIds, savedChords, chordShortcutSizeScale,
  showIncreaseDepthButton, uiUnlocked, uiPositions, updatePosition,
  draggingId, setDraggingId,
  uiScale = 1.0,
  arpeggios = [], arpBpm = 120, arpConfig, onArpToggle, onArpBpmChange, onArpConfigChange, recordingArpId, currentArpStep
}) => {

  const [showSequencer, setShowSequencer] = useState(false);
  const [verticalSeq, setVerticalSeq] = useState(false);

  const handleDrag = (e: React.PointerEvent, key: keyof AppSettings['uiPositions']) => {
    if (!uiUnlocked) return;
    if (draggingId !== null && draggingId !== key) return;

    const el = e.currentTarget as HTMLElement;
    const startX = e.clientX;
    const startY = e.clientY;
    const initialLeft = uiPositions[key as keyof typeof uiPositions].x;
    const initialTop = uiPositions[key as keyof typeof uiPositions].y;

    el.setPointerCapture(e.pointerId);
    setDraggingId(key);

    const onMove = (evt: PointerEvent) => {
        const deltaX = evt.clientX - startX;
        const deltaY = evt.clientY - startY;
        let newX = initialLeft + deltaX;
        let newY = initialTop + deltaY;
        const maxX = window.innerWidth - el.offsetWidth - MARGIN_3MM - SCROLLBAR_WIDTH;
        const maxY = window.innerHeight - el.offsetHeight - MARGIN_3MM - SCROLLBAR_WIDTH;
        const minX = MARGIN_3MM;
        const minY = MARGIN_3MM;
        newX = Math.max(minX, Math.min(newX, maxX));
        newY = Math.max(minY, Math.min(newY, maxY));
        updatePosition(key, { x: newX, y: newY });
    };

    const onUp = () => {
        setDraggingId(null);
        window.removeEventListener('pointermove', onMove);
        window.removeEventListener('pointerup', onUp);
        window.removeEventListener('pointercancel', onUp);
    };

    window.addEventListener('pointermove', onMove);
    window.addEventListener('pointerup', onUp);
    window.addEventListener('pointercancel', onUp);
  };

  const baseSize = 48 * uiScale; 
  const chordSize = baseSize * chordShortcutSizeScale;
  const largeBtnSize = 80 * uiScale;

  // Expanded Width for Audio Stack
  const stackWidth = 400 * uiScale; 

  const draggableStyle = (key: string) => ({
      left: uiPositions[key as keyof typeof uiPositions].x,
      top: uiPositions[key as keyof typeof uiPositions].y,
      touchAction: 'none' as React.CSSProperties['touchAction'],
  });

  const handleButtonPress = (e: React.PointerEvent, key: keyof AppSettings['uiPositions'], action: () => void) => {
      e.stopPropagation();
      if (uiUnlocked) {
          handleDrag(e, key);
      } else {
          action();
      }
  };

  const getLatchStyle = () => {
      const base = "absolute rounded-full flex items-center justify-center font-bold uppercase tracking-wider backdrop-blur transition-all z-[150] select-none shadow-lg";
      const unlocked = uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : '';
      if (latchMode === 1) return `${base} ${unlocked} bg-green-500 text-white border-2 border-green-300 shadow-[0_0_20px_rgba(34,197,94,0.8)]`;
      else if (latchMode === 2) return `${base} ${unlocked} bg-green-900/60 text-green-400 border-2 border-green-400 ring-4 ring-green-500/30 animate-pulse shadow-[0_0_15px_rgba(34,197,94,0.4)]`;
      else return `${base} ${unlocked} bg-green-900/40 border-2 border-green-500/50 text-green-500 hover:bg-green-800/60 active:bg-green-600 active:text-white shadow-[0_0_15px_rgba(34,197,94,0.2)]`;
  };

  // Find currently active or recording arp to display in Sequencer
  const activeArp = arpeggios.find(a => a.isPlaying || a.id === recordingArpId);
  const activeSteps = activeArp ? activeArp.steps : [];

  // Pre-established steps grid generation
  const patternLength = arpConfig?.length || 16;
  const gridSteps = Array.from({ length: patternLength }, (_, i) => {
      // Loop the active steps data into the grid pattern
      if (activeSteps.length > 0) {
          return activeSteps[i % activeSteps.length];
      }
      return null;
  });

  return (
    <>
      <style>{`
        .prismatonal-slider::-webkit-slider-thumb { -webkit-appearance: none; appearance: none; width: 12px; height: 12px; border-radius: 50%; background: currentColor; cursor: pointer; border: 2px solid white; box-shadow: 0 0 5px rgba(0,0,0,0.5); }
        .prismatonal-slider::-moz-range-thumb { width: 12px; height: 12px; border-radius: 50%; background: currentColor; cursor: pointer; border: 2px solid white; box-shadow: 0 0 5px rgba(0,0,0,0.5); }
        input[type=number]::-webkit-inner-spin-button, input[type=number]::-webkit-outer-spin-button { -webkit-appearance: none; margin: 0; }
        .no-spinner { -moz-appearance: textfield; }

        /* Custom Scrollbar for Sequencer Steps */
        .seq-scroll::-webkit-scrollbar { height: 8px; width: 8px; }
        .seq-scroll::-webkit-scrollbar-track { background: rgba(15, 23, 42, 0.5); border-radius: 4px; }
        .seq-scroll::-webkit-scrollbar-thumb { background: rgba(71, 85, 105, 0.8); border-radius: 4px; border: 1px solid rgba(15, 23, 42, 0.5); }
        .seq-scroll::-webkit-scrollbar-thumb:hover { background: rgba(148, 163, 184, 1); }
      `}</style>

      {/* Unified Audio Stack Control */}
      <div 
        className={`absolute bg-slate-900/50 rounded-xl flex flex-col p-3 gap-3 backdrop-blur-sm border border-slate-700/50 transition-colors z-[150] shadow-2xl ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : ''}`}
        style={{ ...draggableStyle('volume'), width: stackWidth }}
        onPointerDown={(e) => handleDrag(e, 'volume')}
      >
        {/* VOLUME ROW */}
        <div className="flex items-center gap-3">
             <span className="font-bold text-slate-400 select-none uppercase tracking-widest text-right" style={{ fontSize: 15 * uiScale, width: 90 * uiScale }}>Volume</span>
             <input 
                type="range" min="0" max="1" step="0.01" value={volume} onChange={(e) => setVolume(parseFloat(e.target.value))} disabled={uiUnlocked}
                className={`prismatonal-slider flex-1 rounded-lg appearance-none text-green-500 ${uiUnlocked ? 'cursor-move opacity-50' : 'cursor-pointer'}`}
                style={{ height: 4 * uiScale, background: `linear-gradient(to right, #22c55e 0%, #22c55e ${volume * 100}%, #334155 ${volume * 100}%, #334155 100%)` }}
                onPointerDown={(e) => !uiUnlocked && e.stopPropagation()} 
             />
        </div>
        {/* REVERB ROW */}
        <div className="flex items-center gap-3">
             <span className="font-bold text-slate-400 select-none uppercase tracking-widest text-right" style={{ fontSize: 15 * uiScale, width: 90 * uiScale }}>Reverb</span>
             <input 
                type="range" min="0" max="2" step="0.01" value={spatialScale} onChange={(e) => setSpatialScale(parseFloat(e.target.value))} disabled={uiUnlocked}
                className={`prismatonal-slider flex-1 rounded-lg appearance-none text-blue-500 ${uiUnlocked ? 'cursor-move opacity-50' : 'cursor-pointer'}`}
                style={{ height: 4 * uiScale, background: `linear-gradient(to right, #3b82f6 0%, #3b82f6 ${(spatialScale/2) * 100}%, #334155 ${(spatialScale/2) * 100}%, #334155 100%)` }}
                onPointerDown={(e) => !uiUnlocked && e.stopPropagation()} 
             />
        </div>
        {/* TONE ROW */}
        <div className="flex items-center gap-3">
             <span className="font-bold text-slate-400 select-none uppercase tracking-widest text-right" style={{ fontSize: 15 * uiScale, width: 90 * uiScale }}>Tone</span>
             <input 
                type="range" min="0" max="1" step="0.01" value={brightness} onChange={(e) => setBrightness(parseFloat(e.target.value))} disabled={uiUnlocked}
                className={`prismatonal-slider flex-1 rounded-lg appearance-none text-yellow-500 ${uiUnlocked ? 'cursor-move opacity-50' : 'cursor-pointer'}`}
                style={{ height: 4 * uiScale, background: `linear-gradient(to right, #eab308 0%, #eab308 ${brightness * 100}%, #334155 ${brightness * 100}%, #334155 100%)` }}
                onPointerDown={(e) => !uiUnlocked && e.stopPropagation()} 
             />
        </div>
      </div>


      {/* Arpeggiator Bar */}
      <div 
        className={`absolute bg-slate-900/50 rounded-xl flex flex-col items-center backdrop-blur-sm border border-slate-700/50 transition-colors z-[150] shadow-2xl overflow-visible ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : ''}`}
        style={{ ...draggableStyle('arpeggioBar'), minWidth: 250 * uiScale, padding: 8 * uiScale }}
        onPointerDown={(e) => handleDrag(e, 'arpeggioBar')}
      >
        <div className="w-full flex flex-col gap-2">
             {/* 3-Column Grid */}
             <div className="grid grid-cols-3 items-center px-1">
                 <div className="flex justify-start">
                    <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">ARPEGGIATOR</span>
                 </div>
                 <div className="flex justify-center">
                    <div className={`w-2 h-2 rounded-full ${arpeggios.some(a => a.isPlaying) && (Math.floor(Date.now() / (30000/arpBpm!)) % 2 === 0) ? 'bg-green-500 shadow-[0_0_5px_lime]' : 'bg-slate-800'}`}></div>
                 </div>
                 <div className="flex justify-end items-center gap-1">
                     <div className="flex items-center gap-px bg-slate-800/50 rounded border border-slate-700/50 overflow-hidden">
                        <button 
                            className="px-1.5 py-0.5 hover:bg-slate-700 active:bg-slate-600 text-slate-400 hover:text-white transition-colors border-r border-slate-700/30"
                            onPointerDown={(e) => { e.stopPropagation(); onArpBpmChange && onArpBpmChange(Math.max(1, (arpBpm || 120) - 1)); }}
                        >
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" /></svg>
                        </button>
                        <input 
                            type="number" 
                            value={arpBpm} 
                            onChange={(e) => onArpBpmChange && onArpBpmChange(parseInt(e.target.value))}
                            className="w-8 bg-transparent text-center text-[10px] font-mono font-bold text-slate-300 focus:outline-none focus:text-white no-spinner"
                            onPointerDown={(e) => e.stopPropagation()}
                        />
                        <button 
                            className="px-1.5 py-0.5 hover:bg-slate-700 active:bg-slate-600 text-slate-400 hover:text-white transition-colors border-l border-slate-700/30"
                            onPointerDown={(e) => { e.stopPropagation(); onArpBpmChange && onArpBpmChange(Math.min(300, (arpBpm || 120) + 1)); }}
                        >
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-3 w-3 rotate-180" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" /></svg>
                        </button>
                     </div>
                     <span className="text-[8px] text-slate-500 font-bold ml-1">BPM</span>
                 </div>
             </div>

             <div className="flex gap-1.5 justify-center flex-wrap">
                 {arpeggios.map(arp => {
                     const isRecording = recordingArpId === arp.id;
                     const isPlaying = arp.isPlaying;
                     const hasData = arp.steps.length > 0;

                     let btnClass = "bg-slate-800/80 border-slate-600 text-slate-400";
                     if (isRecording) btnClass = "bg-red-900/80 border-red-500 text-white animate-pulse shadow-[0_0_10px_red]";
                     else if (isPlaying) btnClass = "bg-blue-600 border-blue-400 text-white shadow-[0_0_10px_blue]";
                     else if (hasData) btnClass = "bg-slate-700 border-blue-500/30 text-blue-200";

                     return (
                         <button 
                            key={arp.id}
                            className={`rounded-lg flex items-center justify-center font-bold border-2 transition-all hover:scale-105 active:scale-95 ${btnClass}`}
                            style={{ width: 40 * uiScale, height: 40 * uiScale, fontSize: 16 * uiScale }}
                            onPointerDown={(e) => { e.stopPropagation(); if(onArpToggle) onArpToggle(arp.id); }}
                         >
                             {arp.id}
                         </button>
                     );
                 })}
             </div>
        </div>

        {/* Dropdown Toggle */}
        <button 
            className="w-full h-4 mt-2 bg-slate-800/50 hover:bg-slate-700/50 rounded flex items-center justify-center cursor-pointer transition-colors"
            onPointerDown={(e) => { e.stopPropagation(); setShowSequencer(!showSequencer); }}
        >
             <svg xmlns="http://www.w3.org/2000/svg" className={`h-3 w-3 text-slate-400 transition-transform ${showSequencer ? 'rotate-180' : ''}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
               <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
             </svg>
        </button>

        {/* Sequencer Dropdown (Revised) */}
        {showSequencer && arpConfig && (
            <div 
                className="absolute top-full left-0 bg-slate-900/50 backdrop-blur-sm border border-slate-700/50 rounded-xl mt-2 shadow-2xl p-4 z-[140] flex flex-col gap-4 overflow-hidden"
                style={{ width: '100%', minWidth: '400px', height: 'auto', maxHeight: '600px', transformOrigin: 'top left', resize: 'both' }}
                onPointerDown={(e) => e.stopPropagation()} 
            >
                <div className="flex justify-between items-center pb-2 border-b border-white/5">
                    <span className="text-xs font-bold text-slate-400 uppercase tracking-wider">SEQUENCER</span>
                    <span className="text-[9px] text-slate-600 font-bold uppercase">{activeArp?.id || 'None'}</span>
                </div>

                {/* Control Matrix Grid */}
                <div className="grid grid-cols-2 gap-4">

                    {/* Pattern Length Slider */}
                    <div className="col-span-2 flex flex-col gap-1">
                        <span className="text-[9px] font-bold text-slate-500 uppercase flex justify-between">
                            <span>Pattern Length</span>
                            <span className="text-white">{arpConfig.length || 16} Steps</span>
                        </span>
                        <input 
                            type="range" min="1" max="32" step="1" 
                            value={arpConfig.length || 16}
                            onChange={(e) => onArpConfigChange && onArpConfigChange({ length: parseInt(e.target.value) })}
                            className="w-full h-3 bg-slate-800 rounded appearance-none cursor-pointer accent-blue-500"
                        />
                    </div>

                    <div className="flex flex-col gap-1">
                        <span className="text-[9px] font-bold text-slate-500 uppercase">Steps (Time Div)</span>
                        <div className="flex gap-1 flex-wrap">
                            {(['1/4', '1/8', '1/16', '1/32'] as ArpDivision[]).map(div => (
                                <button 
                                    key={div} 
                                    onPointerDown={(e) => { e.stopPropagation(); onArpConfigChange && onArpConfigChange({ division: div }); }}
                                    className={`flex-1 h-6 rounded text-[9px] font-mono font-bold border transition-colors min-w-[30px] ${arpConfig.division === div ? 'bg-blue-600/80 border-blue-400 text-white' : 'bg-slate-800/50 border-slate-700 text-slate-500 hover:text-white'}`}
                                >
                                    {div.replace('1/', '')}
                                </button>
                            ))}
                        </div>
                        <div className="flex gap-1 flex-wrap mt-1">
                            {(['1/4T', '1/8T', '1/16T'] as ArpDivision[]).map(div => (
                                <button 
                                    key={div} 
                                    onPointerDown={(e) => { e.stopPropagation(); onArpConfigChange && onArpConfigChange({ division: div }); }}
                                    className={`flex-1 h-6 rounded text-[9px] font-mono font-bold border transition-colors min-w-[30px] ${arpConfig.division === div ? 'bg-purple-600/80 border-purple-400 text-white' : 'bg-slate-800/50 border-slate-700 text-slate-500 hover:text-white'}`}
                                >
                                    {div.replace('1/', '')}
                                </button>
                            ))}
                        </div>
                    </div>

                    <div className="flex flex-col gap-1">
                        <span className="text-[9px] font-bold text-slate-500 uppercase">Direction</span>
                        <div className="flex gap-1 flex-wrap">
                            {(['order', 'up', 'down', 'random'] as ArpDirection[]).map(dir => (
                                <button 
                                    key={dir} 
                                    onPointerDown={(e) => { e.stopPropagation(); onArpConfigChange && onArpConfigChange({ direction: dir }); }}
                                    className={`flex-1 h-6 rounded text-[9px] font-bold uppercase border transition-colors ${arpConfig.direction === dir ? 'bg-red-600/80 border-red-400 text-white' : 'bg-slate-800/50 border-slate-700 text-slate-500 hover:text-white'}`}
                                >
                                    {dir}
                                </button>
                            ))}
                        </div>

                        <div className="flex items-center justify-between mt-2 pt-2 border-t border-white/5">
                             <span className="text-[9px] font-bold text-slate-500 uppercase">Orientation</span>
                             <button 
                                onPointerDown={(e) => { e.stopPropagation(); setVerticalSeq(!verticalSeq); }}
                                className={`px-2 py-0.5 rounded text-[9px] font-bold uppercase border ${verticalSeq ? 'bg-orange-600/80 border-orange-400 text-white' : 'bg-slate-800 border-slate-600 text-slate-400'}`}
                             >
                                 {verticalSeq ? 'Vertical' : 'Horizontal'}
                             </button>
                        </div>
                    </div>

                    <div className="flex flex-col gap-1">
                        <span className="text-[9px] font-bold text-slate-500 uppercase">Octaves ({arpConfig.octaves})</span>
                        <div className="flex gap-1">
                            {[1, 2, 3, 4].map(oct => (
                                <button 
                                    key={oct} 
                                    onPointerDown={(e) => { e.stopPropagation(); onArpConfigChange && onArpConfigChange({ octaves: oct }); }}
                                    className={`flex-1 h-6 rounded text-[10px] font-bold border transition-colors ${arpConfig.octaves === oct ? 'bg-purple-600/80 border-purple-400 text-white' : 'bg-slate-800/50 border-slate-700 text-slate-500 hover:text-white'}`}
                                >
                                    {oct}
                                </button>
                            ))}
                        </div>
                    </div>
                     <div className="flex flex-col gap-1">
                        <span className="text-[9px] font-bold text-slate-500 uppercase">Note Length (Gate) ({(arpConfig.gate * 100).toFixed(0)}%)</span>
                        <input 
                            type="range" min="0.1" max="1.0" step="0.1" 
                            value={arpConfig.gate}
                            onChange={(e) => onArpConfigChange && onArpConfigChange({ gate: parseFloat(e.target.value) })}
                            className="w-full h-6 bg-slate-800/50 rounded appearance-none cursor-pointer"
                        />
                    </div>
                </div>

                <div className="h-px bg-white/5 w-full"></div>

                {/* Pre-established Steps Grid Visualizer */}
                <div className={`flex-1 flex gap-2 p-2 bg-slate-950/30 rounded-lg border border-slate-700/30 relative seq-scroll ${verticalSeq ? 'flex-col overflow-y-auto overflow-x-hidden' : 'flex-row overflow-x-auto overflow-y-hidden items-center'}`}>
                    {gridSteps.length === 0 && (
                        <div className="absolute inset-0 flex items-center justify-center text-slate-600 text-xs italic">
                            No Steps
                        </div>
                    )}
                    {gridSteps.map((step, idx) => {
                        const isCurrent = idx === (currentArpStep || 0) % (arpConfig.length || 16);
                        const hasData = step !== null;

                        return (
                            <div 
                                key={idx} 
                                className={`flex-shrink-0 rounded border flex items-center justify-between transition-all 
                                    ${verticalSeq ? 'w-full h-8 px-2 flex-row' : 'w-8 h-16 py-1 flex-col'}
                                    ${isCurrent ? 'bg-slate-700 border-white shadow-lg z-10 scale-105' : 'bg-slate-800/50 border-slate-700'}
                                `}
                            >
