  midiPitchBendRange: 24,

  // Behavior
  enableKeyboardShortcuts: false,
  strumDuration: 0.5,

  // UI Relocation & Scaling
  uiUnlocked: false,
  uiScale: 1.0, 
  uiEdgeMargin: 4, 
  uiPositions: DEFAULT_UI_POSITIONS
};

