                                            <path fillRule="evenodd" d="M9 2a1 1 0 00-.894.553L7.382 4H4a1 1 0 000 2v10a2 2 0 002 2h8a2 2 0 002-2V6a1 1 0 100-2h-3.382l-.724-1.447A1 1 0 0011 2H9zM7 8a1 1 0 012 0v6a1 1 0 11-2 0V8zm5-1a1 1 0 00-1 1v6a1 1 0 102 0V8a1 1 0 00-1-1z" clipRule="evenodd" />
                                        </svg>
                                    </button>
                                </div>

                                {/* Axis 2: Steps */}
                                <div className="flex-1 flex gap-1 overflow-x-auto seq-scroll pb-1 items-center h-full">
                                    {steps.map((step, idx) => {
                                        // Highlight current step if this arp is playing
                                        // NOTE: currentArpStep tracks the *engine* step. 
                                        // Since we are showing linear steps, index matches engine step % length if in order
                                        const isCurrent = isPlaying && idx === (currentArpStep || 0) % patternLength;
                                        const hasData = step !== null;

                                        const borderColor = hasData ? 'border-blue-500' : 'border-slate-700';
                                        const bgColor = isCurrent ? 'bg-slate-600' : 'bg-slate-800/80';
                                        const textColor = hasData ? 'text-blue-200' : 'text-slate-600';

                                        return (
                                            <div 
                                                key={idx} 
                                                className={`flex-shrink-0 w-8 h-8 rounded-lg border-2 flex items-center justify-center transition-all m-0.5 cursor-pointer
                                                    ${bgColor} ${borderColor} ${isCurrent ? 'shadow-lg scale-110 z-10 border-white' : ''} 
                                                    ${hasData ? 'hover:border-red-500 hover:bg-red-900/30' : ''}
                                                `}
                                                title={hasData ? `Ratio: ${step?.n}/${step?.d} (Click to delete)` : `Step ${idx+1}`}
                                                onPointerDown={(e) => { e.stopPropagation(); if (hasData) handleStepClick(arp.id, idx); }}
                                            >
                                                {hasData ? (
                                                    <span className="text-[9px] font-bold leading-none flex flex-col items-center justify-center select-none pointer-events-none">
                                                        <span className="relative">
                                                            {step?.n}
