                                                    </span>
                                                ) : (
                                                    <span className={`text-[10px] font-mono ${textColor} select-none`}>{idx+1}</span>
                                                )}
                                            </div>
                                        );
                                    })}
                                </div>
                            </div>
                        );
                    })}
                </div>

                <div className="flex justify-between items-end relative mt-1 flex-shrink-0">
                     {playingArp && recordingArpId && (
