  // Key Binder State
  const [listeningFor, setListeningFor] = useState<keyof KeyMappings | null>(null);

  useEffect(() => {
    if (isOpen && activeTab === 'midi') {
        midiService.init().then(success => {
            if (success) {
                midiService.getOutputs().then(devices => {
                    setMidiDevices(devices);
                });
            }
        });
    }
  }, [isOpen, activeTab]);

  // Key Listener Effect
  useEffect(() => {
      const handleBinderKeyDown = (e: KeyboardEvent) => {
          if (!listeningFor) return;
          e.preventDefault();
          e.stopPropagation();

          let key = e.key.toLowerCase();
          if (key === ' ') key = 'Space'; // Visual nicety for Spacebar

          updateSettings({
              ...settings,
              keyMappings: {
                  ...settings.keyMappings,
                  [listeningFor]: key
              }
          });
          setListeningFor(null);
      };

      if (listeningFor) {
          window.addEventListener('keydown', handleBinderKeyDown);
      }
      return () => {
          window.removeEventListener('keydown', handleBinderKeyDown);
      };
  }, [listeningFor, settings, updateSettings]);

  if (!isOpen) return null;

  const handleChange = (key: keyof AppSettings, value: any) => {
    updateSettings({ ...settings, [key]: value });
  };

  const handleLimitDepthChange = (limit: 3 | 5 | 7 | 11 | 13, val: number) => {
    updateSettings({
      ...settings,
      limitDepths: { ...settings.limitDepths, [limit]: val }
    });
  };

  const handleLimitComplexityChange = (limit: 3 | 5 | 7 | 11 | 13, val: number) => {
    updateSettings({
      ...settings,
      limitComplexities: { ...settings.limitComplexities, [limit]: val }
    });
  };

  const handleColorChange = (limit: number, color: string) => {
    updateSettings({
      ...settings,
      colors: { ...settings.colors, [limit]: color }
    });
  };

  const updateChord = (index: number, field: keyof ChordDefinition, value: any) => {
      const newChords = [...settings.savedChords];
      newChords[index] = { ...newChords[index], [field]: value };
      updateSettings({ ...settings, savedChords: newChords });
  };

  const setDefaultColors = () => {
    updateSettings({ ...settings, colors: { ...DEFAULT_COLORS } });
  };

  const hslToHex = (h: number, s: number, l: number) => {
    l /= 100;
    const a = s * Math.min(l, 1 - l) / 100;
    const f = (n: number) => {
      const k = (n + h / 30) % 12;
      const color = l - a * Math.max(Math.min(k - 3, 9 - k, 1), -1);
      return Math.round(255 * color).toString(16).padStart(2, '0');
    };
    return `#${f(0)}${f(8)}${f(4)}`;
  };

  const extractColorsFromImage = (imageSrc: string): Promise<LimitColorMap> => {
    return new Promise((resolve) => {
        const img = new Image();
        img.src = imageSrc;
        img.onload = () => {
            const cvs = document.createElement('canvas');
            const ctx = cvs.getContext('2d');
            cvs.width = 50;
            cvs.height = 50;
            ctx?.drawImage(img, 0, 0, 50, 50);
            const data = ctx?.getImageData(0, 0, 50, 50).data;
            if(!data) { resolve(DEFAULT_COLORS); return; }

            const getHex = (x: number, y: number) => {
                const i = (y * 50 + x) * 4;
                const r = data[i];
                const g = data[i+1];
                const b = data[i+2];
                return "#" + ((1 << 24) + (r << 16) + (g << 8) + b).toString(16).slice(1);
            }

            const extracted: LimitColorMap = {
                1: getHex(25, 25), 
                3: getHex(10, 10), 
                5: getHex(40, 40), 
                7: getHex(40, 10), 
                11: getHex(10, 40),
                13: getHex(25, 10) 
            };
            resolve(extracted);
        };
        img.onerror = () => resolve(DEFAULT_COLORS);
    });
  };

  const pairLimitsToBackground = async () => {
     const mode = settings.backgroundMode;
     if (mode === 'rainbow') {
         const ratios: {[key: number]: number} = {
             1: 1, 3: 1.5, 5: 1.25, 7: 7/8, 11: 11/8, 13: 13/8
         };
         const newColors = { ...settings.colors };
         const offset = settings.rainbowOffset;
         Object.keys(ratios).forEach(k => {
             const key = parseInt(k);
             const ratio = ratios[key];
             const shift = -Math.log2(ratio) * 360;
             let hue = (offset + shift) % 360;
             if (hue < 0) hue += 360;
             newColors[key] = hslToHex(hue, settings.rainbowSaturation || 70, 60); 
         });
         updateSettings({ ...settings, colors: newColors });
     } 
     else if (mode === 'image' && settings.backgroundImageData) {
         const extracted = await extractColorsFromImage(settings.backgroundImageData);
         updateSettings({ ...settings, colors: extracted });
     } 
     else if (PRESET_PALETTES[mode]) {
         updateSettings({ ...settings, colors: { ...settings.colors, ...PRESET_PALETTES[mode] } });
     } 
     else {
         setDefaultColors();
     }
  };

  const handleImportClick = () => {
      fileInputRef.current?.click();
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
          importXML(file).then(success => {
              if (success) onClose();
          });
      }
      if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleBgImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
          const reader = new FileReader();
          reader.onload = (evt) => {
              const result = evt.target?.result as string;
              updateSettings({
                  ...settings,
                  backgroundImageData: result,
                  backgroundMode: 'image'
              });
          };
          reader.readAsDataURL(file);
      }
      if (bgImageInputRef.current) bgImageInputRef.current.value = '';
  };

  const renderKeyBinding = (label: string, actionKey: keyof KeyMappings) => {
      const isListening = listeningFor === actionKey;
      const currentKey = settings.keyMappings[actionKey].toUpperCase();

      return (
          <div className="flex justify-between items-center bg-slate-800 p-2 rounded border border-slate-700 hover:border-slate-600 transition-colors">
              <span className="text-sm font-bold text-slate-300">{label}</span>
              <button 
                  onClick={() => setListeningFor(actionKey)}
                  className={`px-3 py-1 text-xs font-mono font-bold rounded min-w-[80px] border transition-all ${isListening ? 'bg-red-900 border-red-500 text-white animate-pulse' : 'bg-slate-700 border-slate-600 text-blue-300 hover:bg-slate-600'}`}
              >
                  {isListening ? 'Press Key...' : currentKey}
              </button>
          </div>
      );
  };

  return (
    <div className="fixed inset-0 bg-black/80 z-[200] flex items-center justify-center backdrop-blur-sm">
