                        <div className={`space-y-2 max-h-[300px] overflow-y-auto pr-2 custom-scrollbar ${settings.enableKeyboardShortcuts ? 'opacity-100' : 'opacity-40 pointer-events-none grayscale'}`}>
                            {renderKeyBinding('Latch', 'latch')}
