                            style={{ width: 38 * uiScale, height: 38 * uiScale, fontSize: 14 * uiScale }}
                            onPointerDown={(e) => { e.stopPropagation(); if(onArpToggle) onArpToggle(arp.id); }}
                         >
                             {showGreenDot ? (
